var QUESTOES_COLOCACAOPRONOMINAL = [{"id":307,"enunciado":"“Na atividade realizada com os estudantes do 6º ano, por exemplo, o professor percebeu dificuldades em saberes simples, como a separação de sílabas tônicas, por isso, retomou esse conteúdo. Além disso, Jonathan explica que todos os professores estão realizando, regularmente, pequenas avaliações – sempre com habilidades do ano anterior – a fim de olhar para as lacunas que resultaram das limitações impostas pelo período pandêmico”. Fonte: (https://novaescola.org.br/conteudo/21187 – Fragmento retirado do texto “Escuta dos alunos e atividades interdisciplinares são opções para recompor a aprendizagem”). Sobre separação silábica, à luz do que diz Cegalla, afirma-se que: I. A regra geral diz: Na escrita, não se separam letras representativas da mesma sílaba. II. Não se separam letras que representam ditongos, tritongos, dígrafos e encontros consonantais inseparáveis. III. Em oposição à regra geral, separam-se, por tradição, na escrita, as letras dos dígrafos rr, ss, sc, sç e xc. IV. O x com valor fonético de /cs/ junta-se à vogal seguinte (quando houver). Quais estão corretas?","opcoes":["Apenas I.","Apenas IV.","Apenas I e II.","Apenas II, III e IV.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["colocacaoPronominal","ditongos","tritongos","digrafos","silabas","encontrosConsonantais"]},{"id":310,"enunciado":"Sobre o vocábulo aí, no primeiro quadrinho, assinale a alternativa correta.","opcoes":["Trata-se de um vocábulo com hiato.","Trata-se de um monossílabo átono.","Trata-se de um monossílabo tônico.","Trata-se de um vocábulo com ditongo."],"correta":0,"explicacao":"Gabarito: <strong>Trata-se de um vocábulo com hiato.</strong>.","banca":"IESES","ano":2022,"temas_relacionados":["colocacaoPronominal","hiatos"]},{"id":526,"enunciado":"Destaca-se no fragmento: “Água que faz inocente riacho e deságua na corrente do ribeirão” um vocábulo grafado devidamente com “ch”, o que também se verifica na alternativa:","opcoes":["frouxo, queixa, enxugar.","enxoval, enxame, enxada.","enchente, chapéu, chiqueiro.","chingar, xampu, xará.","enxergar, engrachar, eixo."],"correta":2,"explicacao":"Gabarito: <strong>enchente, chapéu, chiqueiro.</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["colocacaoPronominal"]},{"id":656,"enunciado":"No texto “ELEIÇÕES 2014\", I. encontra-se a palavra “saúde\" acentuada porque o “u\" tônico forma um hiato. II. registra-se a presença dos termos “único\" e “políticos\" que recebem acento por serem proparoxítonos. III. identificam-se os termos “preferência\" e “necessário\", acentuados por serem paroxítonos terminados em ditongo. IV. tem-se o termo “além\", acentuado por ser um oxítono terminado em EM. Estão CORRETOS os itens","opcoes":["I, II e IV, apenas.","I, II e III, apenas.","III e IV, apenas.","II e IV, apenas.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"UPENET/IAUPE","ano":2014,"temas_relacionados":["colocacaoPronominal","ditongos","hiatos","proparoxitonas","paroxitonas","oxitonas"]},{"id":659,"enunciado":"As palavras que completam correta e respectivamente as lacunas do primeiro parágrafo do texto encontram-se na alternativa:","opcoes":["ideias, ultrapassado.","ideias, ultra-passado.","idéias, ultra-passado.","idéias, ultrapassado."],"correta":0,"explicacao":"Gabarito: <strong>ideias, ultrapassado.</strong>.","banca":"IESES","ano":2015,"temas_relacionados":["colocacaoPronominal"]},{"id":980,"enunciado":"Assinale a alternativa que se apresenta totalmente de acordo com a norma-padrão da Língua Portuguesa.","opcoes":["Vêm-se resultados satisfatórios naquela pesquisa.","Vêem-se resultados satisfatórios naquela pesquisa.","Vem-se resultados satisfatórios naquela pesquisa.","Vê-se resultados satisfatórios naquela pesquisa.","Veem-se resultados satisfatórios naquela pesquisa."],"correta":4,"explicacao":"Gabarito: <strong>Veem-se resultados satisfatórios naquela pesquisa.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":1127,"enunciado":"[Questão Inédita] Assinale a alternativa com a informação correta.","opcoes":["As palavras contribuíram, raízes, combustível, saúde e proteínas recebem acento gráfico em razão de uma mesma regra.","Em “Muitas dessas contribuições, no entanto, são desconhecidas”, a expressão “no entanto” pode ser substituída pela conjunção adversativa “mas” sem que se altere o sentido nem produza falha gramatical.","Em “era um alimento básico na era pré-colombiana” (5º parágrafo), observa-se a palavra “era” (com o mesmo som e grafia), mas em funções diferentes. Esse mesmo fenômeno ocorre na frase “Eu jogo o jogo”.","Em “como a medicina, a biologia, a matemática, a engenharia e a agricultura”, caso se troque a conjunção “e” por uma vírgula, perde-se a indicação de último elemento da enumeração, ou seja, do fechamento dos itens enumerados, e cria-se com a mudança a impressão de que mais elementos poderiam ser acrescentados.","Nos trechos “indígenas norte-americanos” e “era pré-colombiana”, observa-se uma mesma regra no uso do hífen para ambas as formações."],"correta":3,"explicacao":"Gabarito: <strong>Em “como a medicina, a biologia, a matemática, a engenharia e a agricultura”, caso se troque a conjunção “e” por uma vírgula, perde-se a indicação de último elemento da enumeração, ou seja, do fechamento dos itens enumerados, e cria-se com a mudança a impressão de que mais elementos poderiam ser acrescentados.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":1140,"enunciado":"Considerando-se o uso, de acordo com a norma-padrão da língua, da acentuação, é incorreto:","opcoes":["As nações européias temem a recessão econômica.","A ideia é simbólica, porém deve ser escutada com muita atenção.","A Inteligência Artificial está revolucionando a tecnologia.","O vício a ser tratado com as ferramentas corretas."],"correta":0,"explicacao":"Gabarito: <strong>As nações européias temem a recessão econômica.</strong>.","banca":"IGDRH","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":1251,"enunciado":"Assinale a alternativa que apresenta a justificativa correta da acentuação da palavra AVÓ em \"Atendendo a um pedido da minha AVÓ, levei uma velha tia solteirona de São Paulo ao sul da Bahia\":","opcoes":["Acentuam-se os monossílabos tônicos terminados em O.","Acentuam-se os monossílabos átonos terminados em O.","Acentuam-se as oxítonas homônimas \"avô\" e \"avó\" para diferenciação.","Acentuam-se as oxítonas terminadas em O."],"correta":3,"explicacao":"Gabarito: <strong>Acentuam-se as oxítonas terminadas em O.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal","oxitonas"]},{"id":1283,"enunciado":"Na frase \"Nem todos têm um time para chamar de seu\", a forma verbal \"têm\" foi acentuada pelo seguinte motivo:","opcoes":["Acentua-se o verbo \"ter\", quando empregado na 3.ª pessoa do singular ou do plural, no presente do indicativo.","Acentuam-se as palavras monossílabas tônicas quando terminadas por \"em\".","Acentuam-se todos os vocábulos oxítonos quando forem terminados por \"em\".","Acentua-se o verbo \"ter\", quando empregado na 3.ª pessoa do plural do presente do indicativo."],"correta":3,"explicacao":"Gabarito: <strong>Acentua-se o verbo \"ter\", quando empregado na 3.ª pessoa do plural do presente do indicativo.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":1363,"enunciado":"Analise a frase a seguir: \"A educação de qualidade só tem contribuído para o desenvolvimento social e econômico, tornando possível que pessoas de diferentes origens e contextos possam alcançar seus objetivos e transformar suas realidades; além disso, as políticas públicas têm desempenhado um papel fundamental nesse processo, garantindo que o acesso ao conhecimento seja um direito de todos.\" Em relação a acentuação gráfica das palavras dessa frase, assinale a alternativa que apresenta justificativa CORRETA:","opcoes":["têm - acentuam-se os monossílabos tônicos terminadas em \"EM\".","contribuído - Acentuam-se o \"i\" e \"u\" átonos quando formam hiato com a vogal anterior, estando eles sozinhos na sílaba ou acompanhados apenas de \"s\", desde que não sejam seguidos por \"- nh\".","possível - acentuam-se as paroxítonas terminadas em L.","só - acentuam-se as óxitonas terminadas em \"Ó\"."],"correta":2,"explicacao":"Gabarito: <strong>possível - acentuam-se as paroxítonas terminadas em L.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal","paroxitonas","acentuacaoGrafica"]},{"id":1367,"enunciado":"Assinale a alternativa que contenha a regra de acentuação das seguintes palavras retiradas do texto: “aniversário”, “família” e “secretária”.","opcoes":["Acentuam-se todas as palavras oxítonas terminadas em “io” e “ia”.","Acentuam-se todas as palavras proparoxítonas.","Acentuam-se as palavras paroxítonas terminadas em ditongo oral.","Acentuam-se os monossílabos tônicos terminados em a, e, o, seguidos ou não de s.","Acentuam-se as palavras paroxítonas tônicas."],"correta":2,"explicacao":"Gabarito: <strong>Acentuam-se as palavras paroxítonas terminadas em ditongo oral.</strong>.","banca":"UFCG","ano":2025,"temas_relacionados":["colocacaoPronominal","ditongos","paroxitonas"]},{"id":1406,"enunciado":"Assinale o período abaixo que apresenta um exemplo CORRETO de verbo que perdeu acento segundo a reforma ortográfica:","opcoes":["“A “ego-história” está sempre ameaçada pelas rememorações das experiências, não como foram, mas como deviam ter sido para adequar-se ao presente do indivíduo.”","“Devo dizer que a tarefa se tornou mais complexa e mais problemática do que pensavam os colegas que publicam esta excelente revista,”","“...ler é também apoderar-se de textos que, muitas vezes, não são nem escritos, nem verbais.”","“Nas sociedades do mundo digital todos leem e sempre se lê, para comunicar, informar-se, jogar.”","“Se apropriam sobretudo dos textos breves das redes sociais.”"],"correta":3,"explicacao":"Gabarito: <strong>“Nas sociedades do mundo digital todos leem e sempre se lê, para comunicar, informar-se, jogar.”</strong>.","banca":"Intelectus","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":1501,"enunciado":"Sobre os componentes linguísticos do período transcrito a seguir, marque a alternativa com análise CORRETA. \"Como seres especiais, cuja personalidade, intelecto, caráter estão ainda em formação a tarefa de redirecioná-los e reeducá-los é mais branda e menos trabalhosa, as crianças e os adolescentes são mais suscetíveis em assimilar as ditas orientações\".","opcoes":["A organização do período enunciado comprova o uso da figura de linguagem denominada \"Hipérbato\".","No período, existem vários exemplos de comparações.","No período, temos exemplos de expressões incoerentes com o tema do texto.","A palavra dissílaba: mais faz antítese com muitos.","Os verbos: redirecioná-los e reeducá-los se identificam somente porque têm a mesma quantidade de sílabas e por serem oxítonos."],"correta":0,"explicacao":"Gabarito: <strong>A organização do período enunciado comprova o uso da figura de linguagem denominada \"Hipérbato\".</strong>.","banca":"IDCAP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":1567,"enunciado":"Apoie-se na ortoepia (“a parte da gramática que ensina as regras da boa pronúncia”) e nos aspectos fonéticos, a fim de analisar este excerto “A palavra coragem é muito interessante. Ela vem da raiz latina cor, que significa ‘coração’\" (l. 01) e aponte a alternativa CORRETA.","opcoes":["As palavras “coragem” e “coração” têm o mesmo número de grafemas e o mesmo número de fonemas.","Nos vocábulos “coragem”, “interessante” e “vem”, inexistem ditongos nasais.","Existem somente encontros consonânticos inseparáveis nesse trecho.","Computam-se, nesse fragmento textual, quatro dígrafos vocálicos."],"correta":0,"explicacao":"Gabarito: <strong>As palavras “coragem” e “coração” têm o mesmo número de grafemas e o mesmo número de fonemas.</strong>.","banca":"IMPARH","ano":2025,"temas_relacionados":["colocacaoPronominal","fonemas"]},{"id":1720,"enunciado":"Assinale a alternativa em que o emprego do acento indicativo de crase está CORRETO em todas as ocorrências.","opcoes":["À medida que a tecnologia avança, as pessoas se conectam cada vez mais à internet, buscando informações e diversão à qualquer hora e lugar.","Referindo-se àquele livro, o crítico literário destacou a importância da obra para a literatura brasileira, comparando-a à grandes clássicos da literatura universal.","À noite, costumava ir àquela praça, sentar-se em um banco e observar as pessoas que passavam, à procura de inspiração para seus poemas.","Vou à Paris no próximo mês e a expectativa é enorme! Já comecei à planejar os passeios e os lugares que quero conhecer, como a Torre Eiffel e o Museu do Louvre.","À partir de amanhã, as novas regras entrarão em vigor, e todos os funcionários deverão adaptar-se à elas, sob pena de serem advertidos."],"correta":2,"explicacao":"Gabarito: <strong>À noite, costumava ir àquela praça, sentar-se em um banco e observar as pessoas que passavam, à procura de inspiração para seus poemas.</strong>.","banca":"INAZ do Pará","ano":2024,"temas_relacionados":["colocacaoPronominal","crase"]},{"id":1788,"enunciado":"Nos termos “deteve-se” (3º§), “sentiu-lhe” (2º§) e “aferrar-se” (6º§), o hífen foi usado de modo a demarcar:","opcoes":["Sufixação.","Prefixação.","Translineação.","Ênclise pronominal."],"correta":3,"explicacao":"Gabarito: <strong>Ênclise pronominal.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal","hifen"]},{"id":1865,"enunciado":"Tendo em vista que o fenômeno da crase é indicado ortograficamente através do uso do acento grave, assinale a alternativa em que o seu uso é facultativo.","opcoes":["“Anne-Marie fez-me sentar à sua frente, em minha cadeirinha; [...]” (2º§)","A opinião popular muda à medida que se efetiva a leitura literária rotineira.","“[...] às vezes desapareciam antes que eu pudesse compreendê-las, [...]” (2º§)","“Quanto à história, endomingara-se: o lenhador, a lenhadora e suas filhas, a fada, todas essas criaturinhas, nossos semelhantes, [...]” (2º§)"],"correta":0,"explicacao":"Gabarito: <strong>“Anne-Marie fez-me sentar à sua frente, em minha cadeirinha; [...]” (2º§)</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal","ortografia","crase"]},{"id":1898,"enunciado":"O vocábulo “aí”, presente no texto, acentua-se graficamente pela mesma regra que a palavra:","opcoes":["“há”.","“usá-lo”.","“memória”,","“exercício”.","“saída”."],"correta":4,"explicacao":"Gabarito: <strong>“saída”.</strong>.","banca":"CONTEMAX","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":1916,"enunciado":"Analise a frase a seguir: \"Ao buscar uma solução para os desafios enfrentados na educação, é essencial que os educadores explorem o conteúdo de maneira abrangente, considerando que a única saída pode não ser encontrada até que se avaliem todas as possibilidades, e que não devemos nos limitar a uma abordagem só.\" Em relação às palavras acentuadas da frase, assinale a alternativa com a justificativa CORRETA:","opcoes":["até - acentuam-se as óxitonas terminadas em \"E\"","só - acentuam-se as óxitonas terminadas em \"O\"","conteúdo e saída: acentuam-se o \"i\" e \"u\" átonos quando formam hiato com a vogal anterior, estando eles sozinhos na sílaba ou acompanhados apenas de \"s\", desde que não sejam seguidos por \"-nh\".","única - acentuam-se as paróxitonas terminadas em \"A\""],"correta":0,"explicacao":"Gabarito: <strong>até - acentuam-se as óxitonas terminadas em \"E\"</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":1957,"enunciado":"A alternativa em que os vocábulos NÃO estão acentuados de forma correta é:","opcoes":["palavra – repórter.","êxodo – parabéns.","ritmo – atraí-lo.","redimí-la – hífen."],"correta":3,"explicacao":"Gabarito: <strong>redimí-la – hífen.</strong>.","banca":"MARANATHA Assessoria","ano":2024,"temas_relacionados":["colocacaoPronominal","hifen"]},{"id":2024,"enunciado":"\\[Questão Inédita] Ao longo da história, os povos indígenas contribuíram significativamente para as ciências aplicadas modernas, como a medicina, a biologia, a matemática, a engenharia e a agricultura. Muitas dessas contribuições, no entanto, são desconhecidas. No trecho acima, há um elo coesivo criado por meio da nominalização entre “contribuíram” e “contribuições”. Nas alternativas a seguir, busca-se o procedimento de retomada por meio de nominalização, mas só um mostra adequação. Assinale-o.","opcoes":["os povos indígenas fabricaram produtos (2º parágrafo) / Tal fabrico...","Para sobreviver e se adaptar a diversos ambientes (2º parágrafo) / Essa sobrevida e adaptação...","Muitos povos indígenas desenvolveram uma cultura de medicina (2º parágrafo) / Tal desenvoltura...","Os indígenas norte-americanos conseguiram extrair o ácido da casca dessa árvore (3º parágrafo) / Tal exclusão...","Os mexicas, descendentes dos astecas, colhiam o alimento (5º parágrafo) / Esse armazenamento..."],"correta":0,"explicacao":"Gabarito: <strong>os povos indígenas fabricaram produtos (2º parágrafo) / Tal fabrico...</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":2098,"enunciado":"Julgue o item subsequente.\nO c, com valor de oclusiva velar, das sequências interiores cc (segundo c com valor de sibilante), cç e ct, e o p das sequências interiores pc (c com valor de sibilante), pç e pt, ora se conservam, ora se eliminam. Assim, conservam-se nos casos em que são invariavelmente proferidos nas pronúncias cultas da língua: compacto, convicção, convicto, ficção, friccionar, pacto, pictural; adepto, apto, díptico, erupção, eucalipto, inepto, núpcias, rapto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2101,"enunciado":"Julgue o item a seguir.\nO c, com valor de oclusiva velar, das sequências interiores cc (segundo c com valor de sibilante), cç e ct, e o p das sequências interiores pc (c com valor de sibilante), pç e pt, ora se conservam, ora se eliminam. Assim, conservam-se nos casos em que são invariavelmente proferidos nas pronúncias cultas da língua: compacto, convicção, convicto, ficção, friccionar, pacto, pictural; adepto, apto, díptico, erupção, eucalipto, inepto, núpcias, rapto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2123,"enunciado":"\"o presidente George W. Bush ameaçou vetar projetos que fossem aprovados pelo Congresso americano, mas até agora ele nunca tinha cumprido a ameaça\"; nesse segmento do texto ocorre a substituição de um termo por um cognato. A alternativa em que a substituição NÃO ocorre com o mesmo tipo de cognato é:","opcoes":["O presidente criticou o Congresso, mas as críticas não surtiram efeito;","O ministro viajou para Paris e espera resolver o problema com a viagem;","A acusada diz arrepender-se, mas o arrependimento não comoveu o júri;","A candidata divorciou-se do Governo e espera que esse divórcio a auxilie na campanha;","A seleção trocou de patrocinador, mas a troca não ajudou seu futebol."],"correta":2,"explicacao":"Gabarito: <strong>A acusada diz arrepender-se, mas o arrependimento não comoveu o júri;</strong>.","banca":"NCE-UFRJ","ano":2006,"temas_relacionados":["colocacaoPronominal"]},{"id":2255,"enunciado":"A supressão da vírgula altera sobremaneira o sentido da frase:","opcoes":["Com a passagem do tempo, deixei de considerá-lo um inimigo meu.","Sempre estimei as crônicas, que nos fazem próximos da poesia do cotidiano.","Desde que passei a escrever, dedico boa parte do meu tempo às crônicas.","Como que surgindo do nada, um inseto acabou pousando em meu braço.","Quando conferi melhor as imagens do retrato, dei com uma foto antiga de minha mãe."],"correta":1,"explicacao":"Gabarito: <strong>Sempre estimei as crônicas, que nos fazem próximos da poesia do cotidiano.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2258,"enunciado":"Considerando a charge, analise as assertivas a seguir. I. O texto mobiliza conhecimentos extratextuais relacionados ao uso excessivo da internet e à dependência tecnológica contemporânea. II. O humor decorre parcialmente da inversão de expectativa entre problemas socialmente graves e um medo associado ao conforto digital. III. O emprego reiterado de perguntas no primeiro quadrinho contribui para a construção de uma progressão argumentativa. IV. A ausência de pontuação no segundo quadrinho compromete a coerência textual e impede a compreensão do efeito humorístico. Após análise, conclui-se que estão corretas:","opcoes":["I e IV.","II e III.","III e IV.","I, II e III.","I, II, III e IV."],"correta":3,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2306,"enunciado":"Assinale a alternativa INCORRETA no que se refere à pontuação, de acordo com a norma-padrão da Língua Portuguesa.","opcoes":["Os direitos subjetivos constitucionais, servem de fundamento lógico e jurídico para os outros direitos considerados de hierarquia inferior.","O conjunto de direitos individuais forma o patrimônio jurídico do indivíduo, o qual é completado por todos os demais direitos subjetivos que a pessoa adquire dentro da ordem jurídica.","A Administração Pública está sujeita aos deveres constitucionais como os demais administrados e, portanto, sujeita-se a uma interpelação judicial por via do exercício de uma prestação individual.","As normas constitucionais que criam direitos subjetivos são direta e imediatamente exigíveis tanto do Poder Público quanto do particular, por via de ações constitucionais e infraconstitucionais estabelecidas no ordenamento jurídico vigente.","Os Direitos Fundamentais Sociais, por serem normas constitucionais fundamentais e por conferirem ao indivíduo o poder de exigir, são em sua essência verdadeiros direitos públicos subjetivos."],"correta":0,"explicacao":"Gabarito: <strong>Os direitos subjetivos constitucionais, servem de fundamento lógico e jurídico para os outros direitos considerados de hierarquia inferior.</strong>.","banca":"Nosso Rumo","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2307,"enunciado":"Considerando a norma-padrão da Língua Portuguesa, assinale a alternativa correta","opcoes":["No trecho “Há, no campo de direito privado, normas cuja observância oferece grande interesse para a coletividade \\[…]”, há erro de pontuação. O correto seria “Há no campo de direito privado, normas cuja observância oferece grande interesse, para a coletividade \\[…]”.","No trecho “Vice-versa, não seria lícito contratar matrimônio por dois anos \\[…]”, há erro de ortografia. O correto seria “Vice versa, não seria lícito contratar matrimônio por dois anos \\[…]”.","No trecho “\\[…] não podem ser afastadas ainda que estejam de acordo em não aplicá-las todos os indivíduos mais diretamente interessados”, há erro de colocação pronominal. O correto seria “\\[…] não podem ser afastadas ainda que estejam de acordo em não as aplicar todos os indivíduos mais diretamente interessados”.","No trecho “\\[…] não é lícito obrigar-se num contrato de serviço por toda a vida, porque assim se anularia a liberdade individual \\[…]”, há erro ortográfico. O correto seria “\\[…] não é lícito obrigar-se em um contrato de serviço por toda a vida, por que assim se anularia a liberdade individual \\[…]”.","No trecho “\\[…] não podem ser afastadas ainda que estejam de acordo em não aplicá-las todos os indivíduos mais diretamente interessados \\[…]”, há um erro de regência nominal. O correto seria “\\[…] não podem ser afastadas ainda que estejam de acordo de não aplicá-las todos os indivíduos mais diretamente interessados \\[…]”."],"correta":2,"explicacao":"Gabarito: <strong>No trecho “\\[…] não podem ser afastadas ainda que estejam de acordo em não aplicá-las todos os indivíduos mais diretamente interessados”, há erro de colocação pronominal. O correto seria “\\[…] não podem ser afastadas ainda que estejam de acordo em não as aplicar todos os indivíduos mais diretamente interessados”.</strong>.","banca":"Nosso Rumo","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2311,"enunciado":"A norma-padrão de emprego da vírgula e de colocação pronominal foi respeitada em:","opcoes":["Nos dias atuais, não é raro que se ouça, em diferentes contextos e com muita frequência, a palavra “felicidade”.","Em alguns espaços, se defende que a utilização da palavra “felicidade”, nos meios de comunicação, vem aumentando.","Não existiam, nas décadas passadas, muitas das ideias que hoje divulgam-se acerca do que se entende por felicidade.","Frequentemente se aborda, sob diversos aspectos a questão da felicidade, e daquilo que se deve fazer para alcançá-la.","Há pesquisadores, que têm-se dedicado, a pesquisas sobre as transformações pelas quais passa a noção de felicidade."],"correta":0,"explicacao":"Gabarito: <strong>Nos dias atuais, não é raro que se ouça, em diferentes contextos e com muita frequência, a palavra “felicidade”.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2312,"enunciado":"Em “É uma noção que nos parece e soa tão familiar que já nem pensamos nela ‒ seria estranho ousar questioná-la.” (1º parágrafo), o travessão pode ser substituído, sem prejuízo ao sentido original, por","opcoes":["ao passo que.","já que.","portanto.","contudo.","não obstante."],"correta":2,"explicacao":"Gabarito: <strong>portanto.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2319,"enunciado":"“Entre as causas de morte prematura estão a violência e acidentes de trânsito, além de doenças cardiovasculares.” (3º parágrafo). Outra maneira de se reescrever o período acima, observando-se as normas de pontuação, é:","opcoes":["Além de doenças cardiovasculares, entre as causas de morte prematura, estão a violência e acidentes de trânsito.","Entre as causas de morte prematura, estão além de doenças cardiovasculares, a violência e acidentes de trânsito.","A violência e acidentes de trânsito, além de doenças cardiovasculares estão, entre as causas de morte prematura.","Além de doenças cardiovasculares — entre as causas de morte prematura —, estão a violência e acidentes de trânsito."],"correta":0,"explicacao":"Gabarito: <strong>Além de doenças cardiovasculares, entre as causas de morte prematura, estão a violência e acidentes de trânsito.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2327,"enunciado":"A norma-padrão de emprego da vírgula e de colocação pronominal foi respeitada em:","opcoes":["Nos dias atuais, não é raro que se ouça, em diferentes contextos e com muita frequência, a palavra “felicidade”.","Em alguns espaços, se defende que a utilização da palavra “felicidade”, nos meios de comunicação, vem aumentando.","Não existiam, nas décadas passadas, muitas das ideias que hoje divulgam-se acerca do que se entende por felicidade.","Frequentemente se aborda, sob diversos aspectos a questão da felicidade, e daquilo que se deve fazer para alcançá-la.","&#x20;Há pesquisadores, que têm-se dedicado, a pesquisas sobre as transformações pelas quais passa a noção de felicidade."],"correta":0,"explicacao":"Gabarito: <strong>Nos dias atuais, não é raro que se ouça, em diferentes contextos e com muita frequência, a palavra “felicidade”.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2328,"enunciado":"Em “É uma noção que nos parece e soa tão familiar que já nem pensamos nela ‒ seria estranho ousar questioná-la.” (1º parágrafo), o travessão pode ser substituído, sem prejuízo ao sentido original, por","opcoes":["ao passo que.","&#x20;já que.","portanto.","&#x20;contudo.","&#x20;não obstante."],"correta":2,"explicacao":"Gabarito: <strong>portanto.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2377,"enunciado":"Julgue o seguinte item, referente às estruturas linguísticas e ao vocabulário empregados no texto CG7A1.\nNo trecho \"torna-se indispensável conciliar o crescimento econômico e o desenvolvimento social com a defesa e a proteção do meio ambiente\" (terceiro parágrafo), a inserção de vírgula logo após \"social\" prejudicaria a correção gramatical do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2431,"enunciado":"No fragmento “Peço-lhes desculpas – e prometo silêncio.” (2º§), o travessão tem como propósito:","opcoes":["Enfatizar uma elucidação.","Manifestar o ponto de vista do leitor.","Sugerir prolongamento de uma ideia.","Interromper o pensamento do cronista."],"correta":0,"explicacao":"Gabarito: <strong>Enfatizar uma elucidação.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":2520,"enunciado":"Assinale a alternativa em que a reescrita do trecho “As pessoas, muitas vezes, se comunicam pela internet \\[...]”, do Texto 1, preserva a correção gramatical e o sentido original.","opcoes":["Muitas vezes as pessoas, se comunicam pela internet.","&#x20;As pessoas se comunicam, pela internet muitas vezes.","Muitas vezes as pessoas comunicam-se, pela internet.","Muitas vezes, as pessoas comunicam-se pela internet.","As pessoas, se comunicam, muitas vezes, pela internet."],"correta":3,"explicacao":"Gabarito: <strong>Muitas vezes, as pessoas comunicam-se pela internet.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":2528,"enunciado":"Assinale a alternativa correta, considerando-se a norma culta.","opcoes":["A Biblioteca Pública, será enfim restaurada, dizem os técnicos da prefeitura","As rúbricas não eram de Giovani.","Custei a entender quem era o rapaz sobre o qual falavam.","Todos aqueles que passaram no concurso têm sessenta dias para providenciar a documentação exigida pela Prefeitura."],"correta":3,"explicacao":"Gabarito: <strong>Todos aqueles que passaram no concurso têm sessenta dias para providenciar a documentação exigida pela Prefeitura.</strong>.","banca":"Instituto Unique","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":2535,"enunciado":"A supressão da vírgula altera sobremaneira o sentido da frase:","opcoes":["Com a passagem do tempo, deixei de considerá-lo um inimigo meu.","Sempre estimei as crônicas, que nos fazem próximos da poesia do cotidiano.","Desde que passei a escrever, dedico boa parte do meu tempo às crônicas.","Como que surgido do nada, um inseto acabou pousando em meu braço.","Quando conferi melhor as imagens do retrato, dei com uma foto antiga de minha mãe."],"correta":1,"explicacao":"Gabarito: <strong>Sempre estimei as crônicas, que nos fazem próximos da poesia do cotidiano.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2536,"enunciado":"A supressão da vírgula altera sobremaneira o sentido da frase:","opcoes":["Desde que passei a escrever, dedico boa parte do meu tempo às crônicas.","Como que surgindo do nada, um inseto acabou pousando em meu braço.","Quando conferi melhor as imagens do retrato, dei com uma foto antiga de minha mãe.","Com a passagem do tempo, deixei de considerá-lo um inimigo meu.","Sempre estive às voltas com insetos, que não fazem próximos da poesia do cotidiano."],"correta":4,"explicacao":"Gabarito: <strong>Sempre estive às voltas com insetos, que não fazem próximos da poesia do cotidiano.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2614,"enunciado":"Assinale a alternativa em que o emprego da(s) vírgula(s) ocorre pelo mesmo motivo que no trecho a seguir, retirado do Texto 1: “Desde que esses aparelhos eletrônicos passaram a entrar nas salas de aula, Garofalo defende que eles podem ser aliados.”.","opcoes":["“O uso excessivo desses dispositivos, sem acompanhamento, pode comprometer a aprendizagem.”.","“\\[…] ao acessar uma rede social ou realizar uma pesquisa, há mecanismos que influenciam os resultados obtidos.”.","“Nesse contexto, torna-se necessário educar para o uso desses recursos.”.","“O estudante precisa compreender, por exemplo, que há mecanismos que influenciam os resultados.”","“Não adianta também a escola proibir, e os pais continuarem permitindo o uso.”"],"correta":1,"explicacao":"Gabarito: <strong>“\\[…] ao acessar uma rede social ou realizar uma pesquisa, há mecanismos que influenciam os resultados obtidos.”.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2935,"enunciado":"A ortografia oficial da língua portuguesa organiza-se por princípios convencionais que procuram conciliar tradição, sistematização gráfica e critérios fonológicos compartilhados entre países lusófonos. Alterações normativas visam ajustar a escrita sem modificar o funcionamento estrutural da língua (BRASIL, 2009). Considerando as disposições do Acordo Ortográfico em vigor, assinale a alternativa CORRETA.","opcoes":["Emprega-se hífen quando o prefixo termina em vogal e o segundo elemento se inicia pela mesma vogal, como em \"anti-inflamatório\" e \"micro-ondas\".","O acento nos ditongos abertos \"éi\" e \"ói\" foi suprimido em todas as ocorrências, inclusive em palavras oxítonas e monossílabos tônicos.","O uso do hífen tornou-se facultativo em compostos consagrados pelo uso, independentemente da presença de prefixo ou da estrutura morfológica do termo.","Conservam-se obrigatoriamente as consoantes etimológicas nos vocábulos derivados, ainda que não sejam pronunciadas na variedade culta brasileira contemporânea.","Mantém-se o acento diferencial em pares homógrafos sempre que houver possibilidade de dupla interpretação semântica no enunciado."],"correta":0,"explicacao":"Gabarito: <strong>Emprega-se hífen quando o prefixo termina em vogal e o segundo elemento se inicia pela mesma vogal, como em \"anti-inflamatório\" e \"micro-ondas\".</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["colocacaoPronominal","ortografia","hifen"]},{"id":2940,"enunciado":"Leia o trecho a seguir. \"Ao longo de 75 anos, o CNPq consolidou-se como um dos pilares do sistema nacional de ciência e tecnologia. Milhares de estudantes foram formados por meio de suas bolsas, da iniciação científica ao pós-doutorado, e gerações de pesquisadores tiveram suas trajetórias viabilizadas pela agência, contribuindo para a expansão e qualificação da produção científica brasileira\". De acordo com o trecho, avalie as assertivas que se seguem em relação às normas gramaticais vigentes. I.O segmento \"Milhares de estudantes foram formados por meio de suas bolsas\" encontra-se na voz passiva sintética, o que confere, semanticamente, mais ênfase ao fato do que ao agente que pratica a ação. II.No termo \"pós-doutorado\", o emprego do hífen se justifica pelo fato de o elemento \"pós-\" ser tônico e apresentar autonomia fonológica, mantendo-se, por isso, separado por hífen do elemento seguinte. III.A forma verbal \"tiveram\" encontra-se flexionado na terceira pessoa do plural uma vez que concorda com núcleo do seu sujeito \"pesquisadores\". IV.As palavras \"Milhares\", \"pesquisadores\", \"agência\" e \"qualificação\" apresentam todas mais letras do que fonemas. Acerca das assertivas acima, assinale a alternativa CORRETA.","opcoes":["Apenas três estão corretas.","Todas as quatro estão incorretas.","Todas as quatro estão corretas.","Apenas uma está correta.","Apenas duas estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>Apenas uma está correta.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["colocacaoPronominal","fonemas","hifen"]},{"id":2964,"enunciado":"\\[Questão Inédita] Assinale a alternativa com a informação correta.","opcoes":["As palavras contribuíram, raízes, combustível, saúde e proteínas recebem acento gráfico em razão de uma mesma regra.","Em “Muitas dessas contribuições, no entanto, são desconhecidas”, a expressão “no entanto” pode ser substituída pela conjunção adversativa “mas” sem que se altere o sentido nem produza falha gramatical.","Em “era um alimento básico na era pré-colombiana” (5º parágrafo), observa-se a palavra “era” (com o mesmo som e grafia), mas em funções diferentes. Esse mesmo fenômeno ocorre na frase “Eu jogo o jogo”.","Em “como a medicina, a biologia, a matemática, a engenharia e a agricultura”, caso se troque a conjunção “e” por uma vírgula, perde-se a indicação de último elemento da enumeração, ou seja, do fechamento dos itens enumerados, e cria-se com a mudança a impressão de que mais elementos poderiam ser acrescentados.","Nos trechos “indígenas norte-americanos” e “era pré-colombiana”, observa-se uma mesma regra no uso do hífen para ambas as formações."],"correta":3,"explicacao":"Gabarito: <strong>Em “como a medicina, a biologia, a matemática, a engenharia e a agricultura”, caso se troque a conjunção “e” por uma vírgula, perde-se a indicação de último elemento da enumeração, ou seja, do fechamento dos itens enumerados, e cria-se com a mudança a impressão de que mais elementos poderiam ser acrescentados.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":2979,"enunciado":"Considerando a ortografia das palavras em Língua Portuguesa, assinale a alternativa que preenche, correta e respectivamente, as lacunas tracejadas nas linhas 23, 27 e 35.","opcoes":["auto-sacrifício – Trata-se – bem viver","autossacrifício – Trata-se – bem-viver","auto-sacrifício – Tratasse – bem viver","autossacrifício – Tratasse – bem-viver","autosacrifício – Trata-se – bem-viver"],"correta":1,"explicacao":"Gabarito: <strong>autossacrifício – Trata-se – bem-viver</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["colocacaoPronominal","ortografia"]},{"id":2993,"enunciado":"Conhecimentos sobre aspectos morfossintáticos e/ou ortográficos da língua portuguesa são fundamentais para uma boa compreensão da estrutura do idioma. Sobre eles, é possível afirmar que, na tirinha,","opcoes":["a utilização de hífen na palavra “bem-estar”, no terceiro quadrinho, justifica-se porque o prefixo “bem” sempre é utilizado com hífen, exceto em compostos nos quais “bem” aglutina-se com o segundo elemento.","no período “deviam dar casa, trabalho, proteção e bem-estar aos pobres”, no terceiro quadrinho, há a presença de um sujeito desinencial.","o uso da ênclise em “escondê-los”, no quarto quadrinho, justifica-se porque a oração está em ordem inversa, iniciando pelo objeto direto.","no período “Quando eu vejo um pobre fico com o coração apertado”, no segundo quadrinho, há uma oração subordinada substantiva subjetiva."],"correta":0,"explicacao":"Gabarito: <strong>a utilização de hífen na palavra “bem-estar”, no terceiro quadrinho, justifica-se porque o prefixo “bem” sempre é utilizado com hífen, exceto em compostos nos quais “bem” aglutina-se com o segundo elemento.</strong>.","banca":"IF Sul Rio-Grandense","ano":2025,"temas_relacionados":["colocacaoPronominal","hifen"]},{"id":2995,"enunciado":"Analise o trecho abaixo, retirado do texto: “O cenário sombrio que se vislumbrava em 2024 não se confirmou, devido ao conjunto de providências tomadas para reverter a epidemia”. Em relação à colocação pronominal, assinale a alternativa que indica, correta e respectivamente, a obrigatoriedade do uso da próclise nos casos destacados acima.","opcoes":["Obrigatório – obrigatório.","Obrigatório – facultativo.","Facultativo – obrigatório.","Facultativo – facultativo."],"correta":0,"explicacao":"Gabarito: <strong>Obrigatório – obrigatório.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":2997,"enunciado":"\"O estudo também aponta que mais da metade das escolas (54,8%) nunca realizou um diagnóstico estruturado do clima escolar, etapa considerada essencial para orientar políticas de convivência e aprendizagem.\" Com base nas regras de colocação pronominal, considerando a substituição do complemento do verbo 'realizar' por um pronome oblíquo átono, analise as afirmativas a seguir e assinale a alternativa correta.","opcoes":["As formas 'nunca realizou-o' ou 'nunca o realizou\" serão igualmente corretas, uma vez que, na norma culta, quando o verbo está no infinitivo, pode ocorrer as duas formas de colocação, independentemente da presença de palavras atrativas.","A forma 'nunca realizar-lo-ia' será a adequada, pois a substituição do objeto direto por pronome oblíquo em orações com advérbio negativo exige obrigatoriamente a mesóclise, forma canônica de colocação pronominal na norma culta formal.","A forma 'nunca realizou-o' será a mais adequada, pois o pronome oblíquo deve ser posicionado após o verbo quando este se encontra no pretérito perfeito do indicativo, tempo verbal que favorece a ênclise independentemente da presença de palavras atrativas.","A forma 'nunca o realizou' será a correta, pois o advérbio de sentido negativo 'nunca' funciona como palavra atrativa, determinando obrigatoriamente a próclise e tornando incorreta qualquer construção com o pronome posposto ao verbo."],"correta":3,"explicacao":"Gabarito: <strong>A forma 'nunca o realizou' será a correta, pois o advérbio de sentido negativo 'nunca' funciona como palavra atrativa, determinando obrigatoriamente a próclise e tornando incorreta qualquer construção com o pronome posposto ao verbo.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3001,"enunciado":"\"O tombamento traz um aspecto muito importante porque a política do patrimônio cria uma camada a mais de proteção para essas comunidades, argumentou. \" Com base nas regras de colocação pronominal, marque com V as afirmativas verdadeiras ou com F as falsas. (__) A substituição do complemento do verbo 'trazer' por pronome oblíquo átono admite, nesse contexto, tanto a próclise quanto a ênclise, visto que não há fator de atração que imponha determinada colocação pronominal. (__) Mesmo que se acrescentasse uma palavra atrativa, como em 'O tombamento não traz...', a ênclise permaneceria permitida, pois quando o verbo está no infinitivo, a ênclise é permitida mesmo na presença de elementos atrativos, embora a próclise seja a colocação preferencial. (__) A substituição do complemento por pronome oblíquo enclítico constrói-se na forma 'O tombamento trá-lo', estrutura gramaticalmente correta decorrente da supressão da consoante final do verbo e da adaptação morfológica exigida pela colocação pronominal. Assinale a alternativa que apresenta a sequência que preenche corretamente os itens acima, de cima para baixo. (__) A reescrita 'porque a política do patrimônio lhes cria uma camada a mais de proteção' está de acordo com a norma-padrão, uma vez que o pronome pode ser colocado antes do verbo sem violação das regras de colocação pronominal. Assinale a alternativa que apresenta a sequência que preenche corretamente os itens acima, de cima para baixo.","opcoes":["F, V, V, F.","V, V, V, V.","F, V, F, F.","V, F, V, V."],"correta":3,"explicacao":"Gabarito: <strong>V, F, V, V.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3004,"enunciado":"Assinale a alternativa que apresenta um exemplo de colocação pronominal em mesóclise.","opcoes":["Roberto, olhe dentro dos meus olhos e não me diga mentiras.","A declaração de utilidade pública far-se-á por decreto do Presidente da República.","Deram-lhe os parabéns, afinal, a equipe toda estava contente pela conquista de Ana.","Amar-te foi a escolha mais genuína que já tomei.","Na sexta, assistiram à obra de Alfred Hitchcock. Ninguém se arrependeu da escolha."],"correta":1,"explicacao":"Gabarito: <strong>A declaração de utilidade pública far-se-á por decreto do Presidente da República.</strong>.","banca":"Nosso Rumo","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3008,"enunciado":"Com base nas regras de colocação pronominal da Língua Portuguesa, indique a única alternativa que apresenta a justificativa correta para a forma como os pronomes foram utilizados no trecho fornecido.","opcoes":["No trecho “antes que a migração para o próximo patamar se torne...” (2º parágrafo), o emprego da próclise do pronome “se” é facultativo, uma vez que há um sujeito substantivo intercalado entre o atrator e o verbo.","Na passagem “o que se observa são testes controlados...” (3º parágrafo), a utilização do pronome em posição enclítica (“observa-se”) seria a opção recomendada para conferir maior formalidade ao registro jornalístico.","No segmento “antes que a migração para o próximo patamar se torne...” (2º parágrafo), a posição do pronome justifica-se pela força atrativa da conjunção subordinativa “que”, a qual exige a ocorrência de próclise.","No trecho “o que se observa são testes controlados...” (3º parágrafo), a mesóclise seria a forma de colocação pronominal exigida pela norma culta, visto que o verbo “observar” se encontra flexionado no presente do indicativo."],"correta":2,"explicacao":"Gabarito: <strong>No segmento “antes que a migração para o próximo patamar se torne...” (2º parágrafo), a posição do pronome justifica-se pela força atrativa da conjunção subordinativa “que”, a qual exige a ocorrência de próclise.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3010,"enunciado":"Observe o trecho: “...mais de 140 milhões de pessoas se conectaram à internet entre março e agosto de 2024...”. Considerando as normas da colocação pronominal na variedade padrão da língua portuguesa, assinale a alternativa correta.","opcoes":["A próclise em “se conectaram” encontra respaldo na organização sintática do período, sendo admitida pela norma culta contemporânea da língua.","A construção “conectaram-se” configuraria desvio de colocação pronominal, pois a posição enclítica comprometeria a fluidez sintática do trecho.","A estrutura “se conectaram” ocorre por exigência do verbo pronominal, razão pela qual a posição pós-verbal produziria inadequação gramatical.","A forma “conectaram-se” alteraria o valor semântico do período, pois deslocaria o foco informacional originalmente atribuído ao sujeito oracional."],"correta":0,"explicacao":"Gabarito: <strong>A próclise em “se conectaram” encontra respaldo na organização sintática do período, sendo admitida pela norma culta contemporânea da língua.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3011,"enunciado":"Sobre a colocação pronominal e as vozes verbais no parágrafo anterior, analise a frase “Esse processo educativo consolida-se por meio do diálogo[...]” e assinale a alternativa correta.","opcoes":["A construção está na voz passiva analítica, indicando que o processo educativo sofre a ação de ser consolidado pelo diálogo constante.","O pronome oblíquo “se” encontra-se em posição de ênclise devido à ausência de termos atrativos que exijam a próclise na oração.","A substituição de “consolida-se” por “se consolida” seria obrigatória caso o período fosse iniciado pelo pronome demonstrativo “esse” no plural.","O verbo “consolidar” apresenta-se na voz reflexiva, sugerindo que o processo educativo realiza e sofre a ação de fortalecer a si mesmo."],"correta":1,"explicacao":"Gabarito: <strong>O pronome oblíquo “se” encontra-se em posição de ênclise devido à ausência de termos atrativos que exijam a próclise na oração.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3013,"enunciado":"Quanto à colocação pronominal, assinale a alternativa em que não há erro.","opcoes":["A testemunha não calou-se sobre o ocorrido.","O pedido era absurdo, motivo pelo qual negou-se a deferi-lo.","Durante a audiência de conciliação, o réu disse ao autor que jamais causou-lhe dano.","As testemunhas chegaram cedo ao fórum. Quando as viu, o réu sentiu-se envergonhado.","O advogado arguiu a testemunha: \"Ainda lembra-se do que houve no dia da morte da vítima?\""],"correta":3,"explicacao":"Gabarito: <strong>As testemunhas chegaram cedo ao fórum. Quando as viu, o réu sentiu-se envergonhado.</strong>.","banca":"TJ-MG","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3015,"enunciado":"Em conformidade com a norma-padrão, as lacunas do 1º quadrinho devem ser preenchidas, respectivamente, com:","opcoes":["de que ... ter-lhe levado","que ... ter levado ela","de que ... tê-la levado","que ... ter levado-a","de que ... ter levado-lhe"],"correta":2,"explicacao":"Gabarito: <strong>de que ... tê-la levado</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3016,"enunciado":"Assinale a alternativa que atende à norma-padrão de colocação pronominal.","opcoes":["Parece que a fiscalização ao uso de pesticidas e a punição aos infratores têm mostrado-se insuficientes.","O agronegócio impulsiona a economia, mas não pode-se colocar em risco a saúde da população.","Com a pulverização aérea, evidenciaria-se que os pesticidas alcançam áreas muito afastadas de sua aplicação.","O estudo mapeou pesticidas que usam-se no combate a mosquitos transmissores de doenças.","Afirma-se, no estudo, que é “provável” a presença generalizada de pesticidas no ar de cidades interioranas."],"correta":4,"explicacao":"Gabarito: <strong>Afirma-se, no estudo, que é “provável” a presença generalizada de pesticidas no ar de cidades interioranas.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3018,"enunciado":"A colocação pronominal diz respeito ao posicionamento sintático dos pronomes oblíquos átonos em relação ao verbo que os rege, fenômeno que se manifesta em três possibilidades — próclise, mesóclise e ênclise —, cada qual condicionada por fatores linguísticos específicos, como a presença de palavras atrativas, a natureza do verbo e o registro de linguagem empregado. Considerando o emprego de acordo com a norma-padrão, identifique a alternativa incorreta.","opcoes":["Em locuções verbais formadas por verbo auxiliar seguido de particípio, admite-se duas possibilidades de colocação pronominal: a próclise ao particípio, como em 'Eu tenho lhe falado' e a ênclise ao particípio, como em 'Eu tenho falado-lhe'.","Não se pospõe ou intercala pronome átono a verbo flexionado em oração iniciada por palavra interrogativa ou exclamativa, como em 'Como perseguem-te!', construção gramaticalmente incorreta.","Em locuções verbais, a colocação pronominal admite mais de uma possibilidade sintática, sendo igualmente corretas as construções 'Você me há de ajudar', 'Você há de ajudar-me' e 'Você há de me ajudar'.","Com os infinitivos, próclise e ênclise são válidas, embora haja tendência para esta colocação pronominal, como em 'cantigas para me embalar' e 'Para não fitá-lo, deixei cair os olhos'."],"correta":0,"explicacao":"Gabarito: <strong>Em locuções verbais formadas por verbo auxiliar seguido de particípio, admite-se duas possibilidades de colocação pronominal: a próclise ao particípio, como em 'Eu tenho lhe falado' e a ênclise ao particípio, como em 'Eu tenho falado-lhe'.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3019,"enunciado":"Assinale a alternativa em que a ênclise pronominal segue a mesma regra que a justifica no trecho “estava sendo impedido de distribuí-la de graça” (linhas 18-19).","opcoes":["É necessário ajudá-lo na conclusão do relatório.","Respeitam-na por sua trajetória profissional.","O professor explicou a teoria, ilustrando-a com exemplos práticos.","Digo-lhe com toda a franqueza que o prazo é curto.","Caso aceite a proposta, assine-a e envie o documento por e-mail."],"correta":0,"explicacao":"Gabarito: <strong>É necessário ajudá-lo na conclusão do relatório.</strong>.","banca":"Ibest","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3021,"enunciado":"Analise atentamente as alternativas a seguir e identifique aquela em que há emprego de mesóclise.","opcoes":["Não me informaram sobre a alteração do cronograma prevista para o projeto acadêmico.","Entregar-lhe-ei os documentos solicitados após a conclusão da análise técnica realizada.","Quando te comunicaram a mudança de local do evento organizado pela instituição?","Os alunos apresentaram-se no horário estabelecido para a realização da prova final."],"correta":1,"explicacao":"Gabarito: <strong>Entregar-lhe-ei os documentos solicitados após a conclusão da análise técnica realizada.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3023,"enunciado":"Leia atentamente as afirmativas abaixo: I.Nunca me informaram os motivos que justificaram a suspensão do procedimento administrativo. II.Conforme lhe expliquei anteriormente, os documentos serão encaminhados ainda nesta semana. III.Entregaram-me os resultados da auditoria durante a reunião extraordinária do conselho. IV.Talvez se confirmem as irregularidades apontadas pelo relatório técnico apresentado ontem. V.Orgulhar-me-ei das contribuições acadêmicas desenvolvidas pelos pesquisadores da instituição. Identifique em quais afirmativas há emprego somente de próclise quanto a colocação pronominal.","opcoes":["I, II e IV.","II, III e V.","I, III e IV.","II, IV e V."],"correta":0,"explicacao":"Gabarito: <strong>I, II e IV.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3027,"enunciado":"\"Observei todo tipo maravilhoso de comportamento social e, aos poucos, percebi que também estava sentindo algo um tanto estranho, algo pulsante no ar.\" Com base nas regras de colocação pronominal, caso o complemento do verbo 'observar' seja substituído por um pronome oblíquo átono, assinale a alternativa em que a forma correta de colocação pronominal seja respeitada.","opcoes":["Observei-no e, aos poucos, percebi que também estava sentindo algo um tanto estranho, algo pulsante no ar.","Observei-lhe e, aos poucos, percebi que também estava sentindo algo um tanto estranho, algo pulsante no ar.","Observei-o e, aos poucos, percebi que também estava sentindo algo um tanto estranho, algo pulsante no ar.","Observei-lhes e, aos poucos, percebi que também estava sentindo algo um tanto estranho, algo pulsante no ar."],"correta":2,"explicacao":"Gabarito: <strong>Observei-o e, aos poucos, percebi que também estava sentindo algo um tanto estranho, algo pulsante no ar.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3028,"enunciado":"Analise as afirmativas a seguir com atenção às normas de colocação pronominal. Em seguida, identifique aquela em que ocorre corretamente o emprego de ênclise:","opcoes":["Talvez lhe informem os resultados finais do processo seletivo ainda nesta semana.","Não me disseram a verdade sobre o ocorrido durante a reunião administrativa.","Entregaram-me os documentos solicitados após o encerramento do expediente.","Quando te avisaram sobre a mudança de horário prevista para a próxima semana?"],"correta":2,"explicacao":"Gabarito: <strong>Entregaram-me os documentos solicitados após o encerramento do expediente.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3029,"enunciado":"Considere as regras de colocação pronominal na norma culta da língua portuguesa, que determinam a posição dos pronomes oblíquos átonos em relação ao verbo. Analise atentamente os exemplos apresentados e observe o contexto de uso em cada construção. Em seguida, estabeleça a correspondência correta entre as orações e o tipo de colocação pronominal empregado. Coluna 01: (_)Não me informaram sobre a alteração do cronograma prevista para o projeto. (_)Entregar-lhe-ei os relatórios solicitados assim que finalizar a análise técnica. (_)Convidaram-me para participar do evento acadêmico realizado na universidade. (_)Quando te avisaram sobre a mudança no regulamento interno da instituição? (_)Prometeram-se a ajudá-los durante a execução das atividades propostas. Coluna 02: I.Próclise. II.Mesóclise. III.Ênclise. Correlacione as colunas e assinale a alternativa com a sequência correta:","opcoes":["I, II, I, III, II.","II, I, I, III, III.","I, III, II, I, II.","I, II, III, I, III."],"correta":3,"explicacao":"Gabarito: <strong>I, II, III, I, III.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3033,"enunciado":"A colocação pronominal na língua portuguesa depende de fatores sintáticos e estilísticos que determinam a posição do pronome oblíquo em relação ao verbo. O reconhecimento dessas estruturas exige atenção às regras gramaticais e ao contexto da oração. Considerando as normas da colocação pronominal na língua portuguesa, assinale a alternativa em que há emprego de ênclise.","opcoes":["Nunca me comunicaram os critérios utilizados na avaliação final do projeto acadêmico.","Talvez lhe enviem os documentos complementares antes da reunião administrativa prevista.","Entregaram-me os pareceres técnicos durante a sessão extraordinária do conselho universitário.","Quando se discutirem os resultados da pesquisa, novos encaminhamentos serão apresentados."],"correta":2,"explicacao":"Gabarito: <strong>Entregaram-me os pareceres técnicos durante a sessão extraordinária do conselho universitário.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3037,"enunciado":"Considerando a norma-padrão da Língua Portuguesa, assinale a alternativa correta","opcoes":["No trecho “Há, no campo de direito privado, normas cuja observância oferece grande interesse para a coletividade […]”, há erro de pontuação. O correto seria “Há no campo de direito privado, normas cuja observância oferece grande interesse, para a coletividade […]”.","No trecho “Vice-versa, não seria lícito contratar matrimônio por dois anos […]”, há erro de ortografia. O correto seria “Vice versa, não seria lícito contratar matrimônio por dois anos […]”.","No trecho “[…] não podem ser afastadas ainda que estejam de acordo em não aplicá-las todos os indivíduos mais diretamente interessados”, há erro de colocação pronominal. O correto seria “[…] não podem ser afastadas ainda que estejam de acordo em não as aplicar todos os indivíduos mais diretamente interessados”.","No trecho “[…] não é lícito obrigar-se num contrato de serviço por toda a vida, porque assim se anularia a liberdade individual […]”, há erro ortográfico. O correto seria “[…] não é lícito obrigar-se em um contrato de serviço por toda a vida, por que assim se anularia a liberdade individual […]”.","No trecho “[…] não podem ser afastadas ainda que estejam de acordo em não aplicá-las todos os indivíduos mais diretamente interessados […]”, há um erro de regência nominal. O correto seria “[…] não podem ser afastadas ainda que estejam de acordo de não aplicá-las todos os indivíduos mais diretamente interessados […]”."],"correta":2,"explicacao":"Gabarito: <strong>No trecho “[…] não podem ser afastadas ainda que estejam de acordo em não aplicá-las todos os indivíduos mais diretamente interessados”, há erro de colocação pronominal. O correto seria “[…] não podem ser afastadas ainda que estejam de acordo em não as aplicar todos os indivíduos mais diretamente interessados”.</strong>.","banca":"Nosso Rumo","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3041,"enunciado":"Acerca dos sentidos e de aspectos linguísticos do texto CG6A1, julgue o item que se segue. No trecho \"Trata-se, em última análise, de reconhecer que o exercício contemporâneo da fiscalização depende de agentes públicos dotados de letramento digital específico\" (terceiro parágrafo), é obrigatória a ênclise do pronome átono em \"Trata-se\".\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3043,"enunciado":"Nessas unidades, o monitoramento ocorrerá em tempo real com uso de inteligência artificial para apoiar a regulação de leitos e a tomada de decisões clínicas. Considerando as regras de colocação pronominal da norma culta da língua portuguesa, assinale a alternativa que indica a forma correta de substituir o objeto direto do verbo 'apoiar' por pronome oblíquo átono, com a justificativa adequada.","opcoes":["A colocação pronominal enclítica ou proclítica é permitida na ausência de palavras atrativas; todavia, a partícula negativa 'não' torna obrigatória a próclise também no infinitivo, sendo 'para não as apoiar' a única forma admitida.","A colocação pronominal enclítica ou proclítica permanece facultativa mesmo com a inserção da partícula negativa 'não': 'para não apoiá-las' ou 'para não as apoiar'.","A ênclise constitui a colocação pronominal padrão no infinitivo preposicionado; contudo, a intercalação da partícula negativa 'não' entre a preposição e o verbo altera esse padrão.","A colocação pronominal deixa de ser facultativa com a inserção da preposição 'para', pois esta, ao se posicionar antes do verbo, rompe a unidade sintática que sustentava a ênclise, tornando a próclise a única colocação gramaticalmente admissível."],"correta":1,"explicacao":"Gabarito: <strong>A colocação pronominal enclítica ou proclítica permanece facultativa mesmo com a inserção da partícula negativa 'não': 'para não apoiá-las' ou 'para não as apoiar'.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3044,"enunciado":"Assinale a alternativa cujo posicionamento do pronome destacado atende à norma-padrão da Língua Portuguesa.","opcoes":["Queira o universo que você destaque-se.","Nos esclareça uma questão, por favor.","Imploro que avise-me sobre o show.","Jamais me impeçam de cantar.","Não queira-me tanto mal."],"correta":3,"explicacao":"Gabarito: <strong>Jamais me impeçam de cantar.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3045,"enunciado":"A frase \"Ela me disse que ele iria ao parque\" contém uma construção de colocação pronominal. Qual das alternativas abaixo apresenta uma construção mais coloquial?","opcoes":["Me disse ela que ele iria ao parque.","Ela disse-me que ele iria ao parque.","Ela disse que iria ao parque me.","Ela disse que ele iria ao parque a mim.","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>Me disse ela que ele iria ao parque.</strong>.","banca":"IDHTEC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3046,"enunciado":"\"Os especialistas observaram a ponta do fungo — conhecida tecnicamente como estroma, ou corpo de frutificação — no chão da floresta e, com a ajuda de um canivete, Araújo escavou a área ao redor para retirá-lo por inteiro.\" Considerando as regras de colocação pronominal, analise as afirmativas a seguir: I. A forma pronominal '-lo', em 'retirá-lo', está empregada corretamente em ênclise, uma vez que, com verbos no infinitivo, essa colocação é permitida. II. Caso fosse incluído o advérbio 'não' antes do verbo 'retirar', ocorreria a próclise obrigatoriamente, uma vez que o advérbio 'não' é fator de atração do pronome átono. III. Substituindo a expressão 'ponta do fungo' por um pronome oblíquo átono, obtém-se a forma 'observaram-na', corretamente empregada em ênclise. IV. Substituindo o termo 'a área' em 'escavou a área' por um pronome oblíquo, obtém-se a forma 'escavou-lhe', corretamente empregada em ênclise. É correto o que se afirma em:","opcoes":["I, II e III apenas.","II e IV apenas.","II e III apenas.","I e III apenas."],"correta":3,"explicacao":"Gabarito: <strong>I e III apenas.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3049,"enunciado":"Analise as sentenças quanto à colocação pronominal: I.Chama-se à própria responsabilidade o cuidar do acesso à água. II.A agência se coloca à disposição para discutir e cuidar do acesso à água para toda a população. III.Sempre chamaram-no à responsabilidade, afinal, era responsável pela agência que regula o saneamento básico da cidade. IV.Quem nos explicará os pormenores da nova legislação de saneamento básico? Está correta a colocação dos pronomes átonos em:","opcoes":["III, apenas.","I e III, apenas.","I, II, III e IV.","I, II e IV, apenas.","II e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3051,"enunciado":"\"Caligrafias ilegíveis ou manchas de tinta podiam gerar divergências de informações e resultar na malha fina.\" Com base nas regras de colocação pronominal, identifique a alternativa que apresenta a colocação e substituição adequada da expressão 'divergências'.","opcoes":["Caligrafias ilegíveis ou manchas de tinta podiam gerar-las e resultar na malha fina.","Caligrafias ilegíveis ou manchas de tinta podiam gerar elas e resultar na malha fina.","Caligrafias ilegíveis ou manchas de tinta podiam lhes gerar e resultar na malha fina.","Caligrafias ilegíveis ou manchas de tinta podiam gerá-las e resultar na malha fina."],"correta":3,"explicacao":"Gabarito: <strong>Caligrafias ilegíveis ou manchas de tinta podiam gerá-las e resultar na malha fina.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal","ortografia"]},{"id":3052,"enunciado":"Oferecer melhor controle do tempo, facilidades no pagamento e um serviço de qualidade passa pela modernização do transporte por ônibus, um movimento que já começou. Com base nas regras de colocação pronominal, marque com V as afirmativas verdadeiras ou com F as falsas: (__) Ao substituir o complemento verbal do verbo 'oferecer', ocorrerá a ênclise na forma 'lhes', uma vez que o verbo, por ser transitivo indireto, exige o emprego dessa forma pronominal. (__)Por o verbo 'oferecer' estar no infinitivo, admite-se, conforme o contexto sintático, a colocação pronominal tanto em ênclise quanto em próclise. (__)No contexto, a colocação pronominal deverá ocorrer obrigatoriamente em ênclise, não sendo admitida outra possibilidade de posicionamento do pronome. (__)Na frase 'Espero não encontrá-lo na reunião de amanhã, a colocação pronominal está inadequada, uma vez que a presença do advérbio de negação 'não' constitui fator de atração, exigindo o uso de próclise. A sequência que preenche corretamente os itens acima, de cima para baixo, é:","opcoes":["F, F, V, F.","V, F, F, V.","F, V, F, V","V, V, F, V."],"correta":0,"explicacao":"Gabarito: <strong>F, F, V, F.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3055,"enunciado":"Assinale a alternativa cujas expressões preenchem corretamente as lacunas nos enunciados a seguir, na mesma ordem, de acordo com a norma-padrão: - ________ Sugestões de roupa para a festa. - Ele nunca________ nenhum pedido especial. - Espero que ________ sobre qualquer perigo.","opcoes":["Me dê / fez-nos / me alerte","Dê-me / nos fez / me alerte","Dê-me / fez-nos / alerte-me","Me dê / nos fez / alerte-me","Me dê / fez-nos / alerte-me"],"correta":1,"explicacao":"Gabarito: <strong>Dê-me / nos fez / me alerte</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3056,"enunciado":"As sentenças a seguir foram extraídas do texto. Analise-as quanto à colocação dos pronomes átonos destacados, observando o contexto sintático em que cada um aparece: I.\"Sua pesquisa se concentra no desenvolvimento de métodos sensíveis para detectar poluentes − como metais pesados e contaminantes orgânicos − em rios, solos e sistemas urbanos.\" II.\"[...] mulher negra e nordestina na ciência, tornou-se referência para novas gerações ao ocupar espaços historicamente pouco diversos na pesquisa biomédica.\" III.\"[...]ela se tornou símbolo da capacidade da ciência brasileira de responder rapidamente a crises globais [...].\" Está correta a colocação pronominal em:","opcoes":["I, apenas.","I e III, apenas.","II e III, apenas.","II, apenas.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3063,"enunciado":"As sentenças a seguir foram extraídas do texto. Analise-as quanto à colocação dos pronomes átonos destacados, observando o contexto sintático em que cada um aparece: I.\"Sua pesquisa se concentra no desenvolvimento de métodos sensíveis para detectar poluentes − como metais pesados e contaminantes orgânicos − em rios, solos e sistemas urbanos.\" II.\"[...] mulher negra e nordestina na ciência, tornou-se referência para novas gerações ao ocupar espaços historicamente pouco diversos na pesquisa biomédica.\" III.\"[...]ela se tornou símbolo da capacidade da ciência brasileira de responder rapidamente a crises globais [...].\" Está correta a colocação pronominal em:","opcoes":["I, apenas.","I, II e III.","I e III, apenas.","I e III, apenas","II, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3065,"enunciado":"Leia os seguintes fragmentos do Texto 01. I- se “ ‘Por isso, não se tem aquele azul forte e bonito que vemos aqui’ ”. II- se “O oxigênio começou a se acumular em níveis relevantes na atmosfera”. No tocante à colocação pronominal do se, é CORRETO afirmar que:","opcoes":["nos dois fragmentos, é possível observar o uso da próclise, sem possibilidade de ênclise.","nos dois fragmentos, é possível observar o uso da ênclise, com possibilidade de próclise no primeiro fragmento e sem possibilidade de próclise no segundo fragmento.","nos dois fragmentos, é possível observar o uso da ênclise, com possibilidade de próclise.","nos dois fragmentos, é possível observar o uso da próclise, com possibilidade de ênclise.","nos dois fragmentos, é possível observar o uso da próclise, sem possibilidade de ênclise no primeiro fragmento e com possibilidade de ênclise no segundo fragmento."],"correta":4,"explicacao":"Gabarito: <strong>nos dois fragmentos, é possível observar o uso da próclise, sem possibilidade de ênclise no primeiro fragmento e com possibilidade de ênclise no segundo fragmento.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3067,"enunciado":"Alguns autores da gramática normativa consideram a ênclise como a colocação básica do pronome oblíquo átono. Nesse sentido, Napoleão Mendes de Almeida afirma que, por exercerem função de complemento verbal, esses pronomes tendem, em regra, a ocupar posição posterior ao verbo. De forma semelhante, Rocha Lima (2013) registra que a posição considerada normal dos pronomes átonos ocorre após o verbo. Com base na norma-padrão da língua portuguesa, assinale a alternativa em que a ênclise é obrigatória e corretamente empregada, sem a presença de fator de atração para a próclise.","opcoes":["Macacos não mordam-me.","Aqui trago-vos provisões.","Amigos, digam-me a verdade.","Tudo adapta-se, oferecendo-se soluções.","Quantas vezes desequilibrou-se?"],"correta":2,"explicacao":"Gabarito: <strong>Amigos, digam-me a verdade.</strong>.","banca":"IDECAN","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3069,"enunciado":"Analise as sentenças quanto à colocação pronominal: I. Chama-se à própria responsabilidade o cuidar do acesso à água. II. A agência se coloca à disposição para discutir e cuidar do acesso à água para toda a população. III. Sempre chamaram-no à responsabilidade, afinal, era responsável pela agência que regula o saneamento básico da cidade. IV. Quem nos explicará os pormenores da nova legislação de saneamento básico? Está correta a colocação dos pronomes átonos em:","opcoes":["III, apenas.","I, II, III e IV.","I, II e IV, apenas.","I e III, apenas.","II e IV, apenas."],"correta":2,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3070,"enunciado":"Leia os seguintes fragmentos do Texto 01. I- “ ‘Por isso, não se tem aquele azul forte e bonito que vemos aqui’ ”. II- “O oxigênio começou a se acumular em níveis relevantes na atmosfera”. No tocante à colocação pronominal do se, é CORRETO afirmar que:","opcoes":["nos dois fragmentos, é possível observar o uso da próclise, sem possibilidade de ênclise.","nos dois fragmentos, é possível observar o uso da ênclise, com possibilidade de próclise no primeiro fragmento e sem possibilidade de próclise no segundo fragmento.","nos dois fragmentos, é possível observar o uso da ênclise, com possibilidade de próclise.","nos dois fragmentos, é possível observar o uso da próclise, com possibilidade de ênclise.","nos dois fragmentos, é possível observar o uso da próclise, sem possibilidade de ênclise no primeiro fragmento e com possibilidade de ênclise no segundo fragmento."],"correta":4,"explicacao":"Gabarito: <strong>nos dois fragmentos, é possível observar o uso da próclise, sem possibilidade de ênclise no primeiro fragmento e com possibilidade de ênclise no segundo fragmento.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3071,"enunciado":"Tendo em vista as regras de colocação pronominal da língua portuguesa, assinale a alternativa em que a reescrita proposta mantém-se condizente com a norma-padrão.","opcoes":["“Como já se pode notar, estamos no território de ‘Tubarão’ [...]”. Reescrita: Como já pode-se notar, estamos no território de “Tubarão” [...].","“[...] da imensidade a que se abre o novo filme de Kleber Mendonça Filho.”. Reescrita: [...] da imensidade a que abre-se o novo filme de Kleber Mendonça Filho.","“Muito pessoalmente, devo dizer que nunca me comoveu muito o prêmio do júri [...]”. Reescrita: Muito pessoalmente, devo dizer que nunca comoveu-me muito o prêmio do júri [...].","“[...] o Brasil é o lugar onde práticas iníquas vão se perpetuando [...]”. Reescrita: [...] o Brasil é o lugar onde práticas iníquas vão perpetuando-se [...].","“O prêmio foi dividido com ‘Os Miseráveis’, de Ladj Ly, que me parecia muito superior.”. Reescrita: O prêmio foi dividido com “Os Miseráveis”, de Ladj Ly, que parecia-me muito superior”"],"correta":3,"explicacao":"Gabarito: <strong>“[...] o Brasil é o lugar onde práticas iníquas vão se perpetuando [...]”. Reescrita: [...] o Brasil é o lugar onde práticas iníquas vão perpetuando-se [...].</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3073,"enunciado":"A norma-padrão de regência verbal e de colocação pronominal foi respeitada em:","opcoes":["É natural as pessoas almejarem a um futuro em que se encontrem bem e saudáveis.","O encontro com quem padece de alguma doença grave quase sempre revela-se algo difícil.","Nos preocupamos justificadamente ao bem-estar de nossos pais à medida que eles envelhecem.","Não se deve adotar hábitos que possam acarretar em prejuízos à saúde física ou mental.","Muitas pessoas vêm se esforçando para aderir a um estilo de vida saudável e equilibrado."],"correta":4,"explicacao":"Gabarito: <strong>Muitas pessoas vêm se esforçando para aderir a um estilo de vida saudável e equilibrado.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3075,"enunciado":"Assinale a alternativa redigida de acordo com a norma-padrão quanto à regência, à crase e à colocação pronominal.","opcoes":["Há mensagens que prestam-se à difundir certezas rápidas e a dar-lhes aparência consistente de prova documental.","Há mensagens que se prestam a difundir certezas rápidas e a dar-lhes aparência consistente de prova documental.","Há mensagens que se prestam à difundir certezas rápidas e a lhes dar aparência consistente de prova documental.","Há mensagens que prestam-se a difundir certezas rápidas e a lhes dar aparência consistente de prova documental.","Há mensagens que se prestam a difundir certezas rápidas e a dar aparência consistente lhes de prova documental."],"correta":1,"explicacao":"Gabarito: <strong>Há mensagens que se prestam a difundir certezas rápidas e a dar-lhes aparência consistente de prova documental.</strong>.","banca":"IBADE","ano":2026,"temas_relacionados":["colocacaoPronominal","crase"]},{"id":3076,"enunciado":"Assinale a alternativa em que a reescrita de informações do texto está em conformidade com a norma-padrão de colocação pronominal.","opcoes":["O tempo passa e os danos do perigoso hábito começam a manifestar-se na vida adulta.","Já bebia-se muito cedo, na adolescência, sem qual quer problematização ou julgamento dos pais e de mais responsáveis.","Quando fala-se no combate ao consumo abusivo de álcool, o depoimento das pessoas é fundamental.","Se exigem, portanto, estratégias atualizadas e eficazes para vencer esses e outros obstáculos.","A geração formada por pessoas nascidas a partir de 1997 tem dedicado-se a novos rumos para o lazer e para as celebrações."],"correta":0,"explicacao":"Gabarito: <strong>O tempo passa e os danos do perigoso hábito começam a manifestar-se na vida adulta.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3077,"enunciado":"Assinale a alternativa em que a colocação pronominal está INCORRETA de acordo com a norma culta da língua portuguesa escrita formal.","opcoes":["Entregaram-lhe o processo tão logo foi solicitado.","Não me entregaram os documentos no prazo estipulado.","Quando me entregarem os documentos, assinarei o recibo.","Me entregaram os relatórios antes da reunião."],"correta":3,"explicacao":"Gabarito: <strong>Me entregaram os relatórios antes da reunião.</strong>.","banca":"Instituto Select","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3081,"enunciado":"\"Manter-se\" em uma perna exige que o cérebro integre informações da visão, do sistema de equilíbrio do ouvido interno e dos nervos responsáveis pela percepção corporal. Em relação à colocação pronominal do verbo destacado, assinale a alternativa correta.","opcoes":["Anáclise.","Ênclise.","Próclise.","Mesóclise."],"correta":1,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3104,"enunciado":"A pressão sobre o mercado imobiliário \"se intensificou\" com a presença de estrangeiros de maior poder aquisitivo. A colocação pronominal destacada na frase denomina-se:","opcoes":["Ênclise.","Anáclise.","Mesóclise.","Próclise."],"correta":3,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3109,"enunciado":"No trecho “a conversa se transforma” assinale a alternativa que apresenta a descrição correta do pronome “se” em relação ao posicionamento quanto ao verbo:","opcoes":["A mesóclise seria forma ideal nessa situação, pela presença da expressão “às vezes” que, estando no início da linha, atrai o pronome para próximo de si.","Mesmo estando em ênclise, o verbo sofre influência direta de fatores atrativos que podem modificar a posição do pronome em caso de passagem para a voz passiva.","O pronome “se” é invariável e ocupa por padrão a mesma posição; somente sendo alterado por questões estéticas.","Posição de próclise, encontrando-se anteposto ao verbo, em função do padrão do português contemporâneo."],"correta":3,"explicacao":"Gabarito: <strong>Posição de próclise, encontrando-se anteposto ao verbo, em função do padrão do português contemporâneo.</strong>.","banca":"ABCP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3110,"enunciado":"Em “manifesta-se”, a colocação pronominal é:","opcoes":["Próclise","Mesóclise","Ênclise","Anóclise"],"correta":2,"explicacao":"Gabarito: <strong>Ênclise</strong>.","banca":"CMM - Concursos e Seletivos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3112,"enunciado":"O uso do pronome no verbo em destaque no trecho “Somente assim, poder-se-á construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”, presente no texto, pode ser substituído, sem prejuízo semântico ao texto, respeitando-se a conjugação verbal, pela seguinte construção:","opcoes":["“Somente assim, pode-se construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”.","“Somente assim, deve-se possível construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”.","“Somente assim, é possível construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”.","“Somente assim, seria possível construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”.","“Somente assim, será possível construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”."],"correta":4,"explicacao":"Gabarito: <strong>“Somente assim, será possível construir um cenário de justiça social e de reconhecimento igualitário dos indivíduos perante o corpo social e estatal, [...]”.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3113,"enunciado":"Assinale a alternativa em que a frase atende à norma-padrão de colocação pronominal.","opcoes":["Baleia tinha alimentado-se com os ossos do amigo.","Sinhá Vitória estava confusa e um grito despertaria-a.","Fabiano procurou raízes, mas ali nada encontrou-se.","O papagaio mostrava-se furioso, com os pés apalhetados.","Se equilibrava mal o papagaio na pequena gaiola."],"correta":3,"explicacao":"Gabarito: <strong>O papagaio mostrava-se furioso, com os pés apalhetados.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3118,"enunciado":"A respeito do texto e de suas construções linguísticas, julgue o item seguinte. O pronome átono \"lhe\", na pergunta do entrevistador, poderia ser corretamente substituído, sem prejuízo para os sentidos do texto, pela forma pronominal o.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3122,"enunciado":"Com base nas ideias e nos aspectos linguísticos do texto apresentado, julgue o item seguinte. A forma pronominal “se”, em “vão se beneficiar” (último período do segundo parágrafo), poderia ser corretamente deslocada para imediatamente após a forma verbal infinitiva, da seguinte forma: vão beneficiar-se.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3123,"enunciado":"A colocação do pronome átono está de acordo com a norma-padrão da Língua Portuguesa na seguinte frase:","opcoes":["Porque disseminam-se conteúdos enganosos com rapidez, torna-se essencial o pensamento crítico.","Quando difundem-se notícias falsas por meio de algoritmos, o impacto social pode ser significativo.","Quem deixa-se convencer por textos automatizados corre o risco de aceitar argumentos falaciosos.","Se pode confiar plenamente em informações geradas por IA, desde que haja a verificação adequada.","Se se utilizam inteligências artificiais sem critério, ampliam-se os efeitos da desinformação."],"correta":4,"explicacao":"Gabarito: <strong>Se se utilizam inteligências artificiais sem critério, ampliam-se os efeitos da desinformação.</strong>.","banca":"CESGRANRIO","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3125,"enunciado":"\"Promulgar uma emenda constitucional é aperfeiçoar a Constituição, torná-la mais clara, funcional e próxima da vida real das pessoas.\" Fonte: Agência Senado Segundo a norma-padrão, a colocação pronominal, como o emprego do 'la' na forma 'torná-la', obedece a critérios específicos. Com base nas regras de uso dos pronomes e em suas respectivas justificativas, julgue as afirmativas a seguir. I.Quando o verbo está no futuro do presente ou no futuro do pretérito, dá-se tão somente a próclise ou a mesóclise do pronome: \"Eu me calarei\" e \"Calar-me-ia se não houvesse necessidade de esclarecer os fatos\". II.Com os infinitivos, mesmo quando modificado por negação, é lícita a próclise ou a ênclise, embora haja acentuada tendência para esta última colocação pronominal. \"Senti um súbito desejo de a tomar nos braços\" e \"Para não assustá-los, falou em tom baixo\". III.Em locuções verbais, se não houver justificativa para a próclise, o pronome pode ser colocado depois do verbo auxiliar ou enclítico ao auxiliar. Assim, estão adequadas à norma-padrão as construções: \"Devo-lhe mandar o carro para revisão hoje\" e \"Eu quero lhe apresentar uma proposta\". É correto o que se afirma em:","opcoes":["I apenas.","III apenas.","I e II apenas.","II e III apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e II apenas.</strong>.","banca":"AMAUC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3127,"enunciado":"O pronome esta substituindo de maneira inadequada o objeto em:","opcoes":["\"(...) agradar todo mundo (...) \" - agradá-los.","\"(...) recusar um convite (...)\" - Recusá-lo.","\"(...) pôr ordem (...)\" - pô-la.","\"Coloque ordem (...)\" - Coloque-na."],"correta":3,"explicacao":"Gabarito: <strong>\"Coloque ordem (...)\" - Coloque-na.</strong>.","banca":"Fundação CETAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3131,"enunciado":"Assinale a alternativa em que a reescrita do trecho “As pessoas, muitas vezes, se comunicam pela internet [...]”, do Texto 1, preserva a correção gramatical e o sentido original.","opcoes":["Muitas vezes as pessoas, se comunicam pela internet.","As pessoas se comunicam, pela internet muitas vezes.","Muitas vezes as pessoas comunicam-se, pela internet.","Muitas vezes, as pessoas comunicam-se pela internet.","As pessoas, se comunicam, muitas vezes, pela internet."],"correta":3,"explicacao":"Gabarito: <strong>Muitas vezes, as pessoas comunicam-se pela internet.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3135,"enunciado":"Assinale a alternativa que explica CORRETAMENTE a ênclise em \"Venceste-la\".","opcoes":["Aplicação da regra geral da ênclise em Português, que determina a posposição do pronome oblíquo átono em relação ao verbo quando este inicia a oração.","Presença de um verbo no pretérito perfeito do indicativo, tempo verbal que favorece a ênclise em detrimento da próclise, mesmo na presença de fatores proclíticos.","Ênclise opcional, admitida pela norma culta da língua em contextos poéticos, como forma de garantir a musicalidade e o ritmo do verso.","Influência da sintaxe latina na Língua Portuguesa, que privilegiava a colocação do pronome após o verbo, mesmo em orações iniciadas por palavras que atraem o pronome."],"correta":0,"explicacao":"Gabarito: <strong>Aplicação da regra geral da ênclise em Português, que determina a posposição do pronome oblíquo átono em relação ao verbo quando este inicia a oração.</strong>.","banca":"CONSULPAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3136,"enunciado":"Os seguintes excertos retirados do texto de apoio passaram por uma reescrita. Assinale a alternativa cuja colocação pronominal esteja correta.","opcoes":["O direito de expressar-se é uma conquista da humanidade […].","Cidadãos de todas as idades não têm utilizado-se das redes sociais para expressar opiniões.","Afinal, em um contexto civilizatório, nunca falar-se-ia em “terra de ninguém”.","[…] onde garotos e garotas, boa parte deles ainda menor de idade, sentir-se-iriam totalmente à vontade para postar opiniões pessoais […].","O bullying virtual sempre soma-se ao real, nas escolas […]."],"correta":0,"explicacao":"Gabarito: <strong>O direito de expressar-se é uma conquista da humanidade […].</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3138,"enunciado":"A passagem em que, de acordo com a norma-padrão, o pronome destacado pode ser posto antes ou depois do verbo é","opcoes":["... ao contrário do que se pensa... (1o parágrafo)","... o brasileiro vestia-se como se isto aqui fosse a Sibéria... (1o parágrafo)","Procura-se um fraque... (2o parágrafo)","... e não se encontra um fraque. (2o parágrafo)"],"correta":1,"explicacao":"Gabarito: <strong>... o brasileiro vestia-se como se isto aqui fosse a Sibéria... (1o parágrafo)</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3140,"enunciado":"Segundo o brigadista Deusimar Cardoso, \"trata-se\" de um fogo bom, manso e brando, que \"se apaga\" sozinho com o sereno da noite. As colocações pronominais destacadas na frase denominam-se, respectivamente,","opcoes":["mesóclise e próclise","anáclise e ênclise","ênclise e próclise","próclise e ênclise"],"correta":2,"explicacao":"Gabarito: <strong>ênclise e próclise</strong>.","banca":"UNIVALI","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3144,"enunciado":"A respeito do trecho “Porém, por limitações de infraestrutura, contam-se nos dedos de uma mão os terminais com capacidade para recebê-los com carga máxima.”, assinale a alternativa cuja explicação sobre a colocação pronominal esteja adequada.","opcoes":["Ocorre ênclise com o pronome em destaque, pois, para haver próclise, o verbo deveria estar no singular.","É permitida, nesse excerto, a ocorrência da próclise, visto que o início da oração, efetivamente, acontece com o conectivo “Porém”.","Caso o verbo “contam” fosse flexionado para “contarão”, a colocação pronominal se daria da seguinte forma: “contarão-se”.","Como não há fator próclise no excerto, há duas possibilidades de colocação do pronome em destaque: ênclise e mesóclise.","A ênclise é obrigatória para o pronome em destaque, visto que há uma pausa antes da oração, a qual não pode ser iniciada pelo pronome."],"correta":4,"explicacao":"Gabarito: <strong>A ênclise é obrigatória para o pronome em destaque, visto que há uma pausa antes da oração, a qual não pode ser iniciada pelo pronome.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3145,"enunciado":"A colocação pronominal (próclise, mesóclise e ênclise) no português brasileiro contemporâneo, especialmente na modalidade culta escrita, é regida por um conjunto de regras que priorizam a eufonia e a clareza, mas que muitas vezes divergem do uso coloquial. Fatores de atração, como palavras negativas (não, nunca), advérbios (já, sempre) e pronomes relativos (que, quem), exercem forte influência, exigindo a próclise. A ênclise é a posição padrão em inícios de oração na norma culta, e a mesóclise, embora rara na fala, é obrigatória em futuros (do presente ou do pretérito) quando não há fator de atração. Assim, analise as afirmativas a seguir sobre a correta colocação pronominal segundo a norma culta: I. Na oração \"O documento que enviaram-me está incompleto\", há um desvio da norma culta, pois o pronome relativo \"que\" é um fator de atração que exige a próclise (\"que me enviaram\"). II. A frase \"Em se tratando de finanças, ele é um especialista\" está gramaticalmente incorreta, pois o gerúndio precedido da preposição \"em\" não permite a próclise, exigindo a ênclise (\"Em tratando-se\"). III. A construção \"Não lamentar-se-ia dos resultados\" apresenta um erro de colocação, pois a palavra negativa \"Não\" atrai o pronome, e o verbo no futuro do pretérito exigiria a mesóclise na ausência do \"Não\". A forma correta, com o atrativo, é \"Não se lamentaria\". Está correto o que se afirma em:","opcoes":["II apenas.","I, II e III.","I e II apenas.","I e III apenas."],"correta":3,"explicacao":"Gabarito: <strong>I e III apenas.</strong>.","banca":"IDCAP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3147,"enunciado":"A respeito da colocação pronominal e considerando as regras do português brasileiro, analise as sentenças a seguir: I. Em \"Ela passa a ocupar a cadeira nº 33, que pertenceu ao linguista Evanildo Bechara, tornando-se a primeira mulher negra a integrar a instituição\", o pronome átono está posposto ao verbo porque este está no gerúndio. II. Em \"Com esse gesto, Ana Maria se inscreve na história — não apenas como 'imortal', mas como símbolo de um Brasil que começa a se enxergar em todas as suas cores, ritmos e memórias\", as duas colocações destacadas estão adequadas, pois no português brasileiro, não havendo nada que a impeça, a próclise é a regra geral. III. Em \"[...] é um gesto de continuidade e transformação, um capítulo vivo da literatura brasileira que se reescreve diante de nossos olhos\", o pronome átono é posto antes do verbo porque, nesse contexto, se trata de uma oração subordinada desenvolvida. É correto o que se afirma em:","opcoes":["II e III, apenas.","I, II e III.","I, apenas.","II, apenas.","I e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FURB","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3150,"enunciado":"No trecho \"Acredito que se desconectar, independentemente do motivo, sempre resulta em um saldo positivo...\", o uso do pronome \"se\" está associado ao verbo no infinitivo \"desconectar\". A esse respeito, com base na norma culta da língua portuguesa, assinale a alternativa correta quanto à colocação pronominal.","opcoes":["A colocação pronominal está correta, pois o pronome \"se\" é atraído pela conjunção subordinativa \"que\", fator que exige a próclise.","O emprego da próclise está incorreto, pois a presença de pausa prosódica após \"que\" justifica o uso da ênclise para preservar o paralelismo sintático da oração.","Trata-se de um caso de colocação facultativa, pois a oração subordinada permite tanto o uso de próclise quanto o de ênclise, sem prejuízo gramatical.","O uso de próclise com infinitivo é gramaticalmente inadequado, devendo-se empregar a ênclise \"desconectar-se\", independentemente do fator atrativo anterior.","A posição do pronome \"se\" antes de verbo no infinitivo é proibida, salvo em construções com verbos auxiliares, o que não se verifica no trecho analisado."],"correta":0,"explicacao":"Gabarito: <strong>A colocação pronominal está correta, pois o pronome \"se\" é atraído pela conjunção subordinativa \"que\", fator que exige a próclise.</strong>.","banca":"Unesc","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3151,"enunciado":"No período “Jamais se deve desconsiderar o direito do educando à inclusão”, a próclise é obrigatória, uma vez que o advérbio “jamais” funciona como elemento atrativo que impede o uso da ênclise, o que tornaria a frase inadequada no padrão formal da escrita.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3152,"enunciado":"A colocação pronominal em construções iniciadas por conjunções subordinativas exige, como regra geral da norma culta, o uso da próclise. No entanto, em registros formais, a ênclise ainda é considerada aceitável nesses contextos, desde que o pronome oblíquo átono não esteja distante do verbo ou que se pretenda evitar ambiguidade com formas verbais compostas.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3153,"enunciado":"No trecho “Não me diga que ele se arrependeu do que lhe fizeram”, a colocação pronominal está em conformidade com a norma-padrão, sendo que o uso da ênclise após a negativa “não” está plenamente aceito, já que a negativa se refere apenas à negação do conteúdo verbal, não interferindo na posição do pronome.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3158,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir. No trecho “Apesar de se viver um momento em que a tecnologia está ao redor, acredita&#8209;se que, em qualquer época, as pessoas sempre sentirão vontade de estar juntas”, o emprego da ênclise em “acredita&#8209;se” é obrigatório, devido à pausa determinada pela vírgula anterior ao verbo.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3160,"enunciado":"Em “Danem-se as questões importantes” verifica-se a correta colocação pronominal. Assinale a alternativa em que a colocação do pronome oblíquo átono esteja incorreta de acordo com a gramática tradicional.","opcoes":["Não se verificou nada importante.","Tinha verificado-se uma única questão importante.","Ninguém me entregou o relatório da reunião de ontem.","Verifiquei que me entregaram o relatório.","Nada me abala."],"correta":1,"explicacao":"Gabarito: <strong>Tinha verificado-se uma única questão importante.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3161,"enunciado":"\"Você fica, então, alguns segundos em frente à geladeira, como se o frio pudesse refrescar a intenção que se perdeu com a mudança de ambiente.\" No trecho, o pronome 'se' foi corretamente colocado em próclise, conforme uma regra específica de colocação pronominal. Analise agora as justificativas a seguir de colocação pronominal nos enunciados e identifique a alternativa INCORRETA.","opcoes":["Nas orações exclamativas e optativas, com o verbo no subjuntivo e sujeito anteposto ao verbo, ocorre a próclise, como em 'Deus te ajude!'","Com o gerúndio precedido de preposição 'em', ocorre a próclise, como em 'Em se tratando de dinheiro, não fale comigo'.","Nas locuções verbais, o verbo pode vir proclítico ao auxiliar, como em 'Eu lhe quero dizer a verdade', ou enclítico ao auxiliar, como em 'Eu quero lhe dizer a verdade'.","Quando o verbo estiver no futuro do pretérito do indicativo e não houver justificativa para a próclise, ocorre a mesóclise, como em 'Encontrar-te-ia mais tarde, se não tivesse compromisso'."],"correta":2,"explicacao":"Gabarito: <strong>Nas locuções verbais, o verbo pode vir proclítico ao auxiliar, como em 'Eu lhe quero dizer a verdade', ou enclítico ao auxiliar, como em 'Eu quero lhe dizer a verdade'.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3165,"enunciado":"A colocação pronominal atende à norma-padrão em:","opcoes":["Sem solidez econômica, dificilmente conseguirão-se promover no País as adequações necessárias na área da saúde, por exemplo.","Se registrou no Brasil, em 2023, pelo quinto ano seguido, queda no número de nascimentos, de acordo com o Instituto Brasileiro de Geografia e Estatística (IBGE).","Com menos brasileiros em idade de trabalho e mais cidadãos com direito à aposentadoria, o sistema atual tem provado-se cada vez menos sustentável.","Mesmo escolarizados, muitos cidadãos não demonstram-se hábeis em interpretar textos ou fazer contas ligeiramente mais complexas.","Japoneses e europeus têm educação bem melhor do que a nossa. Por isso, mostram-se mais preparados para lidar com o desafio da queda da natalidade."],"correta":4,"explicacao":"Gabarito: <strong>Japoneses e europeus têm educação bem melhor do que a nossa. Por isso, mostram-se mais preparados para lidar com o desafio da queda da natalidade.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3166,"enunciado":"Assinale a alternativa que apresenta a colocação pronominal correta, segundo as regras da gramática normativa:","opcoes":["Alguém apresentou-nos dados de pesquisas que nos deixaram preocupados.","A equipe de pesquisa divulgou os resultados, os apresentando aos especialistas.","As pesquisas precisam se fazer ouvidas e lidas pela população.","O levantamento não concluíra-se, pois eram muitos dados a analisar.","Os jogadores de risco não se dão conta dos prejuízos que causam a si mesmos."],"correta":4,"explicacao":"Gabarito: <strong>Os jogadores de risco não se dão conta dos prejuízos que causam a si mesmos.</strong>.","banca":"FURB","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3167,"enunciado":"Está plenamente correta a redação da seguinte frase:","opcoes":["Das memórias em que nos valemos nem sempre nos cabem reconhecer sua utilidade.","Imprime-se nas memórias caracterizadas por Bergson a distinção entre suas duas naturezas.","Resultam com o esforço da atenção e da repetição a utilidade desse tipo de memória.","A resistência de que se aplica ao esquecimento aproximam essas imagens da poesia.","Diante do aspecto prático da memória-trabalho opõem-se a poesia das imagens-lembranças."],"correta":1,"explicacao":"Gabarito: <strong>Imprime-se nas memórias caracterizadas por Bergson a distinção entre suas duas naturezas.</strong>.","banca":"FCC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3168,"enunciado":"Julgue o seguinte item, referente a aspectos linguísticos do texto CB2A1. No trecho “se destacam” (segundo período do quinto parágrafo), a ocorrência da próclise pronominal é obrigatória.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3169,"enunciado":"Por isso, este é um exemplo de evento extremo \"se desenvolvendo\" no início da estação. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["Ênclise.","Mesóclise.","Anáclise.","Próclise."],"correta":3,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3170,"enunciado":"Em “o alimento que lhe acompanhará no meio do caminho”, a colocação do pronome “lhe” após o verbo produz erro gramatical, uma vez que ele está no futuro do presente do indicativo. Uma opção gramatical é o uso da mesóclise: “acompanhar-lhe á”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3173,"enunciado":"Acerca das ideias veiculadas no texto, é INCORRETO afirmar que:","opcoes":["Em contextos com alguma formalidade, a próclise se faz presente.","Em começo de frase, nos textos formais, a próclise é regra universal.","Praticamente inexiste a mesóclise no português brasileiro moderno.","Em situações monitoradas de escrita, é prescrito o emprego da ênclise."],"correta":1,"explicacao":"Gabarito: <strong>Em começo de frase, nos textos formais, a próclise é regra universal.</strong>.","banca":"Instituto Consulplan","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3176,"enunciado":"A Colocação Pronominal é um assunto gramatical que normatiza o posicionamento do pronome átono em relação ao verbo. Com base nas frases do texto elencadas a seguir, marque a alternativa em que a próclise é obrigatória.","opcoes":["“Atualmente, muito se fala sobre o poder da empatia.”","“Assim, a pessoa ou a comunidade se sente compelida a agir em situações de calamidade, seja ela social, política ou ambiental.","“Afinal, elas podem se tornar adultas mais conscientes do seu papel na sociedade.”","“Segundo o pensador, a solidariedade é uma relação moral que permite aos indivíduos se sentirem pertencentes a uma sociedade.”","“Dessa maneira, busca-se uma maior compreensão de como essas informações devem estar acessíveis.”"],"correta":0,"explicacao":"Gabarito: <strong>“Atualmente, muito se fala sobre o poder da empatia.”</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3177,"enunciado":"Com base no conceito de Prática de Análise Linguística (Currículo Paulista: etapa ensino médio, 2020), quanto ao uso significativo das palavras no texto, identifica-se emprego de termo com função de realce em:","opcoes":["Só agora me lembrou que faz hoje um ano…","… como no dia em que o perdeu, lá se vão tantos anos.","… e peço a você que me espere para ir comigo.","Rita fá-lo lavar todos os meses, e isto impede que envelheça.","Em quase todas havia a mesma antiga súplica da nossa…"],"correta":1,"explicacao":"Gabarito: <strong>… como no dia em que o perdeu, lá se vão tantos anos.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3181,"enunciado":"Em se tratando de colocação pronominal, qual das frases abaixo está em DESACORDO com a norma culta da língua portuguesa?","opcoes":["Não se preocupe, tudo vai ficar bem.","Gostaria de te abraçar muito.","Prenda-me, se for capaz!.","Ana, dar-te-ei o que me pedires."],"correta":1,"explicacao":"Gabarito: <strong>Gostaria de te abraçar muito.</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3182,"enunciado":"Assinale a alternativa que apresenta colocação pronominal CORRETA:","opcoes":["Nunca senti-me tão apático.","Se você precisar, me chame.","Sempre te amarei, filha!","Se fará o que for necessário."],"correta":2,"explicacao":"Gabarito: <strong>Sempre te amarei, filha!</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3183,"enunciado":"Assinale a alternativa em que a frase atende à norma- -padrão, considerando-se os aspectos de regência nominal, regência verbal, uso ou não do acento indicativo da crase e colocação pronominal.","opcoes":["Se as pessoas me perguntassem a que me referia, responder-lhes-ia que fazia menção a todos os acontecimentos trágicos na pequena localidade de Ferguson, Missouri, relacionados às mortes dos afro-americanos.","Se as pessoas me perguntassem o que me referia, responderia-lhes que fazia menção à todos os acontecimentos trágicos na pequena localidade de Ferguson, Missouri, relacionados as mortes dos afro-americanos.","Se as pessoas me perguntassem no que me referia, responderia-lhes que fazia menção a todos os acontecimentos trágicos na pequena localidade de Ferguson, Missouri, relacionados a mortes dos afro-americanos.","Se as pessoas me perguntassem do que me referia, lhes responderia que fazia menção a todos os acontecimentos trágicos na pequena localidade de Ferguson, Missouri, relacionados à mortes dos afro-americanos.","Se as pessoas me perguntassem o que me referia, responder-lhes-ia que fazia menção à todos os acontecimentos trágicos na pequena localidade de Ferguson, Missouri, relacionados à mortes dos afro-americanos."],"correta":0,"explicacao":"Gabarito: <strong>Se as pessoas me perguntassem a que me referia, responder-lhes-ia que fazia menção a todos os acontecimentos trágicos na pequena localidade de Ferguson, Missouri, relacionados às mortes dos afro-americanos.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal","crase"]},{"id":3184,"enunciado":"Julgue o item que se segue, referente a aspectos linguísticos do texto CG1A1. Estaria mantida a correção gramatical do último período do segundo parágrafo caso a forma pronominal “se”, em “vão encontrar-se”, fosse deslocada para a posição de ênclise ao verbo auxiliar — vão-se encontrar.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3186,"enunciado":"Assinale a única alternativa em que a colocação pronominal foi empregada INCORRETAMENTE:","opcoes":["Karla, dar-te-ei todo o meu amor.","Sabe-se que a água ferve a 100 graus.","Te amo, filho!","Não me negue a verdade."],"correta":2,"explicacao":"Gabarito: <strong>Te amo, filho!</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3187,"enunciado":"A frase “Não o encontraram no esconderijo” contém próclise, isto é, o pronome está colocado antes do verbo. Qual das frases a seguir apresenta o mesmo tipo de estrutura?","opcoes":["Confessou-se ao padre antes da quaresma.","Anderson não se importou em ajudar.","Senti-me mal, por isso precisei sair mais cedo.","Apresentar-se-ão as razões nos autos.","Meu amigo chegou, venha conhecê-lo."],"correta":1,"explicacao":"Gabarito: <strong>Anderson não se importou em ajudar.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3188,"enunciado":"Com relação à colocação pronominal, assinalar a alternativa que preenche as lacunas CORRETAMENTE. _________ de um conto que ouvi há muito, quando eu era criança. Contei para meu irmão, e a história não ________ como imaginei.","opcoes":["Me lembrei | o aborreceu","Lembrei-me | o aborreceu","Me lembrei | lhe aborreceu","Lembrei-me | lhe aborreceu"],"correta":1,"explicacao":"Gabarito: <strong>Lembrei-me | o aborreceu</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3190,"enunciado":"A frase “Abraçou-o porque estava com saudades.” contém ênclise, isto é, o pronome está colocado após o verbo. Qual das frases a seguir apresenta o mesmo tipo de estrutura?","opcoes":["Ver-me-ão superar todos esses obstáculos!","Quando me informaram do ocorrido, fiquei estarrecida.","Capturaram-no logo após a fuga.","Silvio ficou sem fôlego, por isso não me alcançou.","Quem te contou esse segredo?"],"correta":2,"explicacao":"Gabarito: <strong>Capturaram-no logo após a fuga.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3191,"enunciado":"Analise as afirmativas abaixo a respeito da colocação pronominal e destaque, posteriormente, a alternativa correta. I. Na oração “Onde nos encontraremos amanhã?”, utiliza-se a próclise em razão do advérbio interrogativo. II. A posição do termo “me” em “Não me auxiliou na tarefa.” se justifica porque há uma palavra de negação que atrai o pronome. III. Em “Te chamei mais cedo.”, a colocação pronominal está errada, visto que o verbo “chamar” exige a ênclise.","opcoes":["I, II e III estão corretas.","Apenas I e II estão corretas.","Apenas II e III estão corretas.","Apenas I está correta.","Apenas II está correta."],"correta":1,"explicacao":"Gabarito: <strong>Apenas I e II estão corretas.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3192,"enunciado":"Analise as afirmativas abaixo a respeito da colocação pronominal e destaque, posteriormente, a alternativa correta. I. A frase “Não levantar-me cedo atrapalha meus estudos.” está correta em relação ao uso da mesóclise. II. Em “Quem deu-lhe uma coleção de discos?”, a ênclise está incorreta, pois nas orações interrogativas iniciadas por pronomes ou advérbios interrogativos utiliza-se a próclise. III. Utiliza-se a ênclise com verbos que iniciam a frase, por exemplo: “Fez-me bem caminhar ontem.”.","opcoes":["I, II e III estão corretas.","Apenas I e II estão corretas.","Apenas II e III estão corretas.","Apenas I está correta.","Apenas II está correta."],"correta":2,"explicacao":"Gabarito: <strong>Apenas II e III estão corretas.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3193,"enunciado":"As colocações pronominais em “Dava-lhe bom-dia e às vezes lhe passava um recado ou uma correspondência” correspondem, respectivamente, a:","opcoes":["mesóclise e próclise.","próclise e mesóclise.","próclise e ênclise.","ênclise e mesóclise.","ênclise e próclise."],"correta":4,"explicacao":"Gabarito: <strong>ênclise e próclise.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3196,"enunciado":"Assinale a alternativa cuja frase utiliza a colocação pronominal em conformidade com a norma-padrão da Língua Portuguesa.","opcoes":["Ambos puseram-se a refletir sobre aquela afirmação.","A chuva veio interromper-me.","Quando deitei-me, já era tarde da noite.","A opção que foi-me dada era a menos apreciável.","Alguém chamou-lhe lá fora."],"correta":1,"explicacao":"Gabarito: <strong>A chuva veio interromper-me.</strong>.","banca":"INSTITUTO MAIS","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3198,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto anterior, julgue o item seguinte. Estaria mantida a correção gramatical do texto caso as formas pronominais “se”, em “se volta” e “se ergueram”, respectivamente, no primeiro e no segundo períodos do terceiro parágrafo, fossem empregadas logo após as formas verbais — escrevendo-se volta-se e ergueram-se.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3199,"enunciado":"Com relação à colocação pronominal, assinalar a alternativa que preenche as lacunas CORRETAMENTE. Ela não _______ tudo sobre a viagem, mas ______ ter sentido muita falta de casa. Alguns _______ umas dicas que ela ignorou.","opcoes":["me contou | me disse | lhe deram","contou-me | disse-me | deram-lhe","me contou | disse-me | deram-lhe","contou-me | me disse | lhe deram"],"correta":0,"explicacao":"Gabarito: <strong>me contou | me disse | lhe deram</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3201,"enunciado":"A colocação pronominal está em conformidade com a norma-padrão em:","opcoes":["Certamente, se tornou inesquecível o verão de 2025 a quem decidiu viajar ao litoral paulista, e não pela combinação de praia, sol e diversão.","Um elevado volume de casos de gastroenterite superlotou os hospitais da região, tendo tornado-se o símbolo desta alta temporada.","Agora também investiga-se a morte de uma mulher do interior paulista que apresentou sintomas de virose após visitar o litoral.","Durante o verão, milhares de turistas deslocam-se para o litoral paulista e as cidades já deveriam estar preparadas para lidar com isso.","Esperaria-se que as cidades do litoral paulista estivessem preparadas para garantir a diversão dos cidadãos neste verão de 2025."],"correta":3,"explicacao":"Gabarito: <strong>Durante o verão, milhares de turistas deslocam-se para o litoral paulista e as cidades já deveriam estar preparadas para lidar com isso.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3202,"enunciado":"Leia atenciosamente a oração abaixo e, em seguida, siga o comando: \"Dir-lhe-emos a verdade assim que possível.\" Assinale a alternativa que classifica corretamente a colocação pronominal na oração acima:","opcoes":["Ênclise, pois o pronome está posposto ao verbo, seguindo a regra geral de colocação.","Mesóclise, pois o pronome está inserido dentro da forma verbal no futuro do presente.","Uso facultativo, pois a frase permite variação entre próclise e ênclise sem prejuízo de sentido.","Próclise, pois o pronome está antes do verbo devido à presença de uma conjunção subordinativa."],"correta":1,"explicacao":"Gabarito: <strong>Mesóclise, pois o pronome está inserido dentro da forma verbal no futuro do presente.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3203,"enunciado":"Leia com atenção as afirmativas abaixo: I.Nunca me esqueço dos momentos especiais que vivemos juntos. II.Encontrei-o no parque enquanto caminhava tranquilamente. III.Ela cumprimentou-nos com um sorriso logo que chegamos à reunião. IV.O livro que se vende naquela loja é considerado uma raridade. V.Decidiram entregar-lhe o prêmio pessoalmente durante a cerimônia. Em qual das afirmativas lida há o emprego de próclise?","opcoes":["I, III e V.","I e IV.","II, III e V.","II e IV."],"correta":1,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3204,"enunciado":"No trecho “No dia 8 de março de 2025, junte-se a nós para celebrar o Dia Internacional da Mulher […]”, sobre as características e o emprego do elemento sublinhado, é correto afirmar que","opcoes":["corresponde a um vocábulo que serve para indicar uma condição necessária à realização de um evento mencionado anteriormente.","deveria ocorrer imediatamente antes do verbo “juntar”, com base nas regras de colocação pronominal de nossa gramática.","faz referência a quem produziu o texto, ocorrendo em próclise.","está adequadamente empregado, ocorrendo em ênclise.","sinaliza um índice que expressa a voz passiva na oração."],"correta":3,"explicacao":"Gabarito: <strong>está adequadamente empregado, ocorrendo em ênclise.</strong>.","banca":"FADESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3206,"enunciado":"A expressão “o livro inteiro” encontra-se corretamente substituída por um pronome em:","opcoes":["se o haviam lido","se haviam lido-o","se haviam-lo lido","se haviam lido-lo"],"correta":0,"explicacao":"Gabarito: <strong>se o haviam lido</strong>.","banca":"SECPLAN","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3207,"enunciado":"“Lembro-me bem da divisão da casa. A sala de jantar, uma peça com gobelinos, a biblioteca e três quartos grandes ficavam na parte mais afastada, a que dá frente para a Rodríguez Peña.” (Júlio Cortázar) Quanto à colocação pronominal, afirma-se que, no primeiro período do fragmento, usa-se a:","opcoes":["próclise, pois, semanticamente, possui ideia adverbial","ênclise, porque o verbo inicia a oração","próclise, porque possui palavras que expressam desejo","ênclise, pois o verbo está no imperativo"],"correta":1,"explicacao":"Gabarito: <strong>ênclise, porque o verbo inicia a oração</strong>.","banca":"SECPLAN","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3213,"enunciado":"Em relação à colocação pronominal no trecho: \"Protetora de Animais, alinhando-se na luta contra essa crueldade.\", qual das alternativas está correta?","opcoes":["A colocação pronominal está incorreta, pois o pronome se deveria estar em ênclise, mas a oração possui palavra que exige a próclise.","A colocação pronominal está correta, pois o pronome se está em ênclise, já que não se inicia a oração com pronome oblíquo e não há palavra que exija a próclise.","A colocação pronominal está correta, pois o pronome se está em ênclise, já que o verbo está no gerúndio e a oração é afirmativa.","A colocação pronominal está incorreta, pois o pronome se deveria estar em próclise, pois o verbo alinhando é verbo no início da oração."],"correta":1,"explicacao":"Gabarito: <strong>A colocação pronominal está correta, pois o pronome se está em ênclise, já que não se inicia a oração com pronome oblíquo e não há palavra que exija a próclise.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3214,"enunciado":"É possível inserir acessos ali e \"usá-los\" para infusões de medicamentos. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["ênclise.","próclise.","anáclise.","mesóclise."],"correta":0,"explicacao":"Gabarito: <strong>ênclise.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3216,"enunciado":"Em um alerta publicado em seu site, a empresa de meteorologia Climatempo prevê que a onda de calor \"se expandirá\" para as regiões Sudeste e Nordeste do Brasil. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["anáclise, uma vez que o pronome exerce a função de apoio para o verbo destacado.","próclise, com sentido reflexivo, pois a ação recai sobre o próprio sujeito.","mesóclise, pois há presença de dois verbos, um anterior e outro posterior ao pronome oblíquo \"se\".","ênclise, com verbo exercendo uma ação pronominal."],"correta":1,"explicacao":"Gabarito: <strong>próclise, com sentido reflexivo, pois a ação recai sobre o próprio sujeito.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3218,"enunciado":"\"Como podemos \"projetá-lo\" para o futuro, diz o professor Barbante\". A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["Mesóclise.","Catáfrase.","Ênclise.","Paráfrase."],"correta":2,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3219,"enunciado":"A inteligência artificial (IA) \"tornou-se\" um instrumento fundamental para \"se enfrentar\" grandes desafios científicos. As normas-padrão de colocação pronominal destacadas na frase denominam-se, respectivamente:","opcoes":["ênclise e próclise.","mesóclise e anáclise","próclise e mesóclise.","anáclise e próclise."],"correta":0,"explicacao":"Gabarito: <strong>ênclise e próclise.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3220,"enunciado":"O trabalho deles \"nos permite\" agir e reduzir a disseminação de conteúdo problemático em nossos aplicativos. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["Próclise.","Anáclise.","Mesóclise.","Ênclise."],"correta":0,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3222,"enunciado":"A substituição do trecho ou elemento sublinhado pelo pronome oblíquo correspondente não se deu adequadamente e em consonância com a norma culta apenas em:","opcoes":["\"aumentando as expectativas\" − aumentando-as.","\"intensificar e expandir a implementação das duas novas iniciativas\" − intensificar e expandi-las.","\"os consumidores podem trocar carros ou eletrodomésticos antigos\" − trocá-los.","\"estimular o investimento empresarial\" − estimulá-lo."],"correta":1,"explicacao":"Gabarito: <strong>\"intensificar e expandir a implementação das duas novas iniciativas\" − intensificar e expandi-las.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3223,"enunciado":"No trecho \"A sogra, que sempre a alertou, estava certa\", a colocação pronominal está correta de acordo com a gramática normativa. Analise as opções e identifique a justificativa correta para o uso do pronome átono em próclise neste caso.","opcoes":["A próclise é exigida pela presença da palavra atrativa \"sempre\", que atrai o pronome átono para antes do verbo.","A próclise é opcional neste caso, podendo o pronome ser colocado antes ou depois do verbo sem prejuízo gramatical.","A próclise é utilizada porque o verbo está no futuro do presente e deve ser seguido por um pronome átono.","A próclise é utilizada devido à presença de uma conjunção subordinativa antes do verbo, que exige essa colocação pronominal."],"correta":0,"explicacao":"Gabarito: <strong>A próclise é exigida pela presença da palavra atrativa \"sempre\", que atrai o pronome átono para antes do verbo.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3225,"enunciado":"No trecho \"Refleti sobre a velocidade de nossos dias e a necessidade de 'redutores de pressão' em nossa vida para apreciá-la melhor\", a colocação pronominal do pronome \"la\" (pronome oblíquo) foi empregada corretamente como ênclise. Analise as alternativas abaixo e identifique a justificativa correta para o uso da colocação pronominal.","opcoes":["O pronome \"la\" foi usado em ênclise porque há uma palavra atrativa antecedendo o verbo, tornando esta colocação obrigatória.","O pronome \"la\" foi usado em ênclise porque o verbo está no infinitivo e não há palavra anterior que exija a próclise.","O pronome \"la\" foi usado em ênclise porque há uma partícula negativa antes do verbo, o que impede a utilização de próclise.","O pronome \"la\" foi usado em ênclise porque o verbo está conjugado no modo subjuntivo e ocorre em oração subordinada."],"correta":1,"explicacao":"Gabarito: <strong>O pronome \"la\" foi usado em ênclise porque o verbo está no infinitivo e não há palavra anterior que exija a próclise.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3226,"enunciado":"Com base nas regras de colocação pronominal, qual das alternativas melhor explica a função e a necessidade da próclise do pronome em destaque no trecho \"Ela estava irreconhecível: sorria o tempo todo, não se queixava de nada e dividia alegremente sua cama de casada com os três cachorros, que SE alternavam em seu colo e que ao lado do marido eram os quatro amores de sua vida\"?","opcoes":["A colocação pronominal em próclise é utilizada para manter a harmonia rítmica da oração, sem impacto direto na função sintática.","A colocação pronominal em próclise é determinada pela presença de um advérbio modal, que atrai o pronome para antes do verbo, assegurando coesão textual.","A colocação pronominal em próclise é necessária devido à palavra atrativa \"que\", que justifica a antecipação do pronome \"se\" em relação ao verbo \"alternavam \".","A colocação pronominal em próclise é empregada para enfatizar a ação do verbo \"alternavam\", destacando a importância da transformação na narrativa."],"correta":2,"explicacao":"Gabarito: <strong>A colocação pronominal em próclise é necessária devido à palavra atrativa \"que\", que justifica a antecipação do pronome \"se\" em relação ao verbo \"alternavam \".</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3230,"enunciado":"No uso do pronome \"se\" em \"Não se deve aceitar encomenda de amigos e familiares em viagens\", há um aspecto importante relacionado à colocação pronominal. Com base na análise normativa e estilística, escolha a alternativa correta.","opcoes":["A escolha pela próclise em \"Não se deve aceitar\" é opcional, mas contribui para a formalidade do texto, respeitando as normas padrão de colocação pronominal.","A colocação proclítica do pronome \"se\" ocorre devido à presença da palavra negativa \"não\", que exige a posição do pronome antes do verbo, como previsto pelas normas gramaticais do português.","A colocação proclítica do pronome \"se\" é uma escolha estilística do autor, que visa equilibrar o ritmo da oração e enfatizar a ação verbal no contexto da frase.","A ênfase no conselho é reforçada pela próclise do pronome \"se\", que aparece após o verbo em decorrência da ausência de fatores linguísticos que exijam outra posição pronominal."],"correta":1,"explicacao":"Gabarito: <strong>A colocação proclítica do pronome \"se\" ocorre devido à presença da palavra negativa \"não\", que exige a posição do pronome antes do verbo, como previsto pelas normas gramaticais do português.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3231,"enunciado":"Assinale a alternativa em que a frase está em conformidade com a norma-padrão de emprego de pronomes.","opcoes":["A internet pode aproximar pessoas, isto é, reconectar-las.","Todos podem se expressar na internet, isto é, usá-la para se expressar.","Cite as vantagens da internet, isto é, elenque-lhes.","A internet é usada para espalhar mentiras, isto é, para difundi-as.","Acho que já está bom de desvantagens, isto é, de mencioná-lhes."],"correta":1,"explicacao":"Gabarito: <strong>Todos podem se expressar na internet, isto é, usá-la para se expressar.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3232,"enunciado":"No trecho \"Apesar das limitações, sua dedicação e o atendimento emocionalmente afetuoso deixaram-me sensibilizado\", o uso da ênclise com o pronome \"me\" está correto. Assinale a alternativa correta sobre a colocação pronominal nesse contexto.","opcoes":["A colocação pronominal está incorreta, pois deveria ser utilizado a próclise (\"me deixaram sensibilizado\") pela presença de uma conjunção subordinativa.","A colocação pronominal está incorreta, pois a ênclise não é adequada quando o verbo é precedido por palavras negativas ou conjunções coordenativas.","A colocação pronominal está correta, pois o uso da próclise é obrigatório quando o verbo é transitivo direto, como no caso do verbo \"deixar\".","A colocação pronominal está correta, pois não há palavra que atraia a próclise, o que torna o uso da ênclise adequado."],"correta":3,"explicacao":"Gabarito: <strong>A colocação pronominal está correta, pois não há palavra que atraia a próclise, o que torna o uso da ênclise adequado.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3234,"enunciado":"No trecho \"Para quem sabe, daqui dez anos, ainda me lembre de que fugir do passado...\", a colocação do pronome \"me\" está correta. Sobre a colocação pronominal, analise as alternativas e escolha a correta.","opcoes":["A colocação pronominal está correta, pois o advérbio \"ainda\" atrai o pronome, exigindo a próclise.","A colocação pronominal está incorreta, pois a próclise não deve ser utilizada antes do verbo.","A colocação pronominal está correta, porém o pronome \"me\" poderia ser colocado após o verbo.","A colocação pronominal está incorreta, pois, quando há um advérbio de tempo, a ênclise deve ser utilizada."],"correta":0,"explicacao":"Gabarito: <strong>A colocação pronominal está correta, pois o advérbio \"ainda\" atrai o pronome, exigindo a próclise.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3235,"enunciado":"O termo “os” (linha 25) assume, respectivamente, função sintática e posição referente ao verbo “achar” [colocação pronominal], descritas, corretamente, na alternativa:","opcoes":["Objeto indireto e ênclise.","Adjunto adverbial e próclise.","Objeto direto e próclise.","Complemento nominal e ênclise."],"correta":2,"explicacao":"Gabarito: <strong>Objeto direto e próclise.</strong>.","banca":"ABCP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3236,"enunciado":"Assinale a alternativa em que a colocação pronominal está em conformidade com a norma-padrão da língua portuguesa.","opcoes":["Não pode-se ser feliz ou talvez tenha estabelecido-se um novo recorde de felicidade.","Não pode-se ser feliz ou talvez se tenha estabeleci do um novo recorde de felicidade.","Não se pode ser feliz ou talvez se tenha estabelecido um novo recorde de felicidade.","Não se pode ser feliz ou talvez tenha-se estabelecido um novo recorde de felicidade.","Não se pode ser feliz ou talvez tenha estabelecido-se um novo recorde de felicidade."],"correta":2,"explicacao":"Gabarito: <strong>Não se pode ser feliz ou talvez se tenha estabelecido um novo recorde de felicidade.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3237,"enunciado":"Em “Quando se lembrou do aniversário, já era tarde demais.” o pronome “se” está antes do verbo (próclise). Em qual das frases a seguir ocorre o mesmo tipo de colocação pronominal?","opcoes":["Vendem-se salgados para festa.","Um dia, vingar-se-á de todos os inimigos.","Levantaram-se para aplaudir de pé.","Não me chamaram para a formatura.","Preparem-se para a prova com antecedência."],"correta":3,"explicacao":"Gabarito: <strong>Não me chamaram para a formatura.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3238,"enunciado":"A colocação pronominal é um aspecto importante da língua portuguesa e envolve a posição dos pronomes em relação ao verbo. No trecho do texto 'De tão pequenas, é impossível vê-las a olho nu', o pronome 'las' está corretamente posicionado em:","opcoes":["Epêntese.","Ênclise.","Próclise.","Mesóclise."],"correta":1,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"IDESG","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3241,"enunciado":"Considere as alternativas a seguir e selecione aquela que contém um exemplo de ênclise:","opcoes":["Convidá-la-ia para viajar comigo, se pudesse.","Você me faz tão bem.","A professora que me reprovou na prova não veio hoje.","Alguém te telefonou.","Viver é adaptar-se."],"correta":4,"explicacao":"Gabarito: <strong>Viver é adaptar-se.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3242,"enunciado":"Ao longo do texto, em relação à colocação pronominal, houve privilégio da ênclise. No entanto, no último verso, a próclise pode ser justificada:","opcoes":["pela flexão da forma verbal “apagaram”.","por constituir uma oração coordenada.","pela presença de uma construção adjetiva.","por ser um verso de conotação negativa.","pelo tom da oração explicitado pelo ponto."],"correta":4,"explicacao":"Gabarito: <strong>pelo tom da oração explicitado pelo ponto.</strong>.","banca":"IBFC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3243,"enunciado":"Assinale a alternativa em que a frase atende à norma- -padrão de colocação pronominal.","opcoes":["Emmanuel Macron classificou o acordo como “loucura”, e a França certamente o tentará barrar na Comissão Europeia.","Para vencer o protecionismo, os países enfrentarão- -se no campo da diplomacia e, sobretudo, no campo da comunicação.","Tendo descoberto-se as reais motivações da recusa, concluímos que caiu a máscara piedosa da proteção ambiental.","Agora abre-se o capítulo final da ratificação pelos países-membros dos dois blocos, com espaço para muito drama.","Se encerrou ontem, na Cúpula do Mercosul, em Montevidéu, uma longa etapa de 25 anos de negociações."],"correta":0,"explicacao":"Gabarito: <strong>Emmanuel Macron classificou o acordo como “loucura”, e a França certamente o tentará barrar na Comissão Europeia.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3244,"enunciado":"Leia: CARTA ABERTA À SOCIEDADE BRASILEIRA “Pacto nacional por um modelo de desenvolvimento sustentável, justo e inclusivo, urgente” Nós, integrantes da Comissão Nacional para os Objetivos de Desenvolvimento Sustentável (CNODS), nos dirigimos à sociedade brasileira com a convicção de que juntos podemos fortalecer nossa união e construir um Brasil sustentável, hoje. Múltiplas são as crises planetárias que afligem todas as pessoas, mas impactam de maneira desproporcional alguns grupos sociais específicos. A sustentabilidade não é uma pauta para o futuro: devemos alcançá-la agora! Portanto, é urgente realizar a transição para um modelo de desenvolvimento sustentável, economicamente viável, socialmente justo e inclusivo e ambientalmente responsável. CNODS divulga carta aberta à sociedade brasileira. Disponível em: https://www.gov.br. Acesso em: 12 fev. 2025. (adaptado) Em “devemos alcançá-la agora!”, ocorre","opcoes":["próclise, por ser uma locução verbal com verbo no infinito impessoal.","ênclise, por ser uma locução verbal com verbo no infinito impessoal.","ênclise, pois o verbo está no imperativo afirmativo.","mesóclise, pois o verbo está no futuro."],"correta":1,"explicacao":"Gabarito: <strong>ênclise, por ser uma locução verbal com verbo no infinito impessoal.</strong>.","banca":"Inovaty","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3245,"enunciado":"Analise as alternativas abaixo, marque a que possui um erro de colocação pronominal.","opcoes":["Diga-me como foram as festas de final de ano.","Estava fazendo-se de desentendida para evitar problemas com o marido.","Me sigam, se quiserem conhecer o mundo.","Quero encontrar-te mais tarde.","Suas desculpas não me convenceram."],"correta":2,"explicacao":"Gabarito: <strong>Me sigam, se quiserem conhecer o mundo.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3246,"enunciado":"Analise as alternativas abaixo, marque a alternativa que não apresenta nenhum erro de colocação pronominal.","opcoes":["Me conte a verdade, pois sei que você está mentindo.","Paula se fazendo de compreensiva, conquistou a confiança de todos.","Sempre lembrarei-me da minha primeira professora.","Falar-te-ei sobre os meus projetos.","Nunca dir-lhe-ei mentiras!"],"correta":3,"explicacao":"Gabarito: <strong>Falar-te-ei sobre os meus projetos.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3247,"enunciado":"Analise as alternativas abaixo. Assinale a colocação pronominal que foi empregada de forma incorreta.","opcoes":["Diga-me quem venceu a competição.","Ele não quis humilhar-te na frente de seus amigos.","Quem te contou tamanho absurdo?","Não compre-me mais presentes.","Enganou o namorado, fazendo-se de santa."],"correta":3,"explicacao":"Gabarito: <strong>Não compre-me mais presentes.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3248,"enunciado":"Destaque a oração que traz um erro de colocação pronominal, segundo a gramática normativa.","opcoes":["Compraria-te flores, mas estou sem dinheiro.","Quem fez o trabalho? Eu fi-lo.","Você desprezou o presente que te dei?","Era meu desejo abraçar-te.","Na escola, não se entra de bermuda."],"correta":0,"explicacao":"Gabarito: <strong>Compraria-te flores, mas estou sem dinheiro.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3250,"enunciado":"\"Quando a glicemia está alta, o corpo busca reduzi-la por meio da liberação de insulina, um hormônio responsável por varrer o açúcar e transportá-lo para dentro das células, para que o excesso não permaneça no sangue.\" (https://www.bbc.com/portuguese/articles/c98yd859demo). Com base no trecho, analise as afirmativas a seguir: I.A forma pronominal 'la' em 'reduzí-la' e a 'lo' em 'transportá-lo', estão, respectivamente, substituindo os vocábulos 'glicemia' e 'hormônio'. II.O vocábulo 'alta' e 'responsável' são adjetivos que estão caracterizando os vocábulos 'glicemia' e 'hormônio', respectivamente. III.O objetivo da insulina é evitar que o excesso de glicose (açúcar) permaneça no sangue. IV.O vocábulo 'varrer' foi empregado em sentido próprio. Estão corretas:","opcoes":["Apenas II, III e IV.","Apenas I e II.","Apenas I e III.","Apenas II e III.","Apenas I e IV."],"correta":3,"explicacao":"Gabarito: <strong>Apenas II e III.</strong>.","banca":"AMAUC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3251,"enunciado":"Considere as frases. • Em se tratando das principais características para a aquisição de conhecimentos, quem geralmente _____________ são os intelectualmente mais humildes. • Qualidades como saber analisar fatos e reconhecer fake news é mais provável _________ em pessoas que têm pensamento reflexivo. • Para os intelectualmente humildes, curiosidade e mente aberta fazem parte da lista de predicados que __________ vantajosos. De acordo com a norma-padrão de emprego e de colocação de pronomes, as lacunas dessas frases devem ser preenchidas, respectivamente, por:","opcoes":["possuem-nas; encontrar-lhes; lhes são","possuem-nas; encontrá-las; são-lhes","as possuem; encontrá-las; lhes são","as possuem; encontrá-las; são-lhes","as possuem; encontrar-lhes; são-lhes"],"correta":2,"explicacao":"Gabarito: <strong>as possuem; encontrá-las; lhes são</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3252,"enunciado":"Durante décadas de desinformação, as pessoas se ____________ do estigma e do peso da doença, evitando proferir o nome dela. Ninguém _________ nessa situação, porque acreditavam que, se _________ silenciado, poderiam evitar uma má notícia. De acordo com a norma-padrão, as lacunas do enunciado devem ser preenchidas, respectivamente, com:","opcoes":["precaveram … interviu … mantivessem-no","precaviam … intervinha … mantivessem-o","precaveriam … interveio … mantivessem-lhe","precaviam … interviu … lhe mantivessem","precaveram … intervinha … o mantivessem"],"correta":4,"explicacao":"Gabarito: <strong>precaveram … intervinha … o mantivessem</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3253,"enunciado":"A colocação pronominal está de acordo com a norma- -padrão em:","opcoes":["Agora peguei-me com uma saudade danada de visitar uma feira literária, conversar com leitores, assinar-lhes os livros, tirar a selfie de praxe.","Se observava, na biblioteca da escola, duas dezenas de alunos que aguardavam-me pacientemente para a apresentação.","Vestia-me com a camisa e gravata favoritas e corria para a estação de comboio, sempre encontrando-me com outros madrugadores.","Outros madrugadores como eu integraram-se ao leque de personagens, os quais me acompanharam da Flip em Paraty ao Africa Writes em Londres.","Agradaria-me visitar escolas do ensino secundário no Portugal mais remoto, o que, tendo mudado-me para Berlim, deixei de fazer."],"correta":3,"explicacao":"Gabarito: <strong>Outros madrugadores como eu integraram-se ao leque de personagens, os quais me acompanharam da Flip em Paraty ao Africa Writes em Londres.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3254,"enunciado":"Em qual dos trechos abaixo a colocação do pronome em destaque segue uma variedade NÃO padrão da língua portuguesa escrita?","opcoes":["“Sempre que o acompanho nas compras, querendo tornar mais leve o enfrentamento de carrinhos cheios e filas, resta-me observar o alheio.”","“Apreciando esse ou aquele, nos lembramos do que está faltando em nossas prateleiras e começa o corre-corre entre os corredores em busca de mais um produto, enquanto o parceiro segura o lugar na fila.”","“Não é algo que me incomode muito, mas, ainda assim, não tenho tido muita chance de fazê-lo.”","“Sempre que o acompanho nas compras, querendo tornar mais leve o enfrentamento de carrinhos cheios e filas, resta-me observar o alheio.”"],"correta":1,"explicacao":"Gabarito: <strong>“Apreciando esse ou aquele, nos lembramos do que está faltando em nossas prateleiras e começa o corre-corre entre os corredores em busca de mais um produto, enquanto o parceiro segura o lugar na fila.”</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3255,"enunciado":"O público e os pescadores costumam \"considerá-lo\" um peixe não comercial. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["próclise.","ênclise.","mesóclise.","anáclise."],"correta":1,"explicacao":"Gabarito: <strong>ênclise.</strong>.","banca":"ACAFE","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3256,"enunciado":"Considere os trechos a seguir. • ______________ a oportunidade de estudar astronomia. • ______________ que os estudos sobre a vida no espaço avancem. • Sempre ______________ a respeito das pesquisas que realiza. Assinale a alternativa que preenche, correta e respectivamente, as lacunas de acordo com a norma-padrão de colocação pronominal.","opcoes":["Haviam-lhe dado ... Espera-se ... lhe perguntam","Haviam dado-lhe ... Se espera ... lhe perguntam","Lhe haviam dado ... Espera-se ... lhe perguntam","Haviam dado-lhe ... Se espera ... perguntam-lhe","Haviam-lhe dado ... Espera-se ... perguntam-lhe"],"correta":0,"explicacao":"Gabarito: <strong>Haviam-lhe dado ... Espera-se ... lhe perguntam</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3257,"enunciado":"Assinale a afirmativa que possui o emprego de ênclise:","opcoes":["Sempre se deve agir com imparcialidade ao tomar decisões que envolvam o interesse público.","Compromete-se o servidor público a agir com transparência e integridade em suas funções.","Conceder-se-á aos servidores públicos um prazo para apresentar justificativas sobre seus atos administrativos.","Cumprir-se-ão rigorosamente as normas de conduta ética estabelecidas para o serviço público."],"correta":1,"explicacao":"Gabarito: <strong>Compromete-se o servidor público a agir com transparência e integridade em suas funções.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3259,"enunciado":"Marque a alternativa em que a colocação pronominal está INCORRETA.","opcoes":["Não me entregaram o documento no prazo estipulado.","Entregaram-me o relatório sem os anexos obrigatórios.","Preciso ver-te antes da reunião.","Fizeram-nos uma proposta interessante.","Nos informaram sobre as mudanças no regulamento."],"correta":4,"explicacao":"Gabarito: <strong>Nos informaram sobre as mudanças no regulamento.</strong>.","banca":"CETREDE","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3260,"enunciado":"Julgue o item a seguir, referente às ideias e a aspectos linguísticos do texto precedente. No trecho “O aborrecimento dá-nos a noção do tempo; a distração tira-a.” (oitavo período), as formas pronominais “nos” e “a” poderiam ser ambas deslocadas para a posição proclítica, sem prejuízo da correção gramatical do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3261,"enunciado":"Assinale a alternativa que apresenta a colocação pronominal correta:","opcoes":["Me entregou o trabalho.","Entregou-me o trabalho.","Não viu-me.","Viu ele-me. desvendar o mistério."],"correta":1,"explicacao":"Gabarito: <strong>Entregou-me o trabalho.</strong>.","banca":"Prefeitura de Rio Negro - PR","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3262,"enunciado":"Assinale a alternativa incorreta:","opcoes":["Rapidamente nos atendem se formos simpáticos;","Te chamei há horas;","Quantos te disseram a mesma resposta?","Ninguém te vai ouvir."],"correta":1,"explicacao":"Gabarito: <strong>Te chamei há horas;</strong>.","banca":"EVO Concursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3263,"enunciado":"Das alternativas a seguir, a única em desacordo com as regras de colocação pronominal é:","opcoes":["Nunca me esqueci de Daniely.","Dir-te-ei sempre a verdade.","Ele sempre se esforçou para ser o melhor.","Me diga o que aconteceu ontem."],"correta":3,"explicacao":"Gabarito: <strong>Me diga o que aconteceu ontem.</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3264,"enunciado":"Assinale a alternativa correta:","opcoes":["Orgulhar-me-ei dos meus alunos – mesóclise;","Depois de terminar, nos chamem. - próclise","Não o quero aqui. – ênclise;","Gostaria de te pentear à minha maneira. - ênclise"],"correta":0,"explicacao":"Gabarito: <strong>Orgulhar-me-ei dos meus alunos – mesóclise;</strong>.","banca":"EVO Concursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3265,"enunciado":"Observando o excerto abaixo, é possível perceber que as três formas pronominais destacadas são utilizadas de forma enclítica, ou seja, pospostas à forma verbal. Olhou-se no espelho e achou-se bonita. Para uma ex-barata. Maquiou-se. Esse uso é justificado por:","opcoes":["As formas verbais estarem conjugadas no mesmo tempo, ou seja, pretérito perfeito do indicativo.","Serem todas formas verbais pertencentes à primeira conjugação (-AR).","Escolha narrativa do autor, buscando, desta forma, criar um cenário mais rebuscado, típico do gênero textual em questão.","O uso é facultativo, portanto, a troca pela forma proclítica não alteraria a gramaticalidade e nem o sentido do enunciado.","Nas três ocasiões trata-se de início de uma oração e, segundo as normas vigentes da gramática, não é possível iniciar oração com pronome oblíquo."],"correta":4,"explicacao":"Gabarito: <strong>Nas três ocasiões trata-se de início de uma oração e, segundo as normas vigentes da gramática, não é possível iniciar oração com pronome oblíquo.</strong>.","banca":"PS Concursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3267,"enunciado":"Sobre a colocação pronominal exposta no excerto: “[...] nunca mais que se fechava o escritório [...]”, assinale a alternativa CORRETA:","opcoes":["Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. No caso, pronome demonstrativo.","Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes indefinidos e interrogativos.","Trata-se de ênclise, que é a colocação pronominal antes do verbo. A ênclise é usada quando o verbo estiver precedido de palavras negativas que atraem o pronome para antes do verbo.","Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. No caso, pronome relativo.","Trata-se de ênclise, que é a colocação pronominal depois do verbo. A ênclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: conjunções adversativas."],"correta":3,"explicacao":"Gabarito: <strong>Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. No caso, pronome relativo.</strong>.","banca":"UFCG","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3269,"enunciado":"Sobre a colocação pronominal exposta no excerto: “[...] e propôs que se dançasse o minuete da corte [...]”, assinale a alternativa CORRETA:","opcoes":["Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes demonstrativos.","Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes indefinidos.","Trata-se de ênclise, que é a colocação pronominal antes do verbo. A ênclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes relativos.","Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes relativos.","Trata-se de ênclise, que é a colocação pronominal depois do verbo. A ênclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes demonstrativos."],"correta":3,"explicacao":"Gabarito: <strong>Trata-se de próclise, que é a colocação pronominal antes do verbo. A próclise é usada quando o verbo estiver precedido de palavras que atraem o pronome para antes do verbo. São elas: pronomes relativos.</strong>.","banca":"UFCG","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3271,"enunciado":"Segundo a gramática normativa, a oração “Te amarei para sempre”, que encerra o texto, deveria prever, quanto à colocação do pronome átono “te”, o emprego da","opcoes":["próclise: amarei&#8209;te.","ênclise: amarei&#8209;te.","mesóclise: te&#8209;amarei.","mesóclise: amar&#8209;te&#8209;ei.","ênclise: amar&#8209;te&#8209;ei."],"correta":3,"explicacao":"Gabarito: <strong>mesóclise: amar&#8209;te&#8209;ei.</strong>.","banca":"Quadrix","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3272,"enunciado":"O uso da próclise (pronome antes do verbo) não está correto em qual das alternativas abaixo?","opcoes":["Não o vi na festa.","Isso me deixa triste.","Embora se esforçasse, não conseguia aprender.","Me orgulharei sempre do seu sucesso.","Quando te deram o aumento salarial?"],"correta":3,"explicacao":"Gabarito: <strong>Me orgulharei sempre do seu sucesso.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3273,"enunciado":"A ênclise está aplicada em conformidade com a norma-padrão da língua portuguesa apenas em:","opcoes":["Despedirei-me dos alunos assim que possível.","Um dia tudo transforma-se em pó.","Sempre lembro-me daquele verão.","A companhia de teatro enviou uma carta, convidando-o para o evento.","Aquela conversa teria dado-lhe ainda mais expectativas."],"correta":3,"explicacao":"Gabarito: <strong>A companhia de teatro enviou uma carta, convidando-o para o evento.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3274,"enunciado":"Não se usa próclise (pronome antes do verbo) em qual das alternativas abaixo?","opcoes":["Ninguém o respeita, apesar de todo o seu profissionalismo.","Se me derem oportunidade, vou mudar minha declaração.","Aquela professora é muito exigente, nada lhe deixa feliz.","Eu te ajudaria, se você pedisse.","Estou sem conseguir entender o que se passou na reunião."],"correta":3,"explicacao":"Gabarito: <strong>Eu te ajudaria, se você pedisse.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3275,"enunciado":"[Questão inédita] Quanto à colocação pronominal, marque a alternativa em que a próclise não é obrigatória.","opcoes":["Ela se chamava Dona Ilka.","Talvez por medo de que ela se materializasse aqui ao meu lado e exigisse o “Dona”,","onde se viu tratar professora pelo primeiro nome, menino?","No meu tempo ainda não se usava o “tia”.","nem era nada de que me orgulhasse."],"correta":0,"explicacao":"Gabarito: <strong>Ela se chamava Dona Ilka.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3276,"enunciado":"Analise a colocação pronominal dos excertos apresentados a seguir: I. Ou não se confessar nem a si próprio. II. Mas angústia faz parte: o que é vivo, por ser vivo, se contrai. III. Enquanto se espera que o coração entenda. De acordo com a norma-padrão da língua portuguesa, nos casos apresentados, a ênclise não é vetada apenas em:","opcoes":["I.","II.","III.","I e II.","II e III"],"correta":1,"explicacao":"Gabarito: <strong>II.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3278,"enunciado":"Analise as expressões abaixo e destaque, posteriormente, a alternativa que completa corretamente as lacunas. I - _______________ tudo sobre o ocorrido. (Me conte / Conte-me/ Conte-me-ia) II – Tinha ________________ com a resolução do problema. (comprometido-se / se comprometido / comprometido-se-ia) III - ________________ todas as promessas realizadas. (Contaria-me / Contar-me-ia/ Me contaria) IV – Paulinha não _______________ com o projeto. (envolveu-se / se envolveu / envolveu-se-ia)","opcoes":["Conte-me / comprometido-se / Contaria-me / envolveu-se","Me conte / se comprometido / Me contaria/ envolver-se-ia","Conte-me / se comprometido / Contar-me-ia / se envolveu","Contar-me-ia / comprometido-se / Me contaria/ envolveu-se","Me conte/ se comprometido / Contaria-me / se envolveu"],"correta":2,"explicacao":"Gabarito: <strong>Conte-me / se comprometido / Contar-me-ia / se envolveu</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3279,"enunciado":"O uso da ênclise está correto apenas em:","opcoes":["Alegra-me o fato de estar ao seu lado.","Não procurou-lhe porque estava com medo.","Nada agradava-me naquele lugar.","Em tratando-se de saúde, aumentam as preocupações.","Quando perguntarem-nos sobre isso, negaremos tudo."],"correta":0,"explicacao":"Gabarito: <strong>Alegra-me o fato de estar ao seu lado.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3281,"enunciado":"\"A cola também participou das primeiras formas de arte. Se você tivesse um pigmento e quisesse aderi-lo à parede da caverna, precisaria acrescentar algo... uma resina ou amido, explica a professora.\" A posição dos pronomes átonos na frase pode mudar dependendo de diversos fatores, como o tempo e o modo verbais, a pessoa do discurso, a ênfase desejada, a clareza, o nível de formalidade, entre outros. No enunciado, a ênclise ocorreu de forma correta, pois em locuções verbais o pronome átono pode ficar após o verbo principal. Nos enunciados a seguir, a ênclise também está empregada de acordo com as regras da norma culta, EXCETO:","opcoes":["Eles devem nos avisar em breve.","Espero vê-lo hoje.","Tomem esta joia e guardem-na em local seguro.","É preciso encontrar um meio de não magoá-lo.","Quando eu avisar, silenciem-se todos."],"correta":0,"explicacao":"Gabarito: <strong>Eles devem nos avisar em breve.</strong>.","banca":"AMAUC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3282,"enunciado":"\"Consultei especialistas da história da teologia, entre outros, e pouco a pouco trabalhamos juntos para abordar o texto e finalmente decifrá-lo.\" A ênclise é o nome dado à colocação do pronome após o verbo, ligando-se a ele por meio do hífen, como no exemplo do enunciado. A ênclise foi empregada em todos os enunciados a seguir. No entanto, em um deles, seu emprego não seguiu as normas gramaticais. Identifique-o:","opcoes":["\"Espero vê-lo hoje.\"","\"Viram-nos aqui.\"","\"Quando voltava do trabalho, me parecia bem cansado.\"","\"Diga-me toda a verdade.\""],"correta":2,"explicacao":"Gabarito: <strong>\"Quando voltava do trabalho, me parecia bem cansado.\"</strong>.","banca":"ACAFE","ano":2025,"temas_relacionados":["colocacaoPronominal","hifen"]},{"id":3284,"enunciado":"Entre as frases abaixo há uma em que não foi respeitada a norma padrão em relação à colocação de pronomes oblíquos; assinale essa frase.","opcoes":["A derrota não é amarga se você não a engolir.","Afligir-se antes do tempo é afligir-se duas vezes.","A estupidez de gente brilhante nunca deixa de assombrar-me.","Todo mundo me odeia porque sou popular.","Me indigno, logo existo."],"correta":4,"explicacao":"Gabarito: <strong>Me indigno, logo existo.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3287,"enunciado":"Na palavra “Substituí-los”, a colocação do pronome oblíquo é classificada como:","opcoes":["Epêntese.","Próclise.","Mesóclise.","Ênclise."],"correta":3,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3288,"enunciado":"Quanto ao uso dos pronomes notamos duas situações nas quais são usados diferentes colocações em relação ao verbo. Vejamos: “Ele reclinou-se mais um pouco...” e “O rapaz de bigode pediu aos outros que se afastassem...”. Considerando as regras de colocação pronominal, qual das alternativas a seguir está incorreta?","opcoes":["A homologação deste processo seletivo dar-se-á no dia 03/02/2025.","Não se preocupe. A prova não está tão difícil.","Informaram-nos de que o gabarito será divulgado a partir das 20h.","Lhe desejo uma boa prova."],"correta":3,"explicacao":"Gabarito: <strong>Lhe desejo uma boa prova.</strong>.","banca":"Wisdom","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3290,"enunciado":"Analise a colocação pronominal em cada alternativa abaixo. Assinale a alternativa incorreta.","opcoes":["Tomara que se concretizem todos os seus sonhos.","Quem me ligou?","Dizer-lhe-ei tudo que sei.","“Amar-te e dar a vida por ti”.","Nos chamaram para trabalhar nas férias."],"correta":4,"explicacao":"Gabarito: <strong>Nos chamaram para trabalhar nas férias.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3291,"enunciado":"Em relação à colocação pronominal, de acordo com a norma-padrão da língua portuguesa, o único caso em que não se poderia aplicar a próclise é:","opcoes":["Deixei-me levar pelas aparências.","Ela pediu-lhe que fizesse as compras da semana.","A família planejar-se-ia para as férias.","Comprei este presente para agradá-lo.","Usaria esta roupa, mas decidi emprestá-la."],"correta":0,"explicacao":"Gabarito: <strong>Deixei-me levar pelas aparências.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3292,"enunciado":"É correto o emprego da ênclise (colocação dos pronomes oblíquos átonos depois do verbo) apenas em qual das alternativas abaixo?","opcoes":["Aqui pode-se construir prédios livremente.","Alguém procurou-me?","Eu não quero-te aqui.","Por favor, traga-me o cardápio.","Isso alegrou-o muito."],"correta":3,"explicacao":"Gabarito: <strong>Por favor, traga-me o cardápio.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3293,"enunciado":"Quanto à colação pronominal, assinale a alternativa incorreta:","opcoes":["A colocação pronominal indica a posição dos pronomes átonos - me, nos, te, vos, se, o(s), a(s), lhe(s) - em relação ao verbo, do que resulta a próclise, a mesóclise e a ênclise.","A colocação pronominal é feita com base em prioridades. O caso que tem mais prioridade é a próclise, e se nenhuma das situações satisfizer o seu uso, é utilizada a ênclise.","Na próclise, o pronome é colocado antes do substantivo. Isso acontece quando a oração contém palavras que atraem o pronome.","A oração: Para começar, joguem-lhes a bola! Contém um exemplo de ênclise.","A oração: Rapidamente atendem-nos se formos simpáticos, deveria ser escrita: Rapidamente nos antendem se formos simpáticos."],"correta":2,"explicacao":"Gabarito: <strong>Na próclise, o pronome é colocado antes do substantivo. Isso acontece quando a oração contém palavras que atraem o pronome.</strong>.","banca":"FACET Concursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3294,"enunciado":"Leia com atenção as afirmativas abaixo: I.Encontrar-te-ei assim que os sinos tocarem. II.Observou-me lavar o carro. III.Perguntou-me se poderia ajudá-lo. IV.Calar-me-ei diante de tamanho despreparo. V.Não lhe responderei nada do que perguntas. Em quais das afirmativas lidas há o emprego de mesóclise?","opcoes":["I, III e V.","II e III.","I e IV.","II e IV."],"correta":2,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"IGEDUC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3295,"enunciado":"Leia atenciosamente as alternativas abaixo e assinale aquela que possui o emprego de ênclise:","opcoes":["Quem te enviou as flores?","O maior objetivo de Ariela é casar-se.","Orgulhar-me-ei de todas as minhas vitórias.","Embora se apaixonasse facilmente, estava sempre sozinha."],"correta":1,"explicacao":"Gabarito: <strong>O maior objetivo de Ariela é casar-se.</strong>.","banca":"IGEDUC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3296,"enunciado":"Leia com atenção as colunas abaixo: Coluna 01: (__)Conforme lhes foi informado, não haverá folgas. (__)Emocionei-me com o seu discurso. (__)Antes de começarmos, levantem-se. (__)Nunca o vi chegar cedo. (__)Calar-me-ei se achar necessário. Coluna 02: I.Ênclise. II.Mesóclise. III.Próclise. Correlacione as colunas acima de acordo com a posição dos pronomes átonos em relação ao verbo da oração. Após análise, assinale a alternativa que indica a sequência correta:","opcoes":["III > I > I > III > II.","I > II > II > I > III.","I > III > III > I > II.","II > III > III > II > I."],"correta":0,"explicacao":"Gabarito: <strong>III > I > I > III > II.</strong>.","banca":"IGEDUC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3297,"enunciado":"Julgue o item subsequente, referente a construções linguísticas do texto apresentado. Estaria mantida a correção gramatical do texto caso se empregasse a ênclise do pronome “se” no segundo e no terceiro períodos, haja vista a falta de critério impositivo da próclise pronominal nesses períodos.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3298,"enunciado":"Em relação aos sentidos e a aspectos linguísticos do texto apresentado, julgue o item que se segue. No segmento “que vinha oferecer-me” (quarto período), também estaria correto o uso de próclise do pronome ao auxiliar — que me vinha oferecer.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3299,"enunciado":"Em relação ao texto 9A1 e a aspectos gramaticais a ele relacionados, julgue o item que se segue. No último período do texto, a substituição de “se faz” por faz-se manteria a correção gramatical do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3300,"enunciado":"Verifica-se colocação pronominal mesoclítica apenas em:","opcoes":["Pretende-se viajar nas férias.","Tomar-lhe-iam todas as suas coisas, se não fosse cuidadoso.","Não se recuperou ainda daquela doença.","As meninas enviaram-me um presente de aniversário.","Os protocolos lhe seriam enviados antes do feriado."],"correta":1,"explicacao":"Gabarito: <strong>Tomar-lhe-iam todas as suas coisas, se não fosse cuidadoso.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3301,"enunciado":"A próclise é possível em todas as sentenças a seguir, exceto em:","opcoes":["Comprei isto para ajudá-lo.","Por meio deste processo ter-se-iam resultados mais eficientes.","Ana contou-me que viajará daqui a três dias.","Comprou o anel e, tomando-lhe a mão, fez o pedido de casamento.","Eles haviam-no declarado vencedor do combate."],"correta":3,"explicacao":"Gabarito: <strong>Comprou o anel e, tomando-lhe a mão, fez o pedido de casamento.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3302,"enunciado":"Leia o trecho a seguir, adaptado do texto de Fabrício Carpinejar, e analise a colocação pronominal em destaque: \"Não me senti mal. Não me senti desvalorizado. Quem nunca se perguntou isso?\" Com base nas normas gramaticais da língua portuguesa, identifique a alternativa correta quanto ao uso da colocação pronominal:","opcoes":["No período \"não me senti mal\", a próclise ocorre por convenção estilística e não por regra gramatical, sendo possível a ênclise se o autor desejasse realçar o verbo.","A colocação pronominal em \"não me senti mal\" poderia ser alterada para ênclise (\"não senti-me mal\") sem prejuízo à correção gramatical, já que ambas são formas aceitáveis na norma culta.","A próclise em \"não me senti mal\" ocorre devido à regência do verbo senti, que exige que o pronome seja posicionado antes do verbo em qualquer construção.","O uso da próclise no verbo \"senti\" em \"não me senti mal\" é obrigatório, uma vez que a palavra negativa \"não\" exerce atração sobre o pronome."],"correta":3,"explicacao":"Gabarito: <strong>O uso da próclise no verbo \"senti\" em \"não me senti mal\" é obrigatório, uma vez que a palavra negativa \"não\" exerce atração sobre o pronome.</strong>.","banca":"Unesc","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":3303,"enunciado":"A regra de uso de pronome identificada na sentença “[...] assim como quem se despede da vida[..]” é igualmente empregada em:","opcoes":["O escriturário me perguntou o que eu estava fazendo.","Todos se comoveram diante do discurso de despedida dele.","O bom senso do mundo, aplicando-se em ideias imaginárias.","Chamaram-no para ser sócio da empresa em que ele trabalhou."],"correta":1,"explicacao":"Gabarito: <strong>Todos se comoveram diante do discurso de despedida dele.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3305,"enunciado":"Conforme a NORMA CULTA da Língua Portuguesa, assinale a alternativa em que a colocação pronominal está correta.","opcoes":["Te odeio.","Alguém viu-nos.","Não me perturbe.","Ele nunca ajudou-te.","Me conte sobre a viagem."],"correta":2,"explicacao":"Gabarito: <strong>Não me perturbe.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3306,"enunciado":"Analise os excertos a seguir, retirados do texto, quanto à colocação pronominal. Assinale a alternativa em que se verifica ênclise.","opcoes":["Lembrou-se, então, com uma intensidade que quase o sufocou, do time.","Era como o chamavam pelas costas.","Tentou se lembrar do sobrenome.","Lembrava das reuniões no galpão atrás da casa do Chico Babão.","— Só me deixavam jogar de centroavante porque a bola era minha…"],"correta":0,"explicacao":"Gabarito: <strong>Lembrou-se, então, com uma intensidade que quase o sufocou, do time.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3307,"enunciado":"Assinale a alternativa em que o enunciado atende à norma-padrão de colocação pronominal.","opcoes":["Adaptou-se Beethoven à sua condição de surdez, demonstrando-se que limitações físicas não impediram-no de compor obras imortais.","Como poderiam-se imaginar que Django Reinhardt, com dois dedos paralisados, seria um imortal guitarrista do jazz?","Se acredita que as adversidades enfrentadas pelos artistas mencionados nos inspiraram a superar suas limitações físicas.","Portinari expôs-se continuamente a tintas às quais era alérgico, sabendo-se que isso poderia ser prejudicial à sua saúde.","Harold Lloyd, faltando-lhe dois dedos, escalou um edifício em Nova York, tendo realizado-se quase todas as cenas arriscadas por ele mesmo."],"correta":3,"explicacao":"Gabarito: <strong>Portinari expôs-se continuamente a tintas às quais era alérgico, sabendo-se que isso poderia ser prejudicial à sua saúde.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3308,"enunciado":"O pronome oblíquo foi posicionado adequadamente, de acordo com as regras de colocação pronominal da norma-padrão da língua portuguesa, em:","opcoes":["Os especialistas disseram que lançaram-se novos modelos de acordo a conferência.","As regulamentações sugeridas aplicar-se-ão apenas após a assinatura dos tratados internacionais.","Poderiam-se implementar práticas inovadoras caso haja interesse comum.","Se discutem instâncias, até então negligenciadas, do impacto da tecnologia nas culturas locais.","Mesmo que haja divergências, se sugerem estratégias que se poderão ajustar às novas exigências."],"correta":1,"explicacao":"Gabarito: <strong>As regulamentações sugeridas aplicar-se-ão apenas após a assinatura dos tratados internacionais.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3310,"enunciado":"Assinale a alternativa em que a alteração da posição do pronome em relação ao verbo tenha ocorrido em obediência à norma culta.","opcoes":["“[...] propor que os moradores se envolvessem na administração da livraria” — “[...] propor que os moradores envolvessem-se na administração da livraria”.","“[...] foi incentivado a estudar e se capacitar como técnico em biblioteca” — “[..] foi incentivado a estudar e capacitar- se como técnico em biblioteca’.","“Isso me afastava das ruas[...] — “Isso afastava-me das ruas [..]”.","“[...] depois que se formou [...]' — “[...] depois que formou- se [..]”."],"correta":1,"explicacao":"Gabarito: <strong>“[...] foi incentivado a estudar e se capacitar como técnico em biblioteca” — “[..] foi incentivado a estudar e capacitar- se como técnico em biblioteca’.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3311,"enunciado":"Assinalar a alternativa que apresenta o erro de construção do trecho a seguir: Com as descobertas que os cientistas vêm realizando, não se pode ter dúvida de que, daqui há alguns anos, será possível clonar seres humanos.","opcoes":["“vêm” deve ser substituído por “vem”.","“se pode” deve ser substituído por “pode-se”.","“há” deve ser substituído por “a”.","“será” deve ser substituído por “seria”."],"correta":2,"explicacao":"Gabarito: <strong>“há” deve ser substituído por “a”.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3313,"enunciado":"Analise as sentenças a seguir em relação à colocação pronominal. A sentença que apresenta inadequação em relação à ênclise é:","opcoes":["Sentei-me para esperar o táxi.","Ana me pediu para colocá-la neste grupo de trabalho.","Eu tenho falado-lhe a respeito desses assuntos porque os considero importantes.","Fizeram-na passar vergonha no colégio.","Preciso encontrar alguém que possa ajudá-lo com os exercícios de Química."],"correta":2,"explicacao":"Gabarito: <strong>Eu tenho falado-lhe a respeito desses assuntos porque os considero importantes.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3314,"enunciado":"Analise as sentenças a seguir e assinale a alternativa em que se verifica a colocação pronominal correta, segundo a norma-padrão da língua portuguesa.","opcoes":["Lhe compraram todos os presentes que esperava receber.","Desconheço alguém que interessa-se por literatura.","Ainda não entreguei-lhe os livros emprestados.","Os exercícios de matemática vão ajudá-lo no vestibular.","Os pais decidiram a colocar nas aulas de natação ainda bebê."],"correta":3,"explicacao":"Gabarito: <strong>Os exercícios de matemática vão ajudá-lo no vestibular.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3315,"enunciado":"Considerando-se as regras de colocação pronominal, assinalar a alternativa CORRETA:","opcoes":["Nunca disse-lhes o que pensava a respeito desse assunto.","A surpreendeu com um grito.","Talvez nos tenham explicado errado.","O lugar para onde levou-a era seguro."],"correta":2,"explicacao":"Gabarito: <strong>Talvez nos tenham explicado errado.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3316,"enunciado":"Analise a colocação pronominal nas frases indicadas a seguir e identifique as inadequações. I. Quem nos ajudará se precisarmos? II. Você sabe que vai se arrepender. III. Darei -lhe todas as informações necessárias. IV. Poderia-se fazer uma campanha social. V. Nossa equipe havia encontrado-se antes da votação final. Quais frases desrespeitam a colocação pronominal, segundo o padrão de norma culta da língua portuguesa no Brasil?","opcoes":["Apenas I e II.","Apenas II e III.","Apenas III e IV.","Apenas III, IV e V."],"correta":3,"explicacao":"Gabarito: <strong>Apenas III, IV e V.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3319,"enunciado":"Analise as seguintes frases quanto à colocação pronominal: I. \"Me diga o que você pensa sobre isso.\" - A colocação do pronome \"me\" antes do verbo indica um exemplo de próclise, corretamente utilizada neste contexto. II. \"Não se preocupe com os detalhes.\" - A colocação do pronome \"se\" antes do verbo demonstra um uso incorreto da ênclise. III. \"Espero encontrá-lo em breve.\" - A colocação do pronome \"lo\" após o verbo é um exemplo de mesóclise.","opcoes":["Apenas I e II estão corretas.","Apenas II e III estão corretas.","Apenas I e III estão corretas.","Apenas I está correta."],"correta":3,"explicacao":"Gabarito: <strong>Apenas I está correta.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3320,"enunciado":"Em \"se sentem melhor ao fazer uma dieta de limpeza\", o pronome \"se\" é um exemplo de qual colocação pronominal?","opcoes":["Próclise.","Ênclise.","Epêntese.","Mesóclise."],"correta":0,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3321,"enunciado":"A colocação pronominal determina a posição do pronome oblíquo em relação ao verbo. Sendo assim, assinalar a alternativa em que a colocação pronominal atende à norma-padrão:","opcoes":["Me enrolei com o prazo de entrega do artigo da faculdade.","Conforme passei-lhe, hoje vou chegar mais tarde.","Acorde-me quando ela chegar da aula de balé.","Nunca disse-te para concorda com ele.","Lhe disse mais de uma vez!"],"correta":2,"explicacao":"Gabarito: <strong>Acorde-me quando ela chegar da aula de balé.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3322,"enunciado":"Captura_de tela 2025-06-02 145324.png (179×100) google.com.br Aludindo-se à colocação pronominal, leia os itens e assinale a alternativa correspondente. I- A ênclise ocorre também, quando o verbo está no gerúndio. II- Também acontece a ênclise, com o verbo no infinitivo impessoal. III- Ocorre a próclise também, quando, antes do verbo, vier um pronome indefinido. IV- Acontece também a próclise, quando, antes do verbo, vier um advérbio.","opcoes":["Apenas os itens I e IV estão corretos.","Todos os itens estão corretos.","Apenas os itens I, II e III estão corretos.","Apenas os itens II e IV estão corretos."],"correta":1,"explicacao":"Gabarito: <strong>Todos os itens estão corretos.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3323,"enunciado":"Assinale a alternativa em que se verifica o pronome átono colocado em mesóclise.","opcoes":["Disseram-me que os gatos são mais independentes que os cachorros.","Nós o encontramos no restaurante.","Eles não querem te contar o motivo da briga.","Cobrar-lhe-iam se não tivesse aparecido a tempo.","Os vasos quebraram-se durante a madrugada."],"correta":3,"explicacao":"Gabarito: <strong>Cobrar-lhe-iam se não tivesse aparecido a tempo.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3324,"enunciado":"Assinale a alternativa em que há desvio de colocação pronominal, segundo a norma-padrão.","opcoes":["Espera-se que todas as coisas fiquem bem resolvidas.","Não me comunicaram sobre as férias coletivas.","Ajudar-me-am com a correção das provas.","O espírito guardião acompanhar-lhe-á por onde for.","Ela esperava que a filha se tornasse professora, e não atriz."],"correta":2,"explicacao":"Gabarito: <strong>Ajudar-me-am com a correção das provas.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3325,"enunciado":"Considere as afirmações sobre o excerto seguinte, marque V, para verdadeiro, ou F, para falso, e depois assinale a alternativa CORRETA. \"Nesses ambientes abertos, degradados, inóspitos, as embaúbas se instalam e crescem avidamente. Até parece que têm pressa. Logo ficam altas, suas folhas se desenvolvem, mas duram pouco e morrem rápido, caindo enrugadas e marrons no chão, decompondo-se e devolvendo nutrientes para a terra.\" (parágrafo 13) ( ) A palavra \"avidamente\" modifica o sentido do verbo \"crescer\". ( ) A palavra \"pressa\" complementa o sentido do verbo \"parecer\". ( ) Em \"decompondo-se\", a ênclise se justifica porque o verbo \"decompor\" está no gerúndio. ( ) A palavra \"nutrientes\" é complemento objeto direto do verbo \"devolver\". ( ) A palavra \"terra\" é complemento objeto indireto do verbo \"devolver\".","opcoes":["V, F, V, V, V","V, F, V, F, F","F, F, V, V, F","F, F, V, V, V","V, F, V, F, V"],"correta":0,"explicacao":"Gabarito: <strong>V, F, V, V, V</strong>.","banca":"UEM","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3326,"enunciado":"Os excertos a seguir foram elaborados a partir dos Textos 01 e 02, assinale a alternativa que apresenta a correta colocação pronominal:","opcoes":["Não pode-se aceitar que as pesquisas sigam os padrões éticos distorcidos que bem entenderem.","Isso nos mostra a importância de discutirmos a ética em pesquisa durante a formação inicial.","Moreau e seus colegas fizeram sua parte. Os alertaram sobre mais de uma centena de artigos.","Moreau quis colaborar com os grupos minoritários os defendendo na ciência.","Alguém explicou-lhes a razão para não participar desses experimentos."],"correta":1,"explicacao":"Gabarito: <strong>Isso nos mostra a importância de discutirmos a ética em pesquisa durante a formação inicial.</strong>.","banca":"FURB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3328,"enunciado":"Em qual alternativa, a colocação pronominal foi empregada corretamente?","opcoes":["Tudo parece-me assustador, pois o futuro é incerto.","Ninguém ama-te como sua mãe verdadeira.","Bem se vê que no interior vive-se melhor.","No hospital, fala-se muito alto.","Por odiarem-se muito, a separação foi a única alternativa."],"correta":3,"explicacao":"Gabarito: <strong>No hospital, fala-se muito alto.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3329,"enunciado":"Analise as sentenças a seguir quanto à colocação pronominal: I. Ainda que seja difícil, ele contentar-se-á com a situação. II. Espera-se que tudo esteja resolvido até o casamento. III. Depois, os rapazes ajudaram-na a chegar até sua casa. IV. Corri para socorrê-lo. Considerando-se a norma-padrão gramatical, o pronome oblíquo átono poderia ocorrer também em próclise apenas em:","opcoes":["I e II.","II e III.","I e IV.","II, III e IV.","I, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, III e IV.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3330,"enunciado":"Em qual alternativa, a colocação pronominal não foi devidamente construída?","opcoes":["Tudo me parece tão complicado.","Aqui se come muito bem.","Por amarem-se muito, decidiram construir uma vida a dois.","Em se tratando de crianças, todo carinho é pouco.","Estou aqui para dar-te o meu melhor."],"correta":2,"explicacao":"Gabarito: <strong>Por amarem-se muito, decidiram construir uma vida a dois.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3331,"enunciado":"Assinale a alternativa correta, segundo o padrão culto da Língua:","opcoes":["Não ia dizendo-lhe o que aconteceu.","Lhe ia dizendo o que aconteceu.","Como ia-lhe dizendo, não me senti confortável naquele ambiente.","Alguns empresários estavam-lhe chamando para entrevistas."],"correta":0,"explicacao":"Gabarito: <strong>Não ia dizendo-lhe o que aconteceu.</strong>.","banca":"AGIRH","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3334,"enunciado":"Em: \"(...) e xingando ele.\", é inadequado afirmar:","opcoes":["A colocação pronominal deveria ser proclítica.","Na norma padrão, \"o\" substituiria \"ele\".","A forma verbal de gerúndio exige a ênclise.","O pronome foi empregado na norma informal."],"correta":0,"explicacao":"Gabarito: <strong>A colocação pronominal deveria ser proclítica.</strong>.","banca":"CETAP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3335,"enunciado":"Assinale a alternativa redigida em conformidade com a norma-padrão de concordância verbal e de colocação pronominal.","opcoes":["Fazem anos que pesquisadores têm interessado-se por novos sistemas agrícolas de produção de alimentos.","Devem haver diferentes estudos que ocupam-se de leis que versam sobre sistemas agrícolas.","Percebe-se que existe no mundo todo problemas relacionados à utilização irregular de agrotóxicos.","Buscam-se, no Brasil e em outros países, práticas agrícolas que não se mostrem nocivas ao meio ambiente.","Em diferentes partes do mundo, se veem práticas agrícolas que provocam degradação ambiental."],"correta":3,"explicacao":"Gabarito: <strong>Buscam-se, no Brasil e em outros países, práticas agrícolas que não se mostrem nocivas ao meio ambiente.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3336,"enunciado":"No verso \"Eu possa me dizer do amor (que tive)\":","opcoes":["A colocação pronominal destacada é um exemplo de próclise, onde o pronome oblíquo tônico \"me\" vem antes do verbo \"dizer\".","A colocação pronominal é um exemplo de próclise, onde o pronome oblíquo átono \"me\" vem antes do verbo \"dizer\".","A colocação pronominal é um exemplo de ênclise, onde o pronome oblíquo átono \"me\" se justapõe ao verbo \"dizer\".","A colocação pronominal “me” é totalmente inaceitável antes do verbo \"dizer\", por se tratar de um vício de linguagem.","A colocação pronominal é um exemplo de ênclise, onde o pronome oblíquo átono \"me\" vem depois da conjugação verbal “possa\"."],"correta":1,"explicacao":"Gabarito: <strong>A colocação pronominal é um exemplo de próclise, onde o pronome oblíquo átono \"me\" vem antes do verbo \"dizer\".</strong>.","banca":"IBPTEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3337,"enunciado":"A passagem destacada em negrito em – Pois quanto a anjos elas estão muito bem informadas, conhecem todos pelos seus nomes, certamente passeiam com eles de braço dado... – está reescrita de acordo com a norma-padrão em:","opcoes":["... conhecem-lhes pelos seus nomes, certamente têm-nos de braço dado ao passearem...","... conhecem-nos pelos seus nomes, certamente os têm de braço dado ao passearem...","... conhecem-lhes pelos seus nomes, certamente lhes têm de braço dado ao passearem...","... conhecem-os pelos seus nomes, certamente os têm de braço dado ao passearem...","... conhecem eles pelos seus nomes, certamente têm eles de braço dado ao passearem..."],"correta":1,"explicacao":"Gabarito: <strong>... conhecem-nos pelos seus nomes, certamente os têm de braço dado ao passearem...</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3338,"enunciado":"No trecho \"e se mova sem forçar os músculos\", o pronome se está em qual tipo de colocação pronominal?","opcoes":["Ênclise.","Próclise.","Mesóclise.","Epêntese."],"correta":1,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3343,"enunciado":"Com base no texto de Fabrício Carpinejar foram construídas algumas frases, a seguir, analise as alternativas abaixo e identifique a única frase que apresenta correta colocação pronominal de acordo com as regras da norma-padrão.","opcoes":["Cedi, é claro. E ela estava certa: os mineiros ainda estavam dançando, recusando-se a sair às 4h30 da manhã.","Beatriz rapidamente deixou-me a par de todo o roteiro daquela festa interminável.","Às 4h30 da manhã, ninguém recusava-se a dançar as músicas escolhidas pela noiva.","Os amigos gaúchos estavam tão cansados que abraçavam-se ao vaso sanitário no final da noite."],"correta":0,"explicacao":"Gabarito: <strong>Cedi, é claro. E ela estava certa: os mineiros ainda estavam dançando, recusando-se a sair às 4h30 da manhã.</strong>.","banca":"IBAM","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3345,"enunciado":"O conto, escrito no século XIX, apresenta colocação pronominal desabonada pela norma-padrão atual. Isso se evidencia na passagem:","opcoes":["... espécie dessas figuras com que se costuma fazer a imagem mítica dos grandes rios... (2º parágrafo)","Os mais antigos moradores do lugar lembravam-se de que Emílio fora sempre o mesmo homem... (3º parágrafo)","... era aquele velho que via-se de tarde, à janela da torre sob a cúpula enorme do sino grande... (2º parágrafo)","... sentiam só que ela fugisse tanto a meter-se na torre com o avô e esquecesse pelos velhos amigos de bronze... (4º parágrafo)","A pequena Rita admirava os sinos. Esta admiração transformava-se em amorosa simpatia. (6º parágrafo)"],"correta":2,"explicacao":"Gabarito: <strong>... era aquele velho que via-se de tarde, à janela da torre sob a cúpula enorme do sino grande... (2º parágrafo)</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3347,"enunciado":"Assinale a alternativa em que a reescrita do trecho – Festejavam muito aquela criança, davam a ela doces e beijos... (4º parágrafo) – está em conformidade com a norma-padrão.","opcoes":["Festejavam-lhe muito, davam-lhe doces e beijos...","Festejavam muito ela, davam-lhes doces e beijos...","Festejavam-a muito, davam-a doces e beijos...","Festejavam-na muito, davam-lhe doces e beijos...","Festejavam-la muito, davam-lhe doces e beijos..."],"correta":3,"explicacao":"Gabarito: <strong>Festejavam-na muito, davam-lhe doces e beijos...</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3348,"enunciado":"Analise o período que segue: \"O povo de casa não se aquietará até encontrar alguém para levar a comidinha.\" Com base nas regras de colocação pronominal, assinale a alternativa correta que analisa a posição do pronome oblíquo átono \"se\".","opcoes":["O pronome \"se\" deveria estar posicionado após o verbo, em ênclise, pois não há palavra atrativa que exija a próclise.","A colocação do pronome está correta, mas seria facultativa a utilização da mesóclise, devido à forma verbal no futuro do presente (\"aquietará\").","A próclise está incorreta, pois a colocação natural do pronome seria em mesóclise, já que o verbo está conjugado no futuro e não é precedido por palavras atrativas.","A colocação pronominal está correta, pois o advérbio de negação \"não\" atrai o pronome, justificando o uso da próclise."],"correta":3,"explicacao":"Gabarito: <strong>A colocação pronominal está correta, pois o advérbio de negação \"não\" atrai o pronome, justificando o uso da próclise.</strong>.","banca":"IBAM","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3351,"enunciado":"A colocação pronominal está em conformidade com a norma-padrão em:","opcoes":["Quando anuncia-se o fim da censura a filmes na Itália, essa discussão ganha novos capítulos.","Tendo consagrado-se como meio de comunicação no Brasil, a sétima arte sofreu censura.","Segundo a professora da USP, a utilização da censura não limita-se a regimes ditatoriais.","Se cria um conflito entre o que os cidadãos pensam e o que pensa a cultura hegemônica.","Os segmentos da sociedade rapidamente se organizaram, a fim de limitar o poder do cinema."],"correta":4,"explicacao":"Gabarito: <strong>Os segmentos da sociedade rapidamente se organizaram, a fim de limitar o poder do cinema.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3352,"enunciado":"Assinale a alternativa em que a frase está de acordo com a norma-padrão de emprego e colocação dos pronomes.","opcoes":["A versão que difundiu-se de “quem não tem cão, caça com gato” é equivocada.","Nos restou apenas a desagradável expressão “cuspida e escarrada”.","A enxurrada no Rio Grande do Sul só não provocou-me pesadelos porque sou insone.","Quanto às tentativas de socorro a bichos e idosos, parei de acompanhá-las.","Minha avó disse “mais surdo que um portão de cemitério”. Fiquei pensativo ao ouvir-lhe dizer isso pela primeira vez."],"correta":3,"explicacao":"Gabarito: <strong>Quanto às tentativas de socorro a bichos e idosos, parei de acompanhá-las.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3353,"enunciado":"Assinale a única alternativa em que a colocação pronominal atende à norma culta da língua portuguesa.","opcoes":["Quando o entregarem os recursos para a ampliação do saneamento básico no entorno do Rio Tietê, os utilize imediatamente.","Quando lhe entregarem os recursos para a ampliação do saneamento básico no entorno do Rio Tietê, utilize-os imediatamente.","Quando entregarem-no os recursos para a ampliação do saneamento básico no entorno do Rio Tietê, utilize-nos imediatamente.","Quando o entregarem os recursos para a ampliação do saneamento básico no entorno do Rio Tietê, utilize-lhes imediatamente.","Quando entregarem-lhe os recursos para a ampliação do saneamento básico no entorno do Rio Tietê, os utilize imediatamente."],"correta":1,"explicacao":"Gabarito: <strong>Quando lhe entregarem os recursos para a ampliação do saneamento básico no entorno do Rio Tietê, utilize-os imediatamente.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3354,"enunciado":"Analise a frase a seguir: Ela ficou pálida, talvez tenha raciocinado com um frio na barriga: \"onde eu me meti?\" Considerando que foram observadas as regras de colocação pronominal, analise as afirmações relacionadas a essa temática: I.As \"Conjunções subordinativas\" representam um caso obrigatório de próclise. II.Nos Verbos no imperativo afirmativo deve-se usar ênclise. III.Caso o verbo no futuro do presente ou no futuro do pretérito do indicativo venha precedido por pronome pessoal reto, ou de alguma palavra que exija a próclise, está será de rigor. Está CORRETO o que se afirma em:","opcoes":["I e II, apenas.","II e III, apenas.","I e III, apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3359,"enunciado":"Considere os trechos redigidos a partir do texto. • O universo da escrita é interessante. Muitas pessoas têm dominado o universo da escrita. • Há quem goste muito de livros. Grandes leitores sempre têm livros por perto. As expressões destacadas podem ser, correta e respectivamente, substituídas por:","opcoes":["o têm dominado ... têm-os","têm dominado-o ... os têm","têm dominado-o ... têm-nos","têm-no dominado ... os têm","têm-no dominado ... têm-nos"],"correta":3,"explicacao":"Gabarito: <strong>têm-no dominado ... os têm</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3360,"enunciado":"A alternativa em que o enunciado atende à norma-padrão de colocação pronominal é:","opcoes":["Certamente se vê que a juventude atual é materialmente mais privilegiada do que foram as anteriores.","Os jovens de hoje têm habituado-se a ficar mais tempo na casa dos pais e começam a trabalhar mais tarde.","Será que os jovens animariam-se com um novo modelo de vida, que fosse mais interativo e dinâmico?","Não deve-se procurar uma generalização simplista para explicar as aflições tão dramáticas dos jovens.","Se dizem mais solitários e socializam menos os jovens atuais, além de ficarem mais tempo na casa dos pais."],"correta":0,"explicacao":"Gabarito: <strong>Certamente se vê que a juventude atual é materialmente mais privilegiada do que foram as anteriores.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3361,"enunciado":"Considerando-se os aspectos de regência verbal, de flexão verbal e de emprego de pronome, a frase do primeiro quadro está reescrita de acordo com a norma-padrão em:","opcoes":["Não sei o que faço aos rapazes, pois queria dar a eles algo que realmente lhes satisfaz.","Não sei o que faço aos rapazes, pois queria dar-lhes algo que realmente os satisfizesse.","Não sei o que faço aos rapazes, pois queria dar-lhes algo que realmente satisfaça eles.","Não sei o que faço aos rapazes, pois queria dá-los algo que realmente lhes satisfizer.","Não sei o que faço aos rapazes, pois queria dar-nos algo que realmente satisfaz-lhes."],"correta":1,"explicacao":"Gabarito: <strong>Não sei o que faço aos rapazes, pois queria dar-lhes algo que realmente os satisfizesse.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3362,"enunciado":"Na reescrita de informações do texto, o emprego de pronomes e a colocação pronominal atendem à norma- -padrão em:","opcoes":["Meu pai dizia a mim sobre as práticas antigas que tínhamos de combatê-las.","Ficamos com o cão. Chamamos ele de Jasão, que se mostrava bem esperto.","Meu pai disse que o cão andou sempre a o seguir e não quis largar mais ele.","Quando ia para o Instituto, Jasão queria acompanhar-me. Levei-lhe às vezes.","Me corrija as faltas e a pontuação, camarada escritor, pelo que agradeço-lhe."],"correta":0,"explicacao":"Gabarito: <strong>Meu pai dizia a mim sobre as práticas antigas que tínhamos de combatê-las.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3363,"enunciado":"Considere as frases elaboradas a partir das ideias do texto. • Fumar era hábito corriqueiro entre as personagens, e elas _________desenfreadamente. • O estilo dos móveis é um dos detalhes para decifrar a época em que __________a história. • Ismênia faz ameaças ao marido, quando ele exagera em sua paixão pelos filmes, e ela eventualmente________ . Com base na norma-padrão de emprego e de colocação dos pronomes, as lacunas devem ser preenchidas, respectivamente, por:","opcoes":["praticavam-no; se passa; as cumpre","praticavam-no; passa-se; cumpre-as","o praticavam; se passa; cumpre-as","praticavam-lhe; se passa; cumpre-as","lhe praticavam; passa-se; as cumpre"],"correta":0,"explicacao":"Gabarito: <strong>praticavam-no; se passa; as cumpre</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3364,"enunciado":"Assinale a alternativa em que o questionamento de Mafalda, no 3° quadrinho, está reescrito em conformidade com a norma-padrão da língua portuguesa.","opcoes":["Como é que a gente os pode entender?","Como é que a gente pode entendê-los?","Como é que a gente pode entender-lhes?","Como é que a gente lhes pode entender?","Como é que a gente pode lhes entender?"],"correta":0,"explicacao":"Gabarito: <strong>Como é que a gente os pode entender?</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3365,"enunciado":"Assinale a alternativa em que o pronome pessoal oblíquo ocorre em próclise.","opcoes":["Os rapazes daquele colégio não se interessavam por nenhum esporte.","Avisaram-no de última hora sobre a festa de aniversário.","Minhas amigas disseram-me que não participarão da formatura.","Vê-lo-ei na próxima semana.","Contaria a ele tudo isso que contou a mim?"],"correta":0,"explicacao":"Gabarito: <strong>Os rapazes daquele colégio não se interessavam por nenhum esporte.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3366,"enunciado":"A colocação pronominal diz respeito ao posicionamento de um pronome oblíquo em relação ao verbo. Em muitos casos é possível a colocação dos pronomes em mais de uma posição, porém há casos em que apenas uma colocação é possível. Nesse sentido, assinale abaixo a única alternativa em que a colocação pronominal ocorreu de modo adequado ao uso culto da língua e ao que preceitua nossa gramática normativa.","opcoes":["Quando ele ajudar-te, jamais esqueça de agradecer.","A fim de não encontrá-lo, mudei o meu trajeto.","As informações que deram-te mexeram com você.","Me fale a verdade ou será você o responsável pelo problema que estamos enfrentando."],"correta":1,"explicacao":"Gabarito: <strong>A fim de não encontrá-lo, mudei o meu trajeto.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3367,"enunciado":"Assinale a única alternativa em que a colocação pronominal atende à norma culta da língua portuguesa.","opcoes":["Quando chamaram-me era muito tarde.","Nunca esquecerei-me de sua ajuda.","Tudo aquilo incomodava-lhe muito.","Lhe chamou a atenção a briga entre os candidatos.","Esperamos que nos venha visitar."],"correta":4,"explicacao":"Gabarito: <strong>Esperamos que nos venha visitar.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3368,"enunciado":"Considere as passagens: • Imaginou os filhos que aguardavam e já deviam estar acordados. Os filhos que ela odiava! (6º parágrafo) • Tratava bem a lata. (10º parágrafo) Quanto ao emprego de pronomes e à colocação pronominal, as reescritas das passagens atendem à norma-padrão em:","opcoes":["Imaginou os filhos que aguardavam-lhe e já deviam estar acordados. Odiava-lhes! / Tratava-na bem.","Imaginou os filhos que a aguardavam e já deviam estar acordados. Odiava-os! / Tratava-a bem.","Imaginou os filhos que aguardavam-la e já deviam estar acordados. Odiava-os! / Tratava-a bem.","Imaginou os filhos que aguardavam-na e já deviam estar acordados. Lhes odiava! / Tratava ela bem.","Imaginou os filhos que lhe aguardavam e já deviam estar acordados. Os odiava! / A tratava bem."],"correta":1,"explicacao":"Gabarito: <strong>Imaginou os filhos que a aguardavam e já deviam estar acordados. Odiava-os! / Tratava-a bem.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3369,"enunciado":"Analise a colocação pronominal das frases abaixo e marque a alternativa incorreta.","opcoes":["Não te falo mais nada.","Nunca se deve esquecer dos amigos.","Enquanto nos negarem os direitos essenciais, continuaremos lutando!","Quem te falou sobre o concurso?","Me envie a procuração assinada."],"correta":4,"explicacao":"Gabarito: <strong>Me envie a procuração assinada.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3370,"enunciado":"A seguir, foram apresentadas algumas declarações sobre diferentes aspectos da Língua Portuguesa. Identifique a alternativa que contenha uma afirmação ERRADA:","opcoes":["As orações subordinadas substantivas são aquelas que desempenham as funções próprias dos substantivos na frase. Essas funções podem ser de sujeito, predicativo, complemento nominal, objeto direto, objeto indireto e aposto.","A disposição dos pronomes átonos em relação ao verbo é chamada de colocação pronominal, resultando em três formas: próclise, mesóclise e ênclise. A colocação pronominal é determinada por prioridades. A ênclise é a opção prioritária, e caso nenhuma das circunstâncias atenda a essa escolha, recorre-se à próclise.","A crase não deve ser usada nas seguintes situações: antes de palavras masculinas; antes de verbos; antes de pronomes pessoais do caso reto (eu, tu, ele, nós, vós, eles) e do caso oblíquo (me, mim, comigo, te, ti, contigo, se, si, o, lhe); antes dos pronomes demonstrativos isso, esse, este, esta, essa.","O hífen é um sinal gráfico representado por um traço. É usado principalmente para ligar elementos (seja na formação de palavras compostas, em colocação pronominal ou na formação de palavras com prefixos específicos). Algumas de suas regras sofreram alteração no último acordo ortográfico.","Quando o sujeito é um termo coletivo, o verbo permanece na forma singular. Exemplificando: \"A multidão excedeu o limite\". \"O elenco demonstrava grande competência\". No entanto, quando o termo coletivo é especificado, o verbo pode ser conjugado tanto no singular quanto no plural. Exemplos: \"A multidão de fãs ultrapassou o limite\". \"A multidão de fãs ultrapassaram o limite\"."],"correta":1,"explicacao":"Gabarito: <strong>A disposição dos pronomes átonos em relação ao verbo é chamada de colocação pronominal, resultando em três formas: próclise, mesóclise e ênclise. A colocação pronominal é determinada por prioridades. A ênclise é a opção prioritária, e caso nenhuma das circunstâncias atenda a essa escolha, recorre-se à próclise.</strong>.","banca":"AMAUC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3371,"enunciado":"Qual das alternativas o pronome foi colocado de forma incorreta?","opcoes":["Nunca deve-se questionar os mais velhos.","Meus alunos abster-se-ão de participar da discussão.","Por favor, conte-me todas as novidades.","Não me julgues por seus próprios erros.","Disseram-me que você chegaria só amanhã."],"correta":0,"explicacao":"Gabarito: <strong>Nunca deve-se questionar os mais velhos.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3373,"enunciado":"Assinale a alternativa que apresenta uma análise correta da frase quanto à colocação pronominal:","opcoes":["“Meu desejo era não incomodá-lo.” / A frase está correta com a ênclise, pois o verbo está no infinitivo, tornando a próclise facultativa.","“O chefe pediu para responder-lhe com mais clareza.” / A frase está incorreta com a ênclise, pois o pronome está posposto ao verbo “responder”.","“A professora se mostrou animada durante a explicação.” / A frase está correta com a próclise, pois o pronome “se” está posposto ao verbo, já que não há palavra atrativa para a próclise.","“Os alunos têm-se adaptado bem à nova rotina.” / A frase está correta com a ênclise, pois o verbo auxiliar “têm” exige que o pronome “se” venha posposto, já que o verbo no particípio “adaptado” acompanha o verbo auxiliar."],"correta":0,"explicacao":"Gabarito: <strong>“Meu desejo era não incomodá-lo.” / A frase está correta com a ênclise, pois o verbo está no infinitivo, tornando a próclise facultativa.</strong>.","banca":"ABCP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3375,"enunciado":"A colocação pronominal é a posição ocupada pelos pronomes pessoais oblíquos átonos em relação ao verbo. A partir dessa definição, atente-se à posição do pronome destacado, no período entre aspas, a fim de assinalar a alternativa correta. “[...] imaginei um sem-número de sons que nos confortam.” (linha 6)","opcoes":["Trata-se de uma ênclise, em decorrência da preposição que o antecede.","Trata-se de uma próclise, em decorrência da preposição que o antecede.","Trata-se de uma ênclise, em decorrência do pronome relativo que o antecede.","Trata-se de uma próclise, em decorrência do pronome relativo que o antecede.","Trata-se de uma mesóclise, em decorrência do pronome relativo que o antecede."],"correta":3,"explicacao":"Gabarito: <strong>Trata-se de uma próclise, em decorrência do pronome relativo que o antecede.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3376,"enunciado":"Pronomes são palavras variáveis e são divididos em vários tipos. Os pessoais desempenham funções diferentes na sentença. A respeito das regras de colocação pronominal, assinale a alternativa correta.","opcoes":["Ao chegar a encomenda, por favor, me envia o recado.","Quando viu-se sozinho, chorou.","Ninguém lhe enviou o relatório final.","Poucos deram-lhe oportunidade de mostrar seu trabalho."],"correta":2,"explicacao":"Gabarito: <strong>Ninguém lhe enviou o relatório final.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3378,"enunciado":"A colocação pronominal está correta apenas em qual alternativa?","opcoes":["Se sente aqui!","Os jovens reclamam absurdamente, se comportando como verdadeiros bebês.","Não quero-te encontrar nos corredores da escola.","Há lembranças que marcam-nos para sempre.","Talvez te deixe partir."],"correta":4,"explicacao":"Gabarito: <strong>Talvez te deixe partir.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3379,"enunciado":"Em relação à colocação pronominal, assinale a alternativa correta.","opcoes":["Não dê-lhes conselhos.","Nunca deve-se falar sem pensar.","Quem contou-te essa mentira?","Lembrarei-te do aniversário.","Envie-me a procuração até o final do mês."],"correta":4,"explicacao":"Gabarito: <strong>Envie-me a procuração até o final do mês.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3380,"enunciado":"Em qual das alternativas a seguir não é correto usar a próclise (pronome antes do verbo)?","opcoes":["Eu não o quero ver tão cedo, ainda estou muito magoada.","Isso me deixa extremamente feliz.","Ontem me informaram sobre a fusão da empresa.","Conforme lhe disse, amanhã não haverá aula.","Lhe presentearei com flores."],"correta":4,"explicacao":"Gabarito: <strong>Lhe presentearei com flores.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3381,"enunciado":"Assinale a alternativa correta (colocação pronominal).","opcoes":["Não deve-se falar com a boca cheia.","Ele não perde uma chance de satisfazer-me.","Me envie a correspondência ainda hoje.","Meus funcionários comprometeriam-se com a proposta.","Conte-me tudo, não quero perder nenhum detalhe."],"correta":4,"explicacao":"Gabarito: <strong>Conte-me tudo, não quero perder nenhum detalhe.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3382,"enunciado":"A colocação dos pronomes pessoais oblíquos átonos em português — como \"me\", \"te\", \"se\", \"nos\", \"vos\" — obedece a regras específicas, sendo posicionados antes, no meio ou após o verbo, conforme a próclise, mesóclise ou ênclise, respectivamente. Esses pronomes ajudam a indicar a quem ou a que se refere a ação do verbo, agregando clareza e fluidez ao texto. Sobre o uso da próclise, julgue as seguintes afirmações como verdadeiras (V) ou falsas (F): (__)Deverá ocorrer obrigatoriamente próclise em orações imperativas afirmativas. (__)Deverá ocorrer obrigatoriamente próclise sempre que houver uma palavra atrativa que justifique o adiantamento do pronome. (__)Deverá ocorrer obrigatoriamente próclise em orações reduzidas do gerúndio. Assinale a alternativa cuja respectiva ordem de julgamento esteja correta:","opcoes":["V − V − V.","F − F − V.","F − V − F.","F − F − F.","V − F − F."],"correta":2,"explicacao":"Gabarito: <strong>F − V − F.</strong>.","banca":"Instituto Acesso","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3383,"enunciado":"Logo \"me deparei\" com a falta de moradia, aluguéis exorbitantes, e pediam três mil euros. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["Mesóclise.","Anáclise.","Próclise.","Ênclise."],"correta":2,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"UNIVALI","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3384,"enunciado":"Os excertos que seguem são trechos do conto \"A carteira\", de Machado de Assis. Leia os trechos e analise-os quanto à colocação pronominal dos verbos destacados: I. De repente, Honório olhou para o chão e viu uma carteira. Abaixar-se, apanhá-la e guardá-la foi obra de alguns instantes. II. Ninguém o viu , salvo um homem que estava à porta de uma loja, e que, sem o conhecer , lhe disse rindo: — Olhe, se não dá por ela; perdia-a de uma vez. — É verdade, concordou Honório envergonhado. III. Nunca demorou tanto a conta, nem ela cresceu tanto, como agora; e, a rigor, o credor não lhe punha a faca aos peitos; mas disse-lhe hoje uma palavra azeda, com um gesto mau, e Honório quer pagar-lhe hoje mesmo. IV. Eram cinco horas da tarde. Tinha-se lembrado de ir a um agiota, mas voltou sem ousar pedir nada.\" Estão adequadas, conforme a gramática formal da Língua Portuguesa, as colocações pronominais em:","opcoes":["I, II e III, apenas.","II, III e IV, apenas.","IV, apenas.","I, apenas.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FURB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3388,"enunciado":"Leia os trechos a seguir de Vidas Secas, de Graciliano Ramos, e responda conforme os comentários qual alternativa é a correta. “Agora Fabiano era vaqueiro, e ninguém o tiraria dali. Aparecera como um bicho, entocara-se como um bicho, mas criara raízes, estava plantado.” “Tinha a obrigação de trabalhar para os outros, naturalmente, conhecia do seu lugar. Bem. Nascera com esse destino, ninguém tinha culpa de ele haver nascido com um destino ruim. Que fazer? Podia mudar a sorte? Se lhe dissessem que era possível melhorar de situação, espantar-se-ia. (…) Era a sina. O pai vivera assim, o avô também. E para trás não existia família.” (Vidas Secas, 27 ed. São Paulo: Martins Fontes, 1970. P. 53-56)","opcoes":["O primeiro caso é próclise, pois o pronome vem antes do verbo por ter o pronome indefinido que o atrai; no segundo caso é ênclise, pois vem depois de um verbo no infinitivo e nada há antes que o faça ser próclise; e o terceiro caso é mesóclise por se tratar de um verbo no futuro do pretérito do indicativo e sem casos que determinassem ser ênclise ou próclise.","O primeiro caso é próclise por vir antes do pronome indefinido; o segundo caso é próclise pois o verbo está no infinitivo; e o terceiro caso é mesóclise pelo fato de o verbo estar no presente do subjuntivo.","O primeiro caso é próclise pelo fato de o pronome indefinido atrair o pronome oblíquo átono para antes do verbo; no segundo caso, a ênclise se dá pelo fato de ter uma vírgula, uma pausa e um novo fato se inicia, logo a ênclise é a recomendada; e no terceiro caso há uma mesóclise com o verbo no futuro do pretérito do indicativo.","O primeiro caso é de próclise pois o verbo atrai o pronome para a frente dele; o segundo caso é mesóclise pelo fato de o verbo vir posteriormente a ele; e o terceiro caso é de próclise, já que o pronome vem antes do final do verbo.","O primeiro caso é de ênclise pois o pronome está antes do verbo; o segundo caso, é uma ênclise, pois não há nada que possa atrair o pronome para antes dele; e o terceiro caso é uma mesóclise, já que o pronome vem no meio do verbo, estando esse no futuro do pretérito do subjuntivo."],"correta":2,"explicacao":"Gabarito: <strong>O primeiro caso é próclise pelo fato de o pronome indefinido atrair o pronome oblíquo átono para antes do verbo; no segundo caso, a ênclise se dá pelo fato de ter uma vírgula, uma pausa e um novo fato se inicia, logo a ênclise é a recomendada; e no terceiro caso há uma mesóclise com o verbo no futuro do pretérito do indicativo.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3390,"enunciado":"Se tu me amas, ama-me baixinho Não o grites de cima dos telhados Deixa em paz os passarinhos Deixa-me paz! Se me queres enfim tem de ser bem devagarinho, amada, que a vida é breve, e o amor mais breve ainda… QUINTANA, Mário. Obra completa em um volume. Rio de Janeiro: Nova Aguilar, 2005, p. 642 Sobre a colocação dos pronomes oblíquos átonos, assinale a alternativa correta.","opcoes":["No segundo verso, o “não” é responsável pela posição de próclise do pronome “o”.","No primeiro verso, o pronome “me”, em “ama-me baixinho”, aceitaria também a posição proclítica.","No verso “Deixa-me em paz”, o pronome está inadequado à norma de colocação pronominal, pois o correto é “Me deixa em paz”.","A posição proclítica do “me” em “Se tu me amas” e em “Se me queres” é justificada pela mesma regra de colocação pronominal.","No verso “Deixa em paz os passarinhos”, substituindo expressão “os passarinhos” por um pronome, ficaria \"os deixa em paz”."],"correta":0,"explicacao":"Gabarito: <strong>No segundo verso, o “não” é responsável pela posição de próclise do pronome “o”.</strong>.","banca":"COPEVE-UFAL","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3391,"enunciado":"Leia o trecho abaixo e responda à questão: \"Após a morte do parceiro, a fêmea isolou-se, recusou comida e morreu três dias depois.\" Sobre a colocação pronominal no trecho \"a fêmea isolou-se\", assinale a alternativa correta:","opcoes":["A próclise ao verbo \"isolou\" seria obrigatória, resultando em \"se isolou\", porque a oração é introduzida por uma locução adverbial (\"Após a morte do parceiro\").","O pronome \"se\" está corretamente posicionado como enclítico ao verbo \"isolou\", pois não há palavra atrativa antes do verbo que justifique a próclise.","O uso da mesóclise ao verbo \"isolou\" seria mais adequado, ficando \"isolou-se\", devido à forma verbal estar conjugada no futuro do pretérito.","A colocação pronominal está incorreta, pois em situações formais deve-se preferir a próclise independentemente do contexto."],"correta":1,"explicacao":"Gabarito: <strong>O pronome \"se\" está corretamente posicionado como enclítico ao verbo \"isolou\", pois não há palavra atrativa antes do verbo que justifique a próclise.</strong>.","banca":"ACAFE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3392,"enunciado":"Em situações formais de uso da Língua Portuguesa, há regras específicas para a correta colocação dos pronomes oblíquos nas frases. Assim, o pronome pode ser colocando antes, no meio ou depois do verbo, a depender do contexto linguístico. Assinale a alternativa em que o uso e a classificação da colocação pronominal estão corretos.","opcoes":["Quando der-lhes-em presentes, recebam-nos carinhosamente (mesóclise e ênclise).","Quando lhes derem presentes, nos recebam carinhosamente (próclise e próclise).","Quando lhes derem presentes, recebam-nos carinhosamente (próclise e ênclise).","Quando derem-lhes presentes, os recebam carinhosamente (ênclise e próclise).","Quando derem-lhes presentes, recebam os carinhosamente (ênclise e ênclise)."],"correta":2,"explicacao":"Gabarito: <strong>Quando lhes derem presentes, recebam-nos carinhosamente (próclise e ênclise).</strong>.","banca":"COPEVE-UFAL","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3394,"enunciado":"Referindo-se à devida colocação pronominal, marque (V) verdadeiro ou (F) falso e assinale a alternativa correta. ( ) Regra de uso da próclise: diante de oração exclamativa. ( ) Quando houver preposição entre o verbo auxiliar e o infinitivo, a colocação do pronome será facultativa (ênclise ou próclise). ( ) Regra de uso da próclise: diante de oração optativa. ( ) Nas orações coordenadas sindéticas alternativas, usamos a ênclise.","opcoes":["F – V – V – V.","V – F – V – V.","V – V – V – F.","V – V – V – V."],"correta":2,"explicacao":"Gabarito: <strong>V – V – V – F.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3395,"enunciado":"No trecho \"Deixa de aquecer e servir, tornando-se um tecido extinto\", de Fabrício Carpinejar, analise a colocação do pronome reflexivo \"se\" em \"tornando-se\". Com base nas regras de colocação pronominal da norma padrão, assinale a alternativa correta:","opcoes":["O uso de ênclise em \"tornando-se\" está correto, pois o verbo no gerúndio exige essa posição na norma padrão.","O pronome \"se\" está corretamente posicionado, pois segue a regra da próclise obrigatória após gerúndio.","A colocação do pronome \"se\" está incorreta, pois deveria ocorrer antes do verbo, formando \"se tornando\".","A colocação do pronome \"se\" deveria ser facultativa no contexto, podendo estar antes ou depois do verbo."],"correta":0,"explicacao":"Gabarito: <strong>O uso de ênclise em \"tornando-se\" está correto, pois o verbo no gerúndio exige essa posição na norma padrão.</strong>.","banca":"ACAFE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3397,"enunciado":"Levando-se em consideração os aspectos sintáticos da língua portuguesa referentes à pontuação e à colocação pronominal, a reescrita da oração Infelizmente, desconhece-se a identidade da extraordinária inventora (ℓ. 26) mantém-se no nível formal da língua em","opcoes":["A identidade da extraordinária inventora, infelizmente desconhece-se.","Infelizmente se desconhece a identidade da extraordinária inventora.","Se desconhece, infelizmente, a identidade da extraordinária inventora.","Infelizmente, se desconhece a identidade da extraordinária inventora.","Se desconhece a identidade da extraordinária inventora, infelizmente."],"correta":1,"explicacao":"Gabarito: <strong>Infelizmente se desconhece a identidade da extraordinária inventora.</strong>.","banca":"UFSM","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3398,"enunciado":"Leia com atenção as afirmativas abaixo: I.Preciso me organizar antes da reunião. II.Contou-me toda a história com detalhes. III.Devemos nos esforçar para alcançar nossos objetivos. IV.Preocupe-se somente com o que aconteceu. V.Ela sempre se dedica ao trabalho. Em quais das afirmativas lidas há o emprego de ênclise?","opcoes":["II e IV.","II, III e IV.","I, III e V.","I e V,"],"correta":0,"explicacao":"Gabarito: <strong>II e IV.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3399,"enunciado":"Não existem dados sobre quantos pacientes infectados podem ser afetados pelas condições pós-covid... (linha 23) Assinale a alternativa em que a alteração do segmento acima tenha sido feita em total obediência à norma culta.","opcoes":["Não existem dados sobre quantos pacientes infectados se teriam importado com as condições pós-covid...","Não existem dados sobre quantos pacientes infectados importariam-se com as condições pós-covid...","Não existem dados sobre quantos pacientes infectados não importar-se-iam com as condições pós-covid...","Não existem dados sobre quantos pacientes infectados teriam importado-se com as condições pós-covid...","Não existem dados sobre quantos pacientes infectados teriam-se importado com as condições pós-covid..."],"correta":0,"explicacao":"Gabarito: <strong>Não existem dados sobre quantos pacientes infectados se teriam importado com as condições pós-covid...</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3400,"enunciado":"No que se refere aos sentidos e aos aspectos linguísticos do texto CB1A2-I, julgue o próximo item. Seria mantida a correção gramatical do quarto parágrafo do texto caso a forma pronominal “os”, em “e publicou-os em forma de livro”, fosse deslocada para imediatamente antes da forma verbal “publicou” — e os publicou.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3401,"enunciado":"[Questão Inédita] Assinale a alternativa em que o enunciado atende à norma-padrão de colocação pronominal.","opcoes":["Adaptou-se Beethoven à sua condição de surdez, demonstrando-se que limitações físicas não impediram-no de compor obras imortais.","Como poderiam-se imaginar que Django Reinhardt, com dois dedos paralisados, seria um imortal guitarrista do jazz?","Se acredita que as adversidades enfrentadas pelos artistas mencionados nos inspiraram a superar suas limitações físicas.","Portinari expôs-se continuamente a tintas às quais era alérgico, sabendo-se que isso poderia ser prejudicial à sua saúde.","Harold Lloyd, faltando-lhe dois dedos, escalou um edifício em Nova York, tendo realizado-se quase todas as cenas arriscadas por ele mesmo."],"correta":3,"explicacao":"Gabarito: <strong>Portinari expôs-se continuamente a tintas às quais era alérgico, sabendo-se que isso poderia ser prejudicial à sua saúde.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3402,"enunciado":"[Questão Inédita] Assinale a alternativa que apresenta a colocação pronominal correta.","opcoes":["Quando se fala em direitos trabalhistas, os sindicatos sempre destacam-se.","Jamais deve se subestimar o poder da união dos trabalhadores.","Porque se lutou tanto, hoje temos melhores condições de trabalho.","Se organizem para as próximas eleições sindicais."],"correta":2,"explicacao":"Gabarito: <strong>Porque se lutou tanto, hoje temos melhores condições de trabalho.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3403,"enunciado":"Assinale a alternativa correta quanto ao emprego e à colocação do pronome, segundo a norma-padrão da Língua Portuguesa.","opcoes":["Eles não desculparam-se pelo ocorrido na festa.","O bandido rapidamente roubou-me a carteira e o celular.","Depois mandarei entregar-lhes os documentos assinados.","Se realizará uma palestra no auditório da universidade amanhã."],"correta":2,"explicacao":"Gabarito: <strong>Depois mandarei entregar-lhes os documentos assinados.</strong>.","banca":"Instituto Darwin","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3404,"enunciado":"A Fala Vegetal Não é mistério para os entendidos que há uma linguagem das plantas, ou, para ser mais exato, que a cada planta corresponde uma linguagem. Como a variedade de plantas é infinita, faz-se impossível ao entendimento, por muito atilado que seja, captar todas as vozes de vegetais. E só os mais perspicazes entre os humanos conseguem entender a conversa entre duas plantas de espécies diferentes: cada uma usa o seu vocabulário, como por exemplo num diálogo em que A falasse em espanhol e B respondesse em alemão. Levindo, jardineiro experiente, chegou a dominar as linguagens que se entrecruzavam no jardim. Um leigo diria que não se escutava nada, salvo o zumbir de moscas e besouros, mas ele chegava a distinguir o suspiro de uma violeta, e suas confidências ao amorperfeito não eram segredo para os ouvidos daquele homem. Até que um dia as plantas desconfiaram que estavam sendo espionadas e planejaram a conspiração de silêncio contra Levindo. Passaram a comunicar-se por meio de sinais altamente sigilosos, renovados a cada semana. Em vão o jardineiro se acocorava a noite inteira no jardim, na esperança de decifrar o código. Enlouqueceu. Perdendo o emprego, as coisas não voltaram à normalidade. As plantas haviam esquecido o hábito de conversar direito. Já não se entendiam, brigavam de haste contra haste, muitas se aniquilaram em combate. O jardim foi invadido pelas cabras, que pastaram o restante da vegetação. ANDRADE, Carlos Drummond de. Contos plausíveis. São Paulo: Companhia das Letras, 2012. Com base no texto \"A fala vegetal\", assinale a alternativa em que a colocação pronominal NÃO está de acordo com a norma-padrão.","opcoes":["As plantas se comunicavam de forma tão sigilosa que Levindo não conseguia entender o código.","O jardineiro chegou a acreditar que as plantas se comunicavam diretamente com ele.","Levindo tentou compreender o que as plantas diziam, mas elas recusaram-se a cooperar.","No momento em que as plantas começaram a brigar, Levindo não esforçou-se para acalmar o jardim.","Na esperança de decifrar o código, o jardineiro ajoelhou-se ao lado das plantas."],"correta":3,"explicacao":"Gabarito: <strong>No momento em que as plantas começaram a brigar, Levindo não esforçou-se para acalmar o jardim.</strong>.","banca":"INAZ do Pará","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3405,"enunciado":"Imagine pegar uma maçã suculenta, mas em vez de 'comê-la', você guarda as sementes e joga o resto fora. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["próclise.","ênclise.","mesóclise.","anáclise."],"correta":1,"explicacao":"Gabarito: <strong>ênclise.</strong>.","banca":"ACAFE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3407,"enunciado":"No texto \"Viajar com casal de amigos\", de Fabrício Carpinejar, o autor emprega corretamente a colocação pronominal para adequar o uso à norma-padrão. Analise a frase a seguir: \"Enquanto nos divertimos, precisamos intervir como escudo contra ofensas.\" Com base nas regras de colocação pronominal, assinale a alternativa correta sobre a posição do pronome oblíquo em \"nos divertimos\":","opcoes":["O pronome \"nos\" está na próclise porque é precedido pela palavra \"enquanto\", um conectivo subordinativo que exige atração do pronome.","O pronome \"nos\" está na ênclise porque se encontra no início da oração subordinada, antes do verbo.","O pronome \"nos\" está na próclise devido à ausência de elementos que exijam ênclise antes do verbo.","A colocação do pronome é facultativa, podendo ocorrer tanto na próclise quanto na ênclise, já que o verbo está no presente do indicativo."],"correta":0,"explicacao":"Gabarito: <strong>O pronome \"nos\" está na próclise porque é precedido pela palavra \"enquanto\", um conectivo subordinativo que exige atração do pronome.</strong>.","banca":"IGEDUC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3408,"enunciado":"Considerando a regra de colocação pronominal e o contexto que determina o uso de próclise, mesóclise ou ênclise, escolha a frase correta em relação ao uso do pronome oblíquo.","opcoes":["Me telefonou ontem sem avisar.","Preciso lhe ajudar com os relatórios.","Pediu-se aos alunos que me informasse do ocorrido.","Não me disse nada sobre o evento.","Entregar-lhe-ei o documento amanhã."],"correta":3,"explicacao":"Gabarito: <strong>Não me disse nada sobre o evento.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3410,"enunciado":"Na célebre frase de Jânio Quadros, “Fi-lo porque qui-lo”, tem-se a ocorrência de","opcoes":["mesóclise em “fi-lo” e ênclise em “qui-lo”.","ênclise em “fi-lo” e ênclise em “qui-lo”.","ênclise em “fi-lo” e próclise em “qui-lo”.","próclise em “fi-lo” e próclise em “qui-lo”."],"correta":1,"explicacao":"Gabarito: <strong>ênclise em “fi-lo” e ênclise em “qui-lo”.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3411,"enunciado":"Analise o destaque do excerto: “Na educação, pode-se aplicar a IA para personalizar o ensino”. Neste caso, a colocação pronominal trata-se de uma","opcoes":["próclise.","mesóclise.","ênclise.","proposição livre."],"correta":2,"explicacao":"Gabarito: <strong>ênclise.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3413,"enunciado":"Em relação à colocação pronominal, analise as frases abaixo e selecione a alternativa que apresenta a sequência correta de próclise, mesóclise ou ênclise, conforme as regras da gramática normativa. 1. Jamais se esquecerão dos conselhos que receberam durante a palestra. 2. Entregar-se-á ao projeto com toda a dedicação necessária. 3. Me contaram que o evento será adiado para a próxima semana. A sequência correta de colocação pronominal nessas frases é:","opcoes":["Próclise - Mesóclise - Próclise","Próclise - Ênclise - Próclise","Próclise - Mesóclise - Ênclise","Ênclise - Mesóclise - Próclise"],"correta":0,"explicacao":"Gabarito: <strong>Próclise - Mesóclise - Próclise</strong>.","banca":"Instituto Exata","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3416,"enunciado":"[Questão Inédita] A colocação pronominal está correta na seguinte alternativa:","opcoes":["Nunca esqueça-se de tomar um cafezinho para relaxar durante o trabalho.","Nos momentos em que sente-se estressado, ele prefere sair para tomar um café.","Sempre que convidam-me, aceito tomar um cafezinho.","Porque se irritou com a espera, o repórter desistiu de falar com o delegado.","Como tratava-se de um dia frio, todos optaram por um cafezinho quente"],"correta":3,"explicacao":"Gabarito: <strong>Porque se irritou com a espera, o repórter desistiu de falar com o delegado.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3417,"enunciado":"A regra que exige o uso da ênclise com o imperativo afirmativo, como em \"Recuso-me a ficar triste\", não se aplica ao imperativo negativo, no qual a próclise é obrigatória: \"Não me recuso a ficar triste\". Essa diferença no posicionamento dos pronomes ocorre devido à mudança de contexto sintático.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3418,"enunciado":"A frase “Me solta!”, se passada para o registro formal, resulta em","opcoes":["Me solte!","Soltem-me!","Solta-me!","Solte-me!","Me soltem!"],"correta":3,"explicacao":"Gabarito: <strong>Solte-me!</strong>.","banca":"COTEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3419,"enunciado":"Assinale a opção abaixo em que ocorreu um erro de colocação pronominal:","opcoes":["Quem te disse que a justiça dos homens é infalível.","Aqui se vive bem nesta bonita cidade.","Não o ajudarei mais, depois dessa tamanha ingratidão.","Você é o jogador de quem me lembro mais.","Embora agrade-me, não poderei aceitar sua oferta de trabalho."],"correta":4,"explicacao":"Gabarito: <strong>Embora agrade-me, não poderei aceitar sua oferta de trabalho.</strong>.","banca":"IVIN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3420,"enunciado":"No tocante à devida colocação pronominal, marque (V) verdadeiro ou (F) falso e assinale a alternativa correta. ( ) Regra de uso da ênclise: com o verbo no gerúndio. ( ) Com os tempos verbais no futuro do presente e futuro do pretérito, jamais ocorre a ênclise. ( ) Regra de uso da próclise: com o verbo no infinitivo impessoal. ( ) Caso haja pausa depois do advérbio, emprega-se a ênclise.","opcoes":["F – V – V – V.","V – V – V – F.","V – V – F – V.","V – V – V – V."],"correta":2,"explicacao":"Gabarito: <strong>V – V – F – V.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3423,"enunciado":"Há erro de colocação pronominal em:","opcoes":["Nunca diga-me como devo agir.","Deixe-o ir, antes que seja tarde.","Não te conto mais meus segredos.","Quando o jogo começar, jogue-lhes a bola."],"correta":0,"explicacao":"Gabarito: <strong>Nunca diga-me como devo agir.</strong>.","banca":"Gama Consult","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3425,"enunciado":"O domínio da norma culta reflete-se, principalmente, na modalidade escrita da língua, revelando um elevado grau de rigor e correção gramatical, como o devido uso da pontuação, da acentuação , da colocação pronominal, da concordância e da regência , entre outros. (https://www.normaculta.com.br/norma-culta/) Usando esse domínio, identifique a alternativa que preenche os espaços pontilhados do texto abaixo de forma correta, respectivamente: Acredita .... que .... apenas 10 partículas de norovírus para que a infecção .... estabeleça. Em termos comparativos, estima... . que a chamada dose infecciosa de covid-19 seja de cerca de 100 a 400 unidades do vírus SARS-CoV-2. Mas, nas últimas décadas, os virologistas ..... descobrir que alguns de nós ........ fatores biológicos naturais que ... protegem contra... doença. (https://www.bbc.com/portuguese/articles/cgr7zp7gg adaptado).","opcoes":["Acredita-se, sejam necessárias, se estabeleça, estima-se, começaram a, carregam, nos, a.","Se acredita, sejam necessárias, estabeleça-se, estima-se, começaram a, carrega, se, à.","Acredita-se, seja necessárias, se estabeleça, se estima, começaram à, carregam, nos, a.","Se acredita, sejam necessários, estabeleça-se, estima-se, começaram à, carrega, se, à.","Acredita-se, sejem necessárias, estabeleça-se, estima-se, começaram à, carregam, se, à."],"correta":0,"explicacao":"Gabarito: <strong>Acredita-se, sejam necessárias, se estabeleça, estima-se, começaram a, carregam, nos, a.</strong>.","banca":"Unesc","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3427,"enunciado":"Há um ERRO de colocação pronominal em:","opcoes":["Não o verei amanhã.","Talvez o veja ainda hoje.","Empreste-me um livro?","Aquilo entristeceu-me."],"correta":3,"explicacao":"Gabarito: <strong>Aquilo entristeceu-me.</strong>.","banca":"FUNVAPI","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3431,"enunciado":"[Questão Inédita] Assinale a alternativa que atende à norma-padrão de colocação pronominal:","opcoes":["Sempre opus-me à ideia de que contratos de namoro devam ser formalizados em cartório.","Podem-se estabelecer, por meio de contrato de namoro, cláusulas que protejam ambos os parceiros.","Tendo explicado-me sobre os direitos garantidos pelo contrato de namoro, decidi aceitar sua proposta.","Os casais que optarem por um contrato de namoro garantirão-se contra complicações futuras.","Por terem optado pela criação de um contrato de namoro, se asseguram os direitos de ambas as partes claramente."],"correta":1,"explicacao":"Gabarito: <strong>Podem-se estabelecer, por meio de contrato de namoro, cláusulas que protejam ambos os parceiros.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3432,"enunciado":"A frase em que a colocação do pronome átono se está de acordo com a norma-padrão da língua portuguesa é:","opcoes":["As plantas nunca desentenderam-se naquele jardim.","Caso unam-se contra o jardineiro, ele não terá chance.","Ele diuturnamente se dedicava a decifrar aquele código.","Plantas de diferentes espécies não entender-se-ão jamais.","Se impressionar com o mistério da fala das plantas é normal."],"correta":2,"explicacao":"Gabarito: <strong>Ele diuturnamente se dedicava a decifrar aquele código.</strong>.","banca":"CESGRANRIO","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3433,"enunciado":"Analise as colocações pronominais nas frases abaixo. 1. Fique tranquila, tudo ficará entre mim e você. 2. Para mim chegar cedo, preciso sair agora. 3. Ela não iria sem mim! Assinale a alternativa que indica todas as frases corretas quanto as colocações pronominais.","opcoes":["É correta apenas a frase 1.","É correta apenas a frase 2.","É correta apenas a frase 3.","São corretas apenas as frases 1 e 2.","São corretas apenas as frases 1 e 3."],"correta":4,"explicacao":"Gabarito: <strong>São corretas apenas as frases 1 e 3.</strong>.","banca":"FEPESE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3434,"enunciado":"No enunciado “Te amo!” (13º§), a posição do pronome em relação ao verbo configura um caso de próclise. Em que passagem ocorre o mesmo caso de colocação pronominal?","opcoes":["“Me refiro à norma curta, [...]” (3º§)","“Isso foi muito tempo atrás [...]” (11º§)","“Ela ignora mais de um século [...]” (12º§)","“Seu esforço é então recompensado [...]” (9º§)"],"correta":0,"explicacao":"Gabarito: <strong>“Me refiro à norma curta, [...]” (3º§)</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3436,"enunciado":"No que se refere à colocação pronominal, coloque (V) verdadeiro ou (F) falso e marque a alternativa devida. ( ) Espera-se que Mariana e Benjamim venham. Ocorre a ênclise, quando o verbo estiver no início da frase. ( ) Talvez casemos-nos um dia. Ocorre a ênclise, quando, antes do verbo, vier uma palavra que atraia o pronome, como um advérbio. ( ) Esperaria-te a vida toda. Ocorre a ênclise, quando o verbo estiver no futuro do pretérito. ( ) Ficava bêbado, cambaleando-se mais ainda. Ocorre a ênclise, quando o verbo estiver no gerúndio.","opcoes":["V – F – V – V.","F – V – V – F.","V – F – F – V.","V – V – V – V."],"correta":2,"explicacao":"Gabarito: <strong>V – F – F – V.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3437,"enunciado":"Aludindo-se à correta colocação pronominal, assinale a alternativa indevida.","opcoes":["Espantar-se-á com o roubo.","Desejava nos repreender.","Como se enganam!","Talvez nos arrependêssemos daquilo."],"correta":1,"explicacao":"Gabarito: <strong>Desejava nos repreender.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3438,"enunciado":"Julgue as assertivas e assinale a alternativa correta. I. Na frase “Jamais me esquecerei do nosso primeiro encontro”, ocorre próclise, porque termos de sentido negativo atraem o pronome para antes do verbo. II. Na frase “Ele se retirou da sala antes que a reunião acabasse”, ocorre próclise ou mesóclise, tanto faz, em razão de o sujeito explícito estar antes do verbo. III. Na frase “Desconfiada de assédio, recusou a proposta, fazendo-se de desentendida”, ocorre ênclise pois o verbo está no gerúndio e não há palavra atrativa.","opcoes":["Está correta apenas a I.","Está correta apenas a II.","Estão corretas I e II.","Estão corretas apenas I e III."],"correta":3,"explicacao":"Gabarito: <strong>Estão corretas apenas I e III.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3439,"enunciado":"Há normas que orientam para o correto uso dos pronomes pessoais em frases e textos. Eles podem ser usados antes, no meio ou após o verbo da oração. A este respeito, assinale a alternativa correta.","opcoes":["Segue-se a norma da Ênclise quando a oração estiver na negativa. Exemplo: “Não se incomode demais”.","Segue-se a norma da Próclise quando a oração for iniciada por verbo. Exemplo: “Cortou-se sem querer”.","Segue-se a norma da Próclise quando o verbo estiver no gerúndio. Exemplo: “Correu ao seu encontro, abraçando-o fortemente”.","Segue-se a norma da Mesóclise quando o verbo estiver no futuro do presente e não houver palavras que exijam o uso da Próclise. Exemplo: “Encontrar-te-ei mais tarde”.","Segue-se a norma da Mesóclise quando o verbo é conjugado no pretérito mais que perfeito. Exemplo: “A bola já entrara”."],"correta":3,"explicacao":"Gabarito: <strong>Segue-se a norma da Mesóclise quando o verbo estiver no futuro do presente e não houver palavras que exijam o uso da Próclise. Exemplo: “Encontrar-te-ei mais tarde”.</strong>.","banca":"MS Consultoria","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3440,"enunciado":"Julgue o item que se segue. Em contextos de discurso direto e indireto, a colocação pronominal no modo imperativo negativo segue a regra de posicionamento antes do verbo, garantindo a ênclise obrigatória.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3443,"enunciado":"Julgue o item que se segue. Em contextos linguísticos mais formais e elaborados, especialmente no uso do modo subjuntivo, a próclise é uma regra fixa e obrigatória, superando qualquer exigência de ênclise.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3445,"enunciado":"Assinale a opção em que o uso da próclise é obrigatório.","opcoes":["Os convidados que não dançavam se haviam espalhado por várias partes da casa.","Não lhe posso contar o que aconteceu depois desse dia.","E ele se pôs a caminho, mas a pé, para poupar o tostão do bonde.","Em se tratando de música, ele era o especialista.","Depois deste feito, Clara se sentiu completamente só no mundo."],"correta":3,"explicacao":"Gabarito: <strong>Em se tratando de música, ele era o especialista.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3446,"enunciado":"A respeito de aspectos linguísticos do texto CB1A2, julgue o próximo item. No trecho “não obstante a intenção que lhes tenha dado origem” (final do segundo parágrafo), a próclise da forma pronominal “lhes” justifica-se pela presença do vocábulo “não” no início do trecho.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3447,"enunciado":"Conforme Cegalla (2008) “os pronomes pessoais são palavras que substituem os substantivos e representam as pessoas do discurso.” Com base na informação anterior, analise a oração “fui depositá-la no jardim onde desabrochara”, em seguida assinale a alternativa que justifique corretamente a forma como o pronome átono “a”, em destaque, é utilizado.","opcoes":["Justifica-se pela supressão das consoantes -r, -s ou -z na terminação dos verbos.","Justifica-se pela função de objeto ou complemento exercida pelo pronome.","Justifica-se pela função de sujeito na oração.","Justifica-se pela terminação dos verbos em ditongo nasal."],"correta":0,"explicacao":"Gabarito: <strong>Justifica-se pela supressão das consoantes -r, -s ou -z na terminação dos verbos.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3448,"enunciado":"Com base nas normas gramaticais que envolvem a passagem “Me leia enquanto estou quente” (linha 4), assinale a alternativa correta.","opcoes":["A próclise em “Me leia” é corretamente empregada.","“enquanto” é classificada como conjunção explicativa.","O pronome oblíquo deve ser empregado em ênclise.","“enquanto estou quente” é a oração principal."],"correta":2,"explicacao":"Gabarito: <strong>O pronome oblíquo deve ser empregado em ênclise.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3449,"enunciado":"A colocação pronominal tem como base três princípios de posicionamentos de pronomes oblíquos. A mesóclise, a próclise e a ênclise. Assinale a alternativa correta que rege os princípios da mesóclise:","opcoes":["Lembra-se de mim?","Quem ousou te encaminhar os e-mails?","Como poderia nos ajudar?","Dar-te-ei os resultados dos exames."],"correta":3,"explicacao":"Gabarito: <strong>Dar-te-ei os resultados dos exames.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3451,"enunciado":"Analise as afirmativas abaixo sobre o texto 7. 1. No terceiro parágrafo, o pronome oblíquo o foi empregado em situação de ênclise, o que não é admitido pela norma culta neste contexto. 2. A palavra onde no quarto parágrafo deveria ser substituída por aonde, de acordo com a norma culta. 3. Na construção “Deterioração das regiões metropolitanas, baixa escolaridade, desemprego acentuado entre os jovens, são as linhas dessa quadra de exclusão.” (retirada do texto), a vírgula antes do verbo ser está separando sujeito do predicado. Assinale a alternativa que indica todas as afirmativas corretas.","opcoes":["É correta apenas a afirmativa 1.","É correta apenas a afirmativa 2.","São corretas apenas as afirmativas 1 e 2.","São corretas apenas as afirmativas 1 e 3.","São corretas as afirmativas 1, 2 e 3."],"correta":3,"explicacao":"Gabarito: <strong>São corretas apenas as afirmativas 1 e 3.</strong>.","banca":"FEPESE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3452,"enunciado":"O uso do pronome átono se em “Para quem já se esforçou intelectual e criativamente…” (linhas 34-35) é analisado como próclise. Segundo a norma-padrão da língua portuguesa, o pronome átono está corretamente colocado em","opcoes":["Não referir-me-ei apenas a todas as ramificações do mercado editorial, mas também à editoração cientifica e de conteúdo no geral.","Não nos cabe uma má utilização da IA, se considerarmos os verdadeiros limites éticos, artísticos e intelectuais humanos na produção de conteúdo.","Quando utiliza-se a ferramenta para a geração de conteúdo, de quem será a autoria?","Em tratando-se da IA, o avanço da tecnologia nas práticas editoriais é inegável."],"correta":1,"explicacao":"Gabarito: <strong>Não nos cabe uma má utilização da IA, se considerarmos os verdadeiros limites éticos, artísticos e intelectuais humanos na produção de conteúdo.</strong>.","banca":"UECE-CEV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3453,"enunciado":"Ninguém mais 'os fabrica', o que significa que há um número finito de disquetes no mercado. A norma-padrão de colocação pronominal destacada na frase denomina-se:","opcoes":["Ênclise.","Anáclise.","Próclise.","Mesóclise."],"correta":2,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3454,"enunciado":"A próclise, mesóclise e ênclise são os nomes dados para cada tipo de colocação pronominal em relação ao verbo. Nas orações abaixo, identifique a alternativa em que um dos tipos de colocação foi empregado CORRETAMENTE.","opcoes":["Nos disseram que os parentes das vítimas ficaram muito abalados.","Ninguém comprometeu-se a ajudar os parentes das vítimas do acidente aéreo.","Ninguém o informou sobre o acidente aéreo de Vinhedos.","Não autorizam-nos a falar sobre o acidente ocorrido em Vinhedos."],"correta":2,"explicacao":"Gabarito: <strong>Ninguém o informou sobre o acidente aéreo de Vinhedos.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3455,"enunciado":"Assinale a alternativa correta quanto à colocação dos pronomes oblíquos átonos.","opcoes":["Obrigado, meus filhos! Vocês não só deram-me netos, mas também trouxeram-me novamente a alegria de viver.","Vendo-o chegar, me lembrei que, quando era pequeno, sempre pedia-me algum dinheiro para comprar balas e sorvetes.","Critiquei-os sim, pois ninguém socorreu-nos naqueles momentos difíceis, nem apresentou-se para consolar-nos.","Os documentos que remeteram-me estão em ordem; ainda hoje devolvê-los-ei como havia prometido-lhes.","As medidas da largura e da altura dos patamares da escada pareciam-lhe complicadas, mas conseguiu calculá-las após a explicação que lhe apresentei."],"correta":4,"explicacao":"Gabarito: <strong>As medidas da largura e da altura dos patamares da escada pareciam-lhe complicadas, mas conseguiu calculá-las após a explicação que lhe apresentei.</strong>.","banca":"FEPESE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3456,"enunciado":"Com relação à frase “O amigo ___________ dei o presente foi o mesmo _________ eu falei ontem, e ele mora em uma cidade _________ o clima é sempre agradável.”, assinale a alternativa que preenche as lacunas, de acordo com as regras de colocação pronominal.","opcoes":["a quem – do qual – aonde","ao qual – de quem – aonde","a quem – de quem – onde","que – ao qual – onde"],"correta":2,"explicacao":"Gabarito: <strong>a quem – de quem – onde</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3457,"enunciado":"Sobre \"Quando eu dei por mim, três pessoas grandonas me pegaram pelo pescoço e pelos pés, me botaram dentro do carro e não falaram mais nada”, julgue as assertivas a seguir. ( ) Em “deu por mim”, há próclise, pois o pronome pessoal oblíquo tônico está após o verbo. ( ) Em “me pegaram”, a posição do pronome é proclítica. ( ) Em “me botaram”, há mesóclise, pois o pronome pessoal oblíquo átono aparece no meio da oração. ( ) Em “me botaram”, a posição do pronome pessoal oblíquo átono está conforme as regras da ênclise.","opcoes":["V, F, V, V.","F, V, F, F.","F, F, V, F.","F, F, F, V.","V, F, V, F."],"correta":1,"explicacao":"Gabarito: <strong>F, V, F, F.</strong>.","banca":"EDUCA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3458,"enunciado":"Referindo-se à devida colocação pronominal, coloque (V) verdadeiro ou (F) falso e marque a alternativa correta. ( ) A ênclise é a regra geral da Língua Portuguesa, isto é, se não houver situação determinante da próclise ou da mesóclise, usamos sempre o pronome depois do verbo. ( ) A ênclise é obrigatória no início das orações e após sinal de pontuação indicativo de pausa: a oração não pode ser iniciada com pronome oblíquo (me, lhe, te, etc), nem mesmo pode ele ser colocado antes do verbo, imediatamente, depois de sinal de pontuação que demanda pausa na leitura (vírgula, ponto e vírgula, dois-pontos, etc). Exemplos: Aplicaram-lhe a punição merecida; Na noite passada, ouvi-o andar pela casa. ( ) Quanto à mesóclise, ela está em franco desuso em nosso idioma. Não obstante, a norma padrão exige-a em dois casos, desde que não se trate de próclise obrigatória conforme os critérios: a) Verbos no futuro do presente do indicativo, o pronome deve estar mesoclítico (Ver-nos-emos amanhã); b) Verbos no futuro do pretérito do indicativo (Gostei deste carro, comprá-lo-ia se pudesse). ( ) A próclise (anteposição do pronome átono em relação ao verbo), devemos usá-la também, depois de palavras negativas. Exemplos: Não se engane; nunca me vire as costas.","opcoes":["F – V – V – V.","V – V – V – F.","V – V – V – V.","V – F – V – V."],"correta":2,"explicacao":"Gabarito: <strong>V – V – V – V.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3459,"enunciado":"Com relação ao verso do poema “Morde-me a goela ígneo e escaldante molho.”, assinale a alternativa que melhor explica a linguagem padrão.","opcoes":["Acontece um caso de colocação pronominal (ênclise), seguindo todas as regras formais.","É citada uma onomatopeia.","Não mantém um paralelismo e perde-se a formalidade.","Não acontece o uso de conectivo."],"correta":0,"explicacao":"Gabarito: <strong>Acontece um caso de colocação pronominal (ênclise), seguindo todas as regras formais.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3460,"enunciado":"No excerto '...quando lhe disse que contava com a sua adesão...', a norma culta foi seguida corretamente em relação à colocação pronominal?","opcoes":["Sim, pois existe palavra atrativa do pronome.","Não, porque a mesóclise é obrigatória em orações subordinadas.","Sim, mas a ênclise também seria aceita após a conjunção.","Não, 'quando disse-lhe' estaria correto pela presença da pausa.","Não, deveria ser 'disse-lhe' com ênclise."],"correta":0,"explicacao":"Gabarito: <strong>Sim, pois existe palavra atrativa do pronome.</strong>.","banca":"IDHTEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3461,"enunciado":"Levando em consideração a colocação pronominal, qual das alternativas a seguir apresenta a frase corretamente adequada à norma culta e à situação comunicativa?","opcoes":["Agradeço muito, né, pela atenção de vocês.","Muito agradeço-lhes pela atenção, viu?","Muito lhes agradeço pela atenção.","Muito agradeço-lhes pela atenção.","Agradeço muito aí pela atenção de vocês."],"correta":2,"explicacao":"Gabarito: <strong>Muito lhes agradeço pela atenção.</strong>.","banca":"IDHTEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3462,"enunciado":"No contexto de uma conversa formal, é importante que os estudantes saibam empregar a colocação pronominal correta, de acordo com a norma culta da língua portuguesa. Considerando essa situação, analise a seguinte frase: 'Eu ___ entregarei o relatório amanhã.' Qual a colocação pronominal correta para preencher a lacuna?","opcoes":["te","me","o","lhe","nos"],"correta":3,"explicacao":"Gabarito: <strong>lhe</strong>.","banca":"IDHTEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3463,"enunciado":"Assinale a alternativa que apresenta a correta colocação pronominal, segundo a norma padrão brasileira:","opcoes":["Todos os pesquisadores quiseram participar, lhes informando que a utilização de biodiesel pode contribuir para a redução das emissões de gases de efeito estufa quando comparado aos combustíveis fósseis.","Alguém disse-nos que países têm incentivado a mistura de biodiesel ao diesel convencional como uma estratégia para promover a sustentabilidade energética.","Não nos haviam informado que o biodiesel pode ser utilizado inclusive na geração de energia, devido às suas propriedades ambientalmente amigáveis e renováveis.","A pesquisadora não informou-lhe que o biodiesel é um combustível renovável produzido a partir de fontes como óleos vegetais e gorduras animais.","A informação que passei-lhe foi que a produção de biodiesel envolve processos como a transesterificação, que transforma óleos vegetais em um combustível adequado para motores diesel."],"correta":2,"explicacao":"Gabarito: <strong>Não nos haviam informado que o biodiesel pode ser utilizado inclusive na geração de energia, devido às suas propriedades ambientalmente amigáveis e renováveis.</strong>.","banca":"FURB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3466,"enunciado":"Ao analisar a colocação pronominal nos seguintes trechos “Metem-nos pela parte de dentro do beiço”; “nem os estorva no falar” e “vendo-lhe tais feições”, sabe-se que há, respectivamente, casos de","opcoes":["mesóclise, ênclise e próclise.","ênclise, ênclise e próclise.","ênclise, próclise e ênclise.","próclise, ênclise e mesóclise."],"correta":2,"explicacao":"Gabarito: <strong>ênclise, próclise e ênclise.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3467,"enunciado":"[Questão Inédita] Assinale a alternativa correta quanto à colocação pronominal.","opcoes":["Em “As portas do elevador estacionado no térreo já se fechavam [...]”, a ênclise também é permitida (fechavam-se).","Em “[...] coloco o braço no rumo do sensor a tempo de fazê-las reabrirem.”, o pronome átono pode ser substituído por “elas” (fazer elas).","Em “[...] as portas não se abriram.”, a ênclise também é permitida (abriram-se).","Em “Do nada, me vem a palavra ‘claustrofobia’ [...]”, o pronome pode ser substituído por “a mim” e posposto ao verbo (vem a mim).","Em “[...] até que um funcionário [...] me encontra no chão [...]”, o pronome se refere à terceira pessoa do singular (ele me encontra)."],"correta":3,"explicacao":"Gabarito: <strong>Em “Do nada, me vem a palavra ‘claustrofobia’ [...]”, o pronome pode ser substituído por “a mim” e posposto ao verbo (vem a mim).</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3468,"enunciado":"Considerando as regras de colocação pronominal, assinale a alternativa em que a alteração proposta para o trecho retirado do texto “Antes de pagar, agarra um dos pacotes brilhantes” mantém a correção gramatical e o sentido original do trecho.","opcoes":["Agarra um dos pacotes brilhantes; antes de pagar.","Antes de pagar, agarra-o um dos pacotes brilhantes.","Agarra-o antes de pagar um dos pacotes brilhantes.","Antes de pagar, agarra-lhe um dos pacotes brilhantes.","Agarra um dos pacotes brilhantes antes de pagar."],"correta":4,"explicacao":"Gabarito: <strong>Agarra um dos pacotes brilhantes antes de pagar.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3469,"enunciado":"No período: “De repente eu me dava conta de como nossa existência é frágil, “retirado do texto, há a ocorrência de colocação pronominal: Assinale a alternativa CORRETA:","opcoes":["Mesôclise pela ausência da vírgula em seu antecedente.","Próclise por anteceder o verbo no infinitivo.","Ênclise, uma vez que a próclise é proibida.","Mesôclise por anteceder um verbo.","Prôclise pela presença de uma locução adverbial antecedida ao verbo."],"correta":4,"explicacao":"Gabarito: <strong>Prôclise pela presença de uma locução adverbial antecedida ao verbo.</strong>.","banca":"EDUCA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3470,"enunciado":"Há nos exemplos: “Sento-me” e “Dar-me-iam”, RESPECTIVAMENTE, a colocação pronominal do tipo: Assinale a alternativa CORRETA:","opcoes":["Próclise e mesóclise.","Ênclise e próclise.","Mesóclise e ênclise.","Mesóclise e mesóclise.","Ênclise e mesóclise."],"correta":4,"explicacao":"Gabarito: <strong>Ênclise e mesóclise.</strong>.","banca":"EDUCA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3471,"enunciado":"A crônica, como gênero textual, frequentemente adota uma linguagem mais coloquial, e o texto em interpretação não é diferente. Uma forma de o autor alinhar sua escrita à linguagem informal se dá por meio de maior flexibilidade quanto à obediência às normas gramaticais. Um exemplo de inconsistência relacionada à colocação pronominal presente no texto se dá no pronome sublinhado em:","opcoes":["“E se renova com qualquer surpresa boba.” (3º§)","“Olhar seus olhos e entendê-los, olhos adentro.” (3º§)","“Me lembrei do tempo em que o pai de família saía depois do jantar pra fazer o quilo.” (1º§)","“Há de ver que ali estavam lado a lado duas almas que se procuram e, distraídas, disso não se deram conta.” (5º§)"],"correta":2,"explicacao":"Gabarito: <strong>“Me lembrei do tempo em que o pai de família saía depois do jantar pra fazer o quilo.” (1º§)</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3472,"enunciado":"Sobre o emprego dos pronomes, assinale a alternativa correta.","opcoes":["Querida amiga, ontem passei o dia pensando em si.","Filha, por favor traga-me este documento que está aí sobre tua mesa.","Se o barulho lhe perturba, me avisa para mim poder reprogramar a execução da obra.","Antenor, se tu quiseres os animais, pedirei ao motorista do caminhão para entregá-los a você amanhã.","Este programa a que estamos assistindo agora não é tão bom quanto àquele que assistimos na semana passada."],"correta":4,"explicacao":"Gabarito: <strong>Este programa a que estamos assistindo agora não é tão bom quanto àquele que assistimos na semana passada.</strong>.","banca":"FEPESE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3474,"enunciado":"Analise a colocação pronominal no seguinte trecho retirado do texto: É muito preocupante observar que a epidemia de obesidade, já evidente entre adultos em grande parte do mundo em 1990, se reflita agora em crianças e adolescentes em idade escolar. Agora, analise as afirmações a seguir. Marque V, para verdadeiras, e F, para falsas: (__)Podemos afirmar que há um erro de colocação pronominal no trecho. (__)A colocação pronominal está correta, pois o pronome átono deve estar em posição de próclise após a vírgula. (__)Como inicia nova oração, o pronome átono deveria assumir a posição de mesóclise. (__)Como consiste no tempo verbal presente, o correto seria empregar a mesóclise. Assinale a alternativa que apresenta a sequência correta:","opcoes":["V − F − F − V.","V − F − V − F.","F − V − F − F.","V − F − F − F.","F − V − V − V."],"correta":3,"explicacao":"Gabarito: <strong>V − F − F − F.</strong>.","banca":"FURB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3475,"enunciado":"Analise os períodos a seguir e identifique quais estão de acordo com os preceitos gramaticais da Língua Portuguesa do Brasil, no que se refere ao uso de próclise, mesóclise e ênclise. I. Hoje, pode-se corrigir o erro de ontem. II. Dever-se-ia evitar erros, quando já se sabe como os corrigir. III. Deveria -se evitar erros, quando já sabe-se como corrigi-los. IV. Se deveria evitar erros, quando já se sabe como os corrigi-los. Quais estão corretas?","opcoes":["Apenas a I.","Apenas a I e II.","Apenas a II e III.","Apenas a I, III e IV."],"correta":2,"explicacao":"Gabarito: <strong>Apenas a II e III.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3476,"enunciado":"Analise as sentenças a seguir em relação à colocação pronominal e assinale aquela em que ocorre mesóclise.","opcoes":["Eles se despediram e, logo em seguida, ela embarcou.","Disseram-lhe que Maria estava mentindo.","Não queriam me contar sobre o divórcio.","Informar-te-ão quanto às normas de formatação da revista.","Marta sentou-se à esquerda de Danilo."],"correta":3,"explicacao":"Gabarito: <strong>Informar-te-ão quanto às normas de formatação da revista.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3480,"enunciado":"Cada uma das próximas opções apresenta um trecho do texto CG1A1 seguido de uma proposta de reescrita. Assinale a opção em que a proposta de reescrita apresentada preserva o sentido e a correção gramatical do texto, considerando as regras de colocação pronominal.","opcoes":["“Aquelas que não se encaixavam” (segundo período do quinto parágrafo): Aquelas que não encaixavam-se","“no que se refere à análise textual” (sexto parágrafo): no que remete-se à análise textual","‘utilizar ambas em conjunto’ (segundo período do quarto parágrafo): utilizar elas em conjunto","“treinar o algoritmo” (primeiro período do quinto parágrafo): treiná-lo","“para reconhecer essas notícias” (primeiro período do quinto parágrafo): para reconhecerem-nas"],"correta":3,"explicacao":"Gabarito: <strong>“treinar o algoritmo” (primeiro período do quinto parágrafo): treiná-lo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3481,"enunciado":"Qual das alternativas abaixo apresenta uma frase com a correta colocação do pronome átono?","opcoes":["Quero vê-la amanhã na palestra.","Não esqueça-se de levar o dinheiro para o táxi.","Me empreste o vestido que você comprou ontem.","Espero que tragam-me boas notícias.","Eles chamarão-nos quando a discussão começar."],"correta":0,"explicacao":"Gabarito: <strong>Quero vê-la amanhã na palestra.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3482,"enunciado":"Leia o texto para responder às questões de 1 a 7. Máscara em mosaico e outros tesouros são encontrados em tumba de rei maia O auge da civilização maia ocorreu entre 250 d.C. e 900 d.C. Apesar da grande importância histórica, existem poucos resquícios desse período devido ao saqueamento de sítios arqueológicos. Mas, recentemente, um trabalho da Universidade Tulane, nos EUA, conseguiu recuperar raros tesouros da época. Liderado pelo arqueólogo Francisco EstradaBelli, o time de pesquisadores fez investigações no de Chochkitam, localizado na Guatemala, em uma região próxima das fronteiras dos atuais países México e Belize. Em 2022, a equipe encontrou a tumba de um rei maia, datada em 1.700 anos. A descoberta foi possível graças à tecnologia LIDAR, que utilizou um avião para direcionar raios laser para o chão e, assim, fazer um mapeamento da área. “É como tirar raio-X do solo da floresta”, explica Estrada-Belli, em nota. “Isso revolucionou o nosso campo. Agora podemos ver aonde estamos indo, em vez de simplesmente fazer uma expedição na floresta esperando achar alguma coisa”, diz. A tumba contém oferendas funerárias consideradas extraordinárias. Há uma máscara de jade em mosaico, raras conchas de ostra e escritos em ossos humanos. Estima-se que as relíquias sejam de 350 d.C. A expectativa é que elas contribuam para a compreensão de elementos da cultura maia, como a religião e a linhagem real. As conchas, por exemplo, eram utilizadas pela realeza como joias e moedas, além de servirem para oferendas religiosas e de sacrifício. Os escritos em ossos humanos, por sua vez, foram feitos em pedaços de fêmur. Um deles retrata um homem que seria um rei — até então desconhecido — segurando uma máscara de jade similar à encontrada na tumba. Os pesquisadores suspeitam que os hieróglifos vistos no material possam identificar o pai e o avô do líder, conectando-o a outros estados maias, como Tikal e Teotihuacan. “Uma descoberta como essa é um pouco como ganhar na loteria, em termos de informação”, constata o arqueólogo Estrada-Belli. “Ela abre uma janela para um tempo obscuro sobre o qual temos pouquíssimos textos.” Revista Galileu. Disponível em: https://revistagalileu.globo.com/ciencia/arqueologia/noticia/2024/02/mascara-em-mosaico-e-outros-tesouros-sao-encontrados-em-tumba-de-rei-maia.ghtml Considere os seguintes excertos, retirados do texto: I. Estima-se que as relíquias sejam de 350 d.C. II. Os pesquisadores suspeitam que os hieróglifos vistos no material possam identificar o pai e o avô do líder, conectando-o a outros estados maias, como Tikal e Teotihuacan. As normas gramaticais que sugerem a colocação pronominal enclítica nos casos apresentados são, respectivamente:","opcoes":["(A) I. não se inicia período por pronome átono e II. usa-se ênclise em verbos flexionados em oração subordinada.","(B) I. usa-se ênclise quando houver palavra atrativa antes do verbo e II. usa-se ênclise em orações subordinadas com verbos flexionados em qualquer tempo e modo.","(C) I. não se inicia período por pronome átono e II. usa-se ênclise em orações reduzidas de gerúndio não precedidas pela preposição em.","(D) I. usa-se ênclise em orações imperativas afirmativas e II. usa-se ênclise em orações reduzidas de gerúndio, independentemente dos demais elementos colocados.","(E) I. usa-se ênclise em orações reduzidas de infinitivo flexionado e II. usa-se ênclise em orações reduzidas de gerúndio antecedidas pela preposição em, mesmo que esta esteja implícita."],"correta":2,"explicacao":"Gabarito: <strong>(C) I. não se inicia período por pronome átono e II. usa-se ênclise em orações reduzidas de gerúndio não precedidas pela preposição em.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3483,"enunciado":"Considere os seguintes excertos, retirados do texto: I. Estima-se que as relíquias sejam de 350 d.C. II. Os pesquisadores suspeitam que os hieróglifos vistos no material possam identificar o pai e o avô do líder, conectando-o a outros estados maias, como Tikal e Teotihuacan. As normas gramaticais que sugerem a colocação pronominal enclítica nos casos apresentados são, respectivamente:","opcoes":["I. não se inicia período por pronome átono e II. usa-se ênclise em verbos flexionados em oração subordinada.","I. usa-se ênclise quando houver palavra atrativa antes do verbo e II. usa-se ênclise em orações subordinadas com verbos flexionados em qualquer tempo e modo.","I. não se inicia período por pronome átono e II. usa-se ênclise em orações reduzidas de gerúndio não precedidas pela preposição em.","I. usa-se ênclise em orações imperativas afirmativas e II. usa-se ênclise em orações reduzidas de gerúndio, independentemente dos demais elementos colocados.","I. usa-se ênclise em orações reduzidas de infinitivo flexionado e II. usa-se ênclise em orações reduzidas de gerúndio antecedidas pela preposição em, mesmo que esta esteja implícita."],"correta":2,"explicacao":"Gabarito: <strong>I. não se inicia período por pronome átono e II. usa-se ênclise em orações reduzidas de gerúndio não precedidas pela preposição em.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3484,"enunciado":"Identifique a frase em que não há erro de colocação pronominal:","opcoes":["“O livro que li ontem era muito interessante.”","“As pessoas a que devemos agradecer não estão aqui.”","“O aluno que cuja prova foi bem-feita recebeu elogios.”","“O caminho pelo qual, que devemos seguir é esse.”"],"correta":0,"explicacao":"Gabarito: <strong>“O livro que li ontem era muito interessante.”</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3485,"enunciado":"Analise as construções “perguntaram-me” e “afastando-se”, que ocorrem no texto. Assinale a alternativa que classifica corretamente o tipo de pronome e a colocação pronominal que apresentam.","opcoes":["pronome pessoal do caso oblíquo átono, em ênclise.","pronome pessoal do caso oblíquo tônico, em ênclise.","pronome pessoal do caso oblíquo átono, em próclise.","pronome pessoal do caso oblíquo tônico, em próclise.","pronome pessoal do caso reto, em ênclise."],"correta":0,"explicacao":"Gabarito: <strong>pronome pessoal do caso oblíquo átono, em ênclise.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3487,"enunciado":"Observe a colocação pronominal das orações abaixo e assinale a alternativa correta.","opcoes":["Conforme solicitou-me, enviarei seu pedido ainda hoje.","Em tratando-se de viajar, ela sempre consegue se programar.","Devo te acariciar como se fosse a última vez.","Olhou para o filho, apaixonando-se.","Se não houvesse tantas dívidas, me aventuraria em uma jornada pelo mundo."],"correta":3,"explicacao":"Gabarito: <strong>Olhou para o filho, apaixonando-se.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3488,"enunciado":"Em relação à colocação pronominal, assinale a alternativa elaborada erroneamente.","opcoes":["As inferências, conformando-se, formavam uma tese improvável.","“O pão nosso de cada dia dai-nos hoje”.","Todos deram-me apoio quando eu mais precisava.","Muitos se dizem incapazes de suportar os desafios da vida.","Dir-lhe-ei a verdade sobre o crime cometido."],"correta":2,"explicacao":"Gabarito: <strong>Todos deram-me apoio quando eu mais precisava.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3490,"enunciado":"Assinale a alternativa em que a sentença apresentada está correta quanto à colocação pronominal.","opcoes":["Não deixe-me esperando. Estou aqui há horas.","São eles que explicam-nos os detalhes de que teremos que cuidar antes do show.","Me levantei às 8h para alimentar o Spike e não voltei a dormir.","Fiquei calado, embora caiba-me opinar nesse assunto.","Eles mantiveram-no confinado até o final dos testes."],"correta":4,"explicacao":"Gabarito: <strong>Eles mantiveram-no confinado até o final dos testes.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3491,"enunciado":"Analise as sentenças a seguir quanto à colocação pronominal: I. Em se tratando de um caso delicado, estou disposto a ajudar. II. Neste lugar não há pessoas que nos querem bem. III. Reservou as quartas-feiras para o ajudar com a tarefa de casa. A(s) sentença(s) que apresenta(m) condições que permitiriam também a ênclise é (são) apenas:","opcoes":["I.","II.","III.","I e II.","II e III."],"correta":2,"explicacao":"Gabarito: <strong>III.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3492,"enunciado":"De acordo com a norma-padrão da Língua Portuguesa, Identifique a opção correta;","opcoes":["O lugar onde se vende carne é o açougue.","O lugar aonde se vende carne é o açougue.","O açogue é o local onde se compra carne.","O açogue é o local onde compra-se a carne.","O assougue é o local onde compra-se carne."],"correta":0,"explicacao":"Gabarito: <strong>O lugar onde se vende carne é o açougue.</strong>.","banca":"CONTEMAX","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3493,"enunciado":"Analise as sentenças a seguir e assinale a alternativa em que a colocação pronominal é do tipo mesóclise.","opcoes":["Não soube se colocar naquela discussão.","Privar-lhe-ão de todos os seus sonhos.","Esqueceram-se do aniversário da própria mãe.","Eles me avisaram a respeito do jogo de futebol.","A mulher esperou-te até não aguentar mais."],"correta":1,"explicacao":"Gabarito: <strong>Privar-lhe-ão de todos os seus sonhos.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3494,"enunciado":"Considerando o uso adequado dos verbos e dos pronomes, analise os seguintes itens: |- Quando você a vir, diga-lhe que mandei um abraço fraterno. Il - Fomos nós quem redigiu todos os ofícios. Ill - Se o diretor vier ao campus, pedir-lhe-emos que assine as portarias. IV — A secretaria pediu-nos que terminemos a revisão ainda hoje. Estão corretos:","opcoes":["Apenas l e ll.","Apenas ll e Ill.","Apenas lll e IV","Apenas I, Il e IV.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"IF-MT","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3497,"enunciado":"As sentenças a seguir foram criadas a partir do texto. Analise-as: I.Nesta pesquisa fala-se sobre novos modos de produzir baterias. II.Não se trata apenas de uma inovação, mas de uma importante mudança na tecnologia. III.A tecnologia está mudando depressa. Isso deixa-me muito reflexivo! IV.Entregue-me este artigo sobre as novas baterias, estou curioso para lê-lo. Está correta a colocação pronominal, segundo a norma padrão, em:","opcoes":["I e III, apenas.","I, II, III e IV.","II, apenas.","II e IV, apenas.","I, III e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>II e IV, apenas.</strong>.","banca":"FURB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3498,"enunciado":"Considerando as normas da colocação pronominal, marque a alternativa incorreta.","opcoes":["Não se deve admitir a indústria do ódio nas redes sociais.","Combater ações de abuso é urgente, já que nos deparamos com elas.","Havia falado-se acerca de danos psicológicos promovidos pelo cancelamento.","Aplicar-se-iam leis mais severas em relação aos abusos nas redes sociais.","Apresentaram-lhe os altos índices de pessoas vítimas da cultura do cancelamento."],"correta":2,"explicacao":"Gabarito: <strong>Havia falado-se acerca de danos psicológicos promovidos pelo cancelamento.</strong>.","banca":"IDHTEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3501,"enunciado":"Analise as sentenças a seguir e assinale a alternativa em que a colocação pronominal está incorreta.","opcoes":["Eles negar-te-ão tudo aquilo que perguntar.","Ana lhe estava falando a respeito dos trabalhos da faculdade.","Há de acostumar-se com essa situação.","Os familiares sempre tratavam-na bem.","Quanto dinheiro lhe devo?"],"correta":3,"explicacao":"Gabarito: <strong>Os familiares sempre tratavam-na bem.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3502,"enunciado":"Julgue o item subsequente. A ênclise é obrigatoriamente usada após formas verbais no imperativo afirmativo, como em \"Conte-me a história\".\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3506,"enunciado":"Identifique a frase que está com a colocação pronominal inadequada:","opcoes":["Eu estava te ajudando desde ontem.","Nunca o vi assim.","Havia avisado-lhe mais cedo que iria na casa dele.","Não te encontrarei hoje.","Isso me lembra algo."],"correta":2,"explicacao":"Gabarito: <strong>Havia avisado-lhe mais cedo que iria na casa dele.</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3507,"enunciado":"Considere as frases. • Meu pai escolhera uma casa feita de cimento para Bobi, e a loja _______ ao condomínio. • Sabendo de sua captura, vamos ao canil onde _______ que Bobi está atrás das grades. • No retorno para casa, converso com o cão _______ e de que as pessoas podem ser perigosas. Atendendo à norma-padrão de emprego e de colocação dos pronomes, as lacunas das frases devem ser preenchidas, respectivamente, por:","opcoes":["havia levado-a; se confirma; lhe previno","havia-a levado; se confirma; previno-lhe","havia levado-a; confirma-se; previno-o","a havia levado; se confirma; previno-o","a havia levado; confirma-se; lhe previno"],"correta":3,"explicacao":"Gabarito: <strong>a havia levado; se confirma; previno-o</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3508,"enunciado":"Em colocações pronominais, a posição do pronome oblíquo é definida como proclítica, mesoclítica ou enclítica. Analise o fragmento: “(...) é preciso ter certas habilidades e aptidões, responsáveis por torná-lo um profissional competente e diferenciado.” Assinale a alternativa correta em referência ao pronome em destaque.","opcoes":["A posição do pronome do objeto é mesoclítica.","A posição do pronome do objeto é proclítica.","A posição do pronome do objeto é enclítica.","A posição do pronome do sujeito é enclítica.","A posição do pronome do sujeito é mesoclítica."],"correta":2,"explicacao":"Gabarito: <strong>A posição do pronome do objeto é enclítica.</strong>.","banca":"IBFC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3510,"enunciado":"A colocação pronominal atende à norma-padrão em:","opcoes":["Não me refiro à questão de morar sozinho, nunca me queixei disso: o que me preocupa é a segurança do imóvel.","Me diga uma coisa: quando é que você vai me deixar em paz, só quando eu chamar você na justiça?","Vendo-a entrar, me lembrei que, quando era pequena, sempre pedia-me um brinquedo diferente do de seu irmão.","Reagimos daquela forma brutal porque agrediram-nos e eu jamais esqueci-me das palavras maldosas que ele proferiu."],"correta":0,"explicacao":"Gabarito: <strong>Não me refiro à questão de morar sozinho, nunca me queixei disso: o que me preocupa é a segurança do imóvel.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3511,"enunciado":"Em referência às ideias veiculadas no texto apresentado e a seus aspectos linguísticos, julgue o item seguinte. No segundo período do segundo parágrafo, o pronome “se” poderia ser deslocado para depois da forma verbal “torna”, escrevendo-se torna-se, sem prejuízo da correção gramatical do texto, uma vez que a posição do pronome, nesse caso, é mera escolha estilística.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3512,"enunciado":"Em se tratando da sintaxe de colocação pronominal, assinale a alternativa, na qual, a descrição sobre a colocação do pronome negritado está corretamente justificada nos contextos que seguem.","opcoes":["“[...] o português ser hegemônico não nos deve cegar para as muitas línguas [...]”. [linhas 9 e 10] (ocorre próclise, mas deveria ocorrer mesóclise em decorrência da locução verbal deve cegar).","“[...] a situação se torna, no mínimo, preocupante.” [linhas 4 e 5] (ocorre próclise, mas deveria ocorrer ênclise por respeito à hierarquia de colocação pronominal).","“[...] Mostra-nos ainda mais [...]”. [linha 25] (ocorre ênclise, mas deveria ocorrer próclise por respeito à hierarquia de colocação pronominal).","“[...] línguas indígenas, europeias e asiáticas que aqui se falam [...]”. [linha 10] (ocorre próclise em decorrência do pronome relativo que).","“[...] afinal cada um acredita naquilo que bem lhe apraz”. [linha 3] (ocorre próclise em decorrência do advérbio bem)."],"correta":4,"explicacao":"Gabarito: <strong>“[...] afinal cada um acredita naquilo que bem lhe apraz”. [linha 3] (ocorre próclise em decorrência do advérbio bem).</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3514,"enunciado":"Considerando as ideias veiculadas no texto CB1A1-I e as relações de coesão nele estabelecidas, julgue o próximo item. A forma pronominal “eles” (penúltimo período) retoma “Os acordos de 1810” (antepenúltimo período).\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3515,"enunciado":"\"Bom, o meu jardineiro também me atende prontamente. Nunca me deixa esperando. Nunca se atrasa.\" Sobre a colocação dos pronomes átonos, no trecho entre aspas, é CORRETO afirmar que:","opcoes":["Está conforme o uso das regras da próclise.","Está conforme o uso das regras da mesóclise.","Está em desacordo com as regras da próclise.","Está em desacordo com as regras da ênclise.","Está conforme o uso das regras da ênclise."],"correta":0,"explicacao":"Gabarito: <strong>Está conforme o uso das regras da próclise.</strong>.","banca":"Instituto Abaré-eté","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3516,"enunciado":"João estava escrevendo uma redação quando se deparou com uma dúvida sobre a colocação pronominal. Ele escreveu a seguinte frase: “Eu te vi ontem no parque”. No entanto, ele não estava certo se a colocação do pronome “te” estava correta. Com base em seus conhecimentos sobre a colocação pronominal na norma-padrão da Língua Portuguesa, ajude João a verificar se a frase está correta. Assinale a alternativa correta:","opcoes":["A frase está correta, pois o pronome oblíquo “te” deve sempre preceder o verbo.","A frase está incorreta, pois o pronome oblíquo “te” deve sempre suceder o verbo.","A frase está correta, pois o pronome oblíquo “te” pode preceder o verbo quando o verbo está no passado.","A frase está correta, pois a colocação do pronome “te” antes do verbo é permitida em casos de próclise."],"correta":3,"explicacao":"Gabarito: <strong>A frase está correta, pois a colocação do pronome “te” antes do verbo é permitida em casos de próclise.</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3517,"enunciado":"Levando em conta a colocação pronominal, identifique a alternativa incorreta:","opcoes":["Isto me traz memória afetiva.","Homem sem educação, tampouco nos disse um bom dia.","Quem atendeu-lhe na loja.","Cozinhem-lhe o melhor prato da casa.","Ainda que nos contratem, será tarde demais."],"correta":2,"explicacao":"Gabarito: <strong>Quem atendeu-lhe na loja.</strong>.","banca":"CONTEMAX","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3518,"enunciado":"Conforme a norma padrão da Língua Portuguesa, a mesma regra de colocação do pronome “me” em “da vossa alta clemência me despido” é observada na seguinte alternativa:","opcoes":["Sinto-me muito feliz hoje.","Me comoveu toda essa tragédia.","Meu pai carregou-me no colo.","Por fim, dar-me-iam a notícia.","De todas as angústias me liberto."],"correta":4,"explicacao":"Gabarito: <strong>De todas as angústias me liberto.</strong>.","banca":"UFRR","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3519,"enunciado":"A frase em que a colocação pronominal não está adequada à norma padrão da Língua Portuguesa é:","opcoes":["Não pedirei-lhe nada.","Vai-se a primeira pomba despertada! (Raimundo Correia).","Em se tratando de um caso urgente, nada o retinha em casa.","Romano, escuta-me.","Sabe ele se tornará a vê-los algum dia?"],"correta":0,"explicacao":"Gabarito: <strong>Não pedirei-lhe nada.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3520,"enunciado":"Conforme a NORMA CULTA da Língua Portuguesa, assinale a alternativa em que a colocação pronominal está correta.","opcoes":["Te adoro;","Ninguém viu-nos;","Ela sempre ajudou-te;","Não me disseram nada;","Me diga a verdade, por favor."],"correta":3,"explicacao":"Gabarito: <strong>Não me disseram nada;</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3521,"enunciado":"Assinale a alternativa em que a colocação pronominal está correta.","opcoes":["Aquilo diz-te alguma coisa sobre a situação?","Tinha voltado-lhe a conversar quando a viu.","Me empresta o lápis, por favor?","Ninguém o viu ontem na faculdade.","Quem convidou-nos?"],"correta":3,"explicacao":"Gabarito: <strong>Ninguém o viu ontem na faculdade.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3522,"enunciado":"Em relação aos verbos, os pronomes sublinhados a seguir estão enclíticos. Assinale a alternativa em que a justificativa para o uso da ênclise se DIFERE das demais.","opcoes":["“Após a morte prematura de sua amada, Orfeu desceu ao Hades, o reino dos mortos, com a esperança de trazê-la de volta ao mundo dos vivos.” (1º§)","“[...] Orfeu oferece uma alegoria rica para os riscos do mau uso da IA no judiciário, lembrando-nos de que, na busca por justiça, a sabedoria humana é insubstituível [...]” (20º§)","“Os juízes são chamados a não se deixarem influenciar cegamente por previsões algorítmicas, mas sim a considerá-las como uma das muitas ferramentas à sua disposição.” (11º§)","“O desafio que se apresenta não é simplesmente o de integrar a IA no sistema judicial, mas sim o de fazê-lo de maneira que amplifique, e não substitua, a sensibilidade e a flexibilidade humanas.” (12º§)"],"correta":1,"explicacao":"Gabarito: <strong>“[...] Orfeu oferece uma alegoria rica para os riscos do mau uso da IA no judiciário, lembrando-nos de que, na busca por justiça, a sabedoria humana é insubstituível [...]” (20º§)</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3523,"enunciado":"Considerando os pronomes oblíquos, a depender da posição deles na frase em relação ao verbo, sua colocação pode ser denominada de próclise, mesóclise e ênclise.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3524,"enunciado":"Assinale a alternativa em que a colocação pronominal atende à norma-padrão","opcoes":["No estado da Flórida, não permitirão-se jovens com menos de 14 anos navegando em redes sociais, conforme lei já assinada.","De acordo com DeSantis, as crianças têm prejudicado-se de várias maneiras com o tempo excessivo que dedicam à mídia social.","Se prevê uma revolução na vida de muitos jovens, com a promulgação da lei assinada pelo governador da Flórida, Ron DeSantis.","De acordo com a lei, exige-se que as plataformas obtenham permissão dos pais para conceder contas a jovens de 14 e 15 anos."],"correta":3,"explicacao":"Gabarito: <strong>De acordo com a lei, exige-se que as plataformas obtenham permissão dos pais para conceder contas a jovens de 14 e 15 anos.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3527,"enunciado":"Releia este trecho: “Como uma ladra sorrateira, a procrastinação rouba tempo, energia e potencial. Se disfarça de preguiça ou distração [...].” Respeitadas as regras de colocação pronominal, o trecho pode ser reescrito, sem alteração no seu sentido, como:","opcoes":["“Como uma ladra sorrateira, a procrastinação rouba tempo, energia e potencial. Disfarçar-se-ia de preguiça ou distração [...].”","“Como uma ladra sorrateira, a procrastinação rouba tempo, energia e potencial. Disfarça se de preguiça ou distração [...].”","“Como uma ladra sorrateira, a procrastinação rouba tempo, energia e potencial. Disfarça-se de preguiça ou distração [...].”","“Como uma ladra sorrateira, a procrastinação rouba tempo, energia e potencial. Se disfarça-se de preguiça ou distração [...].”"],"correta":2,"explicacao":"Gabarito: <strong>“Como uma ladra sorrateira, a procrastinação rouba tempo, energia e potencial. Disfarça-se de preguiça ou distração [...].”</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3528,"enunciado":"No trecho “Perguntaram-me uma vez qual fora o primeiro livro de minha vida.” (linhas 01-02), a colocação pronominal é","opcoes":["enclítica, pois a oração se classifica como reduzida de gerúndio.","enclítica, uma vez que a oração é iniciada por um verbo acrescido de pronome oblíquo.","mesoclítica, pois a oração é iniciada por verbo no futuro do pretérito do indicativo.","proclítica, pois a oração se classifica como reduzida de infinitivo."],"correta":1,"explicacao":"Gabarito: <strong>enclítica, uma vez que a oração é iniciada por um verbo acrescido de pronome oblíquo.</strong>.","banca":"UECE-CEV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3529,"enunciado":"Considere as passagens: • Os filhos raramente visitam os pais. (5o parágrafo) • Vou gravar os seus roncos. (6o parágrafo) De acordo com a norma-padrão de emprego de pronomes e colocação pronominal, as passagens admitem, respectivamente, as reescritas:","opcoes":["Os filhos raramente visitam-lhes. / Vou gravar eles.","Os filhos os raramente visitam. / Vou gravar-lhes.","Os filhos raramente visitam-nos. / Os vou gravar.","Os filhos raramente visitam eles. / Vou lhes gravar.","Os filhos raramente os visitam. / Vou gravá-los."],"correta":4,"explicacao":"Gabarito: <strong>Os filhos raramente os visitam. / Vou gravá-los.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3530,"enunciado":"Assinale a alternativa em que os pronomes destacados estão empregados e/ou colocados em conformidade com a norma-padrão.","opcoes":["Antes de o cirurgião-dentista fazer a pergunta, o Poeta já a fazia. / Voltavam-se então para o Poeta todas as cabeças. / Mal avistava o dentista, e antes que ele erguesse as trombetas da sua voz, o poeta perguntava-lhe sobre o maçarico.","Antes de o cirurgião-dentista fazer a pergunta, o Poeta já lhe fazia. / Se voltavam então para o Poeta todas as cabeças. / Mal avistava o dentista, e antes que este erguesse as trombetas da sua voz, o poeta o perguntava sobre o maçarico.","Antes de o cirurgião-dentista fazer a pergunta, o Poeta já fazia ela. / Voltavam-se então para o Poeta todas as cabeças. / Mal avistava o dentista, e antes que aquele erguesse as trombetas da sua voz, o poeta já perguntava-o sobre o maçarico.","Antes de o cirurgião-dentista fazer a pergunta, o Poeta já fazia-na. / Se voltavam então para o Poeta todas as cabeças. / Mal avistava o dentista, e antes que esse erguesse as trombetas da sua voz, o poeta lhe perguntava sobre o maçarico."],"correta":0,"explicacao":"Gabarito: <strong>Antes de o cirurgião-dentista fazer a pergunta, o Poeta já a fazia. / Voltavam-se então para o Poeta todas as cabeças. / Mal avistava o dentista, e antes que ele erguesse as trombetas da sua voz, o poeta perguntava-lhe sobre o maçarico.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3531,"enunciado":"Assinale a alternativa que atende à norma-padrão de colocação pronominal e de regência verbal.","opcoes":["Esquecerei-me o trabalho!","Me esquecerei do trabalho!","Tenho esquecido-me do trabalho!","Quero esquecer-me do trabalho!"],"correta":3,"explicacao":"Gabarito: <strong>Quero esquecer-me do trabalho!</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3533,"enunciado":"Julgue o item que se segue. A frase \"Eu não vi ela hoje\" é aceitável em contextos informais da língua portuguesa, pois não prejudica o entendimento, apesar de desviar das normas padrão de colocação pronominal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3534,"enunciado":"A colocação pronominal está em conformidade com a norma-padrão em:","opcoes":["Meu pai buscava no almanaque a informação de algum antepassado ilustre, quem sabe alguma glória de que pudesse gabar-se!","Para não dizer-lhes que estou mentindo, não sei onde meu pai arranjou aquele almanaque, velharia do século passado.","Se foram também, com a tropa de burros e o barulho imaginário dos sinos da madrinha, as esperanças de um passado glorioso.","Meu pai tinha arranjado o almanaque, achando que encontraria-se neste a informação de algum antepassado ilustre.","E o dedo indicador foi percorrendo os sobrenomes, e tendo encontrado-se o sobrenome Espírito Santo, não podia haver mais dúvidas."],"correta":0,"explicacao":"Gabarito: <strong>Meu pai buscava no almanaque a informação de algum antepassado ilustre, quem sabe alguma glória de que pudesse gabar-se!</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3535,"enunciado":"Leia os enunciados abaixo e assinale a alternativa em que a colocação pronominal atende à norma padrão culta","opcoes":["Sempre disse-lhe que as circunstâncias alteram os comportamentos.","Tudo dei-lhe para que conseguisse realizar o procedimento adequadamente.","Bons ventos levem-no.","Dir-te-ei todos os procedimentos realizados na operação."],"correta":3,"explicacao":"Gabarito: <strong>Dir-te-ei todos os procedimentos realizados na operação.</strong>.","banca":"EPL Concursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3536,"enunciado":"Em “as moças chamavam-se mademoiselles”, a colocação pronominal corresponde à","opcoes":["ênclise, quando o pronome precede o verbo.","próclise, quando o pronome precede o verbo.","ênclise, quando o pronome sucede ao verbo.","próclise, quando o pronome sucede ao verbo."],"correta":2,"explicacao":"Gabarito: <strong>ênclise, quando o pronome sucede ao verbo.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3537,"enunciado":"Conforme a NORMA CULTA da Língua Portuguesa, assinale a alternativa em que a colocação pronominal está correta:","opcoes":["Te amo muito;","Alguém viu-nos;","Ele sempre ajudou-te;","Não me falaram nada;","Me ajude a resolver isso."],"correta":3,"explicacao":"Gabarito: <strong>Não me falaram nada;</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3538,"enunciado":"Considerando a colocação pronominal, de acordo com a gramática normativa da Língua Portuguesa, assinale a alternativa que preenche, correta e respectivamente, as lacunas pontilhadas nas linhas 09, 15 e 19.","opcoes":["se debruçou – se seguiram – Se conta","debruçou-se – se seguiram – Se conta","se debruçou – se seguiram – Conta-se","se debruçou – seguiram-se – Conta-se","debruçou-se – seguiram-se – Conta-se"],"correta":2,"explicacao":"Gabarito: <strong>se debruçou – se seguiram – Conta-se</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3539,"enunciado":"Em: “Não se trata, porém, de uma questão etária.” (2º§). A colocação pronominal está corretamente empregada. Assinale a alternativa cuja colocação pronominal está de acordo com as regras gramaticais.","opcoes":["Não emprestei-lhe os livros comprados para estudo.","Me empreste todos os livros adquiridos para estudo.","Em tratando-se dos livros, todos foram emprestados.","Alguém me emprestou os livros comprados para estudo."],"correta":3,"explicacao":"Gabarito: <strong>Alguém me emprestou os livros comprados para estudo.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3541,"enunciado":"Julgue o item subsequente. Na colocação pronominal, quando há palavras de valor negativo (não, nunca, jamais, ninguém, nada, nem etc.)., o pronome oblíquo átono ficará proclítico ao verbo, como ocorre em: Não o permitiram a conversão de real para dólar.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3542,"enunciado":"Julgue o item subsequente. Na colocação pronominal, chamamos de ênclise quando o pronome oblíquo é colocado depois do verbo. Assim, podemos dizer: Quando ele ajudar-te, não esqueças os demais parentes da tua família.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3543,"enunciado":"Leia a imagem a seguir. Imagem associada para resolução da questão Sobre o emprego do pronome oblíquo átono na imagem, analise as asserções a seguir e a relação proposta entre elas. I – É obrigatório o emprego do pronome oblíquo após o verbo \"dar\" PORQUE II – o referido verbo está no infinitivo pessoal e, por isso, exige a ênclise. Sobre as asserções, é correto afirmar que","opcoes":["as duas são falsas.","a primeira é falsa e a segunda é verdadeira.","a primeira é verdadeira e a segunda é falsa.","as duas são verdadeiras e a segunda não justifica a primeira."],"correta":0,"explicacao":"Gabarito: <strong>as duas são falsas.</strong>.","banca":"FCM","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3544,"enunciado":"Leia os fragmentos abaixo e, logo em seguida, analise o que se pede: I. “...apertando-se um único botão se matam milhões de outros sem sair da poltrona”. II. “...pois de nada lhe adiantariam suas façanhas com o polegar...”. III. “A grande arte também se deve à preguiça.” A partir do conhecimento sobre o assunto Colocação Pronominal, pode-se dizer que se tem quanto a isso a seguinte ordem em relação aos fragmentos em evidência acima:","opcoes":["Mesóclise – Próclise – Próclise.","Ênclise – Mesóclise – Mesóclise.","Próclise – Ênclise – Ênclise.","Próclise – Próclise – Ênclise.","Ênclise – Próclise – Próclise."],"correta":4,"explicacao":"Gabarito: <strong>Ênclise – Próclise – Próclise.</strong>.","banca":"ISET","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3546,"enunciado":"No tocante à devida colocação pronominal, marque (V) verdadeiro ou (F) falso e assinale a alternativa correta. ( ) Regra de uso da próclise: com o verbo no imperativo afirmativo. ( ) Regra de uso da ênclise: diante de advérbio: aqui, ontem, calmamente. ( ) Havendo um dos casos que justifique a próclise, desfaz-se a mesóclise. ( ) Regra do uso da mesóclise: verbos no futuro do presente e verbos no futuro do pretérito, (desde que não haja caso que justifique a próclise).","opcoes":["V – V – F – F.","V – F – F – V.","V – V – V – V.","F – F– V – V.","F – V – V – F."],"correta":3,"explicacao":"Gabarito: <strong>F – F– V – V.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3547,"enunciado":"Selecione a opção em que a mesóclise está corretamente empregada:","opcoes":["Poderia entregá-lo-me amanhã?","Diga-me se vir-me-á na festa.","Preciso concluir-me o relatório.","Encontrar-nos-emos no final do dia.","Jamais pensaria em envolver-me nisso."],"correta":3,"explicacao":"Gabarito: <strong>Encontrar-nos-emos no final do dia.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3548,"enunciado":"“Me ensina a parar de chorar que nisso você já tá melhor que eu.” 7º§ É correto afirmar sobre a colocação do pronome no início da frase acima:","opcoes":["ênclise na sequência pronome-verbo.","mesóclise determinada pelo tempo verbal.","prioridade da ênclise na colocação pronominal.","próclise típica da linguagem coloquial.","próclise típica da linguagem padrão."],"correta":3,"explicacao":"Gabarito: <strong>próclise típica da linguagem coloquial.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3550,"enunciado":"Analise as frases abaixo no que se refere à colocação pronominal adequada segundo a norma culta da língua portuguesa. I. \"Não se esqueçam de me enviar os documentos.\" II. \"Diga-me o que desejas sem rodeios.\" III. \"Por que não me dizes a verdade?\" IV. \"Espero que te lembres de comprar o pão.\" Considerando as regras de colocação pronominal em língua portuguesa, qual das alternativas abaixo indica corretamente a adequação das frases à norma culta?","opcoes":["Todas as frases estão corretas.","Apenas as frases I e II estão corretas.","Apenas as frases II e III estão corretas.","Apenas as frases III e IV estão corretas.","Todas as frases estão incorretas."],"correta":0,"explicacao":"Gabarito: <strong>Todas as frases estão corretas.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3551,"enunciado":"Em relação à colocação pronominal, ocorre ênclise e próclise, respectivamente, em:","opcoes":["o apalpam/ Lembro-me","observam-no/ o apalpam","Lembro-me / observam-no","o chamam pelo nome/ o apalpam"],"correta":1,"explicacao":"Gabarito: <strong>observam-no/ o apalpam</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3552,"enunciado":"Qual é a forma correta de colocação pronominal na frase: 'Ela me entregou o livro'?","opcoes":["Ela entregou o livro a mim","Ela entregou-me o livro","Ela entregou o livro para mim","Ela me entregou o livro","Ela entregou o livro pra mim."],"correta":0,"explicacao":"Gabarito: <strong>Ela entregou o livro a mim</strong>.","banca":"INAZ do Pará","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3553,"enunciado":"A colocação pronominal é o posicionamento adequado do pronome oblíquo em relação ao verbo. Quanto a isso, no texto ocorre","opcoes":["próclise em “devem valer-se”, pois o verbo “dever”, assim como o verbo “necessitar”, atua como condicionante e obriga o uso do pronome depois do verbo “valer”. A mesma regra serve para mesóclises.","ênclise em “para se relacionarem”, pois a preposição “para” obriga o uso do pronome antes do verbo “relacionar”, o mesmo ocorre com outras preposições. A regra não vale para mesóclises.","próclise em “distanciando-se dos”, pois está sucedida pela preposição aglutinada “dos”, o que obriga o uso do pronome depois do verbo “distanciar”. A mesma regra serve para mesóclises.","ênclise em “e opondo-se”, pois está precedida da conjunção “e”, como também aconteceria se fosse uma vírgula, o que obriga o uso do pronome depois do verbo “opor”. A regra não vale para mesóclises."],"correta":3,"explicacao":"Gabarito: <strong>ênclise em “e opondo-se”, pois está precedida da conjunção “e”, como também aconteceria se fosse uma vírgula, o que obriga o uso do pronome depois do verbo “opor”. A regra não vale para mesóclises.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3554,"enunciado":"O trecho “Diz-lhe, numa prece, que ela regresse” é iniciado por uma colocação pronominal denominada de","opcoes":["ênclise (obrigatória por se tratar de um texto poético).","próclise (modo indicado em frases imperativas).","ênclise (trata-se da forma básica da norma-padrão).","próclise (facultativa por anteceder uma pontuação)."],"correta":2,"explicacao":"Gabarito: <strong>ênclise (trata-se da forma básica da norma-padrão).</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3557,"enunciado":"Quanto à colocação pronominal, a oração em que há o uso de ênclise é:","opcoes":["Deixei-me influenciar por opiniões alheias.","Sair tarde de casa nos causou transtornos.","Fez bem em seguir as dicas que lhe deram.","Ver-se-ia grande progresso se todos colaborassem."],"correta":0,"explicacao":"Gabarito: <strong>Deixei-me influenciar por opiniões alheias.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3558,"enunciado":"Considerando-se as regras de colocação pronominal, assinalar a alternativa CORRETA.","opcoes":["Nunca faça-me perguntas bobas!","A assustou com as notícias, e ela chorou.","Até me ocorreu de falar com ele, mas não quis.","Meu pai não ouviu-me direito."],"correta":2,"explicacao":"Gabarito: <strong>Até me ocorreu de falar com ele, mas não quis.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3559,"enunciado":"Em relação à colocação do pronome oblíquo e às flexões verbais em “[...] torna-te aquilo que és [...]” (12º§), assinale a alternativa correta.","opcoes":["Próclise. Futuro do pretérito e futuro do indicativo.","Próclise. Presente do indicativo nas duas situações.","Ênclise. Imperativo afirmativo e presente do indicativo sucessivamente.","Mesóclise. Infinitivo pessoal e presente do subjuntivo sequencialmente."],"correta":2,"explicacao":"Gabarito: <strong>Ênclise. Imperativo afirmativo e presente do indicativo sucessivamente.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3560,"enunciado":"Sobre o fragmento “[...] e muito poucas vezes é-me dado ler notícias de crimes nas ruas que atravesso.” (5º§), assinale a afirmativa correta.","opcoes":["Em “é-me dado” ocorre erro de colocação pronominal, pois deveria ocorrer mesóclise: “ser-me-há dado”.","A concordância no trecho “muito poucas vezes” está adequada às normas da língua padrão, pois “poucas” é adjetivo.","A concordância em “muito poucas vezes” está incorreta, pois o vocábulo “muito” deveria estar flexionado no feminino e no plural.","A colocação pronominal em “é-me dado” está incoerente com as regras gramáticas. O correto seria: “e muito poucas vezes me é dado ler notícias de crimes”."],"correta":1,"explicacao":"Gabarito: <strong>A concordância no trecho “muito poucas vezes” está adequada às normas da língua padrão, pois “poucas” é adjetivo.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3561,"enunciado":"Analise os períodos a seguir e identifique quais estão de acordo com os preceitos gramaticais da Língua Portuguesa do Brasil, no que se refere ao uso de próclise, mesóclise e ênclise. I. Deveria -se evitar erros, quando já sabe-se como corrigi-los. II. Se deveria evitar erros, quando já se sabe como os corrigi-los. III. Hoje, pode-se corrigir o erro de ontem. IV. Dever-se-ia evitar erros, quando já se sabe como os corrigir. Quais estão corretas?","opcoes":["Apenas a I.","Apenas a I e II.","Apenas a III e IV.","Apenas a I, III e IV."],"correta":2,"explicacao":"Gabarito: <strong>Apenas a III e IV.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3562,"enunciado":"Julgue o item subsequente, em relação aos sentidos e aspectos linguísticos do texto precedente. No primeiro período do terceiro parágrafo, a próclise pronominal em “se deslocava” justifica-se pelo caráter desenvolvido da oração subordinada em que tal trecho se insere.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3563,"enunciado":"[Questão Inédita] Marque a alternativa que apresenta a colocação pronominal conforme a linguagem formal e culta:","opcoes":["As soluções que a IA oferece-nos podem ser aplicadas em diversos contextos.","Deveria-se sempre considerar os aspectos éticos antes de implementá-los em novos projetos de IA.","Nunca deve-se subestimar os avanços da inteligência artificial.","Os projetos que apoiarem-se em inteligência artificial têm maior chance de sucesso.","A tecnologia pode-se adaptar às necessidades de comunidades carentes."],"correta":4,"explicacao":"Gabarito: <strong>A tecnologia pode-se adaptar às necessidades de comunidades carentes.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3564,"enunciado":"As perguntas a seguir apresentam o pronome pessoal oblíquo em ênclise (após o verbo); assinale a que mostra formulação incorreta, porque só admite próclise.","opcoes":["Os dois bandidos evadiram-se do presídio em Mossoró?","Onde podemos vê-los?","Eles dedicar-se-iam às tarefas com prazer.","Numa entrevista como esta, isto pergunta-se?","Quem dir-me-á tantas barbaridades, senão ele?"],"correta":4,"explicacao":"Gabarito: <strong>Quem dir-me-á tantas barbaridades, senão ele?</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3566,"enunciado":"Assinale a frase em que houve troca indevida entre O/LHE.","opcoes":["Geralmente aqueles que não têm nada a dizer conseguem levar o máximo de tempo para fazê-lo.","Quando você fica mais velho, começam a lhe atribuir virtudes que você jamais possuiu.","O povo é como uma cera mole, tudo depende da mão que o modele.","Toda idade tem seus frutos; o que falta é saber recolher-lhes.","Quanto melhor se enche a vida, menos tempo se tem de perdê-la."],"correta":3,"explicacao":"Gabarito: <strong>Toda idade tem seus frutos; o que falta é saber recolher-lhes.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3568,"enunciado":"A colocação pronominal refere-se à posição dos pronomes oblíquos átonos em relação ao verbo na frase. A colocação pronominal deverá ser feita no meio do verbo quando o verbo estiver conjugado no futuro do presente do indicativo ou no futuro do pretérito do indicativo. Sabendo disso, há mesóclise em qual das seguintes frases?","opcoes":["Talvez te espere no fim das aulas.","Ajudar-te-ei no que for preciso.","Eu tinha-lhe falado sobre esse assunto.","Esta é a faculdade onde me formei."],"correta":1,"explicacao":"Gabarito: <strong>Ajudar-te-ei no que for preciso.</strong>.","banca":"IESES","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3570,"enunciado":"O verbo em destaque na música apresenta:","opcoes":["Mesóclise, e se justifica pelo uso do verbo no futuro do presente.","Ênclise, e se justifica pelo uso do verbo no futuro do pretérito.","Mesóclise, e a colocação pronominal está equivocada.","Ênclise, e se justiça pelo uso do verbo no futuro do presente."],"correta":0,"explicacao":"Gabarito: <strong>Mesóclise, e se justifica pelo uso do verbo no futuro do presente.</strong>.","banca":"FUNATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3571,"enunciado":"Utilizando corretamente pronomes oblíquos átonos nas orações abaixo, tem-se: “Mas os músculos, na verdade, não têm memória”; “Experiências negativas atrapalham o retorno ao treino”; “E, portanto, responder mal aos estímulos”.","opcoes":["“Mas os músculos, na verdade, não as têm”; “Experiências negativas atrapalham-no”; “E, portanto, responder-lhes mal”.","“Mas os músculos, na verdade, não têm-nas”; “Experiências negativas atrapalham-no”; “E, portanto, responder-lhes mal”.","“Mas os músculos, na verdade, não as têm”; “Experiências negativas atrapalham-lo”; “E, portanto, respondê-los mal”.","“Mas os músculos, na verdade, não têm-nas”; “Experiências negativas atrapalham-lo”; “E, portanto, respondê-los mal”."],"correta":0,"explicacao":"Gabarito: <strong>“Mas os músculos, na verdade, não as têm”; “Experiências negativas atrapalham-no”; “E, portanto, responder-lhes mal”.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3572,"enunciado":"“Me chama”, gramaticalmente, está:","opcoes":["Correta.","Incorreta, já que é caso obrigatório de ênclise.","Incorreta, já que é caso obrigatório de mesóclise.","Incorreta, já que é caso obrigatório de próclise."],"correta":1,"explicacao":"Gabarito: <strong>Incorreta, já que é caso obrigatório de ênclise.</strong>.","banca":"FUNATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3573,"enunciado":"Assinale a alternativa na qual a colocação pronominal está correta.","opcoes":["Ninguém telefonou-nos durante a estadia na praia.","Ele foi útil trazendo-me todos os livros pesados.","Isso ajuda-me muito contra a insônia.","Os barulhos da obra me estão irritando-me diariamente.","Você tem que me dizer-me a verdade."],"correta":1,"explicacao":"Gabarito: <strong>Ele foi útil trazendo-me todos os livros pesados.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3575,"enunciado":"Na sentença “Ninguém lhe nega coração” o item que segue a mesma regra de colocação pronominal é","opcoes":["Todos lhe ofereceram o coração por estarem apaixonados por ela.","Então, entreguei-lhe o convite para entrar em meu coração.","Ninguém ajudou-lhe conquistar o coração do seu namorado.","Durante a festa, ninguém, que estava presente, lhe negou o coração amigo."],"correta":0,"explicacao":"Gabarito: <strong>Todos lhe ofereceram o coração por estarem apaixonados por ela.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3577,"enunciado":"Assinale a alternativa em que todos os pronomes estão corretamente empregados.","opcoes":["Os conselhos que os pais lhes deram, levaram-nos em conta mais tarde.","Se tu não se importa, eu quero seguir viagem consigo.","Deixa eu tentar fazer o bolo de acordo com a receita que você me indicou.","Empreste-me este alicate que está aí na tua gaveta? Há muito tento comprar ele.","Quando encontrei ela perto da rodoviária, disse-me que tinha ido comprar linha para mim fazer uma tarrafa."],"correta":0,"explicacao":"Gabarito: <strong>Os conselhos que os pais lhes deram, levaram-nos em conta mais tarde.</strong>.","banca":"FEPESE","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3578,"enunciado":"Em relação à colocação pronominal, o pronome oblíquo “las”, no período “Antes de utilizá-las para valer, os Estados Unidos conduziram o primeiro teste de arma nuclear dentro do “Projeto Manhattan”,...”, ocupa","opcoes":["a posição proclítica, devido à atração exercida pela preposição “de”.","a posição mesoclítica, devido ao verbo no futuro do presente.","a posição enclítica, devido ao verbo no infinitivo.","a posição enclítica, devido ao verbo no imperativo."],"correta":2,"explicacao":"Gabarito: <strong>a posição enclítica, devido ao verbo no infinitivo.</strong>.","banca":"Instituto Darwin","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3579,"enunciado":"Acerca dos sentidos e de aspectos linguísticos do texto anterior, julgue o item a seguir. No primeiro período do terceiro parágrafo, a forma pronominal “se” poderia ser corretamente deslocada para logo após a forma verbal “tornaram” — escrevendo-se tornaram-se.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3581,"enunciado":"Analise o excerto a partir das classificações pela posição do pronome do objeto ou oblíquo, definidas na sintaxe de colocação pronominal: (1) próclise: o pronome antecede o verbo; (2) mesóclise: o pronome se coloca no meio do verbo; (3) ênclise: o pronome colocado no final do verbo. Escolha a alternativa em que a classificação da posição dos pronomes esteja correta. Excerto: “Se essas informações não foram suficientes para levá-los (I) a se (II) interessarem pela GA”.","opcoes":["I. próclise - II. próclise.","I. ênclise - II. mesóclise.","I. ênclise - II. próclise.","I. mesóclise - II. ênclise.","I. próclise - II. ênclise."],"correta":2,"explicacao":"Gabarito: <strong>I. ênclise - II. próclise.</strong>.","banca":"IBFC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3582,"enunciado":"Em se tratando da sintaxe de colocação pronominal, assinale a alternativa, na qual, a descrição sobre a colocação do pronome negritado está corretamente justificada nos contextos que seguem.","opcoes":["“[...] afinal cada um acredita naquilo que bem lhe apraz”. [linha 3] (ocorre próclise em decorrência do advérbio bem)","“[...] o português ser hegemônico não nos deve cegar para as muitas línguas [...]”. [linhas 9 e 10] (ocorre próclise, mas deveria ocorrer mesóclise em decorrência da locução verbal deve cegar).","“[...] a situação se torna, no mínimo, preocupante.” [linhas 4 e 5] (ocorre próclise, mas deveria ocorrer ênclise por respeito à hierarquia de colocação pronominal).","“[...] Mostra-nos ainda mais [...]”. [linha 25] (ocorre ênclise, mas deveria ocorrer próclise por respeito à hierarquia de colocação pronominal).","“[...] línguas indígenas, europeias e asiáticas que aqui se falam [...]”. [linha 10] (ocorre próclise em decorrência do pronome relativo que)."],"correta":0,"explicacao":"Gabarito: <strong>“[...] afinal cada um acredita naquilo que bem lhe apraz”. [linha 3] (ocorre próclise em decorrência do advérbio bem)</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3583,"enunciado":"Observe o fragmento e: assinale a alternativa que contenha o mesmo padrão de colocações pronominais. “O que nos impede? (...) tornamo-nos os melhores no que fazemos”. I. Visitar-te-ei amanhã, daí já lhe entregarei os livros que tomei emprestado. II. O combinado de te trazer o livro raro não vou cumprir. Enviei-o para ser reformado. III. Muitos livros estão empoeirando, jogados em prateleiras esquecidas ao longo do tempo, assim se estragando, então, se não fossemos nós, os leitores, os livros seriam esquecidos.","opcoes":["I apenas","II apenas","III apenas","I e II apenas","I e III apenas"],"correta":1,"explicacao":"Gabarito: <strong>II apenas</strong>.","banca":"IBFC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3584,"enunciado":"Assinale a alternativa que apresenta correta colocação pronominal:","opcoes":["As famílias nunca sentiram-se tão desamparadas...","Ninguém me deixa falando sozinho, Édipo!","Tu farias-me a gentileza de providenciar um barco?","Naquele dia vi-te de uma maneira muito especial.","Nenhuma das alternativas anteriores."],"correta":1,"explicacao":"Gabarito: <strong>Ninguém me deixa falando sozinho, Édipo!</strong>.","banca":"FucapSul","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":3586,"enunciado":"Julgue o item a seguir, relativos a aspectos linguísticos do texto CB1A1-III. No trecho “é o impulso das trocas linguísticas que as está levando a essa situação” (segundo período), seria gramaticalmente correta a colocação da forma pronominal “as” em ênclise à forma de gerúndio “levando” — levando-as.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3587,"enunciado":"Acerca de aspectos linguísticos do texto CG1A1, julgue o seguinte item. No segmento “tendemos a não os notar” (penúltimo período do segundo parágrafo), a anteposição da forma pronominal “os” ao verbo “notar” é obrigatória, não sendo admitida a ênclise pronominal, em razão do emprego do vocábulo “não”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3590,"enunciado":"De acordo com a norma-padrão, pode-se alterar a colocação do pronome no trecho do texto indicado em:","opcoes":["Os outros pararam também em solidariedade, para saber o que passava-se.","Se juntaram os três motoristas, buscando solução.","Os motoristas revezavam-se, martelavam de um lado, do outro, de cima para baixo.","“E se desparafusarem as rodas, será que a pedra não solta-se?”","Todos olharam-se."],"correta":2,"explicacao":"Gabarito: <strong>Os motoristas revezavam-se, martelavam de um lado, do outro, de cima para baixo.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3591,"enunciado":"Assinale a alternativa que apresenta o plural CORRETO da frase, deixando a palavra prefeitura no singular: \"O capitão trouxe o troféu e irá expô-lo na prefeitura\"","opcoes":["Os capitãos trouxeram os troféis e iram expô-los na prefeitura","Os capitães trouxeram os troféus e irão expor eles na prefeitura.","Os capitães trouxeram os troféus e irão expô-los na prefeitura.","Os capitães trouxeram os troféis e irão expor-lhes na prefeitura.","Os capitões trouxerão os troféus e iram expô-los na prefeitura."],"correta":2,"explicacao":"Gabarito: <strong>Os capitães trouxeram os troféus e irão expô-los na prefeitura.</strong>.","banca":"Faculdade Alfa Umuarama - PR","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3592,"enunciado":"Considerando a colocação pronominal, qual a expressão, retirada do texto anterior, há a presença de uma próclise:","opcoes":["Como se sabe, o portfólio de crimes dos meliantes é enorme...","(...) valendo-se das modernas tecnologias e, sempre, aproveitando-se da boa-fé e até da ingenuidade de suas infelizes vítimas.","A verossimilhança é muito grande com um real contato do banco e, se não se estiver muito atento, as possibilidades de cair nessa armadilha são muito grandes.","Diante desses tantos recursos empregados pelos delinquentes, urge que autoridades, operadoras de telefonia, bancos e órgãos públicos se unam para desativar essas ferramentas que eles usam para obter lucro fácil.","Vem um telefone, geralmente 0800, junto para ela ligar, quando acaba falando com o golpista, que, dizendo-se ser do banco, a orienta a retirar o valor da conta como segurança e repassar para uma outra indicada por ele."],"correta":4,"explicacao":"Gabarito: <strong>Vem um telefone, geralmente 0800, junto para ela ligar, quando acaba falando com o golpista, que, dizendo-se ser do banco, a orienta a retirar o valor da conta como segurança e repassar para uma outra indicada por ele.</strong>.","banca":"Wisdom","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3594,"enunciado":"Considere as seguintes sentenças, retiradas do texto: I. “Estima-se que 4 milhões de toneladas de pesticidas sejam lançadas no meio ambiente todos os anos.” II. “Ratos se alimentaram da tesourinha de Santa Helena, um tipo de lacraia, até levar a espécie à extinção” Em relação à colocação pronominal, nas sentenças dadas observa-se, respectivamente:","opcoes":["próclise e ênclise.","próclise e mesóclise.","mesóclise e próclise.","mesóclise e ênclise.","ênclise e próclise."],"correta":4,"explicacao":"Gabarito: <strong>ênclise e próclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3597,"enunciado":"Assinale a alternativa que apresenta o período com colocação pronominal inadequada.","opcoes":["Para não fitá-lo, deixei cair os olhos.","Se soubesse, não continuaria a lê-lo.","Aqui, esboçar-se-ia uma querela sobre a essência da solidão.","Não pode-se calcular o valor de um amor.","Ao despertar, ainda as encontro lá."],"correta":3,"explicacao":"Gabarito: <strong>Não pode-se calcular o valor de um amor.</strong>.","banca":"MSConcursos","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3598,"enunciado":"Considerando a classificação da colocação pronominal no trecho “Santos Dumont imaginou o 14-Bis antes de construí-lo”. (linhas 98-99), é correto afirmar que se utiliza o pronome em posição","opcoes":["enclítica para estabelecer adequadamente a coesão referencial.","proclítica por se tratar de uma oração reduzida de infinitivo.","enclítica por se tratar de uma oração reduzida de gerúndio.","proclítica para estabelecer adequadamente a coesão referencial."],"correta":0,"explicacao":"Gabarito: <strong>enclítica para estabelecer adequadamente a coesão referencial.</strong>.","banca":"UECE-CEV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3599,"enunciado":"Assinale a frase com erro de colocação pronominal:","opcoes":["Nada me assusta mais do que a maldade dos homens.","Informar-lhe-ei sobre todas as mudanças do setor.","Não culpe-se pelos os erros de outras pessoas.","O importante é que nos unamos nesse projeto.","Ela se preocupava muito com a destruição do planeta."],"correta":2,"explicacao":"Gabarito: <strong>Não culpe-se pelos os erros de outras pessoas.</strong>.","banca":"CONTEMAX","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3602,"enunciado":"I. lhe ajudam II. os ajuda III. lhes ajuda IV. o ajuda","opcoes":["I e IV apenas","II apenas","I e II apenas","III e IV apenas","II e III apenas"],"correta":4,"explicacao":"Gabarito: <strong>II e III apenas</strong>.","banca":"IDIB","temas_relacionados":["colocacaoPronominal"]},{"id":3603,"enunciado":"O espaço vazio no trecho acima é completado com correta colocação pronominal e regência verbal em I. deter-lhes II. detê-los III. os deter IV. lhes deter","opcoes":["I e IV apenas","II apenas","I e II apenas","III e IV apenas","II e III apenas"],"correta":4,"explicacao":"Gabarito: <strong>II e III apenas</strong>.","banca":"IDIB","temas_relacionados":["colocacaoPronominal"]},{"id":3604,"enunciado":"Assinale a alternativa em que a transformação da linha 18, A cortina se abre nos olhos, tenha mantido adequação à norma culta no tocante à colocação pronominal.","opcoes":["A cortina não abre-se nos olhos","A cortina abrirá-se nos olhos","A cortina que abre-se nos olhos","A cortina tinha aberto-se nos olhos","A cortina abre-se nos olhos"],"correta":4,"explicacao":"Gabarito: <strong>A cortina abre-se nos olhos</strong>.","banca":"IDIB","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3605,"enunciado":"Assinale a alternativa errada quanto à colocação do pronome átono:","opcoes":["Chegou-se a mim, me cumprimentando lentamente.","Se a memória não me falha, seu nome é Ana.","O disco está com você, entregue-mo.","Ao ver-nos, cumprimentam-nos."],"correta":0,"explicacao":"Gabarito: <strong>Chegou-se a mim, me cumprimentando lentamente.</strong>.","banca":"FUNATEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3606,"enunciado":"Em “Não me abandone”, temos um caso de colocação pronominal do tipo:","opcoes":["Próclise","Mesóclise","Ênclise","Gerúndio"],"correta":0,"explicacao":"Gabarito: <strong>Próclise</strong>.","banca":"FUNATEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3608,"enunciado":"Analise a colocação pronominal das sentenças a seguir, segundo a norma padrão da língua portuguesa do Brasil: I.Conforme disse-lhes ontem, não há professores que possam lecionar essa disciplina. II.Quando te informaram sobre a falta de professores? III.Questiono-me se passaremos por essa crise nas licenciaturas. IV.Entreguem-lhe o microfone para que possa falar a respeito da situação das licenciaturas. V.Às vezes me pergunto onde está o motivo para o esvaziamento das licenciaturas. VI.Nunca esperou-se que as licenciaturas sofressem tal esvaziamento. Está correta a colocação pronominal em:","opcoes":["II, III, IV e V, apenas.","I, II, III, IV, V e VI.","I, III e V, apenas.","II, IV e VI, apenas.","I e VI, apenas."],"correta":0,"explicacao":"Gabarito: <strong>II, III, IV e V, apenas.</strong>.","banca":"FURB","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3611,"enunciado":"Nos enunciados reescritos a partir das informações do texto, a colocação pronominal e a regência atendem à norma-padrão em:","opcoes":["Não fosse a corrente de ar que lhe acometera, Mme. Thérèse já teria-se conformado em ser chamada de dona Teresa.","Dona Teresa certamente vira-se abalada com a corrente de ar, pois veio no meu apartamento magra, mais pálida e menor.","Dona Teresa me contou que, há cerca de 15 anos atrás, tinha exposto-se em uma corrente de ar em um outro apartamento.","Quando voltou, Mme. Thérèse informou-me de que sua debilidade era proveniente de uma corrente de ar no meu apartamento.","Eu entreguei o dinheiro a dona Teresa, ela contou-o. Depois foi lá dentro apanhar umas pobres coisas que se esquecera."],"correta":3,"explicacao":"Gabarito: <strong>Quando voltou, Mme. Thérèse informou-me de que sua debilidade era proveniente de uma corrente de ar no meu apartamento.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3612,"enunciado":"No trecho “Sem grande esforço, encontrar-se-á, em cada pessoa”, o termo “encontrar-se-á” é um exemplo de:","opcoes":["ênclise.","próclise.","gerúndio.","mesóclise.","metáfora."],"correta":3,"explicacao":"Gabarito: <strong>mesóclise.</strong>.","banca":"FAUEL","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3613,"enunciado":"Caso de divórcio (I) O divórcio é necessário. Todos conhecem dezenas de casos que convenceriam até um arcebispo. Eu mesmo conheço meia dúzia. Vou contar uns três ou quatro. O nome dele é Morgadinho. Baixo, retaco, careca precoce. Você conhece o tipo. No carnaval se fantasia de legionário romano e no futebol de praia dá pau que não é fácil. Frequenta o clube e foi lá que conheceu sua mulher, mais alta do que ele, morena, linda, as unhas do pé pintadas de roxo. Na noite de núpcias, ele lhe declarou. ― Se você algum dia me enganar, eu te esgoelo. ― Ora, Morgadinho… Ela se chama Fátima Araci. Ou é Mara Sirlei? Não, Fátima Araci. Não é que ela não goste do Morgadinho, é que nunca prestou muita atenção no marido. Na cerimônia do casamento já dava para notar. O olhar dela passava dois centímetros acima da careca do Morgadinho. Ela estava maravilhada com o próprio casamento e o Morgadinho era um simples acessório daquele dia inesquecível. Como um castiçal ou um coroinha. No álbum de fotografias do casamento que ela guardou junto com a grinalda, há esta constatação terrível: o Morgadinho não aparece. Aparece o coroinha mas não aparece o Morgadinho. Um ou dois meses depois do casamento, o Morgadinho sugeriu que ela lhe desse um apelido. Um nome secreto, carinhoso, para ser usado na intimidade, algo que os unisse ainda mais, sei lá. Ela prometeu que ia pensar no assunto. O Morgadinho insistiu. ― Eu te chamo de Fafá e você me chama de qualquer coisa. ― Vamos ver. Uma semana depois, Morgadinho voltou ao assunto. ― Já pensaste num apelido para mim, Fafá? ― Ainda não. Três semanas depois, ele mesmo deu um palpite. ― Quem sabe Momo? ― Não. ― Gagá? Fofura? ― Tomou coragem e, rindo meio sem jeito, arriscou: ― Tigre? Ela nem riu. Pediu que ele tivesse paciência. Estava lendo o Sétimo Céu. Tinha tempo. O Morgadinho não desistiu. Às vezes, chegava em casa com uma novidade. ― Que tal este: “Barrilzinho”? ― Não gosto. Outra vez, os dois estavam passando por um quintal e ouviram uma criança chamando um cachorro. ― Pitoco. Vem, Pitoco. Morgadinho virou-se para a mulher, cheio de esperança, mas ela fez que não com a cabeça. Finalmente (passava um ano do casamento e nada de apelido), Morgadinho perdeu a paciência. Estavam os dois na cama. Ela pintava as unhas do pé. ― Você não me ama. ― Ora, Morgadinho… ― Até hoje não pensou num apelido para mim. ― Está bem, sabe o que tu és? Um xaropão. Taí teu apelido. Xaropão. O Morgadinho já tinha enfrentado várias levas de policiais a tapa. Uma vez desmontara um bar depois de um mal-entendido e saíra para a rua dando cadeiradas em meio mundo. Homens, mulheres e crianças. Mas naquela noite virou-se para o lado e chorou no travesseiro. Aí a mulher, com cuidado para não estragar o esmalte, chegou perto do seu ouvido e disse, rindo: ― Xaropãozinho… ― Rindo. Rindo! Luís Fernando Verissimo. Ed Mort – todas as histórias. 1ª Ed. São Paulo: Objetiva, 2011. Considere as seguintes sentenças, retiradas do texto: I. “Mas naquela noite virou-se para o lado e chorou no travesseiro.” II. “Você não me ama.” Nas sentenças dadas, a colocação pronominal ocorre, respectivamente, como:","opcoes":["mesóclise e próclise.","mesóclise e ênclise.","próclise e ênclise.","ênclise e ênclise.","ênclise e próclise."],"correta":0,"explicacao":"Gabarito: <strong>mesóclise e próclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal","ortografia"]},{"id":3616,"enunciado":"Relativamente a aspectos gramaticais, analise as assertivas. I. Considerando a colocação pronominal, na frase que se dilata por horizontes infindos, tem-se um caso de ênclise. II. O verbo reboa, na frase reboa entre os mugidos das reses, a voz saudosa e plangente do rapaz, possui como sinônimo o verbo retumba. III. Há linguagem conotativa em ao morrer do dia. Pode-se afirmar que:","opcoes":["As assertivas I e III estão incorretas.","As assertivas I e II estão corretas.","As assertivas I, II e III estão corretas.","As assertivas II e III estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>As assertivas II e III estão corretas.</strong>.","banca":"IESES","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3619,"enunciado":"“Não se sabe o papel dos fatores demográficos (nascimentos e mortes)” (linha 3). Neste trecho, localizado no 2º parágrafo, faz-se o uso da próclise. A próclise, assim como a ênclise e a mesóclise, são colocações pronominais possíveis na língua portuguesa. Assinale a alternativa em que a mesóclise foi usada incorretamente.","opcoes":["Ver-nos-emos mais tarde na praça, conforme o combinado.","A turnê, disseram-me, iniciar-se-á em breve.","Os problemas resolver-se-iam com o tempo, apontou o relatório.","Ela informou que não entregar-se-ia para a polícia."],"correta":3,"explicacao":"Gabarito: <strong>Ela informou que não entregar-se-ia para a polícia.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3620,"enunciado":"Respeitando a hierarquia da sintaxe de colocação pronominal, o trecho “...não daria a mínima para as afirmações...” (linha 16) poderia ser reescrito consoante a alternativa","opcoes":["“Não daria-lhes a mínima”.","“Daria-lhes a mínima”.","“Dar-nos-ei a mínima”.","“Dar-lhes-ia a mínima”."],"correta":3,"explicacao":"Gabarito: <strong>“Dar-lhes-ia a mínima”.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3621,"enunciado":"“A escavação também revelou uma estrutura ornamentada que se acredita ser uma fonte (...). (linha 8) “Referindo-se a um texto medieval, “A Pátria”, que fala sobre Constantinopla, Dunn explicou (...)”. (linha 27) Acerca do uso dos pronomes nos excertos acima, assinale a alternativa correta.","opcoes":["Há próclise obrigatória na primeira oração por causa da presença de pronome relativo; enquanto há ênclise obrigatória na segunda oração porque o verbo está no início da oração.","Há próclise facultativa na primeira oração por causa da presença de pronome relativo; enquanto há ênclise obrigatória na segunda oração porque o verbo está no início da oração.","Há próclise obrigatória na primeira oração por causa da presença de pronome relativo; enquanto há ênclise obrigatória na segunda oração porque o verbo está no imperativo sem palavra atrativa.","Há próclise facultativa na primeira oração por causa da presença de pronome demonstrativo antes do verbo; enquanto há ênclise obrigatória na segunda oração porque o verbo está no imperativo sem palavra atrativa."],"correta":0,"explicacao":"Gabarito: <strong>Há próclise obrigatória na primeira oração por causa da presença de pronome relativo; enquanto há ênclise obrigatória na segunda oração porque o verbo está no início da oração.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3622,"enunciado":"Considere o seguinte excerto do texto: “Descanse que ainda hoje dançará duas ou três valsas com ela, se a tem, ou com elas”. (linhas 45 e 46) Assinale a alternativa que contém o fenômeno e a justificativa acerca do uso do pronome oblíquo “a” destacado no trecho acima.","opcoes":["Ênclise é usada quando há pausa antes do verbo sem palavra atrativa.","Próclise é usada quando há advérbio ou palavra denotativa antes do verbo.","Próclise é usada quando há conjunções e locuções subordinativas antes do verbo.","Ênclise é usada quando há verbo no início da oração sem palavra atrativa."],"correta":2,"explicacao":"Gabarito: <strong>Próclise é usada quando há conjunções e locuções subordinativas antes do verbo.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3623,"enunciado":"Há inadequação de colocação pronominal na seguinte alternativa:","opcoes":["Alguns deram-lhes maus conselhos.","Ontem me disseram que havia greve hoje.","Conforme lhe disse, hoje vou sair mais cedo.","Orgulhar-me-ia dos meus alunos.","Depois de terminar, chamem-nos."],"correta":0,"explicacao":"Gabarito: <strong>Alguns deram-lhes maus conselhos.</strong>.","banca":"ADVISE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3624,"enunciado":"No que diz respeito à colocação pronominal, considere as frases abaixo. I. Nunca deixe-me só. II. Onde me viste? III. Deixar-te-ia ir se você pedisse. IV. Estudar é dedicar-se. Há erro em:","opcoes":["apenas uma das frases acima.","apenas duas das frases acima.","apenas três das frases acima.","nenhuma das frases acima.","todas as frases acima."],"correta":0,"explicacao":"Gabarito: <strong>apenas uma das frases acima.</strong>.","banca":"Instituto SEPROD","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3625,"enunciado":"Em “Olavo Bilac curou-se com Bromil”, há o exemplo de colocação pronominal denominada","opcoes":["próclise, pois o pronome está após o verbo.","próclise, pois o pronome está no meio do verbo.","ênclise, pois o pronome está após o verbo.","ênclise, pois o pronome está no meio verbo."],"correta":2,"explicacao":"Gabarito: <strong>ênclise, pois o pronome está após o verbo.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3626,"enunciado":"No trecho “- Mato-o. Mato-lhe. Mato você. Matar-lhe-ei-te. Ouviu bem?”, o interlocutor faz uma crítica aos usos da colocação pronominal valendo-se do recurso da","opcoes":["ironia.","metáfora.","comparação.","paródia."],"correta":0,"explicacao":"Gabarito: <strong>ironia.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3629,"enunciado":"Assinale a alternativa em que a colocação dos pronomes está de acordo com a norma-padrão da língua portuguesa.","opcoes":["Já se imaginaram doando tudo o que não estão usando mais?","Nunca cuidou-se tanto desses móveis como nos últimos tempos.","Me disseram que as roupas estavam em bom estado.","Aqui costuma-se consertar os sapatos e não comprar novos.","Naquela família, tinham acumulado-se muitos objetos com pouco uso."],"correta":0,"explicacao":"Gabarito: <strong>Já se imaginaram doando tudo o que não estão usando mais?</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3632,"enunciado":"Em relação à colocação pronominal, pode-se afirmar que no verso: I. “À voz do meu amor, que em vão te chama”, está incorreta, pois o correto seria “A voz do meu amor, que em vão lhe chama”; II. “Doce raio do sol que me dê vida”, está incorreta, pois o correto seria “Doce raio do sol que dê-me vida”; III. “A arazóia na cinta me apertaram”, está correta. Sobre as afirmativas acima, é correto afirmar que:","opcoes":["II está correta, I e III estão incorretas.","l e III estão corretas, II está incorreto.","l e II estão incorretas, III está correta.","I, II e III estão corretas.","I, II e III estão incorretas."],"correta":2,"explicacao":"Gabarito: <strong>l e II estão incorretas, III está correta.</strong>.","banca":"UFRR","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3633,"enunciado":"De acordo com as regras da norma padrão da Língua Portuguesa, é possível identificar um desvio de colocação pronominal em “Eu ponho o saco na cabeça e levo-a nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que revolto-me.”. Tal desvio pode ser corrigido com a seguinte reescrita:","opcoes":["Eu o ponho o saco na cabeça e levo-a nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que revolto-me.","Eu ponho o saco na cabeça e levo-a nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que revolto-o.","Eu ponho o saco na cabeça e levo-te nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que revolto-me.","Eu ponho o saco na cabeça e levo-a nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que revolto-nos.","Eu ponho o saco na cabeça e levo-a nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que me revolto."],"correta":4,"explicacao":"Gabarito: <strong>Eu ponho o saco na cabeça e levo-a nos braços. Suporto o peso do saco na cabeça e suporto o peso da Vera Eunice nos braços. Tem hora que me revolto.</strong>.","banca":"UFRR","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3634,"enunciado":"A alternativa em que a colocação pronominal está de acordo com a norma-padrão é:","opcoes":["\"Foi ela que ajudou-o naquilo\".","\"Não despeço-me de ninguém\".","\"Não me despeço de ninguém\".","\"Lhe pedi ajuda, mas ela negou\"."],"correta":2,"explicacao":"Gabarito: <strong>\"Não me despeço de ninguém\".</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3635,"enunciado":"Considerando o trecho “Sua experiência de barata lhe dava acesso a sujeiras mal suspeitadas, [...]” (2º§), assinale a afirmativa que justifica corretamente a colocação do pronome lhe.","opcoes":["É obrigatório o uso da próclise quando houver palavras atrativas que justifiquem o adiantamento dos pronomes, como pronomes possessivos.","É facultativo o uso da próclise quando houver palavras atrativas que justifiquem o adiantamento dos pronomes, como pronomes possessivos.","É obrigatório o uso da próclise, caso o verbo não se encontre no início da frase nem haja situações que justifiquem o uso específico de outra forma de colocação pronominal.","É facultativo o uso da próclise, caso o verbo não se encontre no início da frase nem haja situações que justifiquem o uso específico de outra forma de colocação pronominal."],"correta":1,"explicacao":"Gabarito: <strong>É facultativo o uso da próclise quando houver palavras atrativas que justifiquem o adiantamento dos pronomes, como pronomes possessivos.</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3639,"enunciado":"Considere as seguintes sentenças, retiradas do texto: I. “Lustosa se animou a trabalhar na reprodução de seis espécies” II. “Atribui-se aos jesuítas a introdução de abelhas com ferrão procedentes da África.” Nas sentenças dadas, a colocação dos pronomes corresponde, respectivamente, aos tipos:","opcoes":["ênclise e próclise.","ênclise e mesóclise.","próclise e ênclise.","próclise e mesóclise.","mesóclise e ênclise."],"correta":2,"explicacao":"Gabarito: <strong>próclise e ênclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3640,"enunciado":"Considere as seguintes sentenças: I. Elas se calaram diante do juiz. II. Dir-te-ei sempre o que quiseres ouvir. Em relação à colocação pronominal, nas sentenças dadas ocorre, respectivamente:","opcoes":["próclise e ênclise.","ênclise e próclise.","próclise e mesóclise.","ênclise e mesóclise.","mesóclise e próclise."],"correta":2,"explicacao":"Gabarito: <strong>próclise e mesóclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3642,"enunciado":"Julgue o item que se segue. A regra que determina a ênclise no uso do imperativo afirmativo, como em “Deixe-me entrar”, não vale para o imperativo negativo, situação de pede a próclise: “Não nos interrompa”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3643,"enunciado":"O trecho “Pouco não me serve, médio não me satisfaz, metades nunca foram meu forte” traz em destaque a colocação dos pronomes em relação ao verbo. Sobre a colocação pronominal, pode-se afirmar que se trata de ocorrências de:","opcoes":["Próclise e ênclise.","Próclise e próclise.","Ênclise e mesóclise.","Ênclise e ênclise.","Mesóclise e próclise."],"correta":1,"explicacao":"Gabarito: <strong>Próclise e próclise.</strong>.","banca":"FACET Concursos","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3644,"enunciado":"No trecho “Entupo-me de ausências, esvazio-me de excessos”, percebe-se que os pronomes estão colocados em determinada posição em relação ao verbo. Assinale a alternativa, a seguir, que não apresente o mesmo padrão utilizado no poema:","opcoes":["“Encontre-me ao fim de suas atividades escolares”.","“Jogue-me às chamas e eu renascerei”.","“Dê-lhe espaço suficiente para pensar”.","“Tranquiliza-lo-ei com boas notícias”.","“Libertemo-nos já!”."],"correta":3,"explicacao":"Gabarito: <strong>“Tranquiliza-lo-ei com boas notícias”.</strong>.","banca":"FACET Concursos","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3645,"enunciado":"Julgue o item a seguir. A regra que determina a ênclise no uso do imperativo afirmativo, como em “Deixe-me entrar”, não vale para o imperativo negativo, situação de pede a próclise: “Não nos interrompa”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3646,"enunciado":"Julgue o item a seguir. Na frase “Contarei-te toda a verdade”, a colocação do pronome está adequada, já que no início de frase a próclise é proibida na norma padrão.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3647,"enunciado":"Julgue o item subsequente. A colocação do pronome oblíquo átono está conforme as normas da gramática padrão em “Deus ouça-te!” e em “Eles tinham avisado-nos”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3648,"enunciado":"Julgue o item que se segue. A colocação do pronome oblíquo átono está conforme as normas da gramática padrão em “Deus ouça-te!” e em “Eles tinham avisado-nos”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3649,"enunciado":"Julgue o item a seguir. Na frase “Na próxima semana, traga-me mais sugestões”, o pronome oblíquo átono deveria estar anteposto ao verbo, uma vez que advérbio e locução adverbial são atrativos de próclise.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3650,"enunciado":"A colocação pronominal atende à norma-padrão em:","opcoes":["Premiar é prestigiar quem tem dedicado-se de maneira significativa para o avanço de um campo do conhecimento.","Se reconhece, com uma premiação científica, o trabalho realizado por um pesquisador, uma equipe ou instituição.","Normalmente dispõe-se de alguma quantia em dinheiro, como incentivo, quando acontece uma premiação cientifica.","De que outra maneira se ganharia espaço no horário nobre, além dos momentos de divulgação dos vencedores do Nobel?","É fato que dedicam-se minutos dos telejornais do mundo, quando a academia sueca anuncia os vencedores do Nobel."],"correta":3,"explicacao":"Gabarito: <strong>De que outra maneira se ganharia espaço no horário nobre, além dos momentos de divulgação dos vencedores do Nobel?</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3651,"enunciado":"O período do 1º parágrafo – De lá para cá, passaram-se quase 30 anos e ainda identificamos pontos em comum com aquela realidade. – está reescrito em conformidade com a norma-padrão de concordância verbal e de colocação pronominal em:","opcoes":["30 anos são passados, de lá para cá, e ainda identifica-se pontos em comum com aquela realidade.","Se passaram 30 anos, de lá para cá, e ainda se identifica pontos em comum com aquela realidade.","De lá para cá, já foi 30 anos, e ainda identificam-se pontos em comum com aquela realidade.","Passaram-se 30 anos, de lá para cá, e ainda se identificam pontos em comum com aquela realidade.","Identifica-se ainda pontos em comum com aquela realidade, e se foram 30 anos, de lá para cá"],"correta":3,"explicacao":"Gabarito: <strong>Passaram-se 30 anos, de lá para cá, e ainda se identificam pontos em comum com aquela realidade.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3652,"enunciado":"Nos versos: “Deixem-me quedar, deixem-me quieta” De acordo com as regras da colocação pronominal da norma padrão da língua, é uma análise correta do emprego nos versos acima a alternativa:","opcoes":["A colocação pronominal depois do verbo é a forma básica de colocação pronominal, seguindo a estrutura sintática básica de uma oração: verbo seguido de complemento.","O uso da próclise encontra-se generalizado na linguagem falada e escrita, sendo facultativo o uso da próclise ou da ênclise, caso o verbo se encontre no início da frase.","A próclise deverá ser utilizada quando o verbo se encontrar no início das frases. Nesta situação, a forma correta de colocação pronominal é anterior ao verbo.","A colocação pronominal antes do verbo deverá ser usada em orações imperativas afirmativas.","A colocação pronominal deverá ser feita antes do verbo apenas quando houver palavras atrativas que justifiquem o adiantamento do pronome, como em orações reduzidas de gerúndio."],"correta":0,"explicacao":"Gabarito: <strong>A colocação pronominal depois do verbo é a forma básica de colocação pronominal, seguindo a estrutura sintática básica de uma oração: verbo seguido de complemento.</strong>.","banca":"Instituto Darwin","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3655,"enunciado":"Acerca de aspectos gramaticais do texto apresentado, julgue o item. A colocação pronominal no trecho “Se acostuma para evitar feridas”, no último parágrafo, não segue as normas da modalidade padrão da língua portuguesa, pois, de acordo com tais normas, não se deve iniciar período com pronome átono.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Ibest","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3657,"enunciado":"A colocação pronominal refere-se à posição ocupada pelos pronomes pessoais oblíquos átonos em relação ao verbo. Assinale a alternativa em que a colocação pronominal está de acordo com as regras da escrita formal.","opcoes":["Naquela cidade, muito falou-se sobre os acontecimentos que cercaram a morte do professor.","Ele acreditava que nada faltar-lhe-ia tendo em vista que a aposentadoria era generosa.","Infelizmente, me deram a triste notícia sem qualquer piedade, de maneira brusca.","Sem dúvida, aquilo nos deixou imensamente abalados, por sermos amigos de longa data."],"correta":3,"explicacao":"Gabarito: <strong>Sem dúvida, aquilo nos deixou imensamente abalados, por sermos amigos de longa data.</strong>.","banca":"UFMT","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3658,"enunciado":"Assinale a frase que está de acordo com a norma padrão da língua portuguesa.","opcoes":["Você nunca entre sem mim te mandar; ouviu, Maria?","Ele me pediu para mim deixar de trabalhar.","Na Espanha não se pedem favores; manda-se, e pobre de quem não obedece às ordens.","Quando nós lhe vimos, ele fez-nos sinal que aproximasse-nos.","Não compreendi o ponto que o professor discorreu na aula ontem."],"correta":2,"explicacao":"Gabarito: <strong>Na Espanha não se pedem favores; manda-se, e pobre de quem não obedece às ordens.</strong>.","banca":"FUNTEF - PR","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3659,"enunciado":"No período “Nós os encontráramos mais cedo”, há possibilidade de outra construção dentro da norma culta, de acordo com as regras de colocação pronominal?","opcoes":["Sim, pois o pronome pode vir enclítico ao verbo.","Sim, pois seria possível provocar uma mesóclise.","Não, já que a acentuação em português recai até a antepenúltima sílaba.","Não, pois existe um fato claro de próclise."],"correta":2,"explicacao":"Gabarito: <strong>Não, já que a acentuação em português recai até a antepenúltima sílaba.</strong>.","banca":"Instituto Access","ano":2023,"temas_relacionados":["colocacaoPronominal","silabas"]},{"id":3661,"enunciado":"Em “é possível tentar se proteger individualmente com o uso de repelentes”, há o uso de qual colocação pronominal?","opcoes":["Próclise.","Mesóclise.","Ênclise.","Epêntese."],"correta":0,"explicacao":"Gabarito: <strong>Próclise.</strong>.","banca":"Instituto Fênix","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3663,"enunciado":"Considerando-se a colocação dos pronomes oblíquos átonos, assinalar a alternativa na qual houve ERRO:","opcoes":["Eu vos vejo andar rápido.","Eu tinha vendido-te o livro.","Eu estava lhe vendendo o livro.","Eu estava-lhe vendendo o livro."],"correta":1,"explicacao":"Gabarito: <strong>Eu tinha vendido-te o livro.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3666,"enunciado":"No segundo quadro, o verbo “esquecer” foi usado coloquialmente. Em registro formal, a fala do adulto resultaria em","opcoes":["“Se esquece os vizinhos?!”","“Esqueceu-se os vizinhos?!”","“Esquece dos vizinhos?!”","“Esquece-se dos vizinhos?!”","“Esqueceu-se dos vizinhos?!”"],"correta":4,"explicacao":"Gabarito: <strong>“Esqueceu-se dos vizinhos?!”</strong>.","banca":"FADENOR","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3667,"enunciado":"Considere as passagens a seguir: I. “Sou o que se chama de pessoa impulsiva.” II. “Acho que assim: vem-me uma ideia ou um sentimento [...].” III. “[...] o que prova que não se tratava de intuição [...].” IV. “Trata-se de saber se devo prosseguir nos meus impulsos.” V. “Ou devo lutar e tornar-me uma pessoa mais adulta?” Sobre essas passagens, é CORRETO afirmar:","opcoes":["Em IV, nos dois usos, o “se” constitui índice de indeterminação do sujeito.","Em II e V, a posição enclítica do pronome oblíquo “me” é obrigatória.","Em I e III, ocorre próclise motivada pela presença de palavras atrativas.","Em IV, o “se” em “trata-se” exerce a função de partícula apassivadora.","Em II, o pronome oblíquo “me” indica que o verbo está na voz reflexiva."],"correta":2,"explicacao":"Gabarito: <strong>Em I e III, ocorre próclise motivada pela presença de palavras atrativas.</strong>.","banca":"FADENOR","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3668,"enunciado":"Julgue o item que se segue. A ênclise é a colocação pronominal em que o pronome átono vem antes do verbo, como em “Me dê um tempo.”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3669,"enunciado":"Julgue o item a seguir. A ênclise é a colocação pronominal em que o pronome átono vem antes do verbo, como em “Me dê um tempo.”\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3670,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item a seguir. Em “Acredita&#8209;se que o incêndio da biblioteca foi uma enorme perda para a humanidade” (linhas 8 e 9), a opção pela ênclise foi feita porque o pronome oblíquo “se” está atrelado a um verbo no início de uma frase.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3672,"enunciado":"Quanto à colocação do pronome pessoal oblíquo, assinale a frase incorreta.","opcoes":["Espero não perturbá-lo com essa interrupção.","Que a terra lhe seja leve.","Ao sentirem-no pulsar, choraram de emoção.","As compras, me disse ela, só chegaram à tarde.","Convém que cumpra-se a lei."],"correta":4,"explicacao":"Gabarito: <strong>Convém que cumpra-se a lei.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3674,"enunciado":"Assinale a alternativa em que a colocação pronominal está em conformidade com a norma-padrão.","opcoes":["Como não podia casar-se com Lurdinha, o fantasma pôs-se a fumar sem parar, como forma de suspirar.","Certamente tratava-se de um fantasma antiquado, que interessava-se em ver as moças ao deitar ou despertar.","Tendo verificado-se um doloroso acidente no seu mundo, os fantasmas abstiveram-se do cigarro.","O fantasma se dedicava a assistir às rotinas das moças, sem imaginar que apaixonaria-se por Lurdinha.","Se invisibilizava o fantasma e ficava rotineiramente a espiar as moças, quando se despiam ou se vestiam."],"correta":0,"explicacao":"Gabarito: <strong>Como não podia casar-se com Lurdinha, o fantasma pôs-se a fumar sem parar, como forma de suspirar.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3676,"enunciado":"Em “Eu contarei a verdade a você.”, o segmento está CORRETAMENTE reescrito em qual alternativa?","opcoes":["Eu contarei-lhe a verdade.","Eu contarei-la a você.","Eu contarei-te a você.","Eu lhe contarei a verdade."],"correta":3,"explicacao":"Gabarito: <strong>Eu lhe contarei a verdade.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3677,"enunciado":"Nos versos “Dê-me um cigarro” e “Me dá um cigarro”, os diferentes usos da colocação pronominal evidenciam uma crítica negativa","opcoes":["aos desvios da norma padrão da linguagem.","aos usos padronizados da linguagem.","às variações da linguagem.","à linguagem falada no dia a dia."],"correta":1,"explicacao":"Gabarito: <strong>aos usos padronizados da linguagem.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3678,"enunciado":"No verso “Me dá um cigarro” há a ruptura com a regra gramatical de colocação pronominal, denominada","opcoes":["ênclise.","mesóclise.","próclise.","antítese."],"correta":0,"explicacao":"Gabarito: <strong>ênclise.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3679,"enunciado":"A colocação pronominal foi feita CORRETAMENTE em:","opcoes":["Não pode-se argumentar de modo simplista, pois é necessário que evidências científicas sempre sejam observadas.","Conforme consta, ali tem-se um solo que mantém-se congelado ao longo de todo o ano, independentemente da estação.","Se sabe que as mutações podem ser boas para todos, pois são muitas as pesquisas desenvolvidas no campo das ciências.","Em relação a alguns seres, é possível destacar que muitos se encontram em processo de extinção."],"correta":3,"explicacao":"Gabarito: <strong>Em relação a alguns seres, é possível destacar que muitos se encontram em processo de extinção.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3680,"enunciado":"Nas frases “- Me chame de você” e “- Me enganei, ou eram cascas de camarão?”, os interlocutores rompem com a regra gramatical de colocação pronominal denominada","opcoes":["ênclise.","próclise.","mesóclise.","antítese."],"correta":0,"explicacao":"Gabarito: <strong>ênclise.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3681,"enunciado":"A colocação do pronome oblíquo átono está conforme as normas da gramática padrão em “Deus ouça-te!” e em “Eles tinham avisado-nos”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3682,"enunciado":"Julgue o item subsequente. A ênclise é a colocação pronominal em que o pronome átono vem antes do verbo, como em “Me dê um tempo.”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3684,"enunciado":"Assinale as opções em que a colocação pronominal não está correta.","opcoes":["Minha garotinha me aguarda sempre no portão.","Não se sinta pressionado com essa injustiça.","Me diz tudinho, tin tin por tin tin ...","Ajudá-lo-ei no que for necessário."],"correta":2,"explicacao":"Gabarito: <strong>Me diz tudinho, tin tin por tin tin ...</strong>.","banca":"AGIRH","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3685,"enunciado":"“Se animou. Se mobilizou.” Sobre a colocação do pronome átono, no trecho entre aspas, é correto afirmar que","opcoes":["está conforme o uso das regras da ênclise.","está conforme o uso das regras da próclise.","está em desacordo com as regras da ênclise.","está em desacordo com as regras da próclise."],"correta":2,"explicacao":"Gabarito: <strong>está em desacordo com as regras da ênclise.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3686,"enunciado":"Leia a charge. Fonte: Disponível em: https://mentirinhas.com.br/mentirinhas-20/. Acesso em: 18 set 2023. Em relação aos pronomes utilizados, é correto afirmar que","opcoes":["há um erro de colocação pronominal no primeiro quadrinho, onde deveria ter sido usada mesóclise.","no último quadrinho, o pronome oblíquo deveria ser substituído pelo pronome pessoal do caso reto da primeira pessoa do singular.","há um caso de próclise inaceitável no primeiro quadrinho.","a próclise utilizada no primeiro quadrinho não apresenta desvios em relação às regras de colocação pronominal."],"correta":2,"explicacao":"Gabarito: <strong>há um caso de próclise inaceitável no primeiro quadrinho.</strong>.","banca":"Unoesc","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3688,"enunciado":"A colocação pronominal atende à norma-padrão em:","opcoes":["Lhe afirmou que todas as alterações seriam feitas em breve.","Em se tratando de informações, é necessário ter cuidado.","Ali fazia-se essencial intervenções de grande impacto.","Jamais disse-me que estaria indisponível para viagens internacionais."],"correta":1,"explicacao":"Gabarito: <strong>Em se tratando de informações, é necessário ter cuidado.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3690,"enunciado":"Analise as afirmações seguintes sobre a colocação dos pronomes destacados e assinale a alternativa correta.","opcoes":["Em “contra uma estrutura que já se arrastava por três séculos.” (linhas 35 e 36), a próclise se justifica porque a forma verbal “arrastava” está antecedida pela locução pronominal “que já”.","Em “Ambas lhe são abstrações inacessíveis.” (linha 112), a ênclise se justifica porque o sujeito da oração, anteposto à forma verbal “são”, é um numeral.","Em “abordoado ao clássico bastão em que se apoia o passo tardo dos peregrinos...” (linhas 99-101), a próclise se justifica pela presença da locução conjuntiva “em que”.","Em “Porque não no-los separa um mar, separamno-los três séculos...” (linhas 135 e 136), as duas ocorrências de ênclise em destaque se justificam porque, em ambos os casos, a forma verbal “separa” é pronominal.","Em “Canudos não se rendeu.” (linha 141), a próclise se justifica porque o pronome “se” ocorre depois de uma palavra negativa."],"correta":4,"explicacao":"Gabarito: <strong>Em “Canudos não se rendeu.” (linha 141), a próclise se justifica porque o pronome “se” ocorre depois de uma palavra negativa.</strong>.","banca":"UEM","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3691,"enunciado":"A colocação pronominal atende à norma-padrão em:","opcoes":["Conforme explicado, sempre lhe dirigiria a palavra primeiramente.","Me disse que todas as informações seriam disponibilizadas por meio do aplicativo.","Em tratando-se de novas pesquisas, é preciso que a população colabore.","Nunca informou-nos acerca das normas de convivência do ambiente."],"correta":0,"explicacao":"Gabarito: <strong>Conforme explicado, sempre lhe dirigiria a palavra primeiramente.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3692,"enunciado":"Obedecendo à sintaxe da língua portuguesa, a forma básica de colocação pronominal é a ênclise, mas o uso da próclise está bastante generalizado tanto na escrita como na oralidade, a exemplo de O coordenador me explicou toda a situação OU O coordenador explicou-me toda a situação. Qual trecho admite, no registro formal, uma única colocação pronominal?","opcoes":["E ela os ninava, talvez sem perceber","Essa imagem de livros queridos sendo acalentados encheu-me de ternura","Olho-os e vejo como eles são puros, íntegros – como as crianças e os cristais.","Esse amor pelos livros me comove, um amor que venho aprendendo a desenvolver nos últimos anos."],"correta":2,"explicacao":"Gabarito: <strong>Olho-os e vejo como eles são puros, íntegros – como as crianças e os cristais.</strong>.","banca":"UFMT","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3695,"enunciado":"A colocação pronominal não está de acordo com a norma culta da Língua Portuguesa na seguinte frase:","opcoes":["Não se esqueça da importância da formação profissional dos jovens;","Me comentaram sobre o debate público referente ao NEM;","Devo esclarecer-lhe o ocorrido durante o debate;","Realizar-se-á, em breve, um novo evento sobre o futuro da educação;","Refere-se a um debate importante para o desenvolvimento inclusivo no Brasil."],"correta":1,"explicacao":"Gabarito: <strong>Me comentaram sobre o debate público referente ao NEM;</strong>.","banca":"IBADE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3698,"enunciado":"Observe a sintaxe de colocação do pronome pessoal oblíquo átono destacado no trecho a seguir: “Para Cintia, o servidor do futuro é aquele que se dispõe a aprender todos os dias.”(§ 6) Em relação à colocação do pronome oblíquo átono, é CORRETO afirmar que, no trecho acima, ocorreu:","opcoes":["ênclise.","próclise.","mesóclise.","sinédoque."],"correta":1,"explicacao":"Gabarito: <strong>próclise.</strong>.","banca":"UFV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3701,"enunciado":"Na frase “A história oficial do IBGE iniciou-se na data de 29 de maio de 1936, por meio da implementação do chamado Instituto Nacional de Estatística (INE)”, destaca-se um caso de ênclise, em que o pronome está posposto ao verbo. A alternativa cujo pronome destacado, à luz da norma-padrão, também deve vir nessa posição é:","opcoes":["Corri para o defender.","Ainda se lembra de mim?","Nunca se queixa de nada.","Só me ofereceram um copo d’água.","Quando tiver um tempinho, me avise."],"correta":4,"explicacao":"Gabarito: <strong>Quando tiver um tempinho, me avise.</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3702,"enunciado":"A alternativa em que o pronome destacado deve estar necessariamente na posição em que foi colocado é:","opcoes":["As ambições particulares se sobrepunham às carências coletivas...","Irritado com os críticos de arte a não lhe darem sossego...","... Balzac apontou-lhes o dedo.","Ficção e agudo exame da sociedade mesclaram-se na obstinada defesa do bom jornalismo.","... palavras do livro se articulam para escancarar hipocrisias, falsidades."],"correta":1,"explicacao":"Gabarito: <strong>Irritado com os críticos de arte a não lhe darem sossego...</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3704,"enunciado":"Considere o texto a seguir. Diz que o físico falou para o neurocientista: nada é mais complexo do que o universo, origem de tudo o que existe, ao que o outro retrucou: exceto a massa de células que ______________I_________ . O economista que cruzava a praça não teve dúvidas: eis aí dois agentes racionais, maximizando capital social; enquanto o antropólogo ______________II______________- que não atrapalhasse o debate, de interesse etnográfico. (Álvaro Machado Dias, Piada de cientista. Folha de S.Paulo. 26.07.2022. Adaptado) De acordo com a norma-padrão da língua, as lacunas do texto devem ser preenchidas com:","opcoes":["(I) lhe possibilita conceber-lhe … (II) pedia-lhe","(I) lhe possibilita concebê-lo … (II) pedia-o","(I) lhe possibilita concebê-lo … (II) pedia-lhe","(I) o possibilita concebê-lo … (II) pedia-o","(I) o possibilita concebê-lo … (II) pedia-lhe"],"correta":2,"explicacao":"Gabarito: <strong>(I) lhe possibilita concebê-lo … (II) pedia-lhe</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3706,"enunciado":"Na frase do anúncio “Imigrante, São Paulo te acolhe.”, o pronome oblíquo “te” foi empregado antes da forma verbal “acolhe”, ocasionando a próclise. Acerca desse emprego, pode-se afirmar que","opcoes":["configura um desvio em relação às regras de colocação pronominal, evidenciando um processo de variação linguística.","configura um desvio em relação às regras de colocação pronominal, explicitando sua inadequação na elaboração do gênero textual anúncio.","configura um uso prescrito pelas regras de colocação pronominal, demonstrando a formalidade da linguagem verbal desse anúncio.","configura um uso prescrito pelas regras de colocação pronominal, atendendo à exigência de que todo anúncio deve se estruturar conforme a norma-padrão."],"correta":0,"explicacao":"Gabarito: <strong>configura um desvio em relação às regras de colocação pronominal, evidenciando um processo de variação linguística.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3707,"enunciado":"Considere as seguintes sentenças retiradas do texto: I. \"Ensiná-lo a administrar situações problemáticas\" II. \"Oferecer recursos para que ele se acalme\" Em relação à colocação pronominal, nas sentenças dadas observa-se, respectivamente:","opcoes":["próclise e ênclise.","ênclise e mesóclise.","ênclise e próclise.","próclise e mesóclise.","mesóclise e próclise."],"correta":2,"explicacao":"Gabarito: <strong>ênclise e próclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3708,"enunciado":"Assinale a alternativa em que a colocação pronominal e a flexão verbal estão de acordo com a norma-padrão.","opcoes":["Quem vir conhecer o lugar verá que criou-se uma avenida onde antes tinha-se um templo.","Se tudo se manter como o planejado, a avenida que se abrirá ficará no lugar do templo.","Quando se vir o lugar onde passa a avenida, certamente se sentirá a falta do templo ali.","Ninguém interviu e, no lugar em que se estabeleceu o templo, construirá-se uma avenida.","Se abrirá uma avenida se as pessoas não se disporem a combater a demolição do templo."],"correta":2,"explicacao":"Gabarito: <strong>Quando se vir o lugar onde passa a avenida, certamente se sentirá a falta do templo ali.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3709,"enunciado":"Assinale a alternativa em que o termo entre parênteses substitui corretamente a expressão.","opcoes":["suspender a guarda (suspende-a)","cria o menino (cria-o)","transmitir às sucedentes (transmitir-las)","ignoram o nível social (ignoram-o)","ser um revolucionário (ser-lo)"],"correta":1,"explicacao":"Gabarito: <strong>cria o menino (cria-o)</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3711,"enunciado":"Observe o seguinte pensamento, estruturado em dois segmentos: “A sentença mais correta e ponderada que se pronunciou sobre a questão do celibato e do casamento é esta: Qualquer decisão que tomes, ficarás arrependido”. Acerca da estruturação dessa frase, assinale a afirmativa incorreta.","opcoes":["Os adjetivos “correta” e “ponderada” podem trocar de posição sem modificação no sentido da frase.","A forma passiva “se pronunciou” pode ser adequadamente substituída por “foi pronunciada”.","A forma do demonstrativo “esta” se justifica por ser uma catáfora, ou seja, referir-se a um termo enunciado posteriormente.","O texto se utiliza de uma citação para a expressão de uma opinião.","A forma verbal “se pronunciou” poderia ser adequadamente modificada para “pronunciou-se”."],"correta":4,"explicacao":"Gabarito: <strong>A forma verbal “se pronunciou” poderia ser adequadamente modificada para “pronunciou-se”.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3712,"enunciado":"No texto, a forma pronominal “Ela ...” (linha 7) faz referência","opcoes":["a sua mente.","a sua vida mental.","a inteligência artificial.","a experiência consciente."],"correta":3,"explicacao":"Gabarito: <strong>a experiência consciente.</strong>.","banca":"IDIB","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3715,"enunciado":"Deixe suas preocupações e planos para outro momento Antes de deitar-se escreva uma lista de coisas que você deverá fazer ou seus planos para o dia seguinte. Tal tarefa irá tirar de seus ombros a responsabilidade de lembrar e isso relaxará seu inconsciente. Se seguir discutindo com eles e mentalizando-os, não irá resolvê-los nem conseguirá relaxar. REVISTA Ortobom. Manual do Sono. Outubro 2022, p. 19. Assinale a alternativa correta quanto à colocação pronominal em destaque no texto.","opcoes":["Na primeira ocorrência, o pronome oblíquo “se” está mesoclítico.","Nas três ocorrências, os pronomes pessoais oblíquos deveriam estar proclíticos.","O pronome oblíquo em “não irá resolvê-los” foi indevidamente empregado, já que existe a locução verbal.","Em “não irá resolvê-los”, devido à terminação do verbo a que o pronome está ligado, não houve necessidade de alteração pronominal.","O pronome oblíquo “-los” foi colocado em ênclise e sofreu alterações em sua forma. Isso acontece quando a forma verbal termina em -r, perde essa consoante e o pronome “o” assume a forma “-lo”."],"correta":4,"explicacao":"Gabarito: <strong>O pronome oblíquo “-los” foi colocado em ênclise e sofreu alterações em sua forma. Isso acontece quando a forma verbal termina em -r, perde essa consoante e o pronome “o” assume a forma “-lo”.</strong>.","banca":"COPEVE-UFAL","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3716,"enunciado":"Assinale a alternativa que apresenta a correta colocação pronominal, segundo a norma culta da língua portuguesa:","opcoes":["Por que substituir-lhe agora? Essa forma de trabalho sem IA sempre deu certo!","Me informei a respeito do que a IA pode fazer e fiquei assustado.","Organizou as informações, lhe explicando a respeito das descobertas tecnológicas.","Assim fazem-se as mudanças na tecnologia - e na vida dos homens.","Nada convence-me de que a IA pode ser mais criativa que o ser humano."],"correta":0,"explicacao":"Gabarito: <strong>Por que substituir-lhe agora? Essa forma de trabalho sem IA sempre deu certo!</strong>.","banca":"FURB","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3719,"enunciado":"Considere os excertos: I. “estava determinado a fazê-lo” II.“seria a política que lhe causaria mais problemas.” Em relação à colocação pronominal, observa-se nas sentenças dadas, respectivamente:","opcoes":["ênclise, próclise.","próclise, ênclise.","próclise, mesóclise.","ênclise, mesóclise.","mesóclise, próclise."],"correta":0,"explicacao":"Gabarito: <strong>ênclise, próclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3720,"enunciado":"Assinale a alternativa que apresenta o uso correto da colocação pronominal observando a normapadrão da língua portuguesa.","opcoes":["\"Vou ver-des mais tarde.\"","\"Vou-te ver mais tarde.\"","\"Te vou ver mais tarde.\"","\"Vou ver-tes mais tarde.\"","\"Vou te ver mais tarde.”"],"correta":4,"explicacao":"Gabarito: <strong>\"Vou te ver mais tarde.”</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3721,"enunciado":"Considere os seguintes excertos: I. Onde me espetam, fico. II. Deixe-me, senhora. Em relação à colocação pronominal, as sentenças dadas apresentam, respectivamente:","opcoes":["próclise e mesóclise.","mesóclise e próclise.","próclise e ênclise.","ênclise e próclise.","ênclise e mesóclise."],"correta":2,"explicacao":"Gabarito: <strong>próclise e ênclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3722,"enunciado":"Considere as sentenças: I. Ele se calou diante do tribunal. II. Fizeram-lhe passar vergonha. Em relação à colocação pronominal, observa-se, respectivamente:","opcoes":["I. ênclise, II. próclise.","I. próclise; II. ênclise.","I. próclise; II. mesóclise.","I. ênclise; II. mesóclise.","I. mesóclise; II.próclise."],"correta":1,"explicacao":"Gabarito: <strong>I. próclise; II. ênclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3724,"enunciado":"Assinale a opção que apresenta segundo a norma padrão para a escrita em Língua Portuguesa, a colocação do pronome oblíquo átono que deve ocorrer em ênclise.","opcoes":["Ainda que se esforce bastante, você ainda vai ter dificuldades na prova.","“Na natureza nada se perde; tudo se transforma.” (Lavoisier)","Na sexta-feira, te ligo para marcarmos a ida ao salão de festas.","Não se dedique exageradamente a atividades que lhe causam fadiga mental.","Deus me livre desse calor insuportável!"],"correta":2,"explicacao":"Gabarito: <strong>Na sexta-feira, te ligo para marcarmos a ida ao salão de festas.</strong>.","banca":"CETREDE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3725,"enunciado":"Julgue o item que se segue. A sentença “ninguém avisou-me” foge às regras gramaticais de colocação pronominal, devendo ser corrigida com o uso da próclise: “Ninguém me avisou”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3727,"enunciado":"“Na sola se desenhava a curva graciosa da planta sutil”. No excerto, observa-se a presença de determinada colocação pronominal. Assinale a alternativa que contém o mesmo tipo de classificação e ocorrência.","opcoes":["“Se fosse um calçado em folha, saído da loja, não teria tanto valor”.","“Agora, porém, que de novo o tinha diante dos olhos”.","“Fragrância voluptuosa que se exala ao mesmo tempo do corpo e da alma”.","“Uma das mãos torna-se pé”.","“O delicado tubo de seda, que se elevava como a corola de um lírio”."],"correta":1,"explicacao":"Gabarito: <strong>“Agora, porém, que de novo o tinha diante dos olhos”.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3729,"enunciado":"O pronome em destaque está colocado de acordo com a norma-padrão da língua portuguesa em:","opcoes":["As transações bancárias, atualmente, podem ser feitas pelo celular, a qualquer hora, para que obtenha-se o ideal de maior eficiência e rapidez.","O cadastramento do Pix pode ser realizado em mais de uma instituição bancária, o que considera-se benéfico para as pessoas que precisam diversificar suas operações financeiras.","Os cidadãos que se recusam a utilizar os serviços bancários para efetuar movimentações financeiras, por preferirem o uso de cédulas, encontram muita dificuldade para realizá-las.","Desde que implantou-se o Pix, as pessoas podem realizar até a compra de produtos extremamente baratos por transferência bancária instantânea, porque esse sistema atingiu um significativo grau de confiabilidade.","Embora tenham sido ampliadas as medidas de segurança tecnológica para a movimentação bancária, não sentimo-nos confiantes para operar com grandes somas de dinheiro."],"correta":2,"explicacao":"Gabarito: <strong>Os cidadãos que se recusam a utilizar os serviços bancários para efetuar movimentações financeiras, por preferirem o uso de cédulas, encontram muita dificuldade para realizá-las.</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3730,"enunciado":"Assinale a frase que está de acordo com a norma padrão.","opcoes":["Se você fizer o curso sobre conexões de gás, com certeza não te faltará empregos.","Segundo informaram-me, o governador não quer que se prive os funcionários dessas vantagens.","Exatamente à meia-noite, iniciaram-se as apurações dos votos das seções eleitorais do município de Cunha Porã, cuja prefeitura terá novo comando a partir do dia primeiro de janeiro vindouro.","De acordo com estudos realizados pelo Instituto Mapa, os indicadores políticos-sociais e econômicos-financeiros tendem a piorar nos municípios de pequeno porte.","Refiro-me aquela mulher que fez o discurso ontem à noite, não à esta que agora entrou no auditório."],"correta":2,"explicacao":"Gabarito: <strong>Exatamente à meia-noite, iniciaram-se as apurações dos votos das seções eleitorais do município de Cunha Porã, cuja prefeitura terá novo comando a partir do dia primeiro de janeiro vindouro.</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3731,"enunciado":"O pronome oblíquo átono em destaque está empregado de acordo com a norma-padrão em:","opcoes":["Convidaremo-lo para experimentar algumas novidades tecnológicas em oferta no interior da loja.","Aquele funcionário, que foi aprovado no exame seletivo de uma instituição, para o cargo de tecnólogo, estava em dúvida em aceitá-lo.","Os profissionais da informática, ao serem entrevistados sobre sua carreira, nunca cansavam-se de citar as fontes em que poderiam encontrar novos conteúdos de interesse para a sua área.","Quando os produtos tecnológicos mantêm-se nas prateleiras das lojas por muito tempo, é sinal de que despertaram pouca atenção das pessoas ou que o preço cobrado estava além das possibilidades de compra dos interessados.","Se os pesquisadores especializados em conserto de computadores ou outros dispositivos eletrônicos conservarem-se atualizados, a ciência que se dedica ao tratamento da informação apresentará maior progresso."],"correta":1,"explicacao":"Gabarito: <strong>Aquele funcionário, que foi aprovado no exame seletivo de uma instituição, para o cargo de tecnólogo, estava em dúvida em aceitá-lo.</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3732,"enunciado":"Assinale a alternativa em que a próclise é a única colocação pronominal permitida pela norma padrão.","opcoes":["“Se a intenção for dar conta da experiência da vida apoiado na capacidade de atribuir-lhe sentido [...]”.","“O diálogo interno implica um outro que nos habita [...]”.","“Paradoxalmente, pode-se dizer o oposto também [...]”.","“A técnica de se isolar para não sofrer seria boa [...]”.","“O corpo a corpo com os atores em tempo real [...] enaltece nossa fragilidade ao invés de escamoteá-la.”."],"correta":1,"explicacao":"Gabarito: <strong>“O diálogo interno implica um outro que nos habita [...]”.</strong>.","banca":"INSTITUTO AOCP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3733,"enunciado":"Considere as sentenças: I. Mas me diga a verdade, só a verdade: você nunca beijou uma mulher antes de me beijar? II. Ele, um dos garotos no meio da garotada em algazarra, deixava a brisa fresca bater-lhe no rosto e entrar-lhe pelos cabelos com dedos longos, finos e sem peso como os de uma mãe. Em relação à colocação pronominal, observa-se em cada uma das sentenças, respectivamente:","opcoes":["próclise e ênclise.","ênclise e próclise.","próclise e mesóclise.","ênclise e mesóclise.","mesóclise e ênclise."],"correta":0,"explicacao":"Gabarito: <strong>próclise e ênclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3734,"enunciado":"Um exemplo do emprego da colocação pronominal de acordo com a norma-padrão da língua portuguesa é “conscientizando-os” (l. 23). Considerando as regras de colocação pronominal, analise as orações abaixo: I. Me refiro ao estudo sobre diversidade cultural apresentado pela UNESCO. II. Quero dar-lhes uma boa notícia. III. Por muitos anos não respeitou-se os povos indígenas e sua cultura. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","Apenas II e III."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3735,"enunciado":"Na oração “Ediacaranos foram os primeiros animais de que se tem conhecimento”, com relação à colocação do pronome obliquo átono, analise as assertivas abaixo: I. Trata-se de uso de próclise. II. O pronome “que” justifica a colocação do pronome oblíquo átono. III. Alterando-se a ordem da oração, ficaria: “Se tem conhecimento de que os Ediacaranos foram os primeiros animais”. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","Apenas II e III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas I e II.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3737,"enunciado":"Assinale a frase em que houve troca indevida entre o/lhe.","opcoes":["Se há um Deus, a expressão que deve irritá-lo é “guerra santa”.","Nós todos o observamos à distância.","Minha mãe disse que lhe viu no shopping.","Todos lhe deram parabéns.","Não sei quem lhe entregou o prêmio."],"correta":2,"explicacao":"Gabarito: <strong>Minha mãe disse que lhe viu no shopping.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3738,"enunciado":"Assinalar a frase com ERRO de colocação pronominal:","opcoes":["Ninguém te faltou ao respeito durante o discurso.","Sente-se nesta fileira para facilitar a organização.","Lhe informou sobre o novo contrato.","Agora se negam a discutir a situação."],"correta":2,"explicacao":"Gabarito: <strong>Lhe informou sobre o novo contrato.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3739,"enunciado":"A respeito de sintaxe de colocação, analise as assertivas abaixo, assinalando V, se verdadeiras, ou F, se falsas, conforme descreve Cegalla. ( ) A próclise será de rigor quando antes do verbo houver, na oração, as seguintes palavras, expressões e orações que possam atrair o pronome átono: as expressões locativas, as orações imperativas e os vocativos. ( ) A mesóclise ocorrerá quando a forma verbal estiver flexionada no futuro do pretérito, independentemente de ocorrer qualquer palavra que preceda o verbo e que possa atrair o pronome. ( ) Os pronomes estarão em ênclise nos períodos iniciados pelo verbo (que não seja o futuro), pois, na língua culta, não se abre frase com o pronome oblíquo; nas orações reduzidas de gerúndio, quando nelas não houver palavras atrativas; e nas orações imperativas afirmativas. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V – V – V.","V – F – V.","V – V – F.","F – V – F.","F – F – V."],"correta":4,"explicacao":"Gabarito: <strong>F – F – V.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3740,"enunciado":"Assinale a alternativa em que a frase da tira foi alterada em conformidade com a norma-padrão de colocação pronominal.","opcoes":["O seu equilíbrio vai melhorar se você soltar-se.","Me deixa tenso a iminência da morte, eu admito!","Eu admito que deixa-me tenso a iminência da morte!","Se concentre no seu objetivo.","Pois eu não o vou mudar."],"correta":4,"explicacao":"Gabarito: <strong>Pois eu não o vou mudar.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3741,"enunciado":"O texto abaixo é trecho de uma música, e na cultura artística é permitida a licença poética, onde o autor se desprende de regras normativas da linguagem para elaborar sua produção: I- Me dói falar em bebê Bebê era como eu chamava você... II- Não me atenda Se acaso de madrugada... Chegar algum volta para mim III - Hackearam-me, hackearam-me [...] Composição: Tierry. Considerando as regras gramaticais, quanto ao uso dos pronomes oblíquos, encontramos o uso adequado em:","opcoes":["I e II","I e III","I","II e III","Somente III"],"correta":3,"explicacao":"Gabarito: <strong>II e III</strong>.","banca":"JVL Concursos","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3743,"enunciado":"Diante de um quadro de inflamação excessiva no intestino, ______ causa danos, para _____ , faz- -se necessário diminuir a imunidade ou _____ . Assinale a alternativa que, correta e respectivamente, completa as lacunas conforme o que se afirma no 4º parágrafo do texto.","opcoes":["o que lhe … reduzir-lhe … suprimir-lhe","a qual o … reduzir-la … suprimir-la","a qual lhe … reduzi-la … suprimi-la","o qual lhe … reduzir-la … suprimir-lhe","que o … reduzir-lhe … suprimi-la"],"correta":2,"explicacao":"Gabarito: <strong>a qual lhe … reduzi-la … suprimi-la</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3745,"enunciado":"Analisando os pronomes destacados no texto, assinale a alternativa que indica, respectivamente, o tipo de colocação pronominal, bem como e justificativa da aplicabilidade.","opcoes":["Mesóclise (o verbo trazer por estar no infinitivo exige que o pronome seja colocado ao fim, consoante a norma culta) e próclise (sempre que clítico estiver antes de um verbo no passado, virá antes dele, consoante a norma culta).","Ênclise (verbos em início frase deverão ter o clítico em posição enclítica, consoante a norma culta) e próclise (nas situações em que tiver a presença de pronome relativo, o pronome ficará em posição proclítica, consoante a norma culta).","Próclise (sempre que clítico estiver depois de um verbo no passado, virá antes dele, consoante a norma privada) e Próclise ( por ser uma frase optativa, consoante a norma diatópica).","Ênclise (o verbo sofreu um processo de derivação impróprio pelo emprego do termo ‘te, consoante a variação linguística do momento histórico) e Mesóclise (o pronome ‘‘nos’’ por representar a 2° pessoa do discurso sempre virá em posição medial, consoante a norma culta)."],"correta":1,"explicacao":"Gabarito: <strong>Ênclise (verbos em início frase deverão ter o clítico em posição enclítica, consoante a norma culta) e próclise (nas situações em que tiver a presença de pronome relativo, o pronome ficará em posição proclítica, consoante a norma culta).</strong>.","banca":"Creative Group","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3747,"enunciado":"Assinale a alternativa em que o enunciado atende à norma-padrão de colocação pronominal.","opcoes":["Se engana quem pensa que a internet é terra sem lei, pois as plataformas têm responsabilidade na propagação de crimes.","A sociedade não surpreende-se com o fato de as atenções se voltarem para as plataformas digitais e para a sua responsabilidade.","Parte importante da responsabilidade sobre as mensagens evidentemente se estende às plataformas, que podem e devem agir mais.","Por mais que promovam-se aperfeiçoamentos legislativos sempre bem-vindos, o País dispõe de um marco legal sobre o tema.","A covardia e a barbárie dos recentes ataques a escolas no País jogaram luz sobre a violência que tem propagado-se na internet."],"correta":2,"explicacao":"Gabarito: <strong>Parte importante da responsabilidade sobre as mensagens evidentemente se estende às plataformas, que podem e devem agir mais.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3748,"enunciado":"Assinale a alternativa que apresenta a correta colocação pronominal, segundo a norma culta do português brasileiro:","opcoes":["Não conhecia a natureza das fontes de energia elétrica. Disso informaram-me assim que comprei um carro elétrico.","Soube que apresentar-nos-iam os dados a respeito dos combustíveis poluentes.","Que a economia ajude-nos a comprar carros menos poluentes para proteger o ambiente!","Agora me informei a respeito e não mais terei dúvidas sobre as fontes de energia elétrica.","Nunca perguntei-me a respeito do valor de um carro elétrico."],"correta":3,"explicacao":"Gabarito: <strong>Agora me informei a respeito e não mais terei dúvidas sobre as fontes de energia elétrica.</strong>.","banca":"FURB","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3749,"enunciado":"Marque a alternativa correta, em relação à colocação pronominal.","opcoes":["Não era minha intenção te ferir.","Identificaram dois assaltantes que encontravam-se foragidos.","Se eu conseguir uma promoção, me mudo para uma casa maior.","Se não fossem meus compromissos, ia te acompanhar nesse passeio.","Fi-lo porque não tinha outra opção."],"correta":4,"explicacao":"Gabarito: <strong>Fi-lo porque não tinha outra opção.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3750,"enunciado":"De acordo com as regras gramaticais e norma culta da Língua Portuguesa, qual é a forma correta de colocação pronominal na frase: \"Ela me disse que vai me ajudar com o trabalho.\"?","opcoes":["\"Disse-me ela que vai ajudar-me com o trabalho.\".","\"Disse ela que vai me ajudar com o trabalho.\".","\"Ela disse que vai ajudar-me com o trabalho.\".","\"Ela disse que vai me ajudar com o trabalho.\".","\"Disse que vai me ajudar com o trabalho ela.\"."],"correta":3,"explicacao":"Gabarito: <strong>\"Ela disse que vai me ajudar com o trabalho.\".</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3751,"enunciado":"Considere as seguintes sentenças: I) Eu me lembro daquela canção. II) Falta-me descanso. III) Esforçar-me-ei para que tudo dê certo. Nas sentenças dadas, o uso do pronome \"me\" se trata, respectivamente, de:","opcoes":["próclise, próclise, mesóclise.","ênclise, próclise, próclise.","ênclise, ênclise, mesóclise.","próclise, próclise, ênclise.","próclise, ênclise, mesóclise."],"correta":4,"explicacao":"Gabarito: <strong>próclise, ênclise, mesóclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3752,"enunciado":"De acordo com as regras gramaticais da Língua Portuguesa, assinale a alternativa que apresenta a forma correta de colocação pronominal na frase \"Eu lhe dei o livro ontem\".","opcoes":["\"Lha dei eu o livro ontem\"","\"Dei eu lhes o livro ontem\"","\"Dei-lho livro ontem a ele\"","\"Dei-te ontem o livro pra ele\"","\"Eu dei o livro ontem a ele\""],"correta":4,"explicacao":"Gabarito: <strong>\"Eu dei o livro ontem a ele\"</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3753,"enunciado":"Acerca da colocação dos pronomes átonos, assinale a alternativa correta.","opcoes":["Rapidamente atendem-nos se formos simpáticos.","Te chamei há horas.","Quanto mais o critica, menos ele trabalha.","Ninguém vai te ouvir.","Se chegou à casa e não trancou-se no quarto."],"correta":2,"explicacao":"Gabarito: <strong>Quanto mais o critica, menos ele trabalha.</strong>.","banca":"Quadrix","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3754,"enunciado":"Considere as frases elaboradas a partir do texto. • Quanto às personagens provenientes do exterior, é a voz de Dona Benta que ____________ nas narrativas. • Por respeitar a inteligência das crianças, Lobato ________________ livros cuja abordagem da fantasia era muito inovadora. Com base na norma-padrão de emprego dos pronomes, as lacunas devem ser preenchidas, respectivamente, por:","opcoes":["lhes insere; dedicou-lhes","lhes insere; dedicou-se","se insere; dedicou-as","as insere; dedicou-as","as insere; dedicou-lhes"],"correta":4,"explicacao":"Gabarito: <strong>as insere; dedicou-lhes</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3755,"enunciado":"Considere a reescrita do trecho do quarto parágrafo. Um jovem programador, em relato ao San Francisco Chronicle, revelou que a namorada, ele havia perdido a namorada recentemente e, machucado de um jeito que só quem enfrentou a morte, quem conheceu a morte de perto sabe, alimentou uma dessas linguagens com recordações que traziam para ele saudades. De acordo com a norma-padrão de colocação dos pronomes, as expressões destacadas podem ser substituídas por:","opcoes":["a havia perdido ... a conheceu ... lhe traziam","a havia perdido ... conheceu-a ... traziam-lhe","havia-a perdido ... conheceu-a ... lhe traziam","havia perdido-a ... a conheceu ... traziam-lhe","havia perdido-a ... conheceu-a ... lhe traziam"],"correta":0,"explicacao":"Gabarito: <strong>a havia perdido ... a conheceu ... lhe traziam</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3756,"enunciado":"Assinale a alternativa que apresenta correção no que diz respeito à colocação pronominal, segundo a norma culta da língua portuguesa:","opcoes":["Não aplicar-me-ei em pesquisas que não difundam inovações tecnológicas.","A temática do grafeno é nova para mim. Não a estudei até encontrar este texto.","Conforme explicaram-lhe, houve uma série de reuniões para tratar do novo projeto de emprego do grafeno.","Isso lembra-me de pesquisas que abordam a temática da aplicação do grafeno em eletrônicos.","No início da reunião, lhe expliquem os avanços que o grafeno permitirá."],"correta":1,"explicacao":"Gabarito: <strong>A temática do grafeno é nova para mim. Não a estudei até encontrar este texto.</strong>.","banca":"FURB","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3757,"enunciado":"Leia as frases a seguir. 1 – Eu não o vejo desde ontem à noite. 2 – Assim que possível, contar-lhe-ei os detalhes do casamento. 3 – Acordei e surpreendi-me com tantas notícias ruins. 4 – Ontem me avisaram que não haveria aula. Nas frases acima, os pronomes átonos estão empregados, respectivamente, como","opcoes":["próclise, mesóclise, ênclise e próclise.","próclise, ênclise, mesóclise e ênclise","ênclise, mesóclise, próclise e próclise.","mesóclise, próclise, próclise e ênclise."],"correta":0,"explicacao":"Gabarito: <strong>próclise, mesóclise, ênclise e próclise.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3758,"enunciado":"Há emprego do pronome átono como próclise em:","opcoes":["“Faça-me o favor de não chegar atrasado para a reunião”.","“Ontem o vi no teatro”.","“Convém dar-lhes o aviso agora mesmo”.","“Conformar-nos-emos com a situação”."],"correta":1,"explicacao":"Gabarito: <strong>“Ontem o vi no teatro”.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3760,"enunciado":"Estariam mantidas a correção gramatical do texto bem como a coerência de suas ideias caso","opcoes":["o vocábulo “se”, em “se tornariam” (linhas 3 e 4) fosse colocado em posição enclítica – tornariam-se.","o vocábulo “a”, em “que a dos países europeus” (linha 1) fosse suprimido do período.","o segmento “era dependente” (linha 7) fosse substituído pela forma verbal dependera.","o vocábulo “advindos” (linha 7) fosse substituído por provindos.","a forma verbal “têm demonstrado” (linhas 27 e 28) fosse reescrita como veem demonstrando."],"correta":3,"explicacao":"Gabarito: <strong>o vocábulo “advindos” (linha 7) fosse substituído por provindos.</strong>.","banca":"Ibest","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3761,"enunciado":"No que tange à colocação pronominal, marcar C para as afirmativas Certas, E para as Erradas e, após, assinalar a alternativa que apresenta a sequência CORRETA: (_) Após o intervalo, me juntarei a eles. (_) O meu maior medo é arrepender-me do que deixei de fazer. (_) Fiz-lhe um favor e nada mais.","opcoes":["C - C - E.","E - E - C.","C - E - E.","E - C - C.","C - C - C."],"correta":3,"explicacao":"Gabarito: <strong>E - C - C.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3762,"enunciado":"Assinale a alternativa em que o enunciado, reescrito a partir das informações do texto, atende à norma-padrão de colocação pronominal.","opcoes":["Escolheu-se Branca de Neve para ser o primeiro longa-metragem de animação da Disney, sabendo-se que não poderia haver erro.","Crê-se que o aniversário de Branca de Neve seria no começo do século XVII, ou nas versões orais, que teriam perdido-se na névoa do tempo.","Me pergunto a que contos de fadas refere-se a crítica mais frequente, que fala da abundância de princesas suspirosas à espera do príncipe.","Quem atreveria-se a desdizer que os contos de fadas que disseminaram-se no cotidiano social visam manter as diretrizes sociais em voga no momento?","Os contos maravilhosos se impuseram por séculos, e isso certamente deu-se justamente pela densidade do seu conteúdo e pela sua riqueza simbólica."],"correta":0,"explicacao":"Gabarito: <strong>Escolheu-se Branca de Neve para ser o primeiro longa-metragem de animação da Disney, sabendo-se que não poderia haver erro.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3763,"enunciado":"Assinale a alternativa em que a colocação pronominal está de acordo com a norma-padrão.","opcoes":["Se passam muitas coisas em câmera lenta para nós. Os Anjos, por sua vez, veem-nas em ritmo acelerado.","Nos jornais cinematográficos, parece que as pessoas agitam-se como se alguém tivesse dado-lhes corda.","Tudo que sabe-se da epopeia napoleônica certamente revestiria-se de um cômico e de um absurdo irresistíveis.","Não vislumbram-se grandeza e dignidade possível, quando vê-se o agito automático de coisas como bonecos.","Divertem-se os Anjos com o transcorrer da vida humana, porque evidentemente o veem como cômico e absurdo."],"correta":4,"explicacao":"Gabarito: <strong>Divertem-se os Anjos com o transcorrer da vida humana, porque evidentemente o veem como cômico e absurdo.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3764,"enunciado":"De acordo com as regras gramaticais, qual é a forma correta de colocação pronominal na frase abaixo? \"Eu _____ vi ontem no shopping.\".","opcoes":["Te vi","Vi te","Vi-o","O vi","Vi-lhe"],"correta":3,"explicacao":"Gabarito: <strong>O vi</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3765,"enunciado":"De acordo com as regras gramaticais, qual alternativa apresenta a colocação pronominal adequada para a frase abaixo? \"O gerente me entregou o relatório ontem.\".","opcoes":["Me entregou o relatório, ontem.","Me entregou ontem o relatório.","Entregou o relatório para mim ontem.","Entregou-me o relatório ontem.","Entregou o relatório ontem para mim."],"correta":3,"explicacao":"Gabarito: <strong>Entregou-me o relatório ontem.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3766,"enunciado":"No quarto parágrafo lê-se: “Sentem-se mais interessantes, desejáveis.” Considerando a colocação pronominal nessa frase, assinale a alternativa que apresenta uma variação em desacordo com a norma culta.","opcoes":["Sempre se sentem mais interessantes, desejáveis.","Sentir-se-ão mais interessantes, desejáveis.","Dizem que se sentem mais interessantes, desejáveis.","Se sentem mais interessantes, desejáveis.","Já se sentem mais interessantes, desejáveis."],"correta":3,"explicacao":"Gabarito: <strong>Se sentem mais interessantes, desejáveis.</strong>.","banca":"CETREDE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3767,"enunciado":"A frase em que a colocação do pronome destacado NÃO obedece aos ditames da norma-padrão é:","opcoes":["Feliz é quem se dá o direito de estar bem.","As pessoas nunca acostumam-se com a felicidade.","Agradar-nos-ia a ideia de que todos têm direito à paz.","Viver a vida intensamente é o que lhe confere sentido.","Afastando-nos de quem nos quer bem, saudamos a solidão."],"correta":1,"explicacao":"Gabarito: <strong>As pessoas nunca acostumam-se com a felicidade.</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3770,"enunciado":"“Aceitemo-los” — assim como vós aceitais essa mesóclise. A mesóclise se caracteriza pela colocação do pronome oblíquo no meio de um verbo. A partir disso e de acordo com a norma-padrão da Língua Portuguesa, quanto à colocação pronominal, assinale a alternativa que apresenta uma afirmação correta sobre a frase acima.","opcoes":["O uso do pronome e a caracterização do processo como mesóclise estão corretos, já que o pronome oblíquo “o” vem no meio da conjugação do verbo, que termina com “los”.","O uso do pronome está correto, mas a caracterização como mesóclise não. Trata-se de ênclise, já que o pronome oblíquo “os” está após a conjugação completa do verbo.","O uso do pronome e a caracterização como mesóclise estão erradas, porque seria necessário corrigir a conjugação do verbo para ter “aceitemos-los” e se trata de uma ênclise uma vez que o pronome “los” vem ao final.","O uso do pronome está incorreto apesar de sua classificação como mesóclise estar correta. O pronome oblíquo “o” vem no meio da conjugação do verbo, que termina em “los”, mas o correto seria escrever “aceitemos-los”."],"correta":1,"explicacao":"Gabarito: <strong>O uso do pronome está correto, mas a caracterização como mesóclise não. Trata-se de ênclise, já que o pronome oblíquo “os” está após a conjugação completa do verbo.</strong>.","banca":"INSTITUTO MAIS","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3771,"enunciado":"“É preciso despir-se do que já não nos serve mais [...].” (Decimo parágrafo) Considerando a colocação pronominal na oração sublinhada, é CORRETO afirmar que ocorreu","opcoes":["ênclise facultativa na frase.","ênclise determinada pelo tempo verbal.","próclise na sequência verbo-complemento.","próclise provocada pelo advérbio.","mesóclise com pronome intercalado ao verbo."],"correta":3,"explicacao":"Gabarito: <strong>próclise provocada pelo advérbio.</strong>.","banca":"CETREDE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3772,"enunciado":"Em 1924, em Palmeira dos Índios, interior de Alagoas, encontrei dificuldade séria, pus-me a ver inimigos em toda parte e desejei suicidar-me. Realmente julgo que me suicidei. Talvez isso não seja tão idiota como parece. Abandonando o contas-correntes, o diário, outros objetos da minha profissão, havia-me embrenhado na sociologia criminal. Fatos me induziram a isso. Teria querido matar alguns fantasmas os quais me perseguiam? RAMOS, Graciliano. Garranchos. Rio de Janeiro: Record, 2012, p. 272 Considerando as orações sublinhadas no texto, em qual delas o pronome me poderia ser escrito em outra posição sem causar danos às regras de colocação pronominal?","opcoes":["“havia-me embrenhado na sociologia criminal”","“pus-me a ver inimigos em toda parte”","“Realmente julgo que me suicidei”","\"os quais me perseguiam?”","“Fatos me induziram a isso”"],"correta":4,"explicacao":"Gabarito: <strong>“Fatos me induziram a isso”</strong>.","banca":"FUNDEPES","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3777,"enunciado":"Com base na leitura do texto, marque V para verdadeiro e F para falso: ( ) No trecho “O mato”, é possível observar que o uso da próclise do pronome oblíquo gera uma ambiguidade. ( ) No trecho “Vê se esquece-me”, a próclise é necessária já que a conjunção “se” tem a função de atrair o pronome “me”. ( ) Em “matar-lhe-ei-te”, o interlocutor faz o uso correto da mesóclise. ( ) O uso proclítico do pronome oblíquo no trecho “não sabes-o” configura um equívoco, pois o advérbio “não” exige a próclise do pronome “o”. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["F – V – V – V","V – V – F- V","V – V – F – F","F – V – V - F"],"correta":2,"explicacao":"Gabarito: <strong>V – V – F – F</strong>.","banca":"UniRV - GO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3778,"enunciado":"A crônica de Veríssimo aborda, de forma humorística, o uso da colocação pronominal. A esse respeito, é correto afirmar que:","opcoes":["Enquanto um dos interlocutores faz questão de demarcar o uso gramatical da colocação pronominal, o outro sinaliza que, em situação informal, seria um comportamento pedante.","A intenção do autor é ironizar a importância de se usar, em situações formais, as regras de colocação pronominal.","Os interlocutores discutem a correta forma de utilizar os pronomes do caso reto em situações de fala informal.","A gramática normativa determina que é incorreta a colocação proclítica em início de oração, em situação informalidade, como no caso do diálogo presente na crônica, a regra é, portanto, inadequada."],"correta":0,"explicacao":"Gabarito: <strong>Enquanto um dos interlocutores faz questão de demarcar o uso gramatical da colocação pronominal, o outro sinaliza que, em situação informal, seria um comportamento pedante.</strong>.","banca":"UniRV - GO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3779,"enunciado":"A afirmação apresentada no quarto parágrafo: “Quando se analisam com atenção as inovações do passado [...].” A alternativa que justifica a colocação pronominal nessa frase é","opcoes":["próclise, provocada pela conjunção subordinativa.","próclise, provocada pelo pronome relativo.","ênclise, na sequência verbo-complemento.","ênclise, com sujeito expresso.","mesóclise, determinada pelo tempo verbal."],"correta":0,"explicacao":"Gabarito: <strong>próclise, provocada pela conjunção subordinativa.</strong>.","banca":"CETREDE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3781,"enunciado":"O uso da próclise na oração “Se tornar descasado” (linha 18) é justificado por se tratar de uma frase iniciada com verbo, o que torna gramaticalmente correto o posicionamento do pronome oblíquo átono.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3784,"enunciado":"Em relação a aspectos linguísticos do texto CB1A7, julgue os itens a seguir. I Em “Não se preocupa nem um pouco com a chuva” (quinto período), o pronome “se” poderia ser corretamente empregado logo após a forma verbal preocupa, escrevendo-se Não preocupa-se. II Em “mas logo em velocidade a retiraram” (décimo período), a forma pronominal “a” refere-se a “coxa”, no período anterior. III A inserção de uma vírgula logo após “chuva” (quinto período) prejudicaria a correção gramatical do texto. Assinale a opção correta.","opcoes":["Nenhum item está certo.","Apenas o item I está certo.","Apenas o item II está certo.","Apenas o item III está certo."],"correta":0,"explicacao":"Gabarito: <strong>Nenhum item está certo.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3785,"enunciado":"Assinale a alternativa em que a pontuação, a colocação pronominal e a concordância verbal atendem à norma-padrão.","opcoes":["Quando se opta pela política para que se solucionem pacificamente os conflitos, a democracia viabiliza o crescimento econômico.","Diz o texto que para que se obtenha rendas no curto prazo, a instabilidade de uma democracia induz a comportamento míope.","Prevê-se, em um regime democrático, direitos civis, sociais, políticos e de propriedade. E os conflitos resolvem-se pacificamente.","Em democracias estáveis existe chances de reformas econômicas; as frágeis porém, se configuram como obstáculo a elas.","Se constatam com a democracia, o aumento das chances de reformas econômicas e de ampliação das matriculas na educação básica."],"correta":0,"explicacao":"Gabarito: <strong>Quando se opta pela política para que se solucionem pacificamente os conflitos, a democracia viabiliza o crescimento econômico.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3786,"enunciado":"Assinale a alternativa em que a colocação do pronome átono destacado está em conformidade com a norma- -padrão.","opcoes":["A China é o país mais populoso do planeta. Se tornou, na última década, o maior exportador.","O insucesso das esterilizações na Índia agora tem dado-lhe vantagens comparativas.","Anunciou-se, no dia 15, o primeiro declínio populacional da China desde os anos 60.","Na Índia, também implementariam-se controles draconianos, com esterilizações em massa.","A Índia é uma das economias que desenvolveram-se mais rápido nos últimos anos."],"correta":2,"explicacao":"Gabarito: <strong>Anunciou-se, no dia 15, o primeiro declínio populacional da China desde os anos 60.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3788,"enunciado":"Em língua portuguesa, o pronome oblíquo átono pode ocupar três posições distintas: antes, no meio, ou depois do verbo. Assinale a alternativa com a colocação pronominal incorreta:","opcoes":["Se afirmam absurdos em redes sociais.","Assim se resolvem todos os problemas.","Assim, resolvem-se todos os problemas.","Nunca o convidam para festas.","Tudo se dissolve com o tempo."],"correta":0,"explicacao":"Gabarito: <strong>Se afirmam absurdos em redes sociais.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3790,"enunciado":"Segundo Cegalla (2010, p. 538), “Conforme sua posição junto ao verbo, os pronomes oblíquos podem ser proclíticos (antepostos ao verbo), mesoclíticos (intercalados no verbo), enclíticos (pospostos ao verbo)”. Considere o conceito apresentado pelo gramático e o trecho transcrito do texto: “Como explicar-lhe que tapete se pronuncia ‘tapête’, mas topete é ‘topéte’”? Em seguida, analise as asserções e a relação proposta entre elas. I – A correção gramatical e a coerência textual estariam prejudicadas, caso a reescrita da expressão “explicar-lhe” fosse “lhe explicar” PORQUE, II – segundo a norma-padrão da língua portuguesa, a próclise é de rigor no referido período, pois a oração é iniciada por um termo interrogativo. A respeito das asserções é correto afirmar que","opcoes":["as duas são falsas.","a primeira é falsa e a segunda é verdadeira.","a primeira é verdadeira e a segunda é falsa.","as duas são verdadeiras e a segunda justifica a primeira.","as duas são verdadeiras, mas a segunda não justifica a primeira."],"correta":1,"explicacao":"Gabarito: <strong>a primeira é falsa e a segunda é verdadeira.</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3792,"enunciado":"O pronome oblíquo átono está colocado de acordo com a norma-padrão da língua portuguesa em:","opcoes":["Me surpreende a história de vida de Braille.","Seu método não trouxe-lhe reconhecimento em vida.","O menino cego aos cinco anos tornar-se-ia um herói nacional na França.","Quantos impressionaram-nos como Braille?","Braille recebia os alunos e sempre auxiliava-os com o método criado."],"correta":2,"explicacao":"Gabarito: <strong>O menino cego aos cinco anos tornar-se-ia um herói nacional na França.</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3793,"enunciado":"Assinale a alternativa cuja frase emprega o pronome em conformidade com a norma-padrão da Língua Portuguesa.","opcoes":["Quando dei-me conta da encrenca, resolvi desistir.","Ainda se indagava sobre o motivo daquela decisão.","Quem comparou-lhe, por falta de originalidade, ao Maradona?","Foram se esquivando de suas funções."],"correta":1,"explicacao":"Gabarito: <strong>Ainda se indagava sobre o motivo daquela decisão.</strong>.","banca":"INSTITUTO MAIS","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3794,"enunciado":"“... ao avistar os ramalhetes esmaecidos que forravam ‘paredes da casa onde nasci’”. De acordo com a norma-padrão da Língua Portuguesa e quanto à colocação pronominal, assinale a alternativa que apresenta a correta substituição dos elementos destacados por um pronome pessoal.","opcoes":["... ao avistar os ramalhetes esmaecidos que forravam-nas.","... ao avistar os ramalhetes esmaecidos que forravam-as.","... ao avistar os ramalhetes esmaecidos que forravam-lhes.","... ao avistar os ramalhetes esmaecidos que as forravam."],"correta":3,"explicacao":"Gabarito: <strong>... ao avistar os ramalhetes esmaecidos que as forravam.</strong>.","banca":"INSTITUTO MAIS","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3795,"enunciado":"Em relação ao uso da Língua Portuguesa em sua modalidade padrão, observa-se que:","opcoes":["Ocorrem três casos de próclise e um de ênclise.","Ocorre um caso de ênclise em desacordo com a norma padrão.","Usa-se acento circunflexo no monossílabo tônico “quê” em orações interrogativas diretas.","Usa-se o pronome “lhe” em vez de “te” na sentença: Eu ainda não lhe conhecia pessoalmente..."],"correta":2,"explicacao":"Gabarito: <strong>Usa-se acento circunflexo no monossílabo tônico “quê” em orações interrogativas diretas.</strong>.","banca":"UNIFAL-MG","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3796,"enunciado":"“No dia seguinte, trazidas num saco duas belas mudas de rosa, o homem escolheu o lugar, ajoelhou-se, cavou cuidadoso a primeira cova, mediu um palmo, cavou a segunda, e com gestos sábios de amor enterrou as raízes.” (5º§). Assinale a afirmativa na qual a partícula “se” NÃO exerce a mesma função que em “ajoelhou-se”.","opcoes":["“Voltava-se para ela, sorria, [...]” (10º§)","“[...] mimetizava-se com as estações.” (3º§)","“Quando afinal conseguiu se levantar [...]” (15º§)","“[...] como se o vento o agitasse por dentro.” (10º§)","“[...] mas se deixava ficar por entre as folhas, [...]” (3º§)"],"correta":3,"explicacao":"Gabarito: <strong>“[...] como se o vento o agitasse por dentro.” (10º§)</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3797,"enunciado":"Assinale a alternativa que contém a colocação pronominal correta.","opcoes":["Raios partam-te!","Isso não faz-se, menino!","Ninguém viu-o sair da festa.","Aqui, sabe-se tudo a respeito dele.","Sempre pergunto-te se está tudo sob controle!"],"correta":3,"explicacao":"Gabarito: <strong>Aqui, sabe-se tudo a respeito dele.</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3801,"enunciado":"Analise as orações com base nas regras de colocação pronominal. 1. Nenhuma coisa me faz rir! 2. Quem me enviou estas flores? 3. Se eu disser-te a verdade, você não acreditará! Assinale a alternativa que indica todas as orações gramaticalmente corretas.","opcoes":["É correta apenas a oração 1.","É correta apenas a oração 3.","São corretas apenas as orações 1 e 2.","São corretas apenas as orações 1 e 3.","São corretas apenas as orações 2 e 3."],"correta":2,"explicacao":"Gabarito: <strong>São corretas apenas as orações 1 e 2.</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3803,"enunciado":"Em relação a aspectos linguísticos do texto 2A2-I, julgue o item a seguir. No primeiro período do texto, a ênclise do pronome “se” à forma verbal “desvela”, escrevendo-se desvela-se, seria gramaticalmente correta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3804,"enunciado":"Tendo em vista as normas de colocação pronominal, julgue o item subsequente, relativos ao texto 2A1-I. No trecho “Não apenas se vivencia” (segundo período do primeiro parágrafo), a ênclise do pronome “se” à forma verbal — não apenas vivencia-se — comprometeria a correção gramatical do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3805,"enunciado":"Tendo em vista as normas de colocação pronominal, julgue o item subsequente, relativos ao texto 2A1-I. No trecho “em que se pode vislumbrar” (penúltimo período do segundo parágrafo), a ênclise do pronome “se” ao verbo auxiliar da locução verbal — em que pode-se vislumbrar —preservaria a correção gramatical do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3806,"enunciado":"Considere as frases. • Em Seul, os alimentos são pesados nas latas de lixo depois que os moradores ali ________. • Hoje, a fome e as mudanças climáticas são os maiores problemas da humanidade, tanto que ______ na busca por um equilíbrio global. • É inconcebível que haja pessoas passando fome, portanto medidas que _______ são sempre bem- -vindas. De acordo com a norma-padrão de emprego e de colocação dos pronomes, as lacunas das frases devem ser preenchidas, respectivamente, por:","opcoes":["os despejam; a vêm desafiando; combatam-na","os despejam; vêm desafiando-lhe; combatam-na","os despejam; a vêm desafiando; a combatam","despejam-nos; vêm desafiando-lhe; combatam-na","despejam-nos; vêm desafiando-a; a combatam"],"correta":2,"explicacao":"Gabarito: <strong>os despejam; a vêm desafiando; a combatam</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3807,"enunciado":"Assinale a alternativa em que a colocação pronominal atende à norma-padrão.","opcoes":["Claro que se sentem mal as mães de filhos com fome.","O favelado, quando vê-se com fome, recorre ao lixo.","Tendo suicidado-se a pobre mulher, o que fazer?","Eu agora questiono-me se ela foi ao Serviço Social.","Me vi nervosa com a notícia da mulher que morreu."],"correta":0,"explicacao":"Gabarito: <strong>Claro que se sentem mal as mães de filhos com fome.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3808,"enunciado":"Assinale a alternativa em que a frase redigida está em conformidade com a norma-padrão de colocação pronominal da língua portuguesa.","opcoes":["Caso tenha tentado-se, sem sucesso, conectar à rede, comunique o problema por e-mail.","Em eventual falha de tentativa de conexão, envie um e-mail, em que comunica-a.","Se estiver tentando conexão e não consegue-a, o fato deve ser comunicado por e-mail.","Em caso de conexão mal-sucedida, a reporte por e-mail.","A conexão à rede pode falhar e, nesse caso, comunique-se por e-mail."],"correta":4,"explicacao":"Gabarito: <strong>A conexão à rede pode falhar e, nesse caso, comunique-se por e-mail.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3809,"enunciado":"Assinale a alternativa em que a colocação do pronome está em conformidade com a norma-padrão da língua.","opcoes":["Ainda não se reconheceu que o fracasso na educação traz consequências negativas ao desenvolvimento.","Tendo tornado-se os primeiros a instituir a obrigatoriedade da educação, os alemães fizeram história.","Nada mostra-se tão prejudicial a uma nação quanto a falta de investimento em educação pública.","Atualmente já pode-se dizer que os objetivos para a educação básica foram alcançados no Brasil.","Jamais imaginou-se que estender o alcance do ensino médio a todos os jovens fosse uma tarefa tão árdua."],"correta":0,"explicacao":"Gabarito: <strong>Ainda não se reconheceu que o fracasso na educação traz consequências negativas ao desenvolvimento.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3810,"enunciado":"Quanto à colocação pronominal, no trecho “Mas, uma noite, levantaram-me da cama, enrolada num lençol, e, estremunhada, levaram-me à janela para me apresentarem à força ao temível cometa.” observam-se, respectivamente:","opcoes":["ênclise, ênclise e próclise.","mesóclise, mesóclise e próclise.","ênclise, próclise e próclise.","próclise, mesóclise e mesóclise.","ênclise, ênclise e ênclise."],"correta":0,"explicacao":"Gabarito: <strong>ênclise, ênclise e próclise.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3811,"enunciado":"Assinale a alternativa que está de acordo com a norma- -padrão de colocação pronominal.","opcoes":["Sabe-se que os idosos fazem um uso mais frequente do sistema de saúde, dada a condição física dessa etapa da vida.","Atualmente, ainda verificam-se casos de discriminação em função de cor da pele ou gênero nos serviços públicos.","Jamais pode-se julgar uma pessoa em razão de sua crença, de sua cor, de sua classe social ou de sua sexualidade.","Os pesquisadores têm dedicado-se a estudar estratégias de diminuição da discriminação social.","A discriminação de pessoas idosas é um problema que deve-se enfrentar principalmente no sistema de saúde."],"correta":0,"explicacao":"Gabarito: <strong>Sabe-se que os idosos fazem um uso mais frequente do sistema de saúde, dada a condição física dessa etapa da vida.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3812,"enunciado":"Assinale a alternativa em que o emprego e a colocação do pronome estão de acordo com a norma-padrão.","opcoes":["Existia a esperança de ver ele assumir o cargo de chefia, já que esforçaria-se muito para isso.","Tendo interessado-se pelo meu projeto, o superintendente mandou eu enviar uma cópia para o e-mail dele.","Com receio de vê-la frustrada, os pais da garota já lhe garantiram a viagem de estudo no exterior.","Mesmo os que jamais empenharam-se para obter a certificação agora se verão premiados com as promoções.","Futuramente perseguirá-nos a sombra de situações mal resolvidas que ainda existem entre eu e vocês."],"correta":2,"explicacao":"Gabarito: <strong>Com receio de vê-la frustrada, os pais da garota já lhe garantiram a viagem de estudo no exterior.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3813,"enunciado":"Assinale a alternativa redigida em concordância com a norma-padrão de colocação pronominal.","opcoes":["Me preocupa o distanciamento das novas gerações em relação à natureza.","O pescador não conformava-se com a perda de seu barco no naufrágio.","Tendo registrado-se 10 ºC naquele dia, os turistas não foram à praia.","Os trovões que se escutam ao fundo lembram o barulho de explosões","Ainda lembro-me do dia em que realizei o sonho de viajar de veleiro."],"correta":3,"explicacao":"Gabarito: <strong>Os trovões que se escutam ao fundo lembram o barulho de explosões</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3816,"enunciado":"Sobre a colocação pronominal, conforme a norma culta da língua portuguesa, assinale a que melhor está empregado o pronome.","opcoes":["Em tratando de vacinas, eu confio totalmente na eficácia.","Quem convenceu-te que as vacinas não podem ser usadas?","É imprescindível lhe confiar na eficácia das vacinas.","Me mostre os dados da eficácia das vacinas, fiquei curioso.","Ela não aceitou a vacina, embora lhe tivessem oferecido."],"correta":4,"explicacao":"Gabarito: <strong>Ela não aceitou a vacina, embora lhe tivessem oferecido.</strong>.","banca":"IF-TO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3817,"enunciado":"No trecho “Pessoas que me fazem pensar”, o pronome oblíquo foi empregado procliticamente. Considerando as regras de colocação pronominal, assinale a alternativa na qual a próclise tenha sido empregada INCORRETAMENTE.","opcoes":["Jamais me trate dessa maneira.","João ficou sem graça quando nos viu.","Gostaria de saber quem te contou a novidade.","Já que não entendi, me explique, por favor.","Não consigo saber se te ofenderam."],"correta":3,"explicacao":"Gabarito: <strong>Já que não entendi, me explique, por favor.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3820,"enunciado":"Considere as sentenças a seguir: 1. Ele nos oferece o resultado de toda uma vida dedicada à ciência. 1(a). Ele oferece-nos os resultados de toda uma vida dedicada à ciência. 2. Rodrigues nos lembra que o isolamento é um ato de amor. 2(a). Rodrigues lembra-nos que o isolamento é um ato de amor. Sobre elas, é CORRETO o que se afirma em:","opcoes":["A colocação pronominal enclítica é facultativa quando o pronome se liga a um verbo com sujeito explícito.","A ênclise é interditada em formas verbais cujo tempo seja o presente do indicativo.","A ênclise é obrigatória em orações cujo verbo esteja no infinitivo pessoal.","O pronome relativo que exige o uso da colocação pronominal enclítica em orações simples."],"correta":0,"explicacao":"Gabarito: <strong>A colocação pronominal enclítica é facultativa quando o pronome se liga a um verbo com sujeito explícito.</strong>.","banca":"FUMARC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3822,"enunciado":"A posição do pronome oblíquo destacado é facultativa em:","opcoes":["“Ele sorria e não se movia, como quem sabe que seria importante me deixar ali um pouco [...].”","“Ele sorria e não se movia, como quem sabe que seria importante me deixar ali um pouco [...].”","“O caminho do sagrado, do final de um período escuro, frio e penoso que se abre para uma imensidão de luzes, sonhos e possibilidades.”","“Talvez apenas a emoção de subir uma rampa cujo final é um campo de futebol onde dois times se enfrentarão.”"],"correta":0,"explicacao":"Gabarito: <strong>“Ele sorria e não se movia, como quem sabe que seria importante me deixar ali um pouco [...].”</strong>.","banca":"FUMARC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3824,"enunciado":"Assinale a alternativa correta quanto ao emprego de pronomes oblíquos átonos.","opcoes":["Sem avisá-lo do ocorrido, levaram-no preso.","Espero-lhe amanhã em frente à garagem do condomínio para te entregar a encomenda.","Na pescaria de hoje se metemos numa fria, pois surpreenderam nós com as redes já armadas.","Não se arrisque não, pois tu sabe que a mata pode enganá-lo","Nada encontrou-se lá que pudesse lhe incriminar, mas tu sabes o que enconde-se nas paredes da casa."],"correta":0,"explicacao":"Gabarito: <strong>Sem avisá-lo do ocorrido, levaram-no preso.</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3825,"enunciado":"Todos os pronomes pessoais oblíquos átonos, abaixo, destacados podem mudar de posição em relação ao verbo a que se referem; a EXCEÇÃO encontra-se na alternativa:","opcoes":["“A culinária me fascina.” (1º parágrafo).","“Não vão se transformar na flor branca macia.” (15º parágrafo)","“(...) mas o fato é que houve alguém que teve a ideia de debulhar as espigas e colocá-las numa panela sobre o fogo, (...)” (6º parágrafo)","“O fogo é quando a vida nos lança numa situação que nunca imaginamos.” (11º parágrafo)","“Piruá é o milho de pipoca que se recusa a estourar.” (13º parágrafo)"],"correta":4,"explicacao":"Gabarito: <strong>“Piruá é o milho de pipoca que se recusa a estourar.” (13º parágrafo)</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3826,"enunciado":"Assinale a alternativa em que a colocação pronominal está correta, de acordo com a norma-padrão.","opcoes":["Isso me traz lembranças felizes!","Não deixe-se abater por causa disso!","Talvez sirvam-nos peixe hoje no almoço.","É claro que trata-se de um equívoco.","Se sente imediatamente aqui!"],"correta":0,"explicacao":"Gabarito: <strong>Isso me traz lembranças felizes!</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3831,"enunciado":"Assinale a alternativa em que a colocação pronominal apresenta erro.","opcoes":["Ontem me disseram que não era para vir trabalhar.","Entregar-lhe-ei meus livros autografados.","O meu maior sonho era casar-me.","Alguns deram-lhe presentes.","Devo-lhe explicar o que aconteceu?"],"correta":3,"explicacao":"Gabarito: <strong>Alguns deram-lhe presentes.</strong>.","banca":"Instituto Avalia","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3832,"enunciado":"Assinale a alternativa que justifica, corretamente, a colocação pronominal na oração a seguir: Não te devolvi a borracha?","opcoes":["próclise porque está antes do verbo","mesóclise porque está entre o radical e a desinência do verbo","ênclise porque está depois do verbo","próclise com a palavra atrativa – advérbio de negação","próclise porque está depois do verbo"],"correta":3,"explicacao":"Gabarito: <strong>próclise com a palavra atrativa – advérbio de negação</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3833,"enunciado":"Há uma colocação pronominal correta, na alternativa:","opcoes":["Não percebi-lhe a ausência na reunião.","Tinha falado-lhe que não abrisse a caixa.","Alguns afastaram-se da discussão com cautela.","Ninguém aproximou-se da cena do crime.","Estou inclinado a perdoar-lhe a ofensa."],"correta":4,"explicacao":"Gabarito: <strong>Estou inclinado a perdoar-lhe a ofensa.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3836,"enunciado":"Julgue o item, que consiste em propostas de reescrita para períodos destacados do texto, quanto à correção gramatical e à coerência textual. “Perguntaram-me se o ladrão estava armado ou se já estava no interior da casa” (linhas 12 e 13): Me perguntaram se o ladrão armado esteve na casa\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3837,"enunciado":"No que concerne aos aspectos linguísticos do texto CB1A1, julgue o próximo item. No primeiro período do último parágrafo, estariam prejudicadas a correção gramatical e a coerência textual caso a expressão “se devem efetivar” fosse reescrita como deve-se efetivarem.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3840,"enunciado":"Quanto à Colocação Pronominal, analise os itens abaixo: I. “Reuniram-se e planejaram os detalhes.” II. “Deixem-me”, falou ele.” III. “Passem-me o bebê.” IV. “...a desistir das lutas que lhe competem.” V. “O filho não se deu por vencido.” Em qual(ais) item(ns), o pronome poderia também estar enclítico ao verbo, e isso não caracterizaria desobediência às normas gramaticais vigentes?","opcoes":["Em I, III e V, apenas.","Em I e IV, apenas.","Em I e III, apenas.","Em III, apenas.","Em nenhum."],"correta":4,"explicacao":"Gabarito: <strong>Em nenhum.</strong>.","banca":"UPENET/IAUPE","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":3842,"enunciado":"Sobre a colação do pronome e modo verbal em: \"Afaste-se e vá cuidar da própria vida.\", pode-se afirmar:","opcoes":["A colocação proclítica, no modo indicativo, está correta.","Não se inicia oração com pronome oblíquo no modo imperativo.","Há uso da ênclise e subjuntivo no período.","As formas verbais do indicativo estão na segunda pessoa do singular, afaste-se você."],"correta":1,"explicacao":"Gabarito: <strong>Não se inicia oração com pronome oblíquo no modo imperativo.</strong>.","banca":"Fundação CETAP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3843,"enunciado":"Em:\"(...) explica a Porchat\", ao se substituir o objeto por um pronome oblíquo, de acordo com a norma culta, tem-se:","opcoes":["explicá-lo.","explica-lhe.","explica-no.","explica a ele."],"correta":1,"explicacao":"Gabarito: <strong>explica-lhe.</strong>.","banca":"Fundação CETAP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3845,"enunciado":"Marque o parágrafo iniciado com termo pronominal referindo-se a um interlocutor direto.","opcoes":["Segundo parágrafo.","Quinto parágrafo.","Terceiro parágrafo.","Quarto parágrafo."],"correta":3,"explicacao":"Gabarito: <strong>Quarto parágrafo.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3847,"enunciado":"Na linha 15, em “Perguntava-me”, há a ocorrência de ênclise. Assinale a alternativa na qual a colocação pronominal esteja INCORRETA.","opcoes":["Ele queria que me fossem passados os dados.","Quando me informaram do ocorrido, tive uma reação inesperada.","Por que a maltrataram tanto?","Ninguém enviou-me o pacote.","Aqui se vive feliz."],"correta":3,"explicacao":"Gabarito: <strong>Ninguém enviou-me o pacote.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3852,"enunciado":"Considere o fragmento “[...] dir-se-ia que o fim último, [...]”. O uso da mesóclise não é muito comum no português do Brasil. No lugar dela, mantendo a correção gramatical, é mais usual","opcoes":["apenas colocar o pronome antes do verbo.","apenas colocar o pronome depois do verbo.","colocar o pronome antes do verbo se houver fator de próclise ou, se não houver, colocá-lo depois do verbo.","construir uma locução verbal, formada por verbo auxiliar, mais o verbo principal em uma das formas nominais."],"correta":3,"explicacao":"Gabarito: <strong>construir uma locução verbal, formada por verbo auxiliar, mais o verbo principal em uma das formas nominais.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3853,"enunciado":"Observe a colocação pronominal destacada nos fragmentos: “Chamavam-lhe, por ironia, a Rua do Meio. Agora, outros caminhos de areia solta se abriram num emaranhado.” Em relação à colocação dos pronomes, em destaque, junto aos verbos temos respectivamente:","opcoes":["Próclise e mesóclise.","Ênclise e próclise.","Próclise e ênclise.","Mesóclise e ênclise."],"correta":2,"explicacao":"Gabarito: <strong>Próclise e ênclise.</strong>.","banca":"Aroeira","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3854,"enunciado":"Uma das habilidades da prática de leitura, escuta, produção de textos (orais, escritos, multissemióticos) e análise linguística/semiótica é “analisar elementos e aspectos da sintaxe do português, como a ordem dos constituintes da sentença (e os efeito que causam sua inversão), a estrutura dos sintagmas, as categorias sintáticas, os processos de coordenação e subordinação (e os efeitos de seus usos) e a sintaxe de concordância e de regência, de modo a potencializar os processos de compreensão e produção de textos e a possibilitar escolhas adequadas à situação comunicativa.” (BRASIL, 2018, p. 507) Nesse caso, considerando-se a colocação dos pronomes oblíquos átonos na charge, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir. ( ) No terceiro balão, a palavra negativa determina o emprego da próclise. ( ) No segundo balão, o verbo no gerúndio exige a ênclise. ( ) É facultativo o emprego do pronome oblíquo nas locuções verbais, conforme empregado no segundo balão. ( ) O pronome relativo “que” atrai o pronome oblíquo “o”, por isso a próclise no primeiro balão. De acordo com as afirmações, a sequência correta é","opcoes":["V, V, F, F.","F, F, V, V.","F, V, F, V.","V, F, V, F.","V, V, F, V."],"correta":3,"explicacao":"Gabarito: <strong>V, F, V, F.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3858,"enunciado":"“Os pronomes pessoais oblíquos me, te, se, lhe(s), o(s). a(s), nos e vos podem estar em três posições em relação ao verbo ao qual se ligam: depois (ênclise), no meio (mesóclise) e antes do verbo (próclise)”. CEREJA, William Roberto, MAGALHÃES, Thereza Cochar. Gramática reflexiva: Texto, semântica e interação. São Paulo: Atual, 2013, p. 368. A esse respeito, analise as asserções a seguir e a relação proposta entre elas. I – No trecho “Era uma algazarra. Cada um pontuava como lhe desse na telha.”, a colocação pronominal se realizou de acordo com a norma-padrão PORQUE, II – no caso, a próclise é de rigor, pois há antes do verbo, na oração, uma palavra que atrai o pronome átono, representada pela conjunção subordinativa. A respeito das asserções é correto afirmar que","opcoes":["as duas são falsas.","a primeira é falsa e a segunda é verdadeira.","a primeira é verdadeira e a segunda é falsa.","as duas são verdadeiras e a segunda justifica a primeira.","as duas são verdadeiras, mas a segunda não justifica a primeira."],"correta":3,"explicacao":"Gabarito: <strong>as duas são verdadeiras e a segunda justifica a primeira.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3859,"enunciado":"Assinale a alternativa que apresenta correção na colocação pronominal:","opcoes":["Nunca disseram-lhe quais as outras alternativas para um consumo consciente das fontes não renováveis.","Embora se invista em pesquisas a respeito de fontes renováveis de energia, o petróleo ainda é amplamente explorado.","Muitas pesquisas já foram empreendidas na área da energia renováveis. Algumas foram-lhes apresentadas na última reunião.","Me surpreende que ainda façamos uso de fontes não renováveis de energia, quando há tantas outras disponíveis.","Às vezes pego-me refletindo a respeito dos caminhos aos quais a ambição humana vai nos levar."],"correta":1,"explicacao":"Gabarito: <strong>Embora se invista em pesquisas a respeito de fontes renováveis de energia, o petróleo ainda é amplamente explorado.</strong>.","banca":"FURB","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3863,"enunciado":"Acerca dos aspectos gramaticais e dos sentidos do texto apresentado, julgue o item. A correção gramatical do quinto parágrafo seria mantida caso, no trecho “se tornou” (linha 14), a forma pronominal “se” fosse deslocada para logo após a forma verbal — escrevendo‐se tornou‐se.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3864,"enunciado":"Quanto à colocação pronominal em: “Mas quando existe não se precisa de códigos verbais para se expressar” pode-se afirmar que:","opcoes":["a próclise é facultativa, pois há uma expressão atrativa que antecede o verbo.","a ênclise seria obrigatória, pois uma expressão atrativa antecede o verbo (não).","o pronome está na posição enclítica, pois há palavra atrativa (quando).","o pronome está na posição proclítica, pois há palavra atrativa (não).","o pronome está na posição proclítica, pois há palavra atrativa (quando)."],"correta":3,"explicacao":"Gabarito: <strong>o pronome está na posição proclítica, pois há palavra atrativa (não).</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3865,"enunciado":"Sobre as regras de colocação pronominal, assinale a alternativa incorreta:","opcoes":["Não o permitiram a conversão de real para dólar.","Nem sempre se enxergam as disparidades do mundo contemporâneo.","Certamente eles dariam-nos tudo se pudessem.","Este bar é lugar da cidade onde se encontram os melhores pratos da cidade.","Enquanto me diziam aquilo, eu permanecia imóvel."],"correta":2,"explicacao":"Gabarito: <strong>Certamente eles dariam-nos tudo se pudessem.</strong>.","banca":"AMAUC","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3870,"enunciado":"Leia o texto abaixo: O Coronel Uma das mais tradicionais figuras da sociedade brasileira é o coronel. O coronel, seja ou não do exército (e geralmente não é), comporta-se como alguém que possui um imenso poder, alguém que manda e desmanda, que possui e faz questão de demonstrar sua autoridade. Provavelmente tal figura nasceu nas fazendas de cana-de-açúcar e de café, e sua brutalidade vem do áspero trato com os escravos. (…) O curioso é que, além de persistir a figura do coronel, permanece a do servo. Grande parte da população ama e reverencia esse padrão de comportamento autoritário. Exemplos estão espalhados pelo Brasil. (…) Seus eleitores e admiradores são, em geral, pessoas que não simpatizam ou não entendem os complicados processos da democracia. Para elas, e muitas vezes isso é uma desconfiança justificada, o mundo dos poderosos é composto de enganadores. Nos coronéis elas reconhecem um sujeito franco, espontâneo, daqueles que falam primeiro e pensam depois. Elas o sentem como alguém próximo e com quem podem se identificar. Sentem-se representadas por ele e por isso votam nele. (…) Na canção “Podres Poderes”, o compositor Caetano Veloso põe em destaque este vezo cultural de nossa sociedade: o de reverenciar coronéis. Para quem nunca teve o prazer de ouvir a música, o verso é o seguinte: “Será que nunca faremos senão confirmar a incompetência da América católica, que sempre precisará de ridículos tiranos?”. Queria saber a resposta, mas não sei. José Roberto Torero – Folha de S. Paulo, caderno de Esportes, 5/01/2001 Analise as afirmativas abaixo: 1. A palavra figuras retoma a coronel, logo é elemento de coesão textual. 2. Na expressão esse padrão de comportamento, o pronome se refere a antecedente. 3. A expressão este vezo cultural relaciona-se ao que será exposto mais adiante no texto. 4. Na oração elas o sentem, no 3º parágrafo, o pronome oblíquo o retoma enganadores. Assinale a alternativa que indica todas as afirmativas corretas.","opcoes":["São corretas apenas as afirmativas 1 e 3.","São corretas apenas as afirmativas 2 e 3.","São corretas apenas as afirmativas 1, 2 e 3.","São corretas apenas as afirmativas 2, 3 e 4.","São corretas as afirmativas 1, 2, 3 e 4."],"correta":2,"explicacao":"Gabarito: <strong>São corretas apenas as afirmativas 1, 2 e 3.</strong>.","banca":"FEPESE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3872,"enunciado":"Observe a colocação dos pronomes nas frases abaixo. 1. Quem me chamou? 2. Enfim, abraço-te. 3. Ninguém conheceu-a. 4. Em tratando-se de parentesco, éramos todos uma só família. Segundo a norma-padrão, a colocação pronominal está correta apenas nas frases:","opcoes":["1 e 2.","1 e 3.","2 e 3.","2 e 4.","3 e 4."],"correta":0,"explicacao":"Gabarito: <strong>1 e 2.</strong>.","banca":"FEPESE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3873,"enunciado":"Complete as frases abaixo de acordo com as regras de concordância. ■ ................... algumas horas que estou te esperando. ■ ................... de atendentes eficientes. ■ Margarida anda .................... esquecida de seus afazeres diários. ■ ................... dez pessoas aguardando. Assinale a alternativa que completa correta e sequencialmente as lacunas do texto.","opcoes":["Faz • Precisa-se • meia • Havia","Faz • Precisa-se • meio • Havia","Faz • Precisam-se • meia • Havia","Fazem • Precisa-se • meia • Haviam","Fazem • Precisam-se • meio • Haviam"],"correta":1,"explicacao":"Gabarito: <strong>Faz • Precisa-se • meio • Havia</strong>.","banca":"FEPESE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3874,"enunciado":"Com relação à colocação pronominal e de acordo com a norma-padrão da Língua Portuguesa, assinale a alternativa correta.","opcoes":["Me disseram que um beijo é melhor que a violência.","Leia este livro que ensinará-la coisas melhores.","Sempre me questionei acerca dessas coisas.","Aquela proposta não convenceu-me."],"correta":2,"explicacao":"Gabarito: <strong>Sempre me questionei acerca dessas coisas.</strong>.","banca":"INSTITUTO MAIS","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3876,"enunciado":"Sobre a colocação do pronome “se”, em relação ao verbo “originou”, no período “Segundo Thomas Hobbes, a sociedade se originou de um contrato social...”, analise as assertivas abaixo: I. Ocorreu a próclise por escolha do falante. II. Ocorreu a ênclise, devido ao verbo no passado. III. Ocorreu a mesóclise por estar entre o sujeito e o verbo. IV. Poderia ter ocorrido a ênclise, já que se encontra em situação de uso opcional. É correto o que se apresenta","opcoes":["no item I, apenas.","no item III, apenas.","nos itens I e IV, apenas.","nos itens II e III, apenas."],"correta":2,"explicacao":"Gabarito: <strong>nos itens I e IV, apenas.</strong>.","banca":"IDIB","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3877,"enunciado":"Analise as afirmativas e marque a incorreta, quanto à colocação pronominal.","opcoes":["Capitu deu-me as costas, voltando-se para o espelhinho.","Ganha-se a vida, perde-se a batalha.","Parece que não machucou-se, então.","Encostei-me a um poste da linha telegráfica, reparei num grupo de rapazes e moças."],"correta":2,"explicacao":"Gabarito: <strong>Parece que não machucou-se, então.</strong>.","banca":"MSConcursos","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3879,"enunciado":"Considerando as formas de colocação pronominal, em querê-las, tem-se um caso de:","opcoes":["Próclise.","Hidrólise.","Mesóclise.","Ênclise.","Antítese."],"correta":3,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"IESES","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3881,"enunciado":"De acordo com a norma-padrão da Língua Portuguesa e quanto à colocação pronominal, assinale a alternativa que apresenta uma afirmação correta a respeito do uso do pronome oblíquo “me” destacado na frase acima.","opcoes":["A frase “Me lembro do peso e do fascínio de uma coleção da editora Abril Cultural chamada Tudo – Dicionário Enciclopédico Ilustrado” também estaria correta.","Não se deve iniciar frases com pronomes oblíquos átonos e, portanto, a ênclise é obrigatória nesse caso.","A frase obrigatoriamente precisa ser corrigida para “Eu me lembro do peso e do fascínio de uma coleção da editora Abril Cultural chamada Tudo – Dicionário Enciclopédico Ilustrado”.","A ênclise é obrigatória no contexto apresentado porque o sujeito precisa vir após o verbo “lembro”."],"correta":1,"explicacao":"Gabarito: <strong>Não se deve iniciar frases com pronomes oblíquos átonos e, portanto, a ênclise é obrigatória nesse caso.</strong>.","banca":"INSTITUTO MAIS","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3882,"enunciado":"Assinale a alternativa cuja reescrita do texto emprega a colocação pronominal de acordo com a norma-padrão da Língua Portuguesa.","opcoes":["Me chame o chefe da família, por gentileza.","O curso que fiz não ofereceu-me todas as respostas.","Se o chefe da família estiver, lhe informe de minha presença.","Queira-me informar se o chefe da família está."],"correta":3,"explicacao":"Gabarito: <strong>Queira-me informar se o chefe da família está.</strong>.","banca":"INSTITUTO MAIS","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3884,"enunciado":"Analise o período a seguir: “Some-se a isso o fato de as mulheres vivenciarem experiências como a gravidez e a menopausa, com grandes mudanças hormonais.” (linhas 8 a 10). Sobre sua análise sintática, morfológica e de colocação, assinale a alternativa CORRETA.","opcoes":["O período deveria ter sido iniciado por “Se soma a isso o fato...”.","O verbo “somar”, no contexto em que se encontra, desempenha função pronominal e foi empregado no sentido de “Pôr-se junto a; juntar-se, reunir-se”.","Há erro de colocação pronominal no período em tela.","Há um caso facultativo de ênclise no período.","Há um caso obrigatório de mesóclise no período."],"correta":1,"explicacao":"Gabarito: <strong>O verbo “somar”, no contexto em que se encontra, desempenha função pronominal e foi empregado no sentido de “Pôr-se junto a; juntar-se, reunir-se”.</strong>.","banca":"ADVISE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3886,"enunciado":"Assinale a alternativa em que a frase escrita a partir do texto está em conformidade com a norma-padrão de concordância e de colocação pronominal.","opcoes":["Como sempre soube-se, haviam decisões da prefeitura que deviam ser submetidas ao crivo da Câmara Municipal.","Tendo revelado-se um caminho possível, cogitou-se parcerias entre a educação pública e o terceiro setor.","Jamais se imaginou que houvesse soluções fáceis para os problemas da educação pública.","Nada acrescentou-se à proposta de mudanças na gestão do ensino as quais possa ser significativa.","Obviamente esperam-se que as medidas anunciadas produzam os resultados que já fazem anos que esperamos."],"correta":2,"explicacao":"Gabarito: <strong>Jamais se imaginou que houvesse soluções fáceis para os problemas da educação pública.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3888,"enunciado":"Assinale a alternativa em que os trechos − ...que compartilham comigo esse banquete de ideias... – e − ...sempre propondo novas perguntas. – foram reescritos, respectivamente, de acordo com a norma-padrão de colocação pronominal.","opcoes":["que compartilham-no comigo / sempre as propondo","que o compartilham comigo / sempre as propondo","que compartilham-o comigo/ sempre propondo-as","que o compartilham comigo / sempre propondo-as","que compartilham-o comigo/ sempre as propondo"],"correta":1,"explicacao":"Gabarito: <strong>que o compartilham comigo / sempre as propondo</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3889,"enunciado":"Assinale a alternativa em que a frase escrita a partir do texto está em conformidade com a norma-padrão de colocação pronominal.","opcoes":["Já não acredita-se mais no discurso sobre as razões para o conflito militar.","A OTAN ainda se diz comprometida com a adesão da Ucrânia à organização.","Se tornou ainda mais improvável a aceitação da Ucrânia pelo bloco europeu.","O conflito tem mostrado-se muito mais letal do que inicialmente previsto.","Jamais acreditou-se de fato na alegação russa para o início do conflito armado."],"correta":1,"explicacao":"Gabarito: <strong>A OTAN ainda se diz comprometida com a adesão da Ucrânia à organização.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3891,"enunciado":"Em relação à colocação pronominal, analisar os itens abaixo: I. Quanto custa-lhe o empréstimo por mês? II. Jamais senti-me sozinha.","opcoes":["Os itens I e II estão corretos.","Somente o item I está correto.","Somente o item II está correto.","Os itens I e II estão incorretos."],"correta":3,"explicacao":"Gabarito: <strong>Os itens I e II estão incorretos.</strong>.","banca":"OBJETIVA","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3892,"enunciado":"Assinale a alternativa em que, com a alteração da posição do pronome conforme indicado nos parênteses, a redação permanece em conformidade com a norma-padrão da língua.","opcoes":["... não mostrei as razões que me fervilhavam na cabeça... (que fervilhavam-me)","Trouxeram-me a roupa branca nova. Tentaram calçar-me os borzeguins amarelos... (Me trouxeram)","Fileiras de alunos se perdiam num aglomerado confuso. (Fileiras de alunos perdiam-se)","Não me seria possível espernear, berrar daquele jeito, exibir força... (Não seria-me)","Na civilização e na fraqueza, ia para onde me impeliam, muito dócil… (para onde impeliam-me)"],"correta":2,"explicacao":"Gabarito: <strong>Fileiras de alunos se perdiam num aglomerado confuso. (Fileiras de alunos perdiam-se)</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3893,"enunciado":"“Dormir por muito tempo também é uma coisa, e você não se sentirá descansado”. De acordo com as regras formais de colocação pronominal, o pronome oblíquo “se” está ocupando a posição denominada","opcoes":["ênclise, devido ao verbo no futuro do pretérito.","próclise, devido ao adjunto adverbial de negação.","mesóclise, devido ao verbo no futuro do presente.","próclise, devido à presença do pronome de tratamento “você”.","ênclise, porque não se inicia frase com pronome oblíquo na frente."],"correta":1,"explicacao":"Gabarito: <strong>próclise, devido ao adjunto adverbial de negação.</strong>.","banca":"IDIB","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3894,"enunciado":"Assinale a alternativa que atende à norma-padrão de colocação pronominal.","opcoes":["Libertou-se, com a rocha partida, o espírito da raposa, o qual está novamente vagando pelo Japão.","Nos últimos dias, muitas pessoas têm preocupado-se com a pedra sessho-seki, que está rachada.","De acordo com a lenda, se a pedra sessho-seki se quebrasse, o espírito da raposa libertaria-se.","O espírito da raposa, que já aproximou-se de líderes japoneses, seria a verdadeira identidade de Tamamo-no-Mae.","Em Nasu, muitos turistas diariamente dirigem-se às montanhas vulcânicas, para ver “a pedra da morte”."],"correta":0,"explicacao":"Gabarito: <strong>Libertou-se, com a rocha partida, o espírito da raposa, o qual está novamente vagando pelo Japão.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3895,"enunciado":"Assinale a afirmativa em que a colocação pronominal está incorreta.","opcoes":["Nunca falaram-me sobre a importância da educação na primeira infância.","Quem te falou sobre a necessidade de priorizar a educação na primeira infância?","Em se tratando de criança de até seis anos, a educação é fundamental.","Ajudar-te-ei no que for preciso para colocar sua criança na escola no tempo certo.","Não me faça perder a esperança."],"correta":0,"explicacao":"Gabarito: <strong>Nunca falaram-me sobre a importância da educação na primeira infância.</strong>.","banca":"IDECAN","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3898,"enunciado":"Assinale a alternativa em que a colocação pronominal está de acordo com a norma-padrão.","opcoes":["Se mostra difícil, no Brasil, um combate eficaz aos impactos recessivos na economia.","O quadro de recuperação da economia mudou quando confirmado que o coronavírus não limitou-se à China","No Brasil, tem avaliado-se que o impacto econômico do coronavírus pode resultar em danos.","Havia esperança de que o PIB do emergente asiático recuperaria-se já a partir de março.","Cortes de juros encontram-se já em nível baixo, portanto não há como mexer com eles."],"correta":4,"explicacao":"Gabarito: <strong>Cortes de juros encontram-se já em nível baixo, portanto não há como mexer com eles.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3902,"enunciado":"Considere o seguinte trecho redigido a partir das informações do texto: Quanto à possibilidade de exercer as inspiradoras profissões do futuro, muitos dos nossos jovens ainda não ________________________ , devido à ausência de qualidades que o desempenho delas exige. __________________ em seu horizonte não traz, por si só, qualquer certeza de que exercerão uma dessas atividades no futuro, havendo, sim, necessidade de investimento nesse sentido. De acordo com a norma-padrão relativa ao emprego e colocação de pronomes, as lacunas do texto devem ser preenchidas, correta e respectivamente, com","opcoes":["lhe alcançaram ... As ter","alcançaram-lhe ... Ter-lhes","a alcançaram ... Tê-las","alcançaram-na ... Tê-las","a alcançaram ... Lhes ter"],"correta":2,"explicacao":"Gabarito: <strong>a alcançaram ... Tê-las</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3903,"enunciado":"Assinale a alternativa em que a colocação pronominal está em conformidade com a norma-padrão.","opcoes":["As pessoas, que mediavam seus conflitos pelo diálogo, não se atêm mais a essa prática civilizada.","Sentariam-se à direita de Deus, segundo o narrador, os que fossem conduzidos pelos anjos suaves.","Se dirigiriam para o lado esquerdo, segundo o narrador, os que fossem conduzidos pelos anjos terríveis.","Os profetas certamente enganaram-se em relação ao fim do mundo, uma vez que isso não ocorreu.","Os motoristas, que acham-se cheios de razão, frequentemente deixam seus carros sob as calçadas."],"correta":0,"explicacao":"Gabarito: <strong>As pessoas, que mediavam seus conflitos pelo diálogo, não se atêm mais a essa prática civilizada.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3904,"enunciado":"A colocação pronominal atende à norma-padrão em:","opcoes":["Os cigarros eletrônicos ganham os jovens, que se atraem pela adição de sabores de fruta ou refrescantes.","Autoridades têm mostrado-se impotentes em coibir a comercialização dos cigarros eletrônicos.","Os cigarros eletrônicos rapidamente tornaram-se populares entre adolescentes, símbolo de status social.","Com a renovação da proibição dos cigarros eletrônicos, não garantirá-se que eles deixem de ser consumidos.","Se vendem cigarros eletrônicos em toda parte pelo Brasil, os quais entram aqui pelo contrabando."],"correta":0,"explicacao":"Gabarito: <strong>Os cigarros eletrônicos ganham os jovens, que se atraem pela adição de sabores de fruta ou refrescantes.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3905,"enunciado":"Assinale a alternativa em que o enunciado atende à norma-padrão quanto à colocação pronominal.","opcoes":["As redes sociais têm uma faceta ameaçadora, e quem as descreveu para o jornal foi a Nobel da Paz de 2021, jornalista Maria Ressa.","Nada avaliou-se ainda quanto aos impactos à sociedade decorrentes da veiculação de um turbilhão de falsificações oportunistas nas redes sociais.","Se disseminam, nos meios digitais, ilegalidades que não se praticavam na mesma extensão e profundidade antes da hegemonia das redes sociais.","Tem percebido-se, aos poucos, a importância do jornalista para a sociedade, apurando e publicizando fatos objetivamente verificáveis.","Responsabilizarão-se as redes sociais que, por meio dos seus serviços, cometerem crimes, veiculando informações que contradizem a verdade."],"correta":0,"explicacao":"Gabarito: <strong>As redes sociais têm uma faceta ameaçadora, e quem as descreveu para o jornal foi a Nobel da Paz de 2021, jornalista Maria Ressa.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3907,"enunciado":"Assinale a alternativa que preenche, na sequência, as lacunas do texto a seguir, de acordo com a norma-padrão de concordância e colocação pronominal. _________________ as condições que envolvem o conflito, não __________________ descartar questões de soberania, as quais ________________ na discussão de soluções o mais _____________________ conciliadoras.","opcoes":["Dado ... se poderia ... apresentam-se ... possíveis","Dadas ... poderia-se ... se apresentam ... possível","Dadas ... poderiam-se ... apresenta-se ... possíveis","Dado ...se poderiam ... se apresenta ... possível","Dadas ... se poderiam ... se apresentam ... possível"],"correta":4,"explicacao":"Gabarito: <strong>Dadas ... se poderiam ... se apresentam ... possível</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3910,"enunciado":"Leia a tirinha. Assinale a alternativa que completa, corretamente, as lacunas das frases.","opcoes":["lhe … esse … Espera … mim","te … este … Espera … eu","lhe … este … Espere … mim","te … esse … Espera … mim","lhe … este … Espere … eu"],"correta":4,"explicacao":"Gabarito: <strong>lhe … este … Espere … eu</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3911,"enunciado":"Considerando o emprego e a colocação pronominal, assinale a alternativa em que as palavras ou expressões em destaque na frase apresentam-&shy;se corretamente substituídas no parêntese.","opcoes":["Nunca coloque a tecnologia em uma posição anterior à pedagogia. (coloque-&shy;a)","… nenhuma solução tecnológica é capaz de substituir a mediação humana… (substituir-&shy;la)","Ele é o maestro que combina diferentes mídias… (combina&shy;-as)","… todas as escolas do País fecharam as portas… (fecharam&shy;-nas)","Quais ações práticas as redes de ensino devem adotar para manter professores em sintonia com o universo digital? (manter-&shy;lhes)"],"correta":3,"explicacao":"Gabarito: <strong>… todas as escolas do País fecharam as portas… (fecharam&shy;-nas)</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3912,"enunciado":"Com a mudança da posição do pronome conforme indicado nos parênteses, a frase permanece de acordo com a norma-padrão de colocação pronominal em:","opcoes":["... a evolução ocorre através de pequenas modificações que se acumulam. (acumulam-se)","... quando se discute o lugar do homem no mundo biológico... (discute-se)","... embarcamos em narrativas que nos colocam no ápice da criação. (colocam-nos)","Ainda que bichos não se mostrem capazes de perguntar... (mostrem-se)","Parentes delas, três tipos de formiga passariam até no teste de se reconhecer no espelho. (reconhecer-se)"],"correta":4,"explicacao":"Gabarito: <strong>Parentes delas, três tipos de formiga passariam até no teste de se reconhecer no espelho. (reconhecer-se)</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3913,"enunciado":"Leia os trechos e assinale a alternativa em que as expressões em destaque foram reescritas de acordo com a norma-padrão de emprego e colocação pronominal. • De outras aldeias chegam mulheres carregando pacotes... • ...e ali deita sua mercadoria...","opcoes":["carregando-as / a deita","as carregando / deita-a","carregando-los / deita-a","lhes carregando / deita-na","carregando-os / a deita"],"correta":4,"explicacao":"Gabarito: <strong>carregando-os / a deita</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3915,"enunciado":"Assinale a alternativa em que a colocação pronominal é contrária ao que é prescrito pela norma padrão da língua portuguesa.","opcoes":["“[...] é uma grande honra tê-lo como o nosso entrevistado.”.","“[...] em 1974 fui para a Amazônia e me embrenhei na floresta [...]”.","“[...] fui estudar jornalismo, me tornei repórter [...]”.","“[...] os desafios ambientais que se apresentam?”.","“O cuidado que se deve ter é não confundir [...]”."],"correta":2,"explicacao":"Gabarito: <strong>“[...] fui estudar jornalismo, me tornei repórter [...]”.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3917,"enunciado":"Assinale a alternativa correta sobre a colocação do pronome oblíquo átono, em relação ao verbo, no trecho “[...] é importante incluí-los em um plano alimentar equilibrado.”, do Texto 2.","opcoes":["Como o pronome oblíquo átono apresenta função de objeto indireto, sua posição correta seria a de próclise em relação ao verbo.","Como o pronome oblíquo átono apresenta função de objeto direto e não há palavra atrativa antes do verbo, está correta a sua posição de ênclise em relação ao verbo.","Como o tempo verbal é o infinitivo, o pronome oblíquo átono deveria estar em posição de mesóclise em relação ao verbo.","Como há inversão da oração subordinada, a posição correta do pronome oblíquo átono é a de ênclise em relação ao verbo.","Como há presença de palavra atrativa antes do verbo, a posição correta do pronome oblíquo átono seria a de próclise."],"correta":1,"explicacao":"Gabarito: <strong>Como o pronome oblíquo átono apresenta função de objeto direto e não há palavra atrativa antes do verbo, está correta a sua posição de ênclise em relação ao verbo.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3918,"enunciado":"Considerando as regras de colocação pronominal prescritas pela norma culta, assinale a alternativa que apresenta um desvio no emprego da próclise, uma vez que o autor deveria ter usado, obrigatoriamente, a ênclise.","opcoes":["“A comoção não se sustenta ao fim de 48 horas.” (1º§)","“(...) no vil ato de abordar uma pessoa, se utilizando das práticas mais cruéis e desumanas.” (3º§)","“É evidente que há uma fratura social exposta e ela se personifica no racismo estrutural, (...)” (12º§)","“(...) o racismo é apresentado como decorrência da própria estrutura, ou seja, do modo ‘normal’ com que se constituem as relações políticas, (...)” (12º§)"],"correta":1,"explicacao":"Gabarito: <strong>“(...) no vil ato de abordar uma pessoa, se utilizando das práticas mais cruéis e desumanas.” (3º§)</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3919,"enunciado":"Das alternativas abaixo, qual apresenta INCORRETA colocação pronominal?","opcoes":["Faça-me o favor de avisar quando sair.","Quando eu mandar, retirem-no daqui.","Afinal, deram-me uma boa notícia.","Nunca o vi triste assim.","Me mande notícias assim que puder."],"correta":4,"explicacao":"Gabarito: <strong>Me mande notícias assim que puder.</strong>.","banca":"Avança SP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3920,"enunciado":"A colocação pronominal está em desacordo com o padrão culto da língua portuguesa em:","opcoes":["“Agarrei-me ao banco.” 5º§","“Tento me manter na velocidade exigida pelas placas.” 10º§","“- Parecia que eu estava em um filme, me assistindo.” 20º§","“[...] já não se ouvem tantos gritos [...].” 11º§"],"correta":2,"explicacao":"Gabarito: <strong>“- Parecia que eu estava em um filme, me assistindo.” 20º§</strong>.","banca":"IUDS","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3921,"enunciado":"Complete as lacunas. “ ___________, quando ___________ novamente.” Marque a alternativa que completa corretamente a frase acima.","opcoes":["Me avisem – nos encontraremos.","Avisem-me – nos encontraremos.","Avisem-me – encontraremo-nos.","Me avisem – encontrar-nos-emos."],"correta":1,"explicacao":"Gabarito: <strong>Avisem-me – nos encontraremos.</strong>.","banca":"IUDS","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3922,"enunciado":"No trecho “Viam-na corada e nutrida, e não suspeitavam que aquele sentimento (...)”, no que tange à colocação pronominal, temos:","opcoes":["Correto uso de próclise, pois o verbo inicia a oração.","Correto uso de ênclise, pois o verbo inicia a oração.","Incorreto uso de ênclise, pois o verbo inicia a oração.","Incorreto uso de próclise, pois o verbo inicia a oração.","Uso facultativo de ênclise."],"correta":1,"explicacao":"Gabarito: <strong>Correto uso de ênclise, pois o verbo inicia a oração.</strong>.","banca":"Avança SP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3923,"enunciado":"Quanto à colocação dos pronomes pessoais oblíquos átonos, julgue os itens, abaixo, e assinale o que está correto:","opcoes":["Te entreguei os livros emprestados.","Não referi-me ao professor.","Quando a vi, abri um sorriso largo.","Ninguém dirigiu-me a palavra ali.","Não sei o que responderam-lhe ontem."],"correta":2,"explicacao":"Gabarito: <strong>Quando a vi, abri um sorriso largo.</strong>.","banca":"Avança SP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3924,"enunciado":"Assinale a alternativa em que o termo entre parênteses substitui corretamente a expressão.","opcoes":["colocar em risco uma criatura ancestral (coloca-a em risco)","representa a única fonte natural (representá-la)","pode causar doenças e reações alérgicas (pode causar-las)","quantificar o nível de contaminação (quantificá-lo)","precisa de mais informações (precisa-as)"],"correta":3,"explicacao":"Gabarito: <strong>quantificar o nível de contaminação (quantificá-lo)</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3925,"enunciado":"Assinale a alternativa que apresenta correção no que diz respeito à colocação pronominal, conforme a norma culta da língua portuguesa:","opcoes":["Quem convenceu-te a respeito da ineficácia das vacinas?","Ele não tomou o remédio, embora lhe tivessem oferecido.","Em tratando-se de ciência, é melhor não discordar.","Me mostre os dados dessa pesquisa, fiquei muito interessado.","Convém lhe confiar estas descobertas científicas."],"correta":1,"explicacao":"Gabarito: <strong>Ele não tomou o remédio, embora lhe tivessem oferecido.</strong>.","banca":"FURB","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3926,"enunciado":"Sobre colocação pronominal, analise os itens e responda: I – Sinto-me grata por tudo que tenho. II – Ninguém a viu sair. III – Me diga o horário da prova. IV – Não sinta-se tão culpado.","opcoes":["Apenas I e II estão corretas.","Apenas II e III estão corretas.","Apenas III e IV estão corretas.","Apenas IV está correta.","I, II, III e IV estão corretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I e II estão corretas.</strong>.","banca":"Avança SP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3927,"enunciado":"“Escrevo-lhe aqui de Ipanema [...].” 1º§ É correto afirmar sobre a colocação do pronome oblíquo átono na frase acima.","opcoes":["Ênclise facultativa no início de frase.","Ênclise observada no início de frase.","Próclise na sequência verbo-complemento.","Próclise como tendência brasileira.","Mesóclise com pronome intercalado ao verbo."],"correta":1,"explicacao":"Gabarito: <strong>Ênclise observada no início de frase.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3930,"enunciado":"Com relação à colocação dos pronomes, em não se sabe e em alimentam-se ocorre, respectivamente:","opcoes":["Ênclise e próclise.","Próclise e ênclise.","Mesóclise e próclise.","Próclise e mesóclise"],"correta":1,"explicacao":"Gabarito: <strong>Próclise e ênclise.</strong>.","banca":"IESES","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3932,"enunciado":"Considere o seguinte trecho redigido a partir do texto: Tendo ________ evidente o aumento expressivo da oferta de ensino superior a distância, surgiu, nesse contexto, certa preocupação com a formação dos alunos desses cursos, mais precisamente preocupação com a qualidade do ensino que ________. Apesar dos números relacionados a essa modalidade de ensino, é mais coerente ________ ao perfil do público que ________ do que a uma deficiência atribuível exclusivamente à forma como os cursos são ministrados. As lacunas presentes no trecho devem ser preenchidas, correta e respectivamente, com:","opcoes":["se tornado … era-lhes oferecido … lhes relacionar … lhe busca","se tornado … lhes era oferecido … relacioná-los … a busca","tornado-se … lhes era oferecido … os relacionar … busca-a","se tornado … os era oferecido … relacioná-los … a busca","tornado-se … era-lhes oferecido … relacionar-lhes … busca-lhe"],"correta":1,"explicacao":"Gabarito: <strong>se tornado … lhes era oferecido … relacioná-los … a busca</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3933,"enunciado":"Assinale a alternativa em que o advérbio exigiu a próclise do pronome oblíquo átono.","opcoes":["“A gente vê menos pessoas, mas se diverte com o comércio on-line, por exemplo.” 4º§","“Há menos contato físico, mas voltaremos a tê-lo?” 7º§","“Velhos amigos e amigas me procuram.” 6º§","“Não se vive absolutamente isolado.” 4º§","“Era uma tendência, mas com a quarentena tornou-se comum.” 1º§"],"correta":3,"explicacao":"Gabarito: <strong>“Não se vive absolutamente isolado.” 4º§</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":3943,"enunciado":"Com base no sentido das palavras e expressões no contexto do texto \"Áreas de parque de MG que tiveram pichação em pinturas rupestres serão isoladas para limpeza\", marque com V as afirmativas verdadeiras e com F as falsas. (__) No trecho 'O padrão das pichações é investigado para tentar identificar os autores do crime', a expressão 'padrão das pichações' refere-se ao tamanho e à cor das letras utilizadas pelos autores, elementos visuais que, segundo o texto, constituem as únicas pistas disponíveis para a identificação dos responsáveis pelo crime. (__) No trecho 'Entre os registros estão desenhos de animais e cenas de caça', a substituição de 'registros' por 'manifestações' pode ser considerada adequada sem alteração significativa de sentido, uma vez que, no contexto do texto, ambos os termos se referem às expressões gráficas produzidas pelas populações pré-históricas nas superfícies rochosas do parque. (__) No trecho 'a região de acesso às pinturas rupestres está com o acesso bloqueado para preservar o local que será periciado', o vocábulo 'periciado' pode ser substituído, sem alteração do sentido original, por 'vistoriado', uma vez que ambos os termos indicam, no contexto, uma avaliação técnica especializada a ser realizada no local atingido pelas pichações. (__) No trecho \"marcando a região como um importante sítio arqueológico\", o vocábulo \"sítio\" é empregado em seu sentido denotativo de propriedade rural de pequeno porte, indicando que a região onde estão localizadas as pinturas rupestres é uma área de uso agropecuário reconhecida pelo poder público como de interesse histórico. Assinale a alternativa que apresenta a sequência que preenche corretamente os itens acima, na ordem.","opcoes":["V, F, V, F.","F, V, F, V.","F, V, V, F.","V, V, V, V."],"correta":2,"explicacao":"Gabarito: <strong>F, V, V, F.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":3994,"enunciado":"\"A análise mostrou que a espécie havia infectado uma aranha de alçapão, que já estava morta.\" \"Nós vimos que, de fato, são espécies bastante distintas, que foram todas agrupadas dentro desse nome, Purpureocillium atypicola\", observa o cientista.\" Considerando a classe de palavras dos vocábulos empregados nos trechos, marque V, para as afirmativas verdadeiras, ou F, para as falsas. (__) O vocábulo 'bastante' é classificado como advérbio, diferentemente do uso em \"Ele é bastante inteligente para não fazer besteira\", que classifica-se como 'adjetivo'. (__) A expressão 'havia infectado' pode ser substituída por 'infectara' mantendo-se a correção gramatical e o sentido do trecho. (__) O vocábulo 'espécies' apresenta flexão de plural adequada, assim como o vocábulo 'ancião' em \"Os anciãos da comunidade reuniram-se no pátio da escola\". (__) A forma verbal 'vimos' corresponde ao pretérito perfeito do indicativo, diferentemente da forma empregada em \"Nós vimos de Nova Friburgo para participar da expedição científica\", que pertence a outro verbo e está no presente do indicativo, tratando-se, portanto, de verbos distintos. A sequência que preenche corretamente os itens acima, de cima para baixo, é:","opcoes":["F, F, V, F.","V, V, F, F.","V, V, V, V.","F, V, V, V."],"correta":3,"explicacao":"Gabarito: <strong>F, V, V, V.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":4194,"enunciado":"O protagonista da história narrada no poema não é nomeado, conferindo-se, dessa forma, um caráter de indigência ao personagem. Um outro índice estético presente no poema auxiliaria estudantes da 3a série do ensino médio a compreender essa construção imagética do “leiteiro”. Trata-se do seguinte índice:","opcoes":["omissão de conjunção conclusiva em “Há pouco leite no país, é preciso entregá-lo cedo.” (1a estrofe)","presença de antítese em “sai correndo e distribuindo/ leite bom para gente ruim.” (2a estrofe)","personificação do nome “corpo” em “E já que tem pressa, o corpo/ vai deixando à beira das casas” (3a estrofe)","especificação de dados pessoais em “morador da Rua Namur,/ empregado no entreposto,” (3a estrofe)","uso de orações subordinadas substantivas em “Se era noivo, se era virgem,/ se era alegre, se era bom,” (6a estrofe)"],"correta":4,"explicacao":"Gabarito: <strong>uso de orações subordinadas substantivas em “Se era noivo, se era virgem,/ se era alegre, se era bom,” (6a estrofe)</strong>.","banca":"CESGRANRIO","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":4239,"enunciado":"Leia e analise o excerto a seguir:Sendo o Brasil um país de base histórica escravocrata e racista, muitas das teorias produzidas para pensar a educação brasileira, bem como o ensino de línguas, eram reproduções de ideias europeias que partiam da compreensão de que os grupos sociais miscigenados eram considerados incapazes (Patto, 2015).O fragmento destacado classifica-se como oração","opcoes":["adjetiva explicativa.","substantiva objetiva indireta.","adjetiva restritiva.","substantiva completiva nominal."],"correta":3,"explicacao":"Gabarito: <strong>substantiva completiva nominal.</strong>.","banca":"FUNCERN","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":4247,"enunciado":"[Questão Inédita] Ao longo da história, os povos indígenas contribuíram significativamente para as ciências aplicadas modernas, como a medicina, a biologia, a matemática, a engenharia e a agricultura. Muitas dessas contribuições, no entanto, são desconhecidas.No trecho acima, há um elo coesivo criado por meio da nominalização entre “contribuíram” e “contribuições”. Nas alternativas a seguir, busca-se o procedimento de retomada por meio de nominalização, mas só um mostra adequação. Assinale-o.","opcoes":["os povos indígenas fabricaram produtos (2º parágrafo) / Tal fabrico...","Para sobreviver e se adaptar a diversos ambientes (2º parágrafo) / Essa sobrevida e adaptação...","Muitos povos indígenas desenvolveram uma cultura de medicina (2º parágrafo) / Tal desenvoltura...","Os indígenas norte-americanos conseguiram extrair o ácido da casca dessa árvore (3º parágrafo) / Tal exclusão...","Os mexicas, descendentes dos astecas, colhiam o alimento (5º parágrafo) / Esse armazenamento..."],"correta":0,"explicacao":"Gabarito: <strong>os povos indígenas fabricaram produtos (2º parágrafo) / Tal fabrico...</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":4258,"enunciado":"No 2º§ do texto – “Para organização e planejamento da assistência farmacêutica, é necessário que se disponha de recursos humanos qualificados na área da farmácia, aptos para lidar com diversos aspectos dos medicamentos. [...]”, pode-se afirmar que a partir da estruturação sintática do período observa-se:","opcoes":["A organização e emprego de períodos simples com o objetivo de contribuir com a coerência e coesão textuais.","O emprego da oração subordinada subjetiva como estratégia argumentativa contribuindo para a ampliação da articulação.","A justaposição dos períodos simples que constituem o trecho em análise demonstram uma estratégia linguística argumentativa.","A expressão “é necessário que” introduz uma oração equivalente ao termo sintático “advérbio” demonstrando circunstância em relação à expressão da ação na oração."],"correta":1,"explicacao":"Gabarito: <strong>O emprego da oração subordinada subjetiva como estratégia argumentativa contribuindo para a ampliação da articulação.</strong>.","banca":"Instituto Consulplan","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":4307,"enunciado":"Identifique em qual das sentenças a seguir o elemento em destaque é uma conjunção.","opcoes":["Não queria saber por que tudo aquilo aconteceu.","Disseram-lhe que a reunião seria sobre os novos projetos da escola.","Deram-lhe a opção de entregar a atividade hoje ou amanhã.","Nunca vi tanta elegância em uma só pessoa.","Seja sincero perante as autoridades."],"correta":2,"explicacao":"Gabarito: <strong>Deram-lhe a opção de entregar a atividade hoje ou amanhã.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":4333,"enunciado":"Acerca da frase \"À medida que os alunos desenvolvem suas habilidades de escrita, é imprescindível que os professores entreguem-lhes o feedback construtivo necessário para aprimorar a produção textual e promover um aprendizado mais eficaz\", analise as afirmações que seguem e registre V, para verdadeiras, e F, para falsas: (__) A crase está presente na frase pela presença da locucação conjuntiva. (__) A forma verbal \"entreguem\", quanto à regência verbal, é transitiva direta e indireta. (__) A oração \"que os professores entreguem-lhes o feedback construtivo necessário para aprimorar a produção textual\" é subordinada substantiva predicativa. Assinale a alternativa com a sequência correta:","opcoes":["F, V, V.","V, V, V.","V, V, F.","V, F, V."],"correta":2,"explicacao":"Gabarito: <strong>V, V, F.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal","crase"]},{"id":4380,"enunciado":"Na conhecida frase “Ao persistirem os sintomas, o médico deverá ser consultado”, a circunstância expressa pela oração subordinada é a mesma observada em","opcoes":["ao contrário do que se previa, conseguiu concluir seus estudos.","quando você chegar ao fim da corda, dê um nó nela e segure-se.","ao amanhecer, cada gota de orvalho parece uma lágrima.","todo ser humano evolui à proporção que se esforça para isso.","você pode ser o que quiser, contanto que seja bom."],"correta":4,"explicacao":"Gabarito: <strong>você pode ser o que quiser, contanto que seja bom.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":4389,"enunciado":"Julgue o item que se segue. Um período composto é normalmente formado por orações que operam de maneira independente, e a inclusão de uma oração subordinada pode transformá-lo em um período simples.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":4426,"enunciado":"Sobre o segmento oracional destacado “A professora Tara Spires-Jones, presidente da Associação Britânica de Neurociências, diz que o implante anunciado por Musk \"tem um grande potencial...”” (13º parágrafo), é correto afirmar que:","opcoes":["Trata-se de um período simples.","É composta por uma frase nominal.","Tem como valor semântico a condicionalidade.","Trata-se de uma oração subordinada objetiva direta.","Apresenta um erro de concordância."],"correta":3,"explicacao":"Gabarito: <strong>Trata-se de uma oração subordinada objetiva direta.</strong>.","banca":"IVIN","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":4432,"enunciado":"As frases a seguir mostram a modificação de uma forma reduzida para uma forma de oração desenvolvida; assinale a opção em que essa modificação foi feita de forma adequada.","opcoes":["Há boas razões para proteger a Terra. / Há boas razões para que protegêssemos a Terra.","Quando um homem não observa a natureza, sempre crê poder melhorá-la. / Quando um homem não observa a natureza, sempre crê que possa melhorá-la.","É impossível ensinar um gato a não pegar passarinhos. / É impossível ensinar um gato a que não pegasse passarinhos.","Sirvo-me de animais para instruir os homens. / Sirvo-me de animais para a instrução dos homens.","A natureza não nos permitiu conhecer o limite das coisas. / A natureza não nos permitiu que conheçamos o limite das coisas."],"correta":1,"explicacao":"Gabarito: <strong>Quando um homem não observa a natureza, sempre crê poder melhorá-la. / Quando um homem não observa a natureza, sempre crê que possa melhorá-la.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":4471,"enunciado":"Em ‘É possível, ainda, organizar sua participação em alguma associação de classe’, tem-se, em destaque, uma oração subordinada:","opcoes":["substantiva objetiva direta","substantiva apositiva","adverbial temporal","adverbial causal","substantiva subjetiva"],"correta":4,"explicacao":"Gabarito: <strong>substantiva subjetiva</strong>.","banca":"IDHTEC","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":4518,"enunciado":"Identifica-se oração subordinada que expressa sentido de tempo em:","opcoes":["Não sei, pois antes de começar a escrever para o Jornal do Brasil…","… à medida que escrevia para aqui, ia me tornando pessoal demais…","Outra coisa notei: basta eu saber que estou escrevendo para o jornal…","Não é que me desagrade mudar, pelo contrário.","Aqui no jornal apenas falo com o leitor e agrada-me que ele fique agradado."],"correta":0,"explicacao":"Gabarito: <strong>Não sei, pois antes de começar a escrever para o Jornal do Brasil…</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":4593,"enunciado":"Considerando o emprego da partícula “se”, em “[...] estima-se que o tratamento [...]” (4º§) pode-se afirmar que:","opcoes":["Não é possível determinar o sujeito da forma verbal “estima”, sendo o sujeito inexistente.","Ocorre um exemplo de oração sem sujeito de forma a generalizar a informação apresentada.","Trata-se de pronome apassivador em que a oração substantiva seguinte exerce função sintática.","Denota indeterminação do sujeito, permitindo que enunciador se inclua como parte do grupo social.","A escolha discursiva permite a ênfase ao agente da ação verbal, contribuindo para o efeito de sentido pretendido pelo enunciador."],"correta":2,"explicacao":"Gabarito: <strong>Trata-se de pronome apassivador em que a oração substantiva seguinte exerce função sintática.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":4739,"enunciado":"Considerando-se a formação da locução “cerca de”, que ocorre no excerto “(...) cerca de 180 mil gorilas, bonobos e chimpanzés”, sua classificação gramatical é a de:","opcoes":["locução adverbial.","locução adjetiva.","locução substantiva.","locução conjuntiva.","locução prepositiva."],"correta":4,"explicacao":"Gabarito: <strong>locução prepositiva.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":4793,"enunciado":"Caso na frase \"A confusão levou-me a um profundo constrangimento\" fosse inserido o advérbio NÃO posteriormente ao substantivo \"confusão\":","opcoes":["A próclise seria obrigatória.","A ênclise seria facultativa.","A próclise seria facultativa.","A próclise seria proibida."],"correta":0,"explicacao":"Gabarito: <strong>A próclise seria obrigatória.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":4827,"enunciado":"Considere as frases.• A relação cultural _______________ não é similar ___________ estabelecida entre Portugal e Brasil. • Atualmente, o comércio _______________ está bem aquecido, pois o país asiático tornou-se o primeiro a comprar mais de US$ 100 bilhões em produtos brasileiros em um ano (US$ 104,3 bilhões).De acordo com a norma-padrão, as lacunas das frases devem ser preenchidas, respectivamente, com:","opcoes":["japonesa-portuguesa … ante à … chinês-brasileiro","nipo-portuguesa … a … chino-brasileiro","luso-nipônica… da … chino-brasileira","lusitano-nipônica … com a … china-brasileiro","luso-japonesa… à … sino-brasileiro"],"correta":4,"explicacao":"Gabarito: <strong>luso-japonesa… à … sino-brasileiro</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":5239,"enunciado":"A respeito da oração destacada no trecho “Esse novo modelo previdenciário teve um grande impacto na psiquiatria, beneficiando a indústria farmacêutica e aumentando a demanda por internações”, pode-se afirmar que:","opcoes":["Tem valor adverbial e apresenta uma finalidade do novo modelo previdenciário adotado pelo Estado brasileiro.","Trata-se de um complemento do verbo “ter”, presente na proposição que a antecede.","Refere-se ao substantivo “impacto” e compõe uma estrutura de aposto, ou seja, amplia o sentido da palavra à qual está ligada.","Por apresentar verbo no gerúndio, trata-se de um exemplo de “gerundismo”, estrutura condenada pela norma culta da língua portuguesa."],"correta":2,"explicacao":"Gabarito: <strong>Refere-se ao substantivo “impacto” e compõe uma estrutura de aposto, ou seja, amplia o sentido da palavra à qual está ligada.</strong>.","banca":"HL","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":5344,"enunciado":"A respeito do uso dos artigos, há contextos em que eles denotam o sentido de posse à palavra a que acompanham. Analise as sentenças a seguir e os artigos destacados: I.Trazia os cabelos esbranquiçados há muitos anos, marca de tantas preocupações. II.Quando chegou à reunião, estava acompanhada da filha. III.Aqueles estudantes eram ativistas desde a faculdade. IV.Ana repeliu qualquer contato com ele. Firmou-se nos cotovelos enquanto pensava em tudo que ouvira. O artigo denota sentido de posse e","opcoes":["IV, apenas.","II e III, apenas.","I e III, apenas.","I, II, III, e IV.","I, II e IV, apenas."],"correta":4,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":5345,"enunciado":"A respeito do uso dos artigos, há contextos em que eles denotam o sentido de posse à palavra a que acompanham. Analise as sentenças a seguir e os artigos destacados: I.Trazia os cabelos esbranquiçados há muitos anos, marca de tantas preocupações. II.Quando chegou à reunião, estava acompanhada da filha. III.Aqueles estudantes eram ativistas desde a faculdade. IV.Ana repeliu qualquer contato com ele. Firmou-se nos cotovelos enquanto pensava em tudo que ouvira. O artigo denota sentido de posse em:","opcoes":["I, II, III, e IV.","IV, apenas.","I, II e IV, apenas.","II e III, apenas.","I e III, apenas."],"correta":2,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":5358,"enunciado":"Assinale a informação correta.","opcoes":["No trecho “Após um vídeo seu viralizar na internet, Yasmim Becker, de 17 anos, acabou no centro de uma onda de ataques virtuais” (1º parágrafo), identifica-se sentido denotativo em “viralizar” e sentido conotativo em “onda de ataques virtuais”.","Em “A mãe ficou muito nervosa e me acusou de ‘intolerância materna’ por eu ter recusado o caso” (2º parágrafo), a colocação do pronome átono após a forma verbal – acusou-me – mantém a correção do trecho.","As palavras “hiper-realista” e “recém-nascido” (1º parágrafo) trazem prefixos que sempre devem ser usados com hífen.","Em “um afeto cuidadosamente encenado para parecer real, que só se sustenta porque pode ser controlado e exibido”(4º parágrafo), o pronome “que” retoma o antecedente “real”.","No trecho “A fronteira entre fantasia e realidade está cada vez mais diluída” (3º parágrafo), com correção gramatical pode ser reescrito: “A fronteira entre fantasia e realidade estão cada vez mais diluídas”."],"correta":1,"explicacao":"Gabarito: <strong>Em “A mãe ficou muito nervosa e me acusou de ‘intolerância materna’ por eu ter recusado o caso” (2º parágrafo), a colocação do pronome átono após a forma verbal – acusou-me – mantém a correção do trecho.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":5382,"enunciado":"Quando nos lembramos de algo, nossos cérebros precisam aprender a memória, mantê-la segura e recuperá-la quando necessário. E o esquecimento ocorre em qualquer parte desse processo. O número de artigos simples presentes na frase é de:","opcoes":["Quatro.","Seis.","Três.","Dois.","Cinco."],"correta":3,"explicacao":"Gabarito: <strong>Dois.</strong>.","banca":"IASP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":5499,"enunciado":"Assinale a alternativa que indica o número correto de artigos presentes no trecho “a ciência ajudou-nos a compreender que a maior parte da massa de um átomo está no seu núcleo denso”. Considere todos os artigos presentes, inclusive os que apareçam combinados ou contraídos a outras palavras.","opcoes":["2.","3.","4.","5.","6."],"correta":3,"explicacao":"Gabarito: <strong>5.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":5501,"enunciado":"Considerando o emprego do acento indicador de crase em: “Ela relata ainda que foi graças à Língua Brasileira de Sinais (Libras) que conseguiu recuperar sua autoestima.” (3º§), pode-se afirmar que:","opcoes":["Trata-se de emprego facultativo de acordo com as normas gramaticais.","Trata-se de emprego obrigatório de acordo com a exigência da regência identificada seguida de emprego de artigo feminino.","Caso o termo “graças” fosse substituído por expressão equivalente semanticamente, a ocorrência de crase permaneceria sem alteração.","Tal ocorrência tem como finalidade enfatizar o complemento “Língua Brasileira” de acordo com o contexto apresentado; tratando-se, portanto, de uma escolha estilística."],"correta":1,"explicacao":"Gabarito: <strong>Trata-se de emprego obrigatório de acordo com a exigência da regência identificada seguida de emprego de artigo feminino.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal","crase"]},{"id":5632,"enunciado":"Os artigos definidos indicam uma realidade conhecida; a frase abaixo em que o artigo sublinhado acompanha uma realidade que é do conhecimento do leitor ou ouvinte, não por seu conhecimento de mundo, mas por ter sido mencionando antes, é:","opcoes":["Alguns indígenas aproximaram-se da canoa, mas a um pedido do comandante, os índios se afastaram;","O carro entrou no estacionamento do prédio com os faróis acesos;","O dicionário tinha as páginas amareladas por ser antigo;","Quando os piratas esconderam o imenso tesouro na ilha, não esperavam que a riqueza fosse atrair a atenção de outros navegantes;","Um baralho é um objeto interessante e as figuras nele inseridas mostram valor histórico."],"correta":0,"explicacao":"Gabarito: <strong>Alguns indígenas aproximaram-se da canoa, mas a um pedido do comandante, os índios se afastaram;</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":5636,"enunciado":"Na mesma medida, ele tem direito a um produto confiável, sendo dever moral inalienável do governo regulamentá-lo. (L.42-44) No período acima, há","opcoes":["um artigo.","dois artigos.","três artigos.","quatro artigos."],"correta":2,"explicacao":"Gabarito: <strong>três artigos.</strong>.","banca":"ACCESS","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":5643,"enunciado":"Assinale a frase em que o possessivo sublinhado não poderia ser adequadamente substituído pelo artigo indicado entre parênteses.","opcoes":["Se você não pode morder, não mostre seus (os) dentes.","Aquele que conduz um argumento por apelar para uma autoridade não está usando sua (a) inteligência, mas sim sua (a) memória.","Ninguém pode fazer você se sentir inferior sem seu (o) consentimento.","Controlar sua (a) raiva é bom, evitá-la é ainda melhor.","O coração que odeia, fabrica armas para seus (os) inimigos."],"correta":2,"explicacao":"Gabarito: <strong>Ninguém pode fazer você se sentir inferior sem seu (o) consentimento.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":5825,"enunciado":"Assinale a alternativa que indica o número de artigos definidos presentes no trecho a seguir: “Pedro tem seu pai, Henrique, assassinado em uma operação policial, tal fato o leva para o recolher-se e assim poder nascer para o novo momento que irá viver”.","opcoes":["0.","1.","2.","3.","4."],"correta":2,"explicacao":"Gabarito: <strong>2.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["colocacaoPronominal"]},{"id":5874,"enunciado":"Considerando o papel das classes de palavras na construção dos sentidos do texto, assinale a alternativa correta.","opcoes":["Um ano após se formar, Maria Teresa Corrêa começou a atuar na área de paisagismo.","O sentido original seria alterado com a substituição do trecho “quando começou a atuar na área de paisagismo. Especializou-se em arquitetura sustentável e arquitetura hospitalar.” (linhas 3 e 4) pela redação quando começou a atuar na área de paisagismo e especializou-se em arquitetura sustentável e arquitetura hospitalar.","A relação de sentido entre os períodos ficaria comprometida caso a redação Ela especializou-se em arquitetura sustentável e arquitetura hospitalar fosse empregada no lugar da oração “Especializou-se em arquitetura sustentável e arquitetura hospitalar.” (linhas 3 e 4).","A construção “Alguns de” (linhas 4 e 5) poderia ser substituída pelo artigo definido Os, pois a ideia original seria mantida.","Caso o autor resolvesse substituir a construção “vai ter” (linha 7) pela forma verbal terá, o texto deixaria de indicar uma ação considerada provável e passaria a expressar uma ação tida como certa."],"correta":1,"explicacao":"Gabarito: <strong>O sentido original seria alterado com a substituição do trecho “quando começou a atuar na área de paisagismo. Especializou-se em arquitetura sustentável e arquitetura hospitalar.” (linhas 3 e 4) pela redação quando começou a atuar na área de paisagismo e especializou-se em arquitetura sustentável e arquitetura hospitalar.</strong>.","banca":"IADES","ano":2021,"temas_relacionados":["colocacaoPronominal"]},{"id":6069,"enunciado":"Considerando-se o contexto e a estrutura linguística das expressões “estilo da vida” e “estilo de vida”, pode-se afirmar que:","opcoes":["O uso do artigo “a” em “estilo da vida” provoca uma ideia de generalização não observada em “estilo de vida”.","A alteração de sentido, substituindo o “de” por “da” integra a argumentação do autor acerca de conceitos linguísticos.","Entre as expressões “estilo da vida” e “estilo de vida” observa-se ocorrência de variação tanto morfológica quanto semântica.","Embora haja diferença na escolha vocabular para composição das duas expressões, pode-se afirmar que “estilo da vida” e “estilo de vida” são iguais quanto ao sentido."],"correta":2,"explicacao":"Gabarito: <strong>Entre as expressões “estilo da vida” e “estilo de vida” observa-se ocorrência de variação tanto morfológica quanto semântica.</strong>.","banca":"Instituto Consulplan","ano":2019,"temas_relacionados":["colocacaoPronominal"]},{"id":6107,"enunciado":"O uso de siglas em textos jornalísticos, informativos, acadêmicos e institucionais é bastante comum. Nesses casos, costuma-se explicitar o significado da sigla logo depois de sua primeira ocorrência. Considerando-se que isso foi feito de maneira adequada no texto, pode-se afirmar, sobre a sigla FMI, que: I. a palavra representada pelo F é um pronome. II. a palavra representada pelo M é um adjetivo. III. a palavra representada pelo I é um substantivo. IV. a expressão representada pelas letras FMI pode ser precedida de artigo, por se tratar de uma expressão com natureza substantiva. V. as palavras representadas pelas letras F e M deveriam, ambas, receber acento gráfico. Pode-se afirmar que:","opcoes":["apenas os itens I, II e V estão certos.","apenas os itens II e IV estão certos","apenas os itens III e IV estão certos.","apenas os itens I, III e IV estão certos.","apenas os itens II e V estão certos."],"correta":1,"explicacao":"Gabarito: <strong>apenas os itens II e IV estão certos</strong>.","banca":"Quadrix","ano":2019,"temas_relacionados":["colocacaoPronominal"]},{"id":6108,"enunciado":"Em “Todo discurso tem uma dimensão argumentativa”, observa-se que não foi usado o artigo definido “o”, em razão de o autor querer remeter-se à ideia de “qualquer discurso”. Assinale a opção em que a presença do artigo está INCORRETA:","opcoes":["Toda a mulher precisa reconhecer a capacidade que possui.","Toda a rua estava sem luz na noite de ontem","Todo o comercio estava fechado, em função dos rumores de arrastão.","Todo o mundo está preocupado com a poluição ambiental e com o aquecimento global.","Todo o bairro alarmou-se com a noticia veiculada nos jornais."],"correta":0,"explicacao":"Gabarito: <strong>Toda a mulher precisa reconhecer a capacidade que possui.</strong>.","banca":"IBADE","ano":2019,"temas_relacionados":["colocacaoPronominal"]},{"id":6151,"enunciado":"Enfarte: genética versus hábitos Riad Younes Desde o fim da década de 1930, a comunidade médica detectou com clareza maior concentração de casos de enfarte em algumas famílias, levando à teoria da predisposição genética para a ocorrência de doenças cardiovasculares. Parentes de pacientes que foram diagnosticados com enfarte ou derrame tinham maiores chances de eles mesmos apresentarem o quadro durante sua vida. Nas décadas subsequentes, vários estudos correlacionaram os hábitos dos pacientes como fatores de risco para doenças cardiovasculares. Sedentarismo, tabagismo, obesidade, entre outros, aumentam drasticamente as chances de enfarte. Depois, vários cientistas passaram a estudar a correlação dos riscos genéticos com os comportamentais, na tentativa de avaliar o peso que cada risco tinha na determinação do destino do coração dos indivíduos. Dúvidas como se filhos de pacientes com enfarte, com genética comprometida, teriam algum benefício em modificar seus hábitos pessoais e controlar os outros fatores de risco, ou seriam predestinados ao desastre independentemente de qualquer manobra. Pesquisadores da Universidade de Harvard, em Boston, liderados pelo doutor Amit Khera, concluíram recentemente um estudo extenso que envolveu mais de 55 mil pessoas em vários países e que avaliou a relação entre fatores genéticos e hábitos na determinação do risco de enfarte durante dez anos de seguimento. O estudo foi publicado esta semana na prestigiosa revista médica New England Journal of Medicine. Os especialistas analisaram o perfil genético e os hábitos pessoais dos voluntários e classificaram seus achados em categorias de baixo risco ou favorável, risco intermediário ou elevado, ou desfavorável. Dos fatores de risco relacionados ao estilo de vida, os indivíduos foram separados de acordo com a ausência de um ou mais dos seguintes fatores: tabagismo, obesidade, sedentarismo e dieta de risco. Quem não tinha três ou mais desses fatores era considerado de baixo risco para enfarte. Pacientes com três ou mais desses fatores foram classificados de risco elevado para doença cardiovascular. Os outros teriam risco intermediário. Os resultados do estudo deixaram evidente a relação direta entre aumento do número de fatores de risco ligados ao estilo de vida com a elevação do risco de enfarte em dez anos. Também ficou clara a correlação entre alterações genéticas detectadas no Projeto Genoma e as chances de enfarte. O mais interessante, nesse estudo, foi a total independência dos riscos genéticos daqueles relativos ao estilo de vida. Em outras palavras, mesmo as pessoas com alto risco genético e familiar podem beneficiar-se do controle eficiente da obesidade, do tabagismo, do sedentarismo e do consumo regular de dieta nociva. As pessoas consideradas de alto risco genético, que praticam hábitos saudáveis, tiveram suas chances de enfarte reduzidas pela metade, independentemente de medicamentos ou outras manobras químicas para controle do colesterol. O gráfico mostra o impacto de cada fator sobre cada grupo de risco genético. Os cientistas recomendam para todas as pessoas, principalmente para aquelas com carga genética desfavorável, a aderência intensiva a programas de controle dos hábitos deletérios. A orientação médica é fundamental para evitar enfartes e derrames de forma significativa. Vale a pena insistir. Disponível em: <www.cartacapital.com.br>. Acesso em: 14 dez. 2017. [Adaptado] Nas décadas subsequentes, vários estudos correlacionaram os hábitos dos pacientes como fatores de risco para doenças cardiovasculares. Sedentarismo, tabagismo, obesidade, entre outros, aumentam drasticamente as chances de enfarte. Com relação à quantidade de artigos no trecho, há","opcoes":["cinco.","três.","quatro.","dois."],"correta":2,"explicacao":"Gabarito: <strong>quatro.</strong>.","banca":"COMPERVE - UFRN","temas_relacionados":["colocacaoPronominal"]},{"id":6166,"enunciado":"Gestores públicos vangloriam-se quando o porcentual da população jovem que atinge a universidade cresce. Quanto mais, melhor. O movimento envolve também a pós-graduação, com a multiplicação do número de mestrados e doutorados. Supõe-se que mais mestres e doutores ajudem a gerar mais conhecimento, patentes e riquezas. A não ocorrência do acento grave no a que antecede a palavra “universidade” justifica-se","opcoes":["porque o a é apenas um artigo.","pelo gênero dessa palavra.","porque o a é apenas uma preposição.","pela flexão de número dessa palavra."],"correta":0,"explicacao":"Gabarito: <strong>porque o a é apenas um artigo.</strong>.","banca":"FUNCERN","ano":2018,"temas_relacionados":["colocacaoPronominal"]},{"id":6175,"enunciado":"“A primeira marca do príncipe soberano é o poder de dar lei a todos em geral, e a cada em particular. Mas isso não basta, e é necessário acrescentar: sem o consentimento de maior nem igual nem menor que ele.” “O soberano de uma República, seja ele uma assembleia ou um homem, não está absolutamente sujeito ..I.. leis civis. Pois tendo o poder de fazer ou desfazer as leis, pode, quando lhe apraz, livrar-se dessa sujeição revogando as leis que o incomodam e fazendo novas.” A primeira destas frases é do francês Jean Bodin (1576). A segunda é de Thomas Hobbes (1651). Ambos conferem ao Príncipe legítimo uma potência (potestas) tal que o exercício do seu poder acha-se, como se vê, liberto de toda norma ou regra. E, para medirmos a inovação assim introduzida, basta recorrermos ..II.. frase de um teólogo do século XII: “A diferença entre o príncipe e o tirano é que o príncipe obedece à Lei e governa ..III.. seu povo em conformidade com o Direito.” (Adaptado de: LEBRUN, Gérard. O que é poder. Tradução de Renato Janine Ribeiro e Silvia Lara. São Paulo: Brasiliense, 1995, p. 28-29.) Preenchem corretamente as lacunas I, II e III do texto, na ordem dada:","opcoes":["às – à – o","às – a – ao","as – à – ao","às – a – o","as – à – o"],"correta":0,"explicacao":"Gabarito: <strong>às – à – o</strong>.","banca":"FCC","ano":2018,"temas_relacionados":["colocacaoPronominal"]},{"id":6203,"enunciado":"Se este trecho “Diz-se que um homem, ao olhar o mundo do alto, enxergou a vida humana como um imenso campo iluminado” (l. 1 e 2) for reescrito CORRETAMENTE, colocando-se todas as palavras que podem ser flexionadas de acordo com as regras morfossintático-semânticas, tem-se qual período?","opcoes":["Dizem-se que uns homens, ao olhar o mundo do alto, enxergaram a vida humana como um imenso campo iluminado.","Diz-se que uns homens, ao olhar os mundos do alto, enxergaram as vidas humanas como um imenso campo iluminado.","Diz-se que uns homens, ao olharem o mundo do alto, enxergaram a vida humana como uns imensos campos iluminados.","Dizem-se que uns homens, ao olharem os mundos dos altos, enxergaram as vidas humanas como uns imensos campos iluminados."],"correta":2,"explicacao":"Gabarito: <strong>Diz-se que uns homens, ao olharem o mundo do alto, enxergaram a vida humana como uns imensos campos iluminados.</strong>.","banca":"Prefeitura de Fortaleza - CE","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6238,"enunciado":"O primeiro parágrafo cumpre o papel de introdução do texto, delimitando o tema da saúde da mulher sob o recorte da perspectiva reprodutiva. Considerando os termos empregados e seus respectivos efeitos de sentido, analise as partes que seguem: (1ª parte): O termo integralidade introduz a ideia de que a saúde da mulher deve ser enxergada como um todo. (2ª parte): A pa/avra prementes e empregada no sentido de algo secundário, indicando que as demandas hístóricas pela saúde da mulher eram irrelevantes no passado. (3ª parte): O uso da expressão obstáculos e lutas confere um tom político e social à íntrodução, índicando que os direltos reprodutivos das mulheres não foram concessões naturais, mas conquistas hrstórícas. Pode-se afirmar que:","opcoes":["Todas as partes estão corretas.","Apenas a 1ª e a 3ª partes estão corretas.","Apenas a 2ª e a 3ª partes estão corretas.","Apenas a 1ª e a 2ª partes estão corretas."],"correta":1,"explicacao":"Gabarito: <strong>Apenas a 1ª e a 3ª partes estão corretas.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6256,"enunciado":"Levando-se em consideração que (V) significa “Verdadeiro” e (F) significa “Falso”, a sequência correta das proposições é, respectivamente: (__)- “Vetadas” (linha 09) e “proibidas” são sinônimos; (__)- “Signatários” (linha 13) e “participantes” não se assemelham em sentido empregado no texto; (__)- “Incendiárias” (linha 29) são próprias do fogo; (__)- “Desumanos” (linha 24) refere-se aos seres não humanos, isto é, os animais.","opcoes":["F-F-F-V.","V-F-V-F.","F-V-V-F.","V-V-F-F."],"correta":1,"explicacao":"Gabarito: <strong>V-F-V-F.</strong>.","banca":"ABCP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6268,"enunciado":"Considerando a palavra “pautadas” do trecho a seguir, retirado do texto, analise as assertivas abaixo, assinalando V, se verdadeiras, ou F, se falsas. “consolidaram teorias sobre o desenvolvimento infantil pautadas na importância do brincar”. ( ) Trata-se de um adjetivo derivado de uma forma verbal no particípio. ( ) No contexto em que ocorre, um sinônimo possível para o vocábulo é “embasadas”. ( ) Quanto à acentuação tônica, trata-se de palavra oxítona. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["F – V – V.","F – F – V.","V – V – F.","V – F – F."],"correta":2,"explicacao":"Gabarito: <strong>V – V – F.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["colocacaoPronominal","oxitonas"]},{"id":6324,"enunciado":"Assinale a alternativa em que a palavra destacada atribui uma qualidade à palavra anterior.","opcoes":["... refugiava-se, de tardezinha, na máquina de costura nos fundos de sua casa. (1º parágrafo)","Porém, quando costurava, emudecia completamente. (1º parágrafo)","Nada se igualava à sinfonia da agulha cerzindo... (2º parágrafo)","Nada se igualava à sinfonia da agulha cerzindo, em linha reta. (2º parágrafo)","... repartia com ela o que há de mais precioso numa amizade ... (5º parágrafo)"],"correta":3,"explicacao":"Gabarito: <strong>Nada se igualava à sinfonia da agulha cerzindo, em linha reta. (2º parágrafo)</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6342,"enunciado":"Assinale a alternativa em que a palavra destacada atribui uma qualidade à palavra anterior.","opcoes":["... refugiava-se, de tardezinha, na máquina de costura nos fundos de sua casa. (1o parágrafo)","Porém, quando costurava, emudecia completamente. (1o parágrafo)","Nada se igualava à sinfonia da agulha cerzindo... (2o parágrafo)","Nada se igualava à sinfonia da agulha cerzindo, em linha reta. (2o parágrafo)","... repartia com ela o que há de mais precioso numa amizade ... (5o parágrafo)"],"correta":3,"explicacao":"Gabarito: <strong>Nada se igualava à sinfonia da agulha cerzindo, em linha reta. (2o parágrafo)</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6379,"enunciado":"A respeito das estruturas linguísticas e das relações morfossintáticas presentes nos Íragmentos do último parágrafo do texto, analise as partes que seguem. (1ª parte) No trecho incentivar a criação de ambientes de trabalho mais seguros e saudáveis, o vocábulo mais classifica-se moíologícamente cotno um advérbro de intensidade, atuando no texto como um modíficador de doís adjetívos (seguros e saudáveis). (2ª parte) No trecho As orientações também reforçam a importância da adoção de medidas preventivas, a forma verbal reforçam dpresenta um sujeíto composto, visto que o seu núcleo (As orientações) se encontra flexionado no plural. Pode-se afirmar que","opcoes":["Apenas a 1ª parte está correta.","Apenas a 2ª parte está correta.","Ambas as partes estão corretas.","Ambas as partes estão incorretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas a 1ª parte está correta.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6380,"enunciado":"No que se refere aos aspectos morfossintáticos e semânticos estabelecidos na tirinha, analise as partes que seguem: (1ª parte) A estruturd Lembre-se disso ao ouvir o canto das cigarras! expressa uma relação de temporalidade, de modo que sua perferta substítuíção por uma oração desenvolvida exige o emprego da conjunção conquanto. (2ª parte) O vocábulo poucos, no segundo quadrínho, classifica-se como um pronome indefínído adjetivo, cuja função síntática é determínar o advérbío de tempo dias. (3ª parte) O acento círcunflexo no termo têm, no segundo quadrinho, é de natureza diíerenctal, justificando-se pela concordâncía com o sujeito plura/. Pode-se afirmar que:","opcoes":["Apenas a 3ª parte está correta.","Apenas a 1ª e a 3ª partes estão corretas.","Apenas a 2ª e a 3ª partes estão corretas.","Todas as partes estão incorretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas a 3ª parte está correta.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6397,"enunciado":"\"As flores carvão tornaram-se vermelhas, amarelas, verdes cintilantes.\" A palavra destacada no trecho acima é sinônima de:","opcoes":["\"esbranquiçadas\".","\"barulhentas\".","\"cinzentas\".","\"brilhantes\".","\"apagadas\"."],"correta":3,"explicacao":"Gabarito: <strong>\"brilhantes\".</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6485,"enunciado":"Tratando-se de sinônimos, assinale a alternativa devida.","opcoes":["Ordem – anarquia.","Difícil – árduo.","Pesado – leve.","Presente – ausente."],"correta":1,"explicacao":"Gabarito: <strong>Difícil – árduo.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6508,"enunciado":"“Uma bruxa má lançou-me um encanto e transformei-me nesta rã asquerosa.” A palavra destacada na frase acima é sinônima de:","opcoes":["“falante”.","“cheirosa”.","“charmosa”.","“repugnante”.","“inteligente”."],"correta":3,"explicacao":"Gabarito: <strong>“repugnante”.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":6515,"enunciado":"No trecho seu sistema nervoso ficou obcecado em conseguir sobreviver (l.56-57), a palavra obcecado foi empregada para expressar a intensidade e a persistência da reação emocional internalizada. Considerando o sentido no contexto, assinale a alternativa que apresenta uma palavra que poderia substituí-la sem alterar significativamente o sentido da oração.","opcoes":["Determinado.","Acomodado.","Fascinado.","Motivado.","Fixado."],"correta":4,"explicacao":"Gabarito: <strong>Fixado.</strong>.","banca":"LEGALLE Concursos","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":6563,"enunciado":"O Brasil reivindica o aumento da faixa marítima sobre a qual exerce soberania. São mais 150 milhas náuticas (cerca de 277,8 quilômetros) para além da zona econômica exclusiva. Toda a faixa da plataforma continental brasileira é chamada, pela Marinha do Brasil, de Amazônia Azul. Analise o seguinte fragmento de texto sobre a Amazônia Azul. A Amazônia Azul é assim denominada por ser uma área extensa e possuir uma importância ______________ aos recursos naturais e à biodiversidade nela contidos. No mar, estão recursos pesqueiros e uma rica ________________. Em algumas áreas, em camadas ______________, encontra-se o petróleo, recurso mineral e principal fonte de energia usada no mundo. Nesta área, foi descoberta uma enorme reserva de ______________, que está no mar territorial brasileiro. As palavras que completam corretamente as lacunas do fragmento de texto apresentado, na ordem, são:","opcoes":["estratégica, fauna, submersas, petróleo.","estratégica, biodiversidade, submersas, sal marinho.","estratégica, biodiversidade, profundas, petróleo.","econômica, fauna, profundas, petróleo.","econômica, biodiversidade, submersas, sal marinho."],"correta":2,"explicacao":"Gabarito: <strong>estratégica, biodiversidade, profundas, petróleo.</strong>.","banca":"FADENOR","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":6615,"enunciado":"Quanto à colocação do pronome átono, é CORRETO afirmar que, em “aquecendo quem se aproxima” (l. 4), existe um exemplo de:","opcoes":["apossínclise.","mesóclise.","próclise.","ênclise."],"correta":2,"explicacao":"Gabarito: <strong>próclise.</strong>.","banca":"Prefeitura de Fortaleza - CE","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6617,"enunciado":"\"Cooperativa que produz açaí no Amapá fecha contrato de cinco anos com gigante chinesa.\" Considerando que o complemento do verbo 'produzir' no trecho seja substituído pelo pronome oblíquo correspondente, segundo as regras de colocação pronominal, analise as asserções: I.A forma pronominal correta, segundo a norma-padrão, é 'Cooperativa que o produz no Amapá', com o pronome oblíquo anteposto ao verbo. PORQUE II.O pronome relativo 'que', por ser elemento de natureza subordinativa que inicia oração adjetiva, constitui fator de próclise obrigatória, impedindo a ênclise ainda que, na ausência desse atrator, a ênclise fosse admissível por não haver outro elemento que impusesse a anteposição do pronome. A respeito dessas asserções, assinale a alternativa correta:","opcoes":["As duas asserções são falsas.","A asserção I é verdadeira, e a II é falsa.","As duas asserções são verdadeiras, e a II é uma justificativa correta da I.","A asserção I é falsa, e a II é verdadeira."],"correta":2,"explicacao":"Gabarito: <strong>As duas asserções são verdadeiras, e a II é uma justificativa correta da I.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6622,"enunciado":"No trecho “Ter um pouco de sinceridade interior, uma certa coragem moral e habituar-se a questionar-se nos ajuda a chegar perto deste sujeito esquisito que somos”, observam-se diferentes relações morfossintáticas entre os termos. Analise as assertivas a seguir. I. A sequência “Ter um pouco de sinceridade interior, uma certa coragem moral e habituar-se a questionar-se” exerce função de sujeito da forma verbal “ajuda”. II. A forma verbal “ajuda” está no singular porque concorda com um sujeito oracional composto por formas nominais de verbo, entendido como uma unidade de sentido. III. Em “deste sujeito esquisito”, o termo “esquisito” exerce função de adjunto adnominal, caracterizando o substantivo “sujeito”. IV. Em “que somos”, o termo “que” funciona como conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta. Está correto o que se afirma em:","opcoes":["I, II e III, apenas.","I, II e IV, apenas.","I, III e IV, apenas.","II, III e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III, apenas.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6623,"enunciado":"No trecho “Escrevo isso e me lembro de alguns versos”, a colocação do pronome oblíquo átono me, em relação ao verbo “lembro”, classifica-se como:","opcoes":["elipse.","ênclise.","próclise.","mesóclise."],"correta":2,"explicacao":"Gabarito: <strong>próclise.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6630,"enunciado":"Em dei-me conta da nossa infidelidade, ocorre que tipo de colocação pronominal?","opcoes":["Epêntese.","Mesóclise.","Próclise.","Ênclise."],"correta":3,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6632,"enunciado":"Sobre a colocação pronominal em locuções verbais, assinalar a alternativa INCORRETA.","opcoes":["Os amigos não nos tinham convidado para o jantar.","Os amigos ter-me-iam convidado para o jantar?","Os amigos teriam-me convidado para o jantar.","Os amigos não tinham nos convidado para o jantar."],"correta":2,"explicacao":"Gabarito: <strong>Os amigos teriam-me convidado para o jantar.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6633,"enunciado":"O trecho “Outras, como o papagaio de ombros dourados da Austrália, o fazem em cupinzeiros.”, pode ser reescrito sem prejuízo de sentido em:","opcoes":["Outras, como o papagaio de ombros dourados da Austrália, fazem-no em cupinzeiros.","Outras, como o papagaio de ombros dourados da Austrália, faze-o em cupinzeiros.","Outras, como o papagaio de ombros dourados da Austrália, fazem-lo em cupinzeiros.","Outras, como o papagaio de ombros dourados da Austrália, fazê-lo em cupinzeiros."],"correta":0,"explicacao":"Gabarito: <strong>Outras, como o papagaio de ombros dourados da Austrália, fazem-no em cupinzeiros.</strong>.","banca":"CONSULPAM","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6634,"enunciado":"Leia o trecho a seguir e responda. “Uma bruxa má lançou-me um encanto e transformeime nesta rã asquerosa”. Ocorre ênclise em qual dos termos da frase acima?","opcoes":["Bruxa.","Má.","Lançou-me.","Encanto.","Nesta."],"correta":2,"explicacao":"Gabarito: <strong>Lançou-me.</strong>.","banca":"Instituto IACP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6635,"enunciado":"Quero que vá tudo pro inferno Erasmo Carlos / Roberto Carlos De que vale o céu azul e o sol sempre a brilhar Se você não vem E eu estou a lhe esperar Só tenho você No meu pensamento E a sua ausência É todo o meu tormento [...] Disponível em: https://www.letras.mus.br/erasmo-carlos/775170/. Acesso em: 18 mai. 2026 No verso “Se você não vem e eu estou a lhe esperar”, quanto ao pronome oblíquo “lhe”, dadas as afirmativas, I. A colocação do pronome oblíquo antes do infinitivo (a lhe esperar) é aceitável, mas a ênclise ao infinitivo (a esperar-lhe) é mais comum. II. Embora o uso do pronome oblíquo “lhe” tenha sido empregado de forma coloquial e literária, sabe-se que o verbo “esperar” é transitivo direto (quem espera, espera alguém/algo). Assim, esse uso infringe a norma gramatical. III. Segundo a regra de colocação pronominal nas locuções verbais, o pronome oblíquo também poderá aparecer depois do verbo no infinitivo (ênclise), resultando em “estou a esperar-te” ou “estou a esperá-lo”. verifica-se que está/ão correta/s","opcoes":["II, apenas.","III, apenas.","I e II, apenas.","I e III, apenas.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDEPES","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6646,"enunciado":"Analise as assertivas sobre colocação pronominal e assinale a alternativa correta. I. Na frase “Nunca me avisaram sobre a mudança da reunião”, ocorre próclise devido à presença de palavra atrativa. II. Em “Entregarei-lhe os documentos amanhã”, a colocação pronominal está inadequada, pois o pronome deveria aparecer antes do verbo. III. Na frase “Convidaram-me para participar da palestra”, ocorre ênclise, colocação permitida quando o verbo inicia a oração.","opcoes":["Apenas as assertivas I e II estão corretas.","Apenas as assertivas II e III estão corretas.","Apenas as assertivas I e III estão corretas.","Apenas a assertivas II está correta."],"correta":2,"explicacao":"Gabarito: <strong>Apenas as assertivas I e III estão corretas.</strong>.","banca":"Instituto Indec","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6647,"enunciado":"O Coren encaminhou comunicado interno aos servidores contendo orientações sobre procedimentos administrativos e redação oficial. Durante a revisão textual do documento, observou-se a necessidade de adequação à norma-padrão relacionada à colocação pronominal. Julgue as sentenças abaixo como VERDADEIRAS (V) ou FALSAS (F) (__) Na frase “O servidor se manifestou favoravelmente ao parecer”, a colocação pronominal está adequada à normapadrão. (__) Na frase “Me encaminharam o relatório solicitado”, a colocação pronominal está inadequada à norma-padrão formal da língua portuguesa. (__) Na frase “O profissional não se recordava das orientações recebidas”, a colocação pronominal está adequada em razão da presença de palavra atrativa. A sequência correta é:","opcoes":["V – V – F","F – V – V","V – V – V","V – F – V","V – F – F"],"correta":2,"explicacao":"Gabarito: <strong>V – V – V</strong>.","banca":"IBADE","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6654,"enunciado":"O comitê existe como instância de consulta para fortalecer a atuação institucional da autarquia na preservação, promoção e difusão, fomento e capacitação sobre o Patrimônio de Matriz Africana.\" Considerando as regras de colocação pronominal da norma culta, caso o complemento verbal do verbo 'fortalecer', seja substituído pelo pronome oblíquo átono correspondente, assinale a alternativa que apresenta a justificativa adequada.","opcoes":["A próclise é a colocação obrigatória, uma vez que o verbo 'fortalecer' é um verbo que pertence à categoria de verbos que, pela norma culta do português brasileiro, exigem obrigatoriamente a colocação proclítica do pronome oblíquo átono, à semelhança do que ocorre com os verbos 'deixar' e 'fazer, igualmente causativos e igualmente sujeitos à próclise obrigatória.","A colocação pronominal adequada é a próclise, uma vez que a preposição 'para', por anteceder o verbo no infinitivo, funciona como elemento que favorece o posicionamento do pronome antes do verbo.","Tanto a próclise quanto a ênclise são igualmente aceitas pela norma culta brasileira após verbos no infinitivo, sendo a escolha entre as duas formas determinada exclusivamente por preferência estilística do falante, independentemente da presença de preposição antecedente.","A ênclise é a colocação pronominal obrigatória após verbos no infinitivo na norma culta do português brasileiro, com o pronome posicionado após o verbo e as devidas alterações morfológicas, sendo essa regra aplicável independentemente da presença de preposição antecedente."],"correta":2,"explicacao":"Gabarito: <strong>Tanto a próclise quanto a ênclise são igualmente aceitas pela norma culta brasileira após verbos no infinitivo, sendo a escolha entre as duas formas determinada exclusivamente por preferência estilística do falante, independentemente da presença de preposição antecedente.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6656,"enunciado":"No trecho Assim que dobra a esquina, diminui o passo até parar,encosta-se a uma parede. Por ela escorrega, senta-se na calçada, ainda úmida de chuva. Descansa na pedra o cachimbo, o pronome sublinhado refere-se a","opcoes":["chuva","pedra","esquina","parede","calçada"],"correta":3,"explicacao":"Gabarito: <strong>parede</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6657,"enunciado":"No trecho Assim que dobra a esquina, diminui o passo até parar, encosta-se a uma parede. Por ela escorrega, senta-se na calçada, ainda úmida de chuva. Descansa na pedra o cachimbo, o pronome sublinhado refere-se a","opcoes":["pedra.","esquina.","parede.","calçada.","chuva."],"correta":2,"explicacao":"Gabarito: <strong>parede.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6658,"enunciado":"A frase O rapaz de bigode pede aos outros se afastem e o deixem respirar está corretamente transposta para o discurso direto em:","opcoes":["O rapaz de bigode solicita que os outros: \"Se afastem e o deixem respirar\".","O rapaz de bigode pede aos outros: - Que se afastem, que deixem-no respirar.","O rapaz de bigode pede: - Os outros que se afastem e que lhe deixem respirar.","O rapaz de bigode pede aos outros: \"Afastem-se e deixem-no respirar\".","\"Afasta-o e deixe-o respirar\", pedem aos outros o rapaz de bigode."],"correta":3,"explicacao":"Gabarito: <strong>O rapaz de bigode pede aos outros: \"Afastem-se e deixem-no respirar\".</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6709,"enunciado":"No segundo parágrafo do texto, o pronome átono presente em ‘tê-las obtido’ (linha 9) refere-se a","opcoes":["‘publicações’ (linha 9).","‘citações’ (linha 9).","“aquelas palavras” (linha 8).","‘estudos científicos e notícias’ (linha 10).","“sete fontes” (linha 8)."],"correta":1,"explicacao":"Gabarito: <strong>‘citações’ (linha 9).</strong>.","banca":"Ibest","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6763,"enunciado":"A oração “A suplementação deve ser reservada a situações clínicas específicas...” encontra-se na","opcoes":["voz ativa.","voz passiva analítica.","voz reflexiva.","voz reflexiva recíproca.","voz ativa com sujeito indeterminado."],"correta":1,"explicacao":"Gabarito: <strong>voz passiva analítica.</strong>.","banca":"Instituto UniFil","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6773,"enunciado":"Evolução da atmosfera terrestre Estima-se que a atmosfera terrestre tenha surgido há cerca de quatro bilhões de anos. Essa camada de gás formou-se quando o planeta Terra, depois de um elevado aquecimento, resfriou-se. Vapor d'água, gases e outros elementos provenientes do interior da Terra emergiram. Parte desses gases e elementos dissiparam-se no espaço, contudo, alguns fixaram-se ao redor do planeta em decorrência da gravidade atuante. Na atmosfera primitiva, não havia presença de gases como o oxigênio. Os gases abundantes eram metano, gás carbônico, nitrogênio e, inclusive, gases compostos por substâncias venenosas. Apresentava altas temperaturas e tinha o Sol como a principal fonte de energia. Isso possibilitou que os primeiros organismos vivos surgissem: as bactérias de metabolismo anaeróbico (sem a presença de oxigênio). Por meio da formação dos oceanos, começaram a surgir plantas marinhas primitivas, que passaram a realizar o processo de fotossíntese, modificando, então, a composição de gases da atmosfera. As características atuais da atmosfera só foram adquiridas há cerca de 65 milhões de anos. A concentração de oxigênio na atmosfera levou aproximadamente 1,5 bilhão de anos para chegar aos 21%. Disponível em: https://mundoeducacao.uol.com.br/geografia/atmosfera-terrestre.htm. Acesso em: 14 mai. 2026. Acerca dos aspectos sintáticos, assinale a alternativa correta.","opcoes":["No trecho: “Parte desses gases e elementos dissiparam-se no espaço...”, a concordância verbal também ficaria correta se o verbo destacado fosse colocado no singular.","No período: “Apresentava altas temperaturas e tinha o Sol como a principal fonte de energia”, há uma inadequação gramatical no que se diz respeito à concordância verbal.","No trecho: “Estima-se que a atmosfera terrestre tenha surgido há cerca de quatro bilhões de anos”, o que tem função de sujeito e é, morfologicamente, pronome relativo.","Em: “... começaram a surgir plantas marinhas primitivas, que passaram a realizar o processo de fotossíntese...”, os termos em destaque exercem, respectivamente, as funções de objeto direto e sujeito simples.","Em: “... começaram a surgir plantas marinhas primitivas, que passaram a realizar o processo de fotossíntese...”, a palavra destacada apresenta-se sob essa forma flexional, porque se refere a dois núcleos nominais."],"correta":0,"explicacao":"Gabarito: <strong>No trecho: “Parte desses gases e elementos dissiparam-se no espaço...”, a concordância verbal também ficaria correta se o verbo destacado fosse colocado no singular.</strong>.","banca":"FUNDEPES","ano":2026,"temas_relacionados":["colocacaoPronominal","ortografia"]},{"id":6785,"enunciado":"Considerando o trecho retirado do texto “Até agora foram aplicadas mais de 300 mil doses num projeto-piloto em três municípios”, assinale a alternativa que apresenta a sua reescrita convertida na voz passiva sintética, mantendo-se o sentido original e a correção gramatical.","opcoes":["Até agora, aplicaram-se mais de 300 mil doses num projeto-piloto em três municípios.","Até agora, aplicaram mais de 300 mil doses num projeto-piloto em três municípios.","Até agora, aplicam-se mais de 300 mil doses num projeto-piloto em três municípios.","Até agora, aplica-se mais de 300 mil doses num projeto-piloto em três municípios."],"correta":0,"explicacao":"Gabarito: <strong>Até agora, aplicaram-se mais de 300 mil doses num projeto-piloto em três municípios.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6803,"enunciado":"No quarto parágrafo, encontra-se a seguinte construção na voz passiva analítica: A plataforma foi desenvolvida para facilitar a gestão. Considerando isso, assinale a alternativa que apresenta a transposição CORRETA desse trecho para a voz ativa, preservando o tempo verbal e as regras de concordância da norma-padrão.","opcoes":["Desenvolve-se a plataforma com o propósito de facilitar a gestão.","Têm desenvolvido a plataforma a fim de que facilite a gestão.","Desenvolver-se-ia a plataforma para que se facilitasse a gestão.","Estava sendo desenvolvida a plataforma visando a facilitar a gestão.","Desenvolveram a plataforma para facilitar a gestão."],"correta":4,"explicacao":"Gabarito: <strong>Desenvolveram a plataforma para facilitar a gestão.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6827,"enunciado":"Várias pessoas tropeçam no corpo de Dario, pisoteado dezessete vezes. O verbo flexionado no mesmo tempo, modo e voz que o da frase acima está sublinhado em:","opcoes":["(...) quem pagará a corrida?","A velhinha de cabeça grisalha gritou (...)","Dario levou duas horas para morrer.","Ele reclina-se mais um pouсо.","Abre-lhe o paletó, o colarinho, a gravata e a cinta."],"correta":4,"explicacao":"Gabarito: <strong>Abre-lhe o paletó, o colarinho, a gravata e a cinta.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6828,"enunciado":"políticas públicas que promovam o acesso equitativo à tecnologia em todas as regiões do país. O verbo empregado nos mesmos tempo e modo que o sublinhado na frase acima está em:","opcoes":["que alunos e professores explorem informações além dos limites físicos da sala de aula.","em áreas urbanas os recursos podem ser mais abundantes.","muitas escolas no Brasil enfrentam desafios significativos.","uma divisão digital que aprofunda as desigualdades educacionais.","seu papel na Educação tornou-se ainda mais crucial."],"correta":0,"explicacao":"Gabarito: <strong>que alunos e professores explorem informações além dos limites físicos da sala de aula.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6829,"enunciado":"A utilização de tecnologia na escola proporciona inúmeras vantagens. (2º parágrafo) Transpondo-se a frase acima para a voz passiva, a forma verbal resultante será:","opcoes":["seriam proporcionados.","é proporcionado.","tinham proporcionado.","são proporcionadas.","fora proporcionada."],"correta":3,"explicacao":"Gabarito: <strong>são proporcionadas.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6830,"enunciado":"Várias pessoas tropeçam no corpo de Dario, pisoteado dezessete vezes. O verbo flexionado no mesmo tempo, modo e voz que o da frase acima está sublinhado em:","opcoes":["A velhinha de cabeça grisalha gritou (...)","Dario levou duas horas para morrer.","Ele reclina-se mais um pouco.","Abre-lhe o paletó, o colarinho, a gravata e a cinta.","(...) quem pagará a corrida?"],"correta":3,"explicacao":"Gabarito: <strong>Abre-lhe o paletó, o colarinho, a gravata e a cinta.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6852,"enunciado":"Leia o texto a seguir: Departamento de Libras promove palestra ‘Trazendo a universidade para a vida e vida à universidade’ O Departamento de Libras da UFSC irá promover a palestra “Trazendo a universidade para a vida e vida à universidade” com o educador Fernando Leão (vice-presidente do Instituto Caminho do Meio). O evento será realizado na sala 305 do Espaço Físico Integrado (EFI), 3º andar, no dia 8 de outubro, das 8h30 às 11h30. Haverá interpretação para Libras. https://noticias.ufsc.br/tags/departamento-de-libras/ No texto apresentado, observa-se a predominância de verbos no futuro, como em “irá promover”, “será realizado” e “haverá”. Considerando o efeito de sentido produzido por essa escolha verbal, é correto afirmar que","opcoes":["o emprego de verbos no futuro reforça o caráter informativo e prospectivo do texto, anunciando ações previstas para momento posterior.","o uso predominante de verbos no futuro indica hipótese, sugerindo incerteza quanto à realização do evento anunciado.","a predominância de verbos no futuro contribui para a construção de um texto narrativo, relatando acontecimentos posteriores ao momento da enunciação.","o uso do futuro verbal aproxima o texto da linguagem injuntiva, orientando o leitor sobre ações que deverão ser realizadas.","a utilização do futuro verbal confere subjetividade ao texto, destacando expectativas pessoais do autor sobre o evento divulgado."],"correta":0,"explicacao":"Gabarito: <strong>o emprego de verbos no futuro reforça o caráter informativo e prospectivo do texto, anunciando ações previstas para momento posterior.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6857,"enunciado":"\"Os macacos vivem em contato próximo com as hordas de turistas que visitam o local.\" A frase acima apresenta concordância adequada. Com base nas regras de concordância verbal e nominal, complete as lacunas do texto a seguir, mantendo a correção gramatical. ___ anos até que os pesquisadores pudessem___ das limitações iniciais do estudo. O apoio que as instituições científicas___ aos projetos___ para o avanço das pesquisas, e os cientistas souberam manter o rigor metodológico que___ as conclusões obtidas. Assinale a alternativa que apresenta a sequência que preenche corretamente as lacunas acima.","opcoes":["Passou-se; livrarem-se; deu; foram decisivos; sustenta","Passou-se; livrar-se; deu; foi decisivo; sustentam","Passaram-se, livrar-se, deram, foi decisivo, sustenta","Passaram-se; livrar-se; deu; foram decisivos; sustenta"],"correta":2,"explicacao":"Gabarito: <strong>Passaram-se, livrar-se, deram, foi decisivo, sustenta</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6864,"enunciado":"Assinale a alternativa em que a forma verbal sublinhada NÃO se refere a um fato ocorrido no passado, conforme o texto.","opcoes":["“Outros asilos entraram no circuito”.","“As visitas começaram há quatro anos”.","“No início, limitavam-se a instituições”.","“Os acamados das enfermarias também recebem as visitas”."],"correta":3,"explicacao":"Gabarito: <strong>“Os acamados das enfermarias também recebem as visitas”.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6877,"enunciado":"Observe o trecho: “mentiras sobre vacinas, tratamentos e medidas sanitárias circularam livremente em aplicativos de mensagens e plataformas digitais”. Considerando os processos de transposição entre as vozes verbais, pode-se afirmar que a forma “circularam livremente”:","opcoes":["Admite conversão para a voz passiva sintética, preservando integralmente a organização sintática original do período.","Possibilita construção passiva analítica, desde que o sujeito da oração seja reinterpretado como agente verbal implícito.","Comporta transposição regular para a voz passiva, mantendo-se inalteradas as relações semânticas estabelecidas no texto.","Não admite transposição para a voz passiva analítica, pois o verbo empregado não apresenta objeto direto."],"correta":3,"explicacao":"Gabarito: <strong>Não admite transposição para a voz passiva analítica, pois o verbo empregado não apresenta objeto direto.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6879,"enunciado":"Analise o período abaixo: ............................... nos bastidores da gestão hospitalar que não ............................... desabastecimento de insumos básicos na rede pública se a administração central ............................... o orçamento emergencial e, ao mesmo tempo, os órgãos de controle ............................... de forma oportuna para mediar os impasses burocráticos junto aos fornecedores. Assinale a alternativa que completa corretamente as lacunas do texto.","opcoes":["Comenta-se • haverá • repuser • intervierem","Comenta-se • haverão • repor • intervierem","Comentam-se • haverá • repor • intervirem","Comentam-se • haverá • repuser • intervierem","Comentam-se • haverão • repuser • intervirem"],"correta":0,"explicacao":"Gabarito: <strong>Comenta-se • haverá • repuser • intervierem</strong>.","banca":"FEPESE","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6886,"enunciado":"Associe as colunas abaixo, preenchendo as lacunas das orações com a forma verbal correspondente da primeira coluna. Em seguida, assinale a alternativa que apresenta a sequência correta dessa associação. Formas Verbais (1) detém (2) mantêm (3) intervém (4) mantém Orações ( ) Piloto ________ na manobra do volante. ( ) Eles tentam fugir, mas não conseguem: uma estranha força os ________ imóveis. ( ) A FAB ________ a maior esquadrilha do Brasil. ( ) A sintaxe de regência ocupa-se das relações de dependência que as palavras ________ na frase.","opcoes":["(2); (1); (4); (3).","(4); (2); (3); (1).","(1); (3); (2); (4).","(3); (4); (1); (2)."],"correta":3,"explicacao":"Gabarito: <strong>(3); (4); (1); (2).</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6898,"enunciado":"Associe as colunas abaixo, preenchendo as lacunas das orações com a forma verbal correspondente da primeira coluna. Em seguida, assinale a alternativa que apresenta a sequência correta dessa associação. Formas Verbais (1) detém (2) mantêm (3) intervém (4) mantém Orações (_) Piloto ________ na manobra do volante. (_) Eles tentam fugir, mas não conseguem: uma estranha força os ________ imóveis. (_) A FAB ________ a maior esquadrilha do Brasil. (_) A sintaxe de regência ocupa-se das relações de dependência que as palavras ________ na frase.","opcoes":["(2); (1); (4); (3).","(4); (2); (3); (1).","(1); (3); (2); (4).","(3); (4); (1); (2)."],"correta":3,"explicacao":"Gabarito: <strong>(3); (4); (1); (2).</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6902,"enunciado":"Marque a alternativa em que o verbo destacado indica uma ação no futuro.","opcoes":["Eu sempre quis ser seu acompanhante.","Eu jamais faltei às aulas de Matemática.","Digo agora mesmo que estou a seu favor.","Estarei sempre aqui quando você precisar.","Fale agora ou cale-se para sempre."],"correta":3,"explicacao":"Gabarito: <strong>Estarei sempre aqui quando você precisar.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6906,"enunciado":"Todas as formas verbais estão corretamente flexionadas na frase:","opcoes":["A menos que sobrevenhe um sério imprevisto, toda manhã escrevo uma crônica.","Deteram-se eles numa rigorosa análise do texto e suprimiram os equívocos.","Se o inseto não tivesse intervido eu não poderia ter escrito esta crônica.","O editor não quererá acolher esta crônica se eu não revir os deslizes todos.","Um simples inseto não constitue, como se viu, um obstáculo que não se transponha."],"correta":3,"explicacao":"Gabarito: <strong>O editor não quererá acolher esta crônica se eu não revir os deslizes todos.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6907,"enunciado":"A forma verbal no plural é rigorosamente justificável em:","opcoes":["Costumam derivar das declarações de amor exagerados o efeito colateral da intensificação real de uma paixão.","Atribuem-se à idealização da literatura os hábitos persistentes de uma declaração de amor românticа.","A progressão das coceiras em picadas de mosquitos devem-se à nosso própria insistência em coçar.","Não nos cabem tratar nossos sentimentos como picadas de mosquitos que tanto estimamos coçarem.","Não satisfazem as condições básicas de um amor verdadeiro o talento natural de declará-lo com bom estilo."],"correta":1,"explicacao":"Gabarito: <strong>Atribuem-se à idealização da literatura os hábitos persistentes de uma declaração de amor românticа.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6913,"enunciado":"Considerando o trecho a seguir, retirado do texto, assinale a alternativa que indica a correta conjugação de “precisam” caso substituíssemos “Os adultos” por “Um adulto”, mantendo-se o mesmo tempo verbal. “Os adultos precisam dormir em média oito horas por noite”.","opcoes":["Precisa.","Preciso.","Precisava.","Precisarão."],"correta":0,"explicacao":"Gabarito: <strong>Precisa.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6916,"enunciado":"Considere as passagens: • Na história das civilizações, quando um sistema entra em colapso, a dor imediata frequentemente atua como o mais poderoso catalisador para a inovação. (1º parágrafo) • Em um mundo governado pela racionalidade e pelo instinto de sobrevivência, o bloqueio de Ormuz soaria como o alarme definitivo. Seria o momento em que governos e mercados decidiriam direcionar a fortuna gasta para proteger e subsidiar rotas petroleiras rumo à transição energética sustentável e definitiva. (3º parágrafo) Comparando-se os verbos destacados no 1º parágrafo com os destacados no 3º parágrafo, conclui-se corretamente que eles se diferenciam porque expressam a informação, correta e respectivamente, com sentido de:","opcoes":["certeza e futuro próximo.","conjectura e certeza.","futuro próximo e passado.","certeza e conjectura.","futuro próximo e conjectura."],"correta":3,"explicacao":"Gabarito: <strong>certeza e conjectura.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":6964,"enunciado":"Analise as assertivas que seguem acerca das relações semânticas, morfológicas e sintáticas, apresentadas no Texto II. I- No fragmento “o presunto processado agora é oficialmente classificado como carcinógeno do grupo 1”, o termo “agora” indica uma circunstância de tempo e foi empregado para informar que houve uma mudança recente na classificação do alimento mencionado. II- No fragmento “Estima-se que, a cada duas fatias que você come, você aumenta o risco de câncer colorretal em 18%”, o termo “você” foi empregado como um referente genérico, empregado em sentido universal e não para indicar um interlocutor em particular. III- No fragmento “Estima-se que, a cada duas fatias que você come, você aumenta o risco de câncer colorretal em 18%”, o elemento “se” funciona como índice de indeterminação do sujeito, assim como ocorre em “alugam-se casas”. IV- No fragmento “Estima-se que, a cada duas fatias que você come, você aumenta o risco de câncer colorretal em 18%”, o elemento “se” funciona como conjunção integrante. É CORRETO o que se afirma em:","opcoes":["I, apenas.","II e III, apenas.","I e II, apenas.","IV, apenas.","I, II, III e IV."],"correta":2,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7105,"enunciado":"Assinale a alternativa que preenche, corretamente e na ordem em que se apresentam, as lacunas da frase a seguir, de acordo com a norma-padrão da língua portuguesa. Fomos convidados ______________ ____ 20 horas na porta do restaurante, _________choveu muito e não conseguimos chegar a tempo.","opcoes":["a encontrar-lhes ... as ... logo","de encontrá-los ... às ... portanto","a encontrá-los ... às ... mas","em encontrar-lhes ... às ... entretanto"],"correta":2,"explicacao":"Gabarito: <strong>a encontrá-los ... às ... mas</strong>.","banca":"Diretoria de Ensino de Andradina - SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7120,"enunciado":"Analise as afirmativas a seguir, tendo em vista o uso da palavra “sem” no texto 02. I- Constitui-se um importante elemento de coesão. II- Classifica-se gramaticalmente como uma preposição. III- Apresenta-se, no contexto, com sentido de “ausência”. IV- Apresenta-se, no contexto, vazia quanto à significação. V- Classifica-se, gramaticalmente, como uma interjeição. Estão CORRETAS as afirmativas","opcoes":["I, II e III, apenas.","I, II, e V, apenas.","I e III, apenas.","I, IV e V, apenas.","III e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III, apenas.</strong>.","banca":"FADENOR","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7158,"enunciado":"Assinale a opção que indica a frase em que a preposição A – sozinha ou combinada - tem valor semântico diferente dos demais.","opcoes":["Também os deputados foram tratar-se ao Hospital dos Militares.","Os feridos foram encaminhados ao atendimento no Hospital Miguel Couto.","Minha prima surgiu no fundo do corredor e veio sentar-se comigo à mesa.","A moça estava à janela quando o ladrão lhe roubou o celular das mãos.","Todos os jovens voltaram a casa tarde da noite."],"correta":1,"explicacao":"Gabarito: <strong>Os feridos foram encaminhados ao atendimento no Hospital Miguel Couto.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7195,"enunciado":"Na seguinte passagem do texto “Entretanto, o encantamento diante de um livro não é apenas para aqueles que se dedicam a também fazê-los.”, a palavra “entretanto” insere uma ideia de","opcoes":["adversidade.","alternância.","conclusão.","explicação.","proporção."],"correta":0,"explicacao":"Gabarito: <strong>adversidade.</strong>.","banca":"FADENOR","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7232,"enunciado":"No trecho \"Apesar das limitações, sua dedicação e o atendimento emocionalmente afetuoso deixaram-me sensibilizado\", a expressão \"Apesar das limitações\" exerce a função de estabelecer uma relação de qual ideia?","opcoes":["Causa.","Consequência.","Concessão.","Condição."],"correta":2,"explicacao":"Gabarito: <strong>Concessão.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7235,"enunciado":"Considerando o contexto do trecho \"E à medida que ficamos mais velhos, reclamar é mais fácil que sorrir.\", qual das alternativas apresenta uma frase com o mesmo sentido?","opcoes":["Com o passar dos anos, é mais difícil se queixar do que sorrir.","Com o tempo, torna-se mais desafiador reclamar do que sorrir.","Quando envelhecemos, é mais fácil sorrir do que ficar insatisfeitos.","À medida que envelhecemos, é mais simples nos queixarmos do que expressarmos alegria."],"correta":3,"explicacao":"Gabarito: <strong>À medida que envelhecemos, é mais simples nos queixarmos do que expressarmos alegria.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7237,"enunciado":"No trecho do terceiro parágrafo — Fabrício percebeu a lacuna quando Eduardo, seu amigo que morava em São Paulo, lembrou-lhe de que em 15 de agosto completariam 20 anos de amizade. Combinaram de jantar nesse dia para comemorar as bodas de porcelana da amizade. —, as palavras destacadas estabelecem, respectivamente, sentido de","opcoes":["conclusão e assunto.","explicação e causa.","tempo e finalidade.","condição e modo.","causa e oposição."],"correta":2,"explicacao":"Gabarito: <strong>tempo e finalidade.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7248,"enunciado":"Assinale o enunciado que apresenta relação semântica de causa e consequência.","opcoes":["“Pode-se dizer que essa fórmula de saudação foi bem-aceita e acabou virando regra de [...]” (9º§)","“Em trabalhos acadêmicos [...] passou a ser ‘obrigatório’ o uso da linguagem dita ‘inclusiva’ [...]” (6º§)","“É sempre interessante observar como a língua se comporta diante das tensões que nela se refletem.” (1º§)","“Ninguém nunca disse os ‘homens aqui presentes’ com o intuito de englobar ‘homens e mulheres’ [...]” (7º§)","“O tempo dirá se a sociedade mudou no rastro das palavras ou se o movimento é exatamente o inverso.” (10º§)"],"correta":0,"explicacao":"Gabarito: <strong>“Pode-se dizer que essa fórmula de saudação foi bem-aceita e acabou virando regra de [...]” (9º§)</strong>.","banca":"Instituto Consulplan","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7250,"enunciado":"É adequado o emprego do elemento sublinhado na frase:","opcoes":["Arbitrariedade e autoritarismo são condições de cujas nenhum cidadão pode se submeter.","As esferas de atuação dos Poderes são instâncias que sua autonomia deve preservar-se.","É fundamental o papel político aonde o desempenham os três Poderes constituídos.","A expressão \"separação dos poderes\" confundirá quem dela se acerque apressadamente.","A separação dos poderes é uma exigência política para a qual o Estado não deve abrir mão."],"correta":3,"explicacao":"Gabarito: <strong>A expressão \"separação dos poderes\" confundirá quem dela se acerque apressadamente.</strong>.","banca":"FCC","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7276,"enunciado":"Analise a relação de sentido estabelecida pelas conjunções em negrito e o termo entre parênteses. Destaque a relação incorreta.","opcoes":["Como não tinha aptidão para a música, vendeu seu violão. (conformidade)","Por mais que esteja atrasado, esperarei por você. (concessão)","Esvaziou suas economias, porque estava endividado (explicação)","Seus olhos fecham-se sempre que está com medo. (tempo)","Caso não termine o trabalho, avise-me. (condição)"],"correta":0,"explicacao":"Gabarito: <strong>Como não tinha aptidão para a música, vendeu seu violão. (conformidade)</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7314,"enunciado":"Mantendo-se o sentido do trecho – A dificuldade é que, como isso não vai acontecer da noite para o dia, devemos esperar uma transição complicada. (3° parágrafo) –, a palavra destacada pode ser corretamente substituída por:","opcoes":["ainda que.","caso.","conforme.","uma vez que.","à proporção que."],"correta":3,"explicacao":"Gabarito: <strong>uma vez que.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7354,"enunciado":"Assinale a alternativa cuja palavra destacada está sendo empregada corretamente.","opcoes":["Aonde você está morando atualmente?","Quero saber onde está o xis da questão.","Diga-me aonde está a minha caneta.","Eu paro sempre aonde fico cansado.","Onde você for, eu vou com você."],"correta":1,"explicacao":"Gabarito: <strong>Quero saber onde está o xis da questão.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7371,"enunciado":"\"A grande vantagem desta tecnologia é poder usá-la logo ali, no momento em que o fungo ainda está fresco\", contextualiza o micologista Vasco Fachada, do Kew Gardens, que não esteve envolvido diretamente com a pesquisa do Purpureocillium.\" Considerando a função sintática desempenhada pelos termos no texto, marque V, para as afirmativas verdadeiras, ou F, para as falsas: (__) A forma pronominal 'la' em 'usá-la' exerce a função de objeto direto, substituindo o termo 'vantagem'. (__) O vocábulo 'fresco' exerce a função de predicativo do objeto, indicando que o fungo se encontrava em estado recente de conservação, ainda biologicamente ativo, condição que favorece a análise genética. (__) A forma verbal 'contextualiza' não apresenta sujeito expresso no texto e corresponde ao verbo \"contextualizar\" flexionado no presente do indicativo. (__) O vocábulo 'ainda' exerce função de adjunto adverbial, exprimindo continuidade no tempo, indicando a permanência temporária do estado de frescor do fungo. A sequência que preenche corretamente os itens acima, de cima para baixo, é:","opcoes":["V, F, V, F.","F, F, F, V.","V, V, V, F.","F, V, F, V."],"correta":1,"explicacao":"Gabarito: <strong>F, F, F, V.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7375,"enunciado":"Analise as sentenças e registre, V, para verdadeiras, e F, para falsas: (__)No título, o pronome demonstrativo \"este\" não apresenta referente explícito. Porém, pelo contexto do próprio título, é possível compreender que ele se refere à relação entre o quanto de esgoto é tratado na atualidade e as metas de saneamento. Ou seja, cabe ao(à) leitor(a) ler, interpretar e estabelecer relações para compreender que há uma lentidão no que se refere a viabilizar o tratamento de esgoto em Santa Catarina. (__)No título e no subtítulo, palavras e expressões, como: apenas, só, pouco mais de, distante, têm apenas a função de qualificar outras palavras, sem efeito no sentido que se pretende construir. Os dados estatísticos e informacionais são suficientes para compreender a distância que existe entre o quanto se trata de esgoto e a meta de universalização. (__)Entre o título, o subtítulo e o primeiro parágrafo, observa-se uma gradação de informações, ou seja, elas vão sendo acrescentadas, ampliadas. Para evitar repetições desnecessárias, observa-se que, enquanto no título há \"33,9%\", no subtítulo há \"pouco mais de um terço\". São expressões sinônimas e cabe a quem lê mobilizar seus conhecimentos para interpretá-las e compreender que se referem ao mesmo dado. Assinale a alternativa que apresenta a sequência correta:","opcoes":["F − V − F.","F − F − V.","V − F − V.","V − V − V.","V − F − F."],"correta":2,"explicacao":"Gabarito: <strong>V − F − V.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7384,"enunciado":"Analise as sentenças e registre, V, para verdadeiras, e F, para falsas: (__)No título, o pronome demonstrativo \"este\" não apresenta referente explícito. Porém, pelo contexto do próprio título, é possível compreender que ele se refere à relação entre o quanto de esgoto é tratado na atualidade e as metas de saneamento. Ou seja, cabe ao(à) leitor(a) ler, interpretar e estabelecer relações para compreender que há uma lentidão no que se refere a viabilizar o tratamento de esgoto em Santa Catarina. (__)No título e no subtítulo, palavras e expressões, como: apenas, só, pouco mais de, distante , têm apenas a função de qualificar outras palavras, sem efeito no sentido que se pretende construir. Os dados estatísticos e informacionais são suficientes para compreender a distância que existe entre o quanto se trata de esgoto e a meta de universalização. (__)Entre o título, o subtítulo e o primeiro parágrafo, observa-se uma gradação de informações, ou seja, elas vão sendo acrescentadas, ampliadas. Para evitar repetições desnecessárias, observa-se que, enquanto no título há \"33,9%\", no subtítulo há \"pouco mais de um terço\". São expressões sinônimas e cabe a quem lê mobilizar seus conhecimentos para interpretá-las e compreender que se referem ao mesmo dado. Assinale a alternativa que apresenta a sequência correta:","opcoes":["V − F − F.","F − F − V.","V − F − V.","F − V − F.","V − V − V."],"correta":2,"explicacao":"Gabarito: <strong>V − F − V.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7395,"enunciado":"Analise as sentenças e registre, V, para verdadeiras, e F, para falsas: (__) No título, o pronome demonstrativo \"este\" não apresenta referente explícito. Porém, pelo contexto do próprio título, é possível compreender que ele se refere à relação entre o quanto de esgoto é tratado na atualidade e as metas de saneamento. Ou seja, cabe ao(à) leitor(a) ler, interpretar e estabelecer relações para compreender que há uma lentidão no que se refere a viabilizar o tratamento de esgoto em Santa Catarina. (__) No título e no subtítulo, palavras e expressões, como: apenas, só, pouco mais de, distante, têm apenas a função de qualificar outras palavras, sem efeito no sentido que se pretende construir. Os dados estatísticos e informacionais são suficientes para compreender a distância que existe entre o quanto se trata de esgoto e a meta de universalização. (__) Entre o título, o subtítulo e o primeiro parágrafo, observa-se uma gradação de informações, ou seja, elas vão sendo acrescentadas, ampliadas. Para evitar repetições desnecessárias, observa-se que, enquanto no título há \"33,9%\", no subtítulo há \"pouco mais de um terço\". São expressões sinônimas e cabe a quem lê mobilizar seus conhecimentos para interpretá-las e compreender que se referem ao mesmo dado. Assinale a alternativa que apresenta a sequência correta:","opcoes":["F − V − F.","F − F − V.","V − F − F.","V − F − V.","V − V − V."],"correta":3,"explicacao":"Gabarito: <strong>V − F − V.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7396,"enunciado":"No trecho “Ela prefere a disciplina modesta, sem plateia, sem anúncio e sem heroísmo”, o termo “Ela” refere-se a","opcoes":["vassoura.","saúde.","visita.","ironia.","larva."],"correta":1,"explicacao":"Gabarito: <strong>saúde.</strong>.","banca":"Fundação CETREDE","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7397,"enunciado":"Observe os excertos que seguem. I. “É tão vasto o horizonte aberto por ‘O Agente Secreto’ que mais justo será fatiá-lo [...]”. II. “Ele começa em 1977, quando ‘Tubarão’, o longa de Steven Spielberg, estava na cabeça de todo mundo.”. III. “Nesse momento, Marcelo volta ao Recife para viver, bem discretamente, numa comunidade de ‘refugiados’ e para encontrar um documento de identificação que, de certa forma, pode comprovar para ele a existência de sua mãe.”. Nesses excertos, os termos destacados referem-se, respectivamente, a:","opcoes":["“horizonte aberto” / “em 1977” / “um documento de identificação” / “Marcelo” / “Marcelo”.","“O Agente Secreto” / “em 1977” / “numa comunidade de refugiados” / “um documento de identificação” / “mãe”.","“O Agente Secreto” / “Tubarão” / “um documento de identificação” / “Marcelo” / “mãe”.","“horizonte aberto” / “em 1977” / “identificação” / “Marcelo” / “existência”.","“horizonte aberto” / “Tubarão” / “numa comunidade de refugiados” / “documento” / “Marcelo."],"correta":0,"explicacao":"Gabarito: <strong>“horizonte aberto” / “em 1977” / “um documento de identificação” / “Marcelo” / “Marcelo”.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7413,"enunciado":"Em determinados contextos, o emprego do pronome oblíquo “lhe”, assim como de certos vocábulos e construções, é utilizado com a finalidade de conferir maior formalidade ao enunciado. Contudo, nem sempre essa tentativa de formalização se realiza em conformidade com a norma-padrão, podendo acarretar desvio gramatical. Nesse sentido, assinale a alternativa em que o uso do pronome “lhe” ocorre de forma inadequada.","opcoes":["Deus criou o homem e infundiu-lhe um espírito imortal.","Só quero lembrar-lhe algo crucial.","Não lhe vejo há muito tempo.","Agradeceste-lhe o elogio."],"correta":2,"explicacao":"Gabarito: <strong>Não lhe vejo há muito tempo.</strong>.","banca":"Grupo TALENT","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7433,"enunciado":"Assinale a alternativa em que a colocação pronominal está INCORRETA:","opcoes":["Amanhã, dar-lhe-ei o presente que comprei com muito sacrifício.","Em tratando-se de romances, meu favorito é A Metamorfose, de Kafka.","Contei essa anedota apenas para alegrá-lo.","Amanhã lhe darei o presente que comprei com muito sacrifício.","Contei essa anedota apenas para o alegrar."],"correta":1,"explicacao":"Gabarito: <strong>Em tratando-se de romances, meu favorito é A Metamorfose, de Kafka.</strong>.","banca":"COMVEST UFAM","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7442,"enunciado":"Em relação às regras de colocação pronominal na norma padrão da língua portuguesa, considera-se a aplicação dos pronomes oblíquos átonos em diferentes contextos sintáticos. Nesse sentido, é correto afirmar que:","opcoes":["A ênclise ocorre obrigatoriamente em orações subordinadas com palavra atrativa.","A próclise é obrigatória quando há palavra de valor negativo antes do verbo.","A mesóclise pode ocorrer em qualquer tempo verbal composto do indicativo.","A próclise é facultativa em início de oração independente do contexto sintático."],"correta":1,"explicacao":"Gabarito: <strong>A próclise é obrigatória quando há palavra de valor negativo antes do verbo.</strong>.","banca":"IBEPP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7448,"enunciado":"No trecho Instalo-me dentro da noite banhado pela gratidão, a posição do pronome oblíquo átono em relação à forma verbal exemplifica um caso de:","opcoes":["Anástrofe.","Mesóclise.","Ênclise.","Próclise."],"correta":2,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7449,"enunciado":"Algumas técnicas incluem observar a origem da ansiedade com curiosidade e \"direcioná-la\" para objetivos construtivos. Assinale a alternativa CORRETA quanto à colocação do pronome oblíquo átono no termo destacado.","opcoes":["Trata-se de ênclise, pois o pronome está posposto ao verbo no infinitivo, com adaptação da forma verbal.","Trata-se de próclise, pois o pronome está antes do verbo, atendendo à regra geral de atração obrigatória.","Trata-se de anáclise, pois o pronome se liga ao verbo por adaptação fonológica em posição intermediária.","Trata-se de mesóclise, pois o pronome está inserido no interior da forma verbal, característica típica de tempos do futuro."],"correta":0,"explicacao":"Gabarito: <strong>Trata-se de ênclise, pois o pronome está posposto ao verbo no infinitivo, com adaptação da forma verbal.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7456,"enunciado":"Tratando-se de colocação pronominal, leia os itens e assinale a alternativa correta. I- Os pronomes átonos o, a, os, as, lhe, lhes, me, te, se, nos, vos apoiam-se na tonicidade de outra palavra. No tocante ao verbo, eles podem ser enclíticos, proclíticos e mesoclíticos. II- Em geral, ocorre a ênclise, quando o verbo está no início da frase, no imperativo afirmativo, no gerúndio, no infinitivo impessoal. III- Ocorre a próclise quando, antes do verbo, vier uma palavra que atraia o pronome, como: palavras de sentido negativo, pronome indefinido, advérbio, conjunção subordinativa, pronome relativo, palavras interrogativas ou exclamativas. IV- Há mesóclise com o verbo no futuro do presente ou no futuro do pretérito. Quando houver palavra que atraia o pronome antes do verbo, deverá ser dada preferência à próclise.","opcoes":["Apenas os itens I, II e III são verdadeiros.","Todos os itens são verdadeiros.","Apenas os itens I e II são verdadeiros.","Apenas os itens I e IV são verdadeiros."],"correta":1,"explicacao":"Gabarito: <strong>Todos os itens são verdadeiros.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["colocacaoPronominal","tonicidade"]},{"id":7464,"enunciado":"Atualmente, em evidência por questões geopolíticas envolvendo \"conflitos\" no Oriente Médio, o estreito de Ormuz já integrou \"o conjunto de territórios conquistados por Portugal\" durante o período das Grandes Navegações. Assinale a alternativa CORRETA quanto à substituição por pronomes oblíquos átonos, mantendo a correção gramatical.","opcoes":["Atualmente, em evidência por questões geopolíticas envolvendo-os no Oriente Médio, o estreito de Ormuz já o integrou durante o período das Grandes Navegações.","Atualmente, em evidência por questões geopolíticas envolvendo-os no Oriente Médio, o estreito de Ormuz já integrou-o durante o período das Grandes Navegações.","Atualmente, em evidência por questões geopolíticas envolvendo-lhes no Oriente Médio, o estreito de Ormuz já lhe integrou durante o período das Grandes Navegações.","Atualmente, em evidência por questões geopolíticas envolvendo-lhe no Oriente Médio, o estreito de Ormuz o já integrou durante o período das Grandes Navegações."],"correta":0,"explicacao":"Gabarito: <strong>Atualmente, em evidência por questões geopolíticas envolvendo-os no Oriente Médio, o estreito de Ormuz já o integrou durante o período das Grandes Navegações.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7465,"enunciado":"O pronome oblíquo átono pode ser colocado antes, depois ou no meio do verbo. Assim, de acordo com a sua posição, marque a alternativa, onde temos uma próclise.","opcoes":["Manda-me notícias, quando tiveres saudade.","Escrever-me-ás sempre?","Dar-te-ei todo o meu amor.","Não te esqueças, que a vida é curta."],"correta":3,"explicacao":"Gabarito: <strong>Não te esqueças, que a vida é curta.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7468,"enunciado":"No trecho em itálico no fim do terceiro parágrafo, os pronomes demonstrativos destacados cumprem papel coesivo anafórico na progressão do texto. Avaliando esse uso, é CORRETO afirmar que","opcoes":["aquelas retoma o termo antecedente imediatamente mais próximo (\"homens\"), e esses retoma o termo mais distante (\"mulheres\"), indicando inversão de papéis com finalidade estilística.","aquelas refere-se a \"mulheres\" (elemento mais distante), porém o emprego de esses deve ser substituído por \"estes\" para referir-se adequadamente ao termo mais próximo (\"homens\").","A escolha dos pronomes demonstra uma relação sintática de equipolência, em que tanto aquelas quanto esses referenciam, de modo neutro e não marcado, o termo composto anterior \"funções e posturas\".","O uso de esses justifica-se por retomar o núcleo principal do período anterior, enquanto aquelas atua na substituição do complemento nominal."],"correta":1,"explicacao":"Gabarito: <strong>aquelas refere-se a \"mulheres\" (elemento mais distante), porém o emprego de esses deve ser substituído por \"estes\" para referir-se adequadamente ao termo mais próximo (\"homens\").</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7472,"enunciado":"A comida do local nem sempre agradava _________ todos. ____________ muito, o que dava uma __________ do cozinheiro. Em conformidade com a norma-padrão, as lacunas da frase devem ser preenchidas, respectivamente, com:","opcoes":["à … Criticavam-na … pena","a … Criticavam-na … pena","a … Criticavam-a … compaixão","à … Criticavam ela … dó","a … Criticavam-a … dó"],"correta":1,"explicacao":"Gabarito: <strong>a … Criticavam-na … pena</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7475,"enunciado":"Considerando os seguintes trechos retirados do texto, em relação aos mecanismos de coesão referencial e uso de pronomes, analise as assertivas abaixo: I. Em “O diagnóstico do relatório promovido pelo Ministério da Juventude e Infância da Espanha é devastador. Ele aponta que as redes sociais geram um contexto de alto risco para a saúde mental”, o termo “Ele” retoma o “diagnóstico”. II. Em “As plataformas de redes sociais estão plenamente conscientes dos riscos do seu modelo de negócios e, ainda assim, continuam a promovê-lo”, o pronome oblíquo “-lo” (l.20) retoma “modelo de negócios”. III. Em “Existe uma firme vontade por parte dos dirigentes das plataformas de ameaçar a regulamentação e quebrá-la”, o pronome oblíquo “-la” retoma “regulamentação”. Quais estão corretas?","opcoes":["Apenas I e II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7476,"enunciado":"A colocação pronominal em língua portuguesa refere-se à posição do pronome oblíquo átono em relação ao verbo. A identificação dessa colocação depende da estrutura da oração e da forma verbal a que o pronome se vincula. No trecho EIa atravessa a renda, o acesso a serviços, os espaços de poder e até os instrumentos que deveriam revelá-la, a colocação pronominal presente em revelá-la classifica-se como","opcoes":["Ênclise.","Próclise.","Epêntese.","Hipérclise.","Mesóclise."],"correta":0,"explicacao":"Gabarito: <strong>Ênclise.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7486,"enunciado":"(O melhor de Calvin Bill Watterson) Assinale a alternativa que completa as lacunas, na ordem em que aparecem, de acordo com a norma-padrão.","opcoes":["pegar-lo … arrastava … aconteciam","pegá-lo … arrastasse … aconteceriam","pegar-lo … arrastasse … aconteceriam","pegá-lo … arrastaria … aconteciam","pegar-o … arrastaria … acontecessem"],"correta":1,"explicacao":"Gabarito: <strong>pegá-lo … arrastasse … aconteceriam</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7498,"enunciado":"Assinale a opção em que a passagem da voz ativa para a voz passiva é feita de forma correta.","opcoes":["As empresas contrataram novos médicos. / Novos médicos serão contratados pelas empresas.","Os médicos visitarão os pacientes no hospital. / Os pacientes são visitados pelos médicos no hospital.","Noticiam novas descobertas sobre o câncer nos jornais de hoje. / Noticiam-se novas descobertas sobre o câncer nos jornais de hoje.","Os hospitais públicos, se recebessem mais verba, seriam mais eficientes. / Os hospitais públicos, se mais verba for recebida, serão mais eficientes.","As doenças silenciosas prejudicam mais os homens que as mulheres. / Mais os homens que as mulheres foram prejudicados pelas doenças silenciosas."],"correta":2,"explicacao":"Gabarito: <strong>Noticiam novas descobertas sobre o câncer nos jornais de hoje. / Noticiam-se novas descobertas sobre o câncer nos jornais de hoje.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7499,"enunciado":"Considere o excerto da canção É Preciso Saber Viver: “Toda pedra no caminho Você pode retirar” A respeito dos sentidos construídos no fragmento e dos recursos expressivos empregados na canção, analise as afirmativas a seguir e julgue-as como verdadeiras (V) ou falsas (F). ( ) O termo “pedra” assume valor metafórico, representando entraves e adversidades da experiência humana. ( ) O uso do verbo modal “pode” sugere possibilidade e autonomia do sujeito diante das dificuldades. ( ) O fragmento constrói uma visão determinista da existência, defendendo a impossibilidade de transformação da realidade. ( ) O deslocamento sintático de “Toda pedra no caminho” contribui para a ênfase semântica do obstáculo apresentado. ( ) A simplicidade estrutural da linguagem reduz a densidade reflexiva do texto poético. Após análise, conclui-se que a sequência correta é:","opcoes":["V – F – V – F – V.","F – V – V – F – V.","V – V – F – F – V.","F – F – V – V – F.","V – V – F – V – F."],"correta":4,"explicacao":"Gabarito: <strong>V – V – F – V – F.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7535,"enunciado":"No trecho do 1º parágrafo – Quando cozinhava, ela conversava. –, os dois verbos destacados estão no tempo passado. Passando-os para o tempo presente, têm-se, na ordem em que se apresentam:","opcoes":["Quando cozinhou, ela conversou.","Quando cozinha, ela conversa.","Quando cozinhar, ela conversará.","Quando cozinha, ela conversaria.","Quando cozinhou, ela conversa."],"correta":1,"explicacao":"Gabarito: <strong>Quando cozinha, ela conversa.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7536,"enunciado":"Assinale a alternativa em que a expressão destacada pode ser substituída pela palavra apresentada, sem prejuízo à norma-padrão de concordância verbal.","opcoes":["“... a maioria dos escritores mais importantes dessa região do mundo tinha vivido em Paris...” (2º parágrafo) ‒ tinham","“... uma literatura nova, rica, pujante e inventiva, que experimentava novas maneiras de contar histórias...” (3º parágrafo) ‒ experimentavam","“O meu descobrimento da América Latina, naqueles anos, levou-me a ler seus poetas, historiadores...” (4º parágrafo) ‒ levaram-me","“... viajar por todos os seus países e a viver os seus problemas e suas lutas políticas como se fossem meus.” (4º parágrafo) ‒ fosse","“Continuei a sê-lo no decurso de todos esses anos e assim será nos anos que ainda me restam.” (4º parágrafo) ‒ resta"],"correta":0,"explicacao":"Gabarito: <strong>“... a maioria dos escritores mais importantes dessa região do mundo tinha vivido em Paris...” (2º parágrafo) ‒ tinham</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7568,"enunciado":"Considere o trecho: “A lei protege o consumidor pessoa natural de boa-fé [...]” (linha 8). A alternativa que apresenta a transposição correta da oração acima para a voz passiva analítica é","opcoes":["protege-se o consumidor pessoa natural de boa-fé pela lei.","o consumidor pessoa natural de boa-fé protege-se pela lei.","o consumidor pessoa natural de boa-fé é protegido pela lei.","foi protegido o consumidor pessoa natural de boa-fé pela lei.","o consumidor pessoa natural de boa-fé era protegido pela lei."],"correta":2,"explicacao":"Gabarito: <strong>o consumidor pessoa natural de boa-fé é protegido pela lei.</strong>.","banca":"CEFET-BA","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7613,"enunciado":"Assinale a alternativa cuja forma verbal destacada apresenta concordância de acordo com os casos previstos pela norma-padrão.","opcoes":["Vende-se vários apartamentos a pregos populares naquela cidade.","A lista de mercadorias entregues na loja vieram com erros de informação.","São meio-dia dia e vinte minutos, de acordo com o relógio da matriz central.","Precisa-se de maquinas e equipamentos para terminar a obra dentro do prazo.","Um quinto da população da cidade foram ao evento no estádio municipal."],"correta":3,"explicacao":"Gabarito: <strong>Precisa-se de maquinas e equipamentos para terminar a obra dentro do prazo.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7614,"enunciado":"“Se me fosse dado o dom completo de escritor, eu havia de ser assim um Rousseau.” (Lima Barreto) Em relação à forma verbal destacada no período acima, é correto afirmar que ela se encontra na voz:","opcoes":["reflexiva, referindo ao sujeito “me”.","passiva sintética, referindo-se ao objeto direto “o dom completo de escritor”.","passiva analitica, referindo-se ao objeto direto “o dom completo de escritor”.","passiva analítica, referindo-se ao sujeito “o dom completo de escritor”.","passiva sintética, referindo-se ao sujeito “o dom completo de escritor”."],"correta":3,"explicacao":"Gabarito: <strong>passiva analítica, referindo-se ao sujeito “o dom completo de escritor”.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7618,"enunciado":"Todas as formas verbais estão corretamente flexionadas na frase:","opcoes":["Determem-se eles numa rigorosa análise do texto e suprimiram os equívocos.","Se o inseto não tivesse intervido eu não poderia ter escrito esta crônica.","O editor não quererá acolher esta crônica se eu não revi os deslizes todos.","Um simples inseto não constitue, como se viu, um obstáculo que não se transponha.","A menos que sobrevenhe um sério imprevisto, toda manhã escrevo uma crônica."],"correta":2,"explicacao":"Gabarito: <strong>O editor não quererá acolher esta crônica se eu não revi os deslizes todos.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7620,"enunciado":"Considere o período na voz ativa: O aumento de internações e a baixa adesão à vacina contra a gripe causam o cenário de alerta no estado. Diante disso, assinale a alternativa que apresenta a transposição CORRETA dessa oração para a voz passiva a na lÍtica.","opcoes":["O cenário de alerta no estado causou o aumento de internações e a baixa adesão à vacina contra a gripe.","O cenário de alerta no estado foi causado pelo aumento de internações e pela baixa adesão à vacina contra a gripe.","O cenário de alerta no estado é causado pelo aumento de internações e pela baixa adesão à vacina contra a gripe.","Causou-se o cenário de alerta no estado pelo aumento de internações e baixa adesão à vacina contra a gripe."],"correta":2,"explicacao":"Gabarito: <strong>O cenário de alerta no estado é causado pelo aumento de internações e pela baixa adesão à vacina contra a gripe.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7629,"enunciado":"Todas as formas verbais estão corretamente flexionadas na frase:","opcoes":["A menos que sobrevenha um sério imprevisto, toda manhã escrevo uma crônica.","Determo-se eles numa rigorosa análise do texto e suprimiram os equívocos.","Se o inseto não tivesse intervindo eu não poderia ter escrito esta crônica.","O editor não quererá acolher esta crônica se eu não revir os deslizes todos.","Um simples inseto não constitue, como se viu, um obstáculo que não se transponha."],"correta":3,"explicacao":"Gabarito: <strong>O editor não quererá acolher esta crônica se eu não revir os deslizes todos.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7632,"enunciado":"É plenamente adequada a correlação entre os tempos e modos verbais na frase","opcoes":["Ainda que não houvesse aquele transtorno, haverei de ter dificuldade com o início da crônica.","O inseto tornava-se meu ex-inimigo à medida que ia desvendando coisas de que eu já me esquecera.","Presume-se que cada escritor venha a encontrar em seu ofício desafios que não lograsse vencer.","Tão logo passou a voar pela sala, o inseto teria revelado imagens que o autor deu como perdidas.","Não fosse o inseto sentimental, o cronista teria podido escrever uma bela crônica, mas não esta a que desse forma."],"correta":1,"explicacao":"Gabarito: <strong>O inseto tornava-se meu ex-inimigo à medida que ia desvendando coisas de que eu já me esquecera.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7640,"enunciado":"Considere o seguinte período retirado do texto: A Comissão Nacional de Erradicação do Trabalho Infantil (Conaeti) publicou, no dia 25 de maio, o Fluxo Nacional de Atendimento. Considerando isso, assinale a alternativa que apresenta a transposição morfossintática CORRETA dessa oração da voz ativa para a voz passiva analítica, mantendo-se a mesma relação temporal.","opcoes":["O Fluxo Nacional de Atendimento publicou-se, no dia 25 de maio, pela Comissão Nacional de Erradicação do Trabalho Infantil (Conaeti).","O Fluxo Nacional de Atendimento foi publicado, no dia 25 de maio, pela Comissão Nacional de Erradicação do Trabalho Infantil (Conaeti).","A Comissão Nacional de Erradicação do Trabalho Infantil (Conaeti) tinha publicado, no dia 25 de maio, o Fluxo Nacional de Atendimento.","Publicaram o Fluxo Nacional de Atendimento, no dia 25 de maio, para a Comissão Nacional de Erradicação do Trabalho Infantil (Conaeti)."],"correta":1,"explicacao":"Gabarito: <strong>O Fluxo Nacional de Atendimento foi publicado, no dia 25 de maio, pela Comissão Nacional de Erradicação do Trabalho Infantil (Conaeti).</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7649,"enunciado":"\"Mas os impactos psicológicos, físicos e econômicos da enxaqueca são muito palpáveis, explica Monteith.\" O trecho acima apresenta concordância adequada. Agora, complete as lacunas com palavras corretamente flexionadas, de modo a manter também a concordância adequada. I.___as correspondências. II.A boiada___ um grande rio. III.Fomos nós quem___a conta. IV.___terrenos na área litoral. A sequência que preenche corretamente as lacunas acima é:","opcoes":["Chegaram, atravessava, pagou, Vendem-se.","Chegaram, atravessava, pagamos, Vende-se.","Chegaram, atravessavam, pagou, Vendem-se.","Chegou, atravessava, pagamos, Vende-se."],"correta":0,"explicacao":"Gabarito: <strong>Chegaram, atravessava, pagou, Vendem-se.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7661,"enunciado":"A conversão das vozes verbais exige conhecimento das relações morfossintáticas. Considere o trecho retirado do texto: O Instituto de Pesquisa Econômica Aplicada (Ipea) identificou custos operacionais. Diante disso, assinale a alternativa que apresenta a conversão CORRETA dessa oração da voz ativa para a voz passiva analítica, mantendo-se o tempo verbal original.","opcoes":["Custos operacionais identificavam o Instituto de Pesquisa Econômica Aplicada (Ipea).","Custos operacionais são identificados pelo Instituto de Pesquisa Econômica Aplicada (Ipea).","Custos operacionais foram identificados pelo Instituto de Pesquisa Econômica Aplicada (Ipea).","Identificaram-se custos operacionais pelo Instituto de Pesquisa Econômica Aplicada (Ipea)."],"correta":2,"explicacao":"Gabarito: <strong>Custos operacionais foram identificados pelo Instituto de Pesquisa Econômica Aplicada (Ipea).</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7662,"enunciado":"Ao transpor a oração O resultado foi celebrado por representantes do Poder Público e da sociedade civil interessada no tema para a voz ativa, mantendo estritamente o tempo e o modo verbal originais, obtém-se qual das seguintes estruturas?","opcoes":["Celebrou-se o resultado por representantes do Poder Público e da sociedade civil interessada no tema.","Representantes do Poder Público e da sociedade civil interessada no tema têm celebrado o resultado.","Representantes do Poder Público e da sociedade civil interessada no tema celebraram o resultado.","Representantes do Poder Público e da sociedade civil interessada no tema celebravam o resultado."],"correta":2,"explicacao":"Gabarito: <strong>Representantes do Poder Público e da sociedade civil interessada no tema celebraram o resultado.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["colocacaoPronominal"]},{"id":7685,"enunciado":"Assinale a alternativa correta:","opcoes":["Na frase “Encontram-se ilegíveis as datas da certidão de publicação do acórdão recorrido e do protocolo da petição de recurso extraordinário.”, é possível substituir a forma verbal “encontram-se” pela forma flexionada na singular: “encontra-se” sem prejuízo da correção gramatical.","Não há erro de concordância nesse texto: “No atual estágio do conhecimento científico, que indica ser incerta a existência de efeitos nocivos da exposição ocupacional e da população em geral a campos elétricos, magnéticos e eletromagnéticos gerados por sistemas de energia elétrica, não existe impedimentos, por ora, a que sejam adotados os parâmetros propostos pela Organização Mundial de Saúde, conforme estabelece a Lei nº 11.934/2009.”","Na frase “Parte dos entes federativos inadimplentes se notabilizou pelo descumprimento das diretrizes normativas previstas no art. 100 do corpo dogmático da Constituição.”, é possível substituir a forma verbal “notabilizou” pela forma flexionada no plural: “notabilizaram” sem prejuízo da correção gramatical.","No texto “Houve o sequestro de uma quantia de álcool pertencentes à empresa empregadora (1,5 milhão de litros de álcool), a qual ficou depositada em favor da empregada.”, é possível substituir a forma verbal “milhão” pela forma flexionada no plural: “milhões” sem prejuízo da correção gramatical."],"correta":2,"explicacao":"Gabarito: <strong>Na frase “Parte dos entes federativos inadimplentes se notabilizou pelo descumprimento das diretrizes normativas previstas no art. 100 do corpo dogmático da Constituição.”, é possível substituir a forma verbal “notabilizou” pela forma flexionada no plural: “notabilizaram” sem prejuízo da correção gramatical.</strong>.","banca":"MPE-GO","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7701,"enunciado":"Considere as seguintes passagens do texto: • Investiga-se também se a morte de uma mulher do interior paulista... (1° parágrafo) • Embora ainda não se saiba com certeza o que exatamente levou ao aumento expressivo de casos... (2° parágrafo) • ... fiscalizar e garantir que a venda desses produtos esteja minimamente de acordo com padrões sanitários. (6° parágrafo) Os termos destacados estabelecem, correta e respectivamente, relações de sentido de:","opcoes":["intensidade; modo; comparação.","afirmação; meio; conformidade.","inclusão; modo; intensidade.","afirmação; causa; conformidade.","inclusão; dúvida; intensidade."],"correta":2,"explicacao":"Gabarito: <strong>inclusão; modo; intensidade.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["colocacaoPronominal"]},{"id":7782,"enunciado":"Embora dominante, o ethos burguês ________________ e possessivo não é a única referência moral da sociedade ________________. Formas de comportamento ético-morais são orientadas por visões de mundo e valores que se reproduzem _________________ desde que tenham uma base de sustentação nas relações sociais capitalistas, seja em face de sua afirmação ou de sua negação. Na medida em que o ethos burguês é dominante, a formação ___________________ dos indivíduos tende a incorporá-lo e reproduzi-lo a partir da influência ideológica das várias instâncias de desenvolvimento da sociabilidade. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.","opcoes":["coletivo – socialista – economicamente – ética","individualista – contemporânea – moralmente – ética","progressista – capitalista – organicamente – moral","privatista – de classes – socialmente – dominante","individualista – capitalista – socialmente – moral"],"correta":4,"explicacao":"Gabarito: <strong>individualista – capitalista – socialmente – moral</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7791,"enunciado":"No trecho \"Em outras palavras, a infraestrutura necessária para a inteligência artificial precisa estar melhor distribuída.\" (5º parágrafo), há um erro gramatical, que deve corrigido da seguinte forma:","opcoes":["A vírgula deve ser excluída.","O verbo “precisa” deve flexionar-se no futuro: precisará.","Deve-se trocar “para” por em relação a","Deve-se trocar “melhor” por mais bem.","Deve haver hífen em “infraestrutura”, da seguinte forma: infra-estrutura."],"correta":3,"explicacao":"Gabarito: <strong>Deve-se trocar “melhor” por mais bem.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7798,"enunciado":"Considere as afirmações abaixo sobre aspectos gramaticais presentes no texto: I. A palavra \"celebrado\", em “o Ano Novo Chinês é celebrado no sábado” é um exemplo de voz passiva, indicando que a ação é recebida pelo sujeito. II. \"Cerca de 15 dias\" exemplifica o uso de uma locução adverbial de tempo. III. A expressão \"segundo a cultura da China\" introduz uma ideia de contraste ou oposição. Das assertivas, pode-se afirmar que:","opcoes":["Apenas I e II estão corretas.","Apenas II e III estão corretas.","Apenas I está correta.","Todas estão corretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I e II estão corretas.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7804,"enunciado":"Nas sentenças a seguir, verifica-se locução adverbial apenas em:","opcoes":["A mãe afirmou com certeza que as coisas dariam certo.","Não sabia o que fazer diante do delegado.","Apesar de não ir a todas as aulas, tirava boas notas.","Os paletós de linho serviram perfeitamente.","Desde que foi para o exterior, mudou seus hábitos alimentares."],"correta":0,"explicacao":"Gabarito: <strong>A mãe afirmou com certeza que as coisas dariam certo.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7815,"enunciado":"Considerando-se sua constituição interna e sua função, a expressão “pelo menos”, que ocorre no texto, – Pelo menos é o que sugere uma descoberta descrita esta semana em um artigo da revista científica Nature Plants. –, é uma:","opcoes":["locução adjetiva.","locução prepositiva.","locução adverbial.","locução substantiva.","locução verbal."],"correta":2,"explicacao":"Gabarito: <strong>locução adverbial.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7865,"enunciado":"Considerando a expressão destacada do excerto retirado do texto, assinale a alternativa correta: “Parei justamente porque você chegou”.","opcoes":["Trata-se de uma palavra que modifica um verbo.","Trata-se de uma conjunção.","Trata-se de uma preposição.","Trata-se de uma palavra que expressa sentido de lugar."],"correta":0,"explicacao":"Gabarito: <strong>Trata-se de uma palavra que modifica um verbo.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7867,"enunciado":"Assinale a alternativa em que a relação expressa pelo vocábulo em destaque está corretamente analisada nos parênteses.","opcoes":["[...] a natação, embora popular, demorou muito para se transformar em uma competição organizada [...]. (relação de restrição)","Um dos primeiros registros data de 1696, quando o francês M. Thevenal descreveu uma maneira singular de nadar [...]. (relação de explicação)","[...] foi aperfeiçoada pelo australiano Richard Cavill e, posteriormente, transformou-se no nado crawl (livre) que conhecemos hoje. (relação de temporalidade)","Finalmente, na década de 1930, nadadores norte-americanos, já durante competições [...]. (relação de finalidade)"],"correta":2,"explicacao":"Gabarito: <strong>[...] foi aperfeiçoada pelo australiano Richard Cavill e, posteriormente, transformou-se no nado crawl (livre) que conhecemos hoje. (relação de temporalidade)</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7878,"enunciado":"Considerando os sentidos e aspectos linguísticos do texto precedente, que apresenta um trecho da letra da canção Índios, interpretada pela banda Legião Urbana, julgue o próximo item. Os segmentos “ao menos uma vez”, “mais simples” e “mais importante” classificam-se no texto como locuções adjetivas.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":7882,"enunciado":"Assinale a alternativa em que o emprego do acento indicativo de crase está em conformidade com a norma-padrão.","opcoes":["O exagero de Rubem Braga o conduz à uma imagem negativa de si mesmo.","Alega-se que um erro médico tirou à vida do escrito Otto Lara Resende.","Hoje, tem-se a sensação de que a velhice leva mais tempo à chegar.","Rachel de Queiroz não temia as críticas à sua forma de escrever.","Quem vem a este mundo está sujeito à ciladas, já dizia o escritor."],"correta":3,"explicacao":"Gabarito: <strong>Rachel de Queiroz não temia as críticas à sua forma de escrever.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal","crase"]},{"id":7885,"enunciado":"Analise o texto, a seguir, e marque a alternativa correta. “ Tô feito mato, desejando a chuva Madrugada fria, esperando o Sol Tô tão carente feito um prisioneiro.” (Eu sem você, Paula Fernandes)","opcoes":["O termo destacado refere-se a mato.","O vocábulo “feito”, que está em destaque, pode ser substituído pela preposição “como” sem modificar o sentido da frase.","O termo em negrito relaciona-se com a palavra Sol.","O vocábulo em evidência, “feito”, é o mesmo que concluído."],"correta":1,"explicacao":"Gabarito: <strong>O vocábulo “feito”, que está em destaque, pode ser substituído pela preposição “como” sem modificar o sentido da frase.</strong>.","banca":"RH MAIS","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7896,"enunciado":"Em outro, houve substituição de frases mais curtas e econômicas por períodos mais longos e redundantes; em outro, houve troca de \"entre\" por \"dentre\" (naturalmente, sem critério gramatical). No trecho acima, faz-se referência à diferença de uso das palavras \"entre\" e \"dentre\", cuja diferença nem sempre é respeitada na língua. A esse respeito, assinale a alternativa em que se tenha empregado corretamente a palavra \"dentre\".","opcoes":["Passamos dentre os atalhos até chegar à via principal.","Um dentre os candidatos será eleito Prefeito.","Eles se colocaram dentre os demais.","Ele ficou preso dentre as opções a escolher."],"correta":1,"explicacao":"Gabarito: <strong>Um dentre os candidatos será eleito Prefeito.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7902,"enunciado":"Considere as passagens: • O primeiro é mais visível, possui acessórios caros; impõe-se pela capacidade de comprar soluções; o segundo, por evitar comprá-las, pois não gera problemas. (1º parágrafo) • Embora o lucro continue a ser condição básica, pois sem ele nenhuma empresa consegue permanecer em atividade, surge com vigor nas grandes corporações, e até nas pequenas empresas, a necessidade da ação correta... (3º parágrafo) As preposições destacadas estabelecem, correta e respectivamente, relações de sentido de:","opcoes":["conformidade; modo; causa; causa.","finalidade; causa; modo; modo.","causa; consequência; modo; causa.","conformidade; causa; causa; modo.","finalidade; consequência; modo; causa."],"correta":1,"explicacao":"Gabarito: <strong>finalidade; causa; modo; modo.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7910,"enunciado":"Considerando-se a função da expressão “de sorte que”, que ocorre no texto — “de sorte que não há férias [...]” —, sua classificação é a de:","opcoes":["locução substantiva.","locução adjetiva.","locução conjuntiva.","locução prepositiva.","locução adverbial."],"correta":2,"explicacao":"Gabarito: <strong>locução conjuntiva.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7915,"enunciado":"Considere as reescritas de informações do texto. • Esperava que _____ qualquer hora o coração lhe perfurasse o peito, lhe rasgasse a blusa. • O coração corresponderia mesmo _____ forma bonita dos postais coloridos? • Pensou em jogar _____ lata de água ao chão, esparramar-se no líquido, fazer-se lama. • O barranco dirigia _____ ela um sorriso irresistível, convidando-a para o encontro final. De acordo com a norma-padrão, as lacunas devem ser preenchidas, respectivamente, com:","opcoes":["a … àquela … a … a","a … àquela … à … à","à … aquela … a … a","à … àquela … a … a","a … aquela … a … à"],"correta":0,"explicacao":"Gabarito: <strong>a … àquela … a … a</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7941,"enunciado":"É adequado o emprego do elemento sublinhado na frase:","opcoes":["É trabalhar duro para fazer jus de novas férias.","A noção de férias está vinculada à figuras de linguagem.","Restringindo-me a essa minha concepção, resolvi tirar férias.","A pressa é um elemento constitutivo na era do jatos.","Disse não aos convites, sobre a alegação de motivos pessoais."],"correta":2,"explicacao":"Gabarito: <strong>Restringindo-me a essa minha concepção, resolvi tirar férias.</strong>.","banca":"FCC","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7963,"enunciado":"Nas relações estabelecidas pelas preposições, assinale a alternativa que indique instrumento.","opcoes":["Hilda feriu-se com a faca.","O São Paulo jogou contra o Palmeiras.","Este é o carro de Eliane.","Devolva-me meu anel de ouro."],"correta":0,"explicacao":"Gabarito: <strong>Hilda feriu-se com a faca.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7965,"enunciado":"Assinale a frase em que a preposição de é empregada por exigência de um termo anterior.","opcoes":["Querer convencer os governadores da necessidade de cortar verbas é inútil.","O maior déficit de certos governos situa-se entre as orelhas de seus governantes.","O Brasil é uma nação de espertos.","No Oriente Médio, o processo de paz avança em prestações.","Horas perdidas em greves acabam por transformar-se em anos de avanço econômico e social."],"correta":0,"explicacao":"Gabarito: <strong>Querer convencer os governadores da necessidade de cortar verbas é inútil.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":7998,"enunciado":"Está correto o emprego de ambas as expressões sublinhadas na frase:","opcoes":["As pessoas com quem devemos prestar contas são aquelas cujos direitos os setores dominantes não costumam dar atenção.","Nem sempre conseguem os homens sobrepor-se diante de suas circunstâncias ou redimir-se perante seus fracassos.","Os direitos em cuja defesa devemos nos empenhar são os mesmos pelos quais os acumuladores de capital demonstram desprezo.","O alerta de Einstein de que nos mantenhamos em guarda é, de fato, um imperativo moral do qual não podemos deixar de atender.","Os métodos legais de cujos se valem os detentores do poder econômico reforçam a má distribuição de renda em que os trabalhadores são vítimas."],"correta":2,"explicacao":"Gabarito: <strong>Os direitos em cuja defesa devemos nos empenhar são os mesmos pelos quais os acumuladores de capital demonstram desprezo.</strong>.","banca":"FCC","ano":2008,"temas_relacionados":["colocacaoPronominal"]},{"id":8005,"enunciado":"Levando em consideração o terceiro parágrafo do texto e as orientações da prescrição gramatical no que se refere a textos escritos na modalidade padrão da Língua Portuguesa, assinale a alternativa correta.","opcoes":["Em “Lembro da construção já na fase final”, há uma construção coloquial do ponto de vista da regência, que pode adequar-se à modalidade padrão escrita com o uso do verbo “lembrar” em sua forma pronominal (Lembro-me da construção).","Em “Era então frágil e curva”, o termo destacado assume um valor adverbial, referindo-se à época em que Maria Preta havia, conforme o restante da frase, assumido determinadas características físicas. Assim, uma construção semanticamente equivalente ao trecho seria “Era, desse modo, frágil e curva”.","Em “aplicando o mais na realização de seu grande objetivo”, o termo destacado é um advérbio de intensidade, equivalendo em sentido ao destacado nesta frase: Passou a trabalhar mais no novo emprego.","Nos trechos: “Ela passava semanalmente pelas casas”, “Subia da casa onde morava” e “trazendo com dificuldade nas costas o saco onde punha os retalhos”, todas as expressões destacadas expressam a mesma circunstância: a de movimento.","Nos trechos: “a fim de apanhar retalhos de pano” e “que iam alimentar a construção”, a substituição dos termos destacados pelo pronome oblíquo teria como resultado as seguintes expressões, adequadas à correção gramatical: “a fim de apanharlhes” e “que lhe iam alimentar”."],"correta":0,"explicacao":"Gabarito: <strong>Em “Lembro da construção já na fase final”, há uma construção coloquial do ponto de vista da regência, que pode adequar-se à modalidade padrão escrita com o uso do verbo “lembrar” em sua forma pronominal (Lembro-me da construção).</strong>.","banca":"CETRO","ano":2013,"temas_relacionados":["colocacaoPronominal"]},{"id":8015,"enunciado":"Apenas uma das opções a seguir foi corretamente redigida, empregando apenas a preposição “A”, como em: “com 394 unidades habitacionais A uma curta distância de seus escritórios.”","opcoes":["Dirijam-se A esta secretária.","Quero assistir A palestra do diretor.","A pouco tempo nem se pensava nisso.","Refiro-me A secretária do diretor.","Foram todos A festa da empresa."],"correta":0,"explicacao":"Gabarito: <strong>Dirijam-se A esta secretária.</strong>.","banca":"IBADE","ano":2017,"temas_relacionados":["colocacaoPronominal"]},{"id":8024,"enunciado":"Assinale a opção que apresenta a frase que está integralmente redigida em forma gramaticalmente correta.","opcoes":["Presume-se toda pessoa boa até prova em contrário.","Guerra é uma série de catástrofes que podem resultar numa vitória.","Muitas vezes damos ao inimigo os meios para nos destruírem.","Tem poder aquele quem a multidão confia.","Guerra implica em baixas."],"correta":1,"explicacao":"Gabarito: <strong>Guerra é uma série de catástrofes que podem resultar numa vitória.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":8042,"enunciado":"Marque a alternativa em que não existe uma relação de causa e consequência entre as ideias.","opcoes":["“Os infelizes tinham caminhado bastante na areia do rio seco, a viagem progredia bem três léguas. ”","“[…] mas dormiram ao relento, estavam cansados e famintos. ”","“A seca aparecia-lhe como responsável – e a obstinação da criança irritava-o.” Insegurança","“Como isto não acontecesse, esperou-os quatro cantos, zangado, praguejando baixo. ”"],"correta":2,"explicacao":"Gabarito: <strong>“A seca aparecia-lhe como responsável – e a obstinação da criança irritava-o.” Insegurança</strong>.","banca":"EVO Concursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":8080,"enunciado":"As frases abaixo estão divididas em dois segmentos. Assinale a frase em que a relação entre esses dois segmentos é, respectivamente, de causa e consequência.","opcoes":["Todo mundo precisa crer em algo. / Creio que vou tomar uma cerveja.","Nem tudo o que se enfrenta pode ser modificado, / mas nada pode ser modificado até que seja enfrentado.","O sábio busca a sabedoria; / o tolo a encontrou.","Mestre não é quem sempre ensina, / mas quem de repente aprende.","Sabedoria é saber o que fazer; / virtude é saber fazê-lo."],"correta":0,"explicacao":"Gabarito: <strong>Todo mundo precisa crer em algo. / Creio que vou tomar uma cerveja.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":8102,"enunciado":"As expressões destacadas indicam ideias de, EXCETO:","opcoes":["“Seguramente, o discurso não me era destinado.” (2º§) – modo.","“Além disso, eu não reconhecia sua linguagem.” (2º§) – inclusão.","“Quando parou de ler, retomei-lhe vivamente os livros [...]” (2º§) – tempo.","“Respondi no entanto: minha débil voz perdeu-se e senti tornar-me outro.” (2º§) – explicação."],"correta":3,"explicacao":"Gabarito: <strong>“Respondi no entanto: minha débil voz perdeu-se e senti tornar-me outro.” (2º§) – explicação.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":8133,"enunciado":"Na leitura do seguinte trecho “O contexto de vinculação excessiva das tecnologias no dia a dia é um dos motores para o aparecimento da condição, uma vez que elas possuem a potência de tirar os sujeitos do presente e direcionar para algo que, muitas vezes, é mais confortável que a realidade.” (5º§), identifica-se que a expressão conjuntiva “uma vez que” estabelece","opcoes":["oposição a uma ideia.","relação de causa e introduz uma explicação.","conclusão em relação ao que foi exposto anteriormente.","comparação com a ideia apresentada no início do fragmento."],"correta":1,"explicacao":"Gabarito: <strong>relação de causa e introduz uma explicação.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":8161,"enunciado":"[Questão Inédita] Analise a oração destacada no trecho: “As 50 peças da face e as oito das mãos foram moldadas em Paris e vieram para cá como um quebra-cabeça”. O conectivo introduz uma relação de A sentença destacada classifica-se como","opcoes":["adição.","consequência.","conclusão .","complemento.","adversidade."],"correta":0,"explicacao":"Gabarito: <strong>adição.</strong>.","banca":"Qconcursos","ano":2024,"temas_relacionados":["colocacaoPronominal"]},{"id":8175,"enunciado":"Assinale a alternativa INCORRETA quanto às relações sintático-semânticas estabelecidas pelas conjunções destacadas.","opcoes":["“...sofre por não saber se deve vender as ações que estão patinando e estancar as perdas ou apostar na recuperação dos papéis e mantê-los em carteira.” (relação de exclusão)","“Em vez de traçar uma estratégia sólida, o novato dá grandes tacadas de uma vez só, para evitar a tensão de analisar e optar...”. (relação de finalidade)","“...uma boa oportunidade de investimentos tanto para os padeiros e cervejeiros de Adam Smith quanto para os bungee jumpers de Kahneman.” (relação de consecução)","“As frustrações se tornam ainda mais agudas quando as cotações caem.” (relação temporal)","“...sofre por não saber se deve vender as ações que estão patinando e estancar as perdas ou apostar na recuperação dos papéis e mantê-los em carteira.” (relação de adição)"],"correta":2,"explicacao":"Gabarito: <strong>“...uma boa oportunidade de investimentos tanto para os padeiros e cervejeiros de Adam Smith quanto para os bungee jumpers de Kahneman.” (relação de consecução)</strong>.","banca":"AOCP","ano":2009,"temas_relacionados":["colocacaoPronominal"]},{"id":8177,"enunciado":"“Restringir-se, pois, à sua gramática é limitar-se a um de seus componentes apenas. É perder de vista sua totalidade e, portanto, falsear a compreensão de suas múltiplas determinações.” Acerca dos termos destacados, é correto afirmar que:","opcoes":["o primeiro introduz a causa de um fato; o segundo indica uma conclusão.","o primeiro indica uma conclusão; o segundo, uma condição.","ambos foram utilizados para indicar condição.","o primeiro sinaliza uma explicação; o segundo indica uma condição.","funcionam, ambos, para indicar uma conclusão."],"correta":4,"explicacao":"Gabarito: <strong>funcionam, ambos, para indicar uma conclusão.</strong>.","banca":"IPAD","ano":2008,"temas_relacionados":["colocacaoPronominal"]},{"id":8196,"enunciado":"Pode-se afirmar que a palavra COMO, no trecho “A menção a um projeto comunista suscita o debate sobre os limites da democracia COMO regime capaz de promover e de beneficiar-se de uma reforma agrária” (10º parágrafo), pode ser substituída, sem alteração de sentido, por:","opcoes":["enquanto;","conforme;","do modo que;","tal qual;","dado que."],"correta":0,"explicacao":"Gabarito: <strong>enquanto;</strong>.","banca":"COSEAC","ano":2009,"temas_relacionados":["colocacaoPronominal"]},{"id":8202,"enunciado":"Releia o fragmento a seguir. “Mas quando se surgiu, uma vez o cientista botou no jornal, parece que foi 97, que era seco, aí descobriram por aí que eu sabia. Aí o jornalista me chamou: ‘Rapaz, ouvi dizer por aí que você sabe até o dia que chove.’ ” O trecho que reescreve adequadamente o extrato acima, substituindo o uso popular da palavra aí por vocábulos ou recursos lingüísticos que explicitem as relações pretendidas pelo autor, sem alteração de sentido, é:","opcoes":["“...seco. Em decorrência desse fato, descobriram, por meio da notícia, que eu sabia. Então, o jornalista ... : ‘Rapaz, ouvi dizerem que você sabe’...”.","“...seco. Assim, descobriram deste modo, que eu sabia. Já o jornalista... ‘Rapaz, ouviram dizer que você sabe’...”.","“...seco. Descobriram , portanto, que eu sabia. Em conseqüência, o jornalista...: ‘Rapaz, ouvi dizer no jornal que você sabe’...”.","“...seco. Só deste jeito, descobriram por todo canto que eu sabia. Assim sendo, o jornalista.... : ‘Rapaz, diz-se que você sabe’...”.","“... seco. Agora, descobriram, então, que eu sabia. Por isso, o jornalista...: ‘Rapaz, pessoas dizem que você sabe’...”."],"correta":0,"explicacao":"Gabarito: <strong>“...seco. Em decorrência desse fato, descobriram, por meio da notícia, que eu sabia. Então, o jornalista ... : ‘Rapaz, ouvi dizerem que você sabe’...”.</strong>.","banca":"CESGRANRIO","ano":2008,"temas_relacionados":["colocacaoPronominal"]},{"id":8208,"enunciado":"1 Os mitólogos costumam chamar de imagens de mundo certas estruturas simbólicas pelas quais, em todas as épocas, as diferentes sociedades humanas fundamen taram, tanto coletiva quanto individualmente, a experiência 5 do existir. Ao longo da história, essas constelações de idéias foram geradas quer pelas tradições étnicas, locais, de cada povo, quer pelos grandes sistemas religiosos. No Ocidente, contudo, desde os últimos três séculos uma outra prática de pensamento veio se acrescentar a estes 10 modos tradicionais na função de elaborar as bases de nossas experiências concretas de vida: a ciência. Com efeito, a partir da revolução científica do Renascimento as ciências naturais passaram a contribuir de modo cada vez mais decisivo para a formulação das categorias que a 15 cultura ocidental empregará para compreender a realidade e agir sobre ela. Mas os saberes científicos têm uma característica inescapável: os enunciados que produzem são necessaria mente provisórios, estão sempre sujeitos à superação e à 20 renovação. Outros exercícios do espírito humano, como a cogitação filosófica, a inspiração poética ou a exaltação mística poderão talvez aspirar a pronunciar verdades últimas; as ciências só podem pretender formular verdades transitórias, sempre inacabadas. Ernesto Sábato assinala 25 com precisão que todas as vezes que se pretendeu elevar um enunciado científico à condição de dogma, de verdade final e cabal, um pouco mais à frente a própria continuidade da aplicação do método científico invariavel mente acabou por demonstrar que tal dogma não passava 30 senão... de um equívoco. Não há exemplo melhor deste tipo de superstição que o estatuto da noção de raça no nazismo (Luiz Alberto Oliveira. “Valores deslizantes: esboço de um ensaio sobre técnica e poder”, In O avesso da liberdade. Adauto Novaes (Org). São Paulo: Companhia das Letras, 2002. p. 191) No parágrafo 2,","opcoes":["a conjunção Mas (linha 17) foi empregada não para eliminar o que foi dito anteriormente, e, sim, para introduzir uma contrapartida do objeto, fruto de distinta perspectiva de análise.","constrói-se uma relativização das conquistas da ciência, sustentada na crítica de que ela se vale de procedimentos pouco objetivos na busca da verdade.","constata-se o caráter incontrolável das experiências científicas, implicitamente atribuído às condições de descontinuidade em que se realizam.","a expressão necessariamente provisórios (linhas 18 e 19) compõe uma advertência, dirigida a filósofos, poetas e místicos, que desconsideram a objetividade na produção do saber.","incentiva-se a luta do ser para a constante superação de suas fragilidades pessoais, advindas de sua humana condição e permanente sujeição ao erro."],"correta":0,"explicacao":"Gabarito: <strong>a conjunção Mas (linha 17) foi empregada não para eliminar o que foi dito anteriormente, e, sim, para introduzir uma contrapartida do objeto, fruto de distinta perspectiva de análise.</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["colocacaoPronominal"]},{"id":8219,"enunciado":"Denomina-se adequação sintática a construção coerente de períodos e orações, observadas as relações existentes entre seus termos e a sua organização. O parágrafo, den- tre os abaixo transcritos, que preserva o princípio do paralelismo sintático, segundo o qual quaisquer elemen- tos da frase coordenados entre si devem apresentar estru- tura gramatical similar, é","opcoes":["Aqui não pretendemos defender a ideia de mais inter- venção do Estado na economia ou que ele volte a pro- duzir aço em grande quantidade.","Aqui não pretendemos defender a ideia de que o Esta- do intervenha mais na economia ou a volta de uma produção de aço em grande quantidade.","Aqui não pretendemos defender a ideia de um Estado intervindo mais na economia ou que ele volte à produ- ção de aço em grande quantidade.","Aqui não pretendemos defender a ideia de que a inter- venção do Estado deva ser maior na economia ou uma produção de aço voltando a ter quantidade.","Aqui não pretendemos defender a ideia de que o Esta- do intervenha mais na economia ou que volte a produ- zir aço em grande quantidade."],"correta":0,"explicacao":"Gabarito: <strong>Aqui não pretendemos defender a ideia de mais inter- venção do Estado na economia ou que ele volte a pro- duzir aço em grande quantidade.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["colocacaoPronominal"]},{"id":8338,"enunciado":"Infere-se corretamente do texto que, com a expansão do crédito, I. há riscos maiores de ocorrer inadimplência de consumidores. II. a venda de itens de maior valor passa a ser equiva- lente ao volume dos mais acessíveis à população. III. com o aumento das vendas à vista diminui a receita no comércio, pois o crédito contempla compras de maior valor. Está correto o que se afirma SOMENTE em","opcoes":["I.","II.","I e II.","I e III.","II e III. 2"],"correta":3,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["colocacaoPronominal"]},{"id":8341,"enunciado":"As sementes do impulso fundamental da indústria de agronegócio nacional foram lançadas quando um núcleo de sete especialistas da Embrapa debruçou-se sobre o desafio de tropicalizar a soja. O sentido da frase inicial do texto está expresso com clareza e correção, em outras palavras, da seguinte forma:","opcoes":["As possibilidades de desenvolvimento da produção agrícola brasileira concretizaram-se quando espe- cialistas voltaram-se para as tentativas de adaptar a soja ao clima tropical.","Foram vários os tipos de sementes utilizados por pesquisadores para descobrir o melhor meio de au- mentar a importância do agronegócio na região tropical.","A soja é o produto mais valorizado do agronegócio brasileiro por apresentar diversidade de tipos de sementes que o trópico conseguiu desenvolver.","Especialistas da Embrapa consideram impossível re- solver o impasse da soja para ser tropicalizada, no importante aumento da indústria do agronegócio nacional.","A indústria nacional de agronegócio cujas as se- mentes foram plantadas para conseguir a tropi- calização da soja, feitas no desafio dos especialistas da Embrapa."],"correta":0,"explicacao":"Gabarito: <strong>As possibilidades de desenvolvimento da produção agrícola brasileira concretizaram-se quando espe- cialistas voltaram-se para as tentativas de adaptar a soja ao clima tropical.</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["colocacaoPronominal"]},{"id":8342,"enunciado":"O impacto da inovação foi formidável. (2 parágrafo) A afirmativa transcrita acima","opcoes":["perde importância em vista dos diferentes tipos de soja existentes no mercado.","aponta um certo fracasso nas pesquisas, tendo em vista o pequeno desenvolvimento da planta no Brasil.","indica as dificuldades de escolha do tipo de soja mais adequado para regiões mais quentes.","é comprovada pelo considerável aumento ocorrido atualmente na produção de soja.","refere-se ao extraordinário esforço dos especialistas da Embrapa em obter as sementes para suas pesquisas."],"correta":3,"explicacao":"Gabarito: <strong>é comprovada pelo considerável aumento ocorrido atualmente na produção de soja.</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["colocacaoPronominal"]},{"id":8343,"enunciado":"O segmento abaixo que indica uma razão para a afirma- tiva que, no texto, se segue a ele \u0010 segmento \u0010, é:","opcoes":["As sementes do impulso fundamental da indústria de agronegócio nacional foram lançadas ...","... quando um núcleo de sete especialistas da Embrapa debruçou-se ...","Planta de origem asiática ...","... a planta atingia no máximo 15 centímetros, um sexto de sua altura normal ...","Foram necessários anos de pesquisas num banco genético ... 2"],"correta":2,"explicacao":"Gabarito: <strong>Planta de origem asiática ...</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["colocacaoPronominal"]},{"id":8398,"enunciado":"Os textos argumentativos podem apoiar-se em tipos diferentes de argumentos. Assinale a opção em que o argumento empregado pelo enunciador é apoiado na intimidação do receptor.","opcoes":["Não deixe para amanhã o que pode fazer hoje.","Ganhe muito e gaste menos.","Trabalhe pouco e ganhe muito.","Conserte seu carro em mecânicos competentes, é mais caro, mas é mais seguro.","Alimente-se de forma saudável e você chegará atrasado à outra vida."],"correta":4,"explicacao":"Gabarito: <strong>Alimente-se de forma saudável e você chegará atrasado à outra vida.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8400,"enunciado":"Observe o relato de uma testemunha de um processo de auditoria fiscal, num diálogo com um fiscal: “Aí o empresário tentou misturar o documento falsificado com outros negócios que estavam numa gaveta, mas ele deu azar e o documento caiu e como eu tava lá, pude apanhar o papel no chão, que é esse que tá aí.” Tendo esse texto como referência, assinale a opção que marca uma característica da língua culta e não da língua popular.","opcoes":["O emprego de vocábulos de conteúdo geral, como, por exemplo, o vocábulo “negócios”.","O emprego de conectores em lugar de outros de significados mais específicos, como, por exemplo, “Aí”, na frase inicial.","A presença de repetições de palavras em busca de precisão, como, por exemplo, a repetição de “documento”.","A utilização de um hiperônimo para evitar-se a repetição de palavras idênticas, como, por exemplo, “papel”.","A utilização de expressões da linguagem popular, como, por exemplo, “deu azar”."],"correta":3,"explicacao":"Gabarito: <strong>A utilização de um hiperônimo para evitar-se a repetição de palavras idênticas, como, por exemplo, “papel”.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8401,"enunciado":"“Renda é o produto ou resultado do trabalho, do capital ou dos dois. De forma simples, um empregado que trabalha um mês recebe um salário que é o resultado da função que ele exerce. É como se ele “vendesse” sua atividade pelo salário. No caso do emprego do capital, o raciocínio é parecido: quando uma pessoa empresta dinheiro, ela não espera somente o pagamento do empréstimo, no mesmo valor. Ela possui a expectativa de receber os juros deste empréstimo, que são a remuneração do capital aplicado. Da mesma forma, o empresário, ao exercer sua atividade empresarial, não “troca” dinheiro. Ele investe seu capital na expectativa de auferir lucro – que é a remuneração da atividade empresarial, superior ao capital investido.” A respeito desse segmento, assinale a afirmativa correta.","opcoes":["Trata-se de um texto jornalístico que procura informar aos leitores as últimas novidades na área do imposto de renda.","Identifica-se como um verbete de dicionário, com a preocupação de definir uma série de termos pertinentes ao mesmo campo semântico.","Faz parte de um texto normativo, pois mostra os princípios legais que regem atividades econômicas.","Aproxima-se de um texto didático que tem a preocupação de simplificar conhecimentos técnicos da área econômica.","Mostra-se como um texto argumentativo, defendendo a tese de tornar os conhecimentos econômicos mais populares."],"correta":3,"explicacao":"Gabarito: <strong>Aproxima-se de um texto didático que tem a preocupação de simplificar conhecimentos técnicos da área econômica.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8404,"enunciado":"Observe o que nos diz o escritor Lima Barreto sobre o nosso país: “Não há dúvida alguma que o Brasil é um país muito rico. Nós que nele vivemos não nos apercebemos bem disso, e até, ao contrário, o supomos muito pobre, pois a toda hora e a todo instante, estamos vendo o governo lamentar-se que não faz isto ou não faz aquilo por falta de verba. Nas ruas da cidade, nas mais centrais até, andam pequenos vadios, a cursar a perigosa universidade das sarjetas, aos quais o governo não dá destino, ou os mete num asilo, num colégio profissional qualquer, porque não tem verba, não tem dinheiro. É o Brasil rico… Surgem epidemias pasmosas, a matar e a enfermar milhares de pessoas, que vêm mostrar a falta de hospitais na cidade, a má localização dos existentes. Pede-se a construção de outros bem situados; e o governo responde que não pode fazer porque não tem verba, não tem dinheiro. E o Brasil é um país rico.” Considerando-se o trecho de Lima Barreto como um exemplo de texto argumentativo, assinale a afirmativa correta sobre sua estrutura.","opcoes":["A tese apresentada é a de que o Brasil é um país rico, mas que, por má administração, se mostra como pobre.","Na defesa da tese apresentada o autor apela para informações presentes na imprensa sobre a nossa realidade cotidiana.","Os argumentos utilizados para o convencimento do público- alvo se apoiam em depoimentos sobre as evidências de pobreza no país.","O texto apresenta sua argumentação com base na ironia, pois apesar de pobre, o Brasil se mostra como rico.","O público-alvo a ser convencido é a imensa população brasileira, que vê o país como rico, mas não nota os frutos dessa riqueza na realidade cotidiana."],"correta":0,"explicacao":"Gabarito: <strong>A tese apresentada é a de que o Brasil é um país rico, mas que, por má administração, se mostra como pobre.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8409,"enunciado":"Num artigo interessante sobre os impostos no Brasil, intitulado Sete fatos impressionantes sobre os impostos no Brasil, o autor, Emanuel Steffen, cita como um desses fatos: “Não bastasse a complexidade existente, todos os dias são criadas mais 46 leis tributárias - Desde a promulgação da Constituição de 1988, o Brasil criou 320.343 leis tributárias. Sim: trezentos e vinte mil, trezentos e quarenta e três leis tributárias. Levando-se em conta o número de dias úteis no período, foram criadas 46 novas leis todos os dias, segundo um levantamento do IBPT. Se continuarmos nesse ritmo, nossa complexidade tributária só tende a piorar e complicar ainda mais os negócios do país, que já precisam seguir 40.865 artigos legais para poderem funcionar.” O fato citado é considerado “impressionante” pelo autor do texto em função","opcoes":["da alta complexidade do sistema tributário, acrescido do grande número de novas leis, criadas diariamente.","do grande número de novas leis diariamente publicadas, o que torna o trabalho dos administradores impossível de ser realizado.","da complicação legal trazida pelas novas leis, que contrariam leis já previamente existentes, fazendo com que o funcionamento de negócios se complique demasiadamente.","do enorme espaço de tempo dispendido no aprendizado das novas leis, que são rapidamente substituídas por outras.","da impossibilidade da criação de novos negócios já que é inexequível a obediência a mais de 40.865 artigos legais."],"correta":0,"explicacao":"Gabarito: <strong>da alta complexidade do sistema tributário, acrescido do grande número de novas leis, criadas diariamente.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8410,"enunciado":"“Aquele candidato estava mexendo no celular; vou tomar a prova dele!” Essa é uma afirmação de um fiscal de prova, que é formulada, passando de uma premissa diretamente a uma conclusão, assumindo como verdadeira uma ideia intermediária. Assinale a opção que indica corretamente a ideia intermediária omitida.","opcoes":["Há um grande engarrafamento na nossa frente; vamos desviar pela estrada de terra à direita – Vai demorar bastante para liberarem o trânsito.","Segui a orientação do médico durante todo esse tempo; fiquei curado em menos de uma semana – Os remédios utilizados eram importados de ótimos laboratórios.","Soou a sirene que marca o final do concurso; vamos recolher as provas – Temos ainda muito trabalho a fazer.","O candidato estudou bastante nos últimos meses; os resultados dele foram ótimos – Os estudos do candidato foram orientados por outros candidatos experientes.","A pesquisa mostrou que este emprego é dos mais procurados; vou inscrever-me para concorrer a uma vaga – A pesquisa foi encomendada pela direção da empresa."],"correta":0,"explicacao":"Gabarito: <strong>Há um grande engarrafamento na nossa frente; vamos desviar pela estrada de terra à direita – Vai demorar bastante para liberarem o trânsito.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8467,"enunciado":"A origem dos tributos Atualmente a atividade tributária tem assumido o papel de prover os recursos destinados ao governo para a realização dos fins almejados e revertidos para o bem-estar da coletividade, porém nem sempre foi assim. Na antiguidade a tributação se destinava basicamente a custear guerras e a prover o sustento de uma classe governante que excedia em seus gastos com luxo e obras suntuosas para o seu mero deleite. Em comunidades primitivas, quando a terra passou a ser um bem de muito valor e objeto constante de disputa entre diversas tribos, as tribos vencedoras exigiam vantagens tributárias tais como, contribuições em ouro, escravos e mercadorias a título de despojos de Guerra. Na Pérsia no governo de Ciro, no século VI a. C foi implantado um eficiente sistema de correio que permitia o acompanhamento da arrecadação e controle. Tem origem na Pérsia a mais antiga taxa de prestação de serviço público, referente à expedição de carta de correspondência. Nos antigos impérios a população pagava a “décima”, que correspondia a 10% sobre a produção devida ao Estado para as obras públicas. No Egito antigo o império instituiu uma administração altamente especializada e centralizada e dentre as carreiras públicas, a de escriba real que controlavam a arrecadação de tributos, estava no topo da carreira. O regime tributário no Egito incidia sobre os camponeses que tinham a obrigação de pagarem a título de imposto uma contribuição sobre o montante da produção. Na Grécia antiga os tributos serviam para custear as despesas de guerra e para isso o Estado cobrava impostos sobre estrangeiros, assim como a conquista de novas áreas servia para aumentar o controle da arrecadação tributária naquela região. No império Romano a arrecadação de impostos também teve grande importância, pois sua riqueza e expansão foram conquistadas sobre bases tributárias. A expansão do império Romano resultou na anexação de territórios fora da Itália, sendo que as cidades provinciais pagavam os tributos diretos e permanentes sobre as pessoas, e sobre a produção da terra, bem como sobre exploração das minas. O atual sistema de múltiplos impostos foi herdado dos romanos. (Alessandro Leôncio Frazão) Um texto obedece a uma determinada estruturação, que, segundo seu autor, é mais conveniente. Assinale a observação adequada sobre a estruturação desse texto.","opcoes":["Tratando-se de um texto histórico, cada parágrafo mostra sucessão cronológica e uma contínua retomada de informações anteriormente fornecidas.","O critério de paragrafação do texto é fundamentado na diferença cronológica e na noção de progresso aplicada aos impostos.","O parágrafo final do texto mostra um ponto de chegada do sistema de impostos, caracterizado pela multiplicidade e pela ligação mais próxima ao sistema atual de cobrança.","O primeiro parágrafo mostra a etapa mais antiga do sistema de impostos, em oposição a todos os citados na sequência do texto.","O título selecionado para o texto abrange todos os tópicos abordados nos diversos parágrafos, encaminhados a justificar o sistema atual de cobrança de impostos."],"correta":2,"explicacao":"Gabarito: <strong>O parágrafo final do texto mostra um ponto de chegada do sistema de impostos, caracterizado pela multiplicidade e pela ligação mais próxima ao sistema atual de cobrança.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8468,"enunciado":"“Os tributos são tão antigos quanto a própria humanidade, sua origem não pode ser definida com exatidão, mas acompanha a própria evolução humana, desde épocas pré-históricas quando o homem passou a fixar-se em apenas um local para caça e guarda de alimentos, sendo, portanto, dono daquele pedaço de terra. No início os tributos eram ofertas voluntárias dos homens como forma de presentear ou homenagear seus Deuses e Líderes. Com o passar do tempo, pelo que se pode ver, as disputas por terras por meio de centenas de guerras foram responsáveis pela evolução da humanidade com o surgimento de grandes civilizações. A partir dessa época os tributos passaram a ser obrigatórios e exigidos pelos reis para financiar seus exércitos e com isso conquistar mais terras.” (Ederson Leandro Pereira Farias) O texto acima mostra a opinião e as informações do autor do texto sobre alguns temas ligados aos tributos. Sobre a estruturação envolvendo informações e opiniões, assinale a opção adequada.","opcoes":["O enunciador reivindica a paternidade das informações prestadas, como frutos da sua própria opinião.","O autor do texto apresenta sua própria opinião travestida de uma aparência de opinião geral.","O autor do texto o apresenta como fruto de seu próprio trabalho de pesquisa, não identificando as fontes.","O enunciador apresenta informações de origem alheia, acompanhadas de comentários sobre elas.","O autor do texto apresenta informações diversas, colocando as divergências em destaque."],"correta":1,"explicacao":"Gabarito: <strong>O autor do texto apresenta sua própria opinião travestida de uma aparência de opinião geral.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8471,"enunciado":"“O surgimento do imposto de renda ocorreu relativamente tarde no desenvolvimento dos povos. A instituição de um real imposto sobre a renda exige um modelo econômico que possa ser avaliado e monitorado, para possibilitar o controle, a fiscalização e a cobrança do tributo. O sistema econômico de trocas de produtos ou serviços por outros produtos ou serviços dificultava a medição da renda. Com a criação da moeda, houve uma unidade para determinar o acréscimo do patrimônio das pessoas, possibilitando determinar a renda e tributá-la. Em vez de a riqueza ser avaliada apenas pelos bens que o indivíduo possuía, pôde ser medida pelo produto desses bens, isto é, pela renda.” (A História do Imposto de Renda – Cristóvão Barcellos da Nóbrega) Observe os dois primeiros períodos desse texto: “O surgimento do imposto de renda ocorreu relativamente tarde no desenvolvimento dos povos. / A instituição de um real imposto sobre a renda exige um modelo econômico que possa ser avaliado e monitorado, para possibilitar o controle, a fiscalização e a cobrança do tributo.” A relação lógica entre esses períodos pode ser explicada adequadamente do seguinte modo:","opcoes":["o primeiro período mostra uma consequência do segundo.","o segundo período traz uma ampliação das informações contidas no primeiro.","o segundo período situa cronológica e espacialmente os fatos informados no primeiro.","o segundo período dá forma objetiva à informação dada de forma geral no primeiro período.","o primeiro período mostra uma ideia concessiva em relação ao segundo."],"correta":0,"explicacao":"Gabarito: <strong>o primeiro período mostra uma consequência do segundo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8548,"enunciado":"O trecho que apresenta a proposta do autor para a solu- ção do problema discutido é:","opcoes":["“O Brasil vive um drama: ao acordar do sonho de uma economia agrária pujante, o país desperta para o pe- sadelo de ser, pelo quinto ano consecutivo, o maior consumidor de agrotóxicos do planeta” (parágrafo 1)","“A Bolsa de Chicago define o preço da soja; mas não considera que, para se produzir cada saca, são apli- cadas generosas doses de agrotóxicos que permane- cem no ambiente natural – e no ser humano – por anos ou mesmo décadas” (parágrafo 2)","“Levando-se em conta os casos crônicos, acrescidos da contaminação ambiental difusa nos ecossistemas, os prejuízos podem atingir cifras assustadoramente maiores.” (parágrafo 3)","“Todos os milhares de profissionais envolvidos no co- mércio e na manipulação dessas substâncias são po- tenciais vítimas.” (parágrafo 5)","“Precisamos de outra estrutura agrária – baseada em propriedades menores, com produção diversificada, privilegiando mercados locais e contemplando a con- servação da biodiversidade.” (parágrafo 7)"],"correta":4,"explicacao":"Gabarito: <strong>“Precisamos de outra estrutura agrária – baseada em propriedades menores, com produção diversificada, privilegiando mercados locais e contemplando a con- servação da biodiversidade.” (parágrafo 7)</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8549,"enunciado":"No trecho “Em seu melhor economês, ele garante que as ‘externalidades negativas’ de nosso modelo agrário continuam de fora dos cálculos” (parágrafo 2), a expres- são destacada refere-se a","opcoes":["prejuízos sociais e ambientais causados pelo uso dos agrotóxicos","opiniões dos produtores sobre os benefícios dos agro- tóxicos","lucros obtidos com o grande crescimento do agrone- gócio","influências negativas de outros países na economia agrária","efeitos do aumento das commodities na economia brasileira"],"correta":0,"explicacao":"Gabarito: <strong>prejuízos sociais e ambientais causados pelo uso dos agrotóxicos</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":8550,"enunciado":"Considere os dois períodos do seguinte trecho do pará- grafo 6: “Esses venenos seriam, portanto, um mal ne- cessário, de acordo com esses produtores. Agricultores garantem que não há nenhuma dificuldade em produzir alimentos orgânicos, sem agrotóxicos, para alimentar a população”. Para transformá-los em um só período, mantendo-se o sentido do trecho original, deve-se empregar a palavra","opcoes":["para","porque","quando","portanto","entretanto 3"],"correta":4,"explicacao":"Gabarito: <strong>entretanto 3</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["colocacaoPronominal"]},{"id":18515,"enunciado":"O termo \"ali\" (.9) refere-se ao antecedente \"um grupo de escolas estaduais de ensino médio de Pernambuco\" (.6-7).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":18519,"enunciado":"O emprego de vírgula logo após \"alunos\" (.21) justifica-se por isolar elementos de mesma função gramatical","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":18520,"enunciado":"Em linhas gerais, os procedimentos administrativos e pedagógicos adotados nas escolas pernambucanas citadas no texto assemelham-se significativamente aos que são praticados na maioria das redes estaduais e municipais de educação brasileiras.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":18522,"enunciado":"Infere-se do texto que a melhoria do desempenho na educação resulta de um conjunto de ações e de atitudes, entre as quais se situam o planejamento e a avaliação sistemática de alunos e docentes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":18755,"enunciado":"O uso de são interrompidos em substituição a \"interrompem-se\" (.10) preserva a correção gramatical do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28378,"enunciado":"Se, em lugar de \"referir-se\" (L.6), fosse empregada a forma verbal referirmos, seria mantida a coerência da argumentação, mas a correção gramatical exigiria a substituição de \"é\" (L.7) por são.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28382,"enunciado":"Ao se reconhecer que o pensamento \"é sempre pensamento acerca de alguma coisa\" (L.11), justifica-se pensamento como sinônimo de \"instrumento\" (L.9) na argumentação do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28404,"enunciado":"Infere-se do texto que a atual crise norte-americana é conseqüência da fragilidade estrutural e tecnológica do sistema financeiro daquele país.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28408,"enunciado":"Mais de 52 milhões de hectares da área desmatada na Amazônia tornaram-se pastagens.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28421,"enunciado":"Preservam-se a coerência das idéias e a correção gramatical do texto ao se reescrever o termo \"Os filmes indicados\" (L.3-4) como A indicação dos filmes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28523,"enunciado":"Infere-se da argumentação do texto que a crise do mercado de hipotecas nos Estados Unidos foi causada pela falta de transparência desse mercado para o investidor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28524,"enunciado":"Mantendo-se a correção gramatical e a coerência do texto, é possível deslocar a oração \"para discutir um tema desafiante\" (L.2-3), que expressa uma finalidade, para o início do período, fazendo-se os devidos ajustes nas letras maiúsculas e acrescentando-se uma vírgula logo após \"desafiante\".","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28525,"enunciado":"No texto, \"ele\" (L.6) refere-se a \"tema desafiante\" (L.2-3), e \"essa bolha\" (L.10) refere-se a \"turbulência\" (L.9).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28532,"enunciado":"A globalização caracteriza-se, entre outros aspectos, pela rapidez e pela facilidade com que os capitais circulam pelos mercados financeiros, não raro com objetivos meramente especulativos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28535,"enunciado":"Infere-se do texto que, no atual estágio da economia mundial, os riscos de prejuízo nas transações realizadas no mercado financeiro são nulos ou quase inexistentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":28570,"enunciado":"Preservam-se a coerência textual e a correção gramatical se o termo \"despesas extras\" (L.12) for escrito entre aspas no texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":42380,"enunciado":"Infere-se do texto que, em relação a diferenças entre as formas institucionais analisadas, a família, mas não o Estado, fazia parte do ideário da literatura romântica do século XIX.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":42381,"enunciado":"Infere-se do texto que o círculo familiar tem formato institucional que abriga indivíduos que desobedecem às leis, diferentemente do que se aplica ao Estado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":42385,"enunciado":"Caracteriza-se como facultativo o emprego das vírgulas que isolam a expressão \"na ordem interna e internacional\" (L.8).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":42386,"enunciado":"O termo \"sob a proteção de Deus\" (L.9) poderia ser substituído por perante à proteção de Deus, mantendo-se a correção gramatical do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":42387,"enunciado":"Sem prejuízo para o sentido e a correção gramatical do texto, a forma verbal \"compreende\" (L.13) poderia ser substituída por consiste-se.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":69866,"enunciado":"O período sintático iniciado por \"Inovar significa\" (L.12) estabelece, com o período anterior, relação semântica que admite ser explicitada pela expressão Por conseguinte, escrevendo-se: Por conseguinte, inovar significa (...).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":69889,"enunciado":"Entende-se da leitura do texto que a \"realidade contemporânea\" (L.2) caracteriza-se pela velocidade vertiginosa e pelo acúmulo de bens materiais, assim como pela ausência de integração existencial e falta de tempo para usufruir \"as dádivas materiais da vida\" (L.17).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":85334,"enunciado":"A afirmativa correta, em relação ao texto, é:","opcoes":["A expectativa de muitos, ao colocarem a felicidade acima de quaisquer outras situações da vida diária, leva à frustração diante dos pequenos sucessos que são regularmente obtidos, como, por exemplo, no emprego.","Sentir-se alegre por haver conquistado algo pode significar a mais completa felicidade, se houver uma determinação, aprendida desde a infância, de sentirse feliz com as pequenas coisas da vida.","As dificuldades que em geral são encontradas na rotina diária levam à percepção de que a alegria é um sentimento muitas vezes superior àquilo que se supõe, habitualmente, tratar-se de felicidade absoluta.","A possibilidade de que mais pessoas venham a sentir- se felizes decorre de uma educação voltada para a simplicidade de vida, sem esperar grandes realizações, que acabam levando apenas a frustrações.","Uma resposta provável à questão colocada como título do texto remete à constatação de que felicidade é um estado difícil de ser alcançado, a partir da própria complexidade de conceituação daquilo que se acredita ser a felicidade."],"correta":4,"explicacao":"Gabarito: <strong>Uma resposta provável à questão colocada como título do texto remete à constatação de que felicidade é um estado difícil de ser alcançado, a partir da própria complexidade de conceituação daquilo que se acredita ser a felicidade.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85336,"enunciado":"Nos pares de frases abaixo, é correto afirmar que o sentido expresso na frase I está sendo retomado com outras palavras na frase II APENAS em:","opcoes":["I. O primeiro [fardo] é procurar uma definição para felicidade...","I. O segundo [fardo] é examinar-se, em busca de uma resposta.","I. Nesse processo, depara-se com armadilhas.","I. ... até a conquista da bem-aventurança.","I. ... felicidade é coisa grandiosa."],"correta":3,"explicacao":"Gabarito: <strong>I. ... até a conquista da bem-aventurança.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85337,"enunciado":"O segmento cujo sentido original está reproduzido com outras palavras é:","opcoes":["dois fardos são lançados às costas do inquirido = sérios embates se apresentam à questão.","a rastrear uma escala = a estabelecer um novo caminho.","depara-se com armadilhas = as interferências são enormes.","assim como a euforia pelo aumento de salário = tendo em vista um pagamento maior.","ao influxo das teses libertárias = sob a influência das ideias em defesa da liberdade."],"correta":4,"explicacao":"Gabarito: <strong>ao influxo das teses libertárias = sob a influência das ideias em defesa da liberdade.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85339,"enunciado":"Considere as alterações feitas nos segmentos abaixo grifados. I. Dá trabalho, e a conclusão pode não ser clara. Dá trabalho, e a conclusão não pode ser clara. II. Nesse processo, depara-se com armadilhas. Depara-se com armadilhas nesse processo. III. Não dá para preencher caderno de encargos mais cruel para a pobre criança. Não dá para preencher caderno de encargos mais cruel para a criança pobre. Com as modificações feitas na 2a frase, altera-se o sentido do que foi afirmado na 1a frase em","opcoes":["II, apenas.","III, apenas.","I e II, apenas.","I e III, apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85340,"enunciado":"De acordo com o texto, o Relatório de 2010","opcoes":["aponta vários problemas de saúde da população mundial, com as medidas a serem adotadas para resolvê-los.","deixa de lado a avaliação das causas do crescimento econômico desigual, que ocorre no mundo todo","mostra preocupação com a persistência de problemas no mundo, apesar da constatação de alguns avanços, desde 1990.","assinala algumas divergências, entre os autores do documento, em relação às conclusões possíveis a partir de seus dados.","reconhece a importância da intervenção da ação pública no controle permanente da economia."],"correta":2,"explicacao":"Gabarito: <strong>mostra preocupação com a persistência de problemas no mundo, apesar da constatação de alguns avanços, desde 1990.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85346,"enunciado":"...que impedem esse potencial de se realizar.(3o parágrafo) A expressão grifada acima retoma, considerando-se o contexto, o sentido de","opcoes":["busca de formas alternativas. (1o parágrafo)","compartilhamento do saber científico. (2o parágrafo)","conceito de Tecnologia Social. (2o parágrafo)","construção do desenvolvimento local. (3o parágrafo)","espaço de inclusão digital. (4o parágrafo)"],"correta":3,"explicacao":"Gabarito: <strong>construção do desenvolvimento local. (3o parágrafo)</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85347,"enunciado":"Nesse processo, o objetivo é, ao mesmo tempo, dinamizar as potencialidades locais e desbloquear aqueles entraves que impedem esse potencial de se realizar. (3o parágrafo) Os dois segmentos grifados acima podem ser substituídos, mantendo-se o mesmo sentido, na ordem, por:","opcoes":["reduzir - equacionar os problemas","incentivar - afastar os obstáculos","desconsiderar - libertar os fatores","diversificar - identificar os empecilhos","valorizar - perceber as dificuldades"],"correta":1,"explicacao":"Gabarito: <strong>incentivar - afastar os obstáculos</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":85351,"enunciado":"A afirmativa INCORRETA, considerando-se o que dizem os versos, é:","opcoes":["As cabras e os peixes são considerados animais benfazejos, por constituírem a base da alimentação dos moradores.","A velhinha e o pescador oferecem seus produtos ainda bastante cedo aos moradores, recém-acordados.","O silêncio que impera durante a madrugada pode ser visto como guardião do sono das pessoas aconchegadas em suas camas.","O último verso deixa evidente o fato de que o pescador trazia peixes que havia acabado de pescar.","A repetição da palavra orvalho acentua a sensação de frio e de umidade característicos de uma madrugada de inverno."],"correta":0,"explicacao":"Gabarito: <strong>As cabras e os peixes são considerados animais benfazejos, por constituírem a base da alimentação dos moradores.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["colocacaoPronominal"]},{"id":90990,"enunciado":"Depreende-se do texto que o número de trabalhadores na área científica é diretamente proporcional ao número de mestres e doutores egressos dos cursos de pós-graduação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":90999,"enunciado":"Da leitura do texto conclui-se que, a partir do significativo desenvolvimento da biologia, ocorrido entre o final do século XIX e o início do século XX, as relações entre essa disciplina, a física e a química passaram a ser estabelecidas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":91007,"enunciado":"Da leitura do texto infere-se que artigos científicos podem ser confiáveis e de boa qualidade, mesmo com dados que contrariam a teoria adotada e resultados que extrapolam as expectativas dos pesquisadores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":132993,"enunciado":"A argumentação do texto desenvolve-se a partir de uma afirmação — “estabeleceram-se as condições e o cenário para a convergência entre a informática, a eletrônica e a comunicação” (L.3-4) — que decorre de uma causa — “Com o extraordinário desenvolvimento científico e tecnológico experimentado na segunda metade do século XX” (L.1-2).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":132994,"enunciado":"Nas relações de coesão do texto, o termo “Esse fato” (L.4) refere-se a “desenvolvimento científico e tecnológico” (L.1-2).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":132997,"enunciado":"A tese defendida no texto apoia-se em argumentos fundamentados no papel que a ciência e a tecnologia têm desempenhado desde o “século XIX” (L.1).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":132998,"enunciado":"O uso de metáforas, tais como “rimou com a fé” (L.3), “concluiu-se em prantos” (L.4) e “encarnam a promessa” (L.12- 13), cria a possibilidade de significações imprecisas, tornando vagas e pouco objetivas as argumentações apresentadas no texto, cuja natureza é institucional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":132999,"enunciado":"Na constituição da informatividade do texto, está a ideia de que a tecnologia perpassa o século XX, destacando-se, nas suas “duas últimas décadas” (L.10), como uma forma de solucionar o que se chama de crise ‘de civilização’ (L.14).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133013,"enunciado":"A colocação pronominal em “caracteriza-se” (L.6) indica a escolha dos autores por um registro mais formal de linguagem; o emprego desse pronome antes da forma verbal, além de caracterizar desrespeito às regras gramaticais do registro padrão da linguagem, representaria, no contexto, uso inadequado da linguagem, dado o caráter institucional do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133033,"enunciado":"A respeito da reescritura do período “A despeito da sucessão de crises financeiras e cambiais que se abateram nos últimos 30 anos sobre os ex-periféricos (agora emergentes), a turma do Fundo Monetário continua a acreditar na fábula dos mercados eficientes”, entre as linhas 11 e 14 do texto, julgue os itens que se seguem.\n\nFicariam mantidos o sentido e a correção gramatical do texto caso o trecho fosse assim reescrito: O FMI continua a propalar a novela dos mercados eficientes, embora uma sequência de crises financeiras e cambiais tenha abatido-se, nos últimos 30 anos, sobre os ex-periféricos (agora emergentes).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133039,"enunciado":"Com relação às estruturas linguísticas do texto, julgue os próximos itens.\n\nEstaria mantida a correção gramatical se as formas verbais “são formuladas” (L.4) e “Privilegiou-se” (L.5) fossem substituídas, respectivamente, por formulam-se e foi privilegiada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133041,"enunciado":"Com relação às estruturas linguísticas do texto, julgue os próximos itens.\n\nConstituem exemplos de orações que não seguem a ordem sujeito-verbo-objeto: “como nos inclina a pensar a prevalência da forma pronominal” (L.10) e “uma vez que foi necessário levar em conta a noção de memória coletiva” (L.17-18).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133047,"enunciado":"Julgue os itens subsequentes, relativos ao seguinte trecho do texto: “lembrar-se de alguma coisa é, de imediato, lembrar-se de si?” (L.11).\n\nEstaria mantido o sentido do texto, mas alterada a estrutura conceitual do período, caso o trecho fosse assim reescrito: quando uma pessoa se lembra de alguma coisa, ela está, de imediato, lembrando-se de si?","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133048,"enunciado":"Julgue os itens subsequentes, relativos ao seguinte trecho do texto: “lembrar-se de alguma coisa é, de imediato, lembrar-se de si?” (L.11).\n\nMantém o sentido e a correção gramatical do texto a seguinte reescritura: lembrar algo é, de pronto, lembrar a si?","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133049,"enunciado":"Julgue os itens subsequentes, relativos ao seguinte trecho do texto: “lembrar-se de alguma coisa é, de imediato, lembrar-se de si?” (L.11).\n\nMantêm-se o sentido e a correção gramatical do texto, acrescentando-se elemento enfático ao sentido original, caso o trecho seja assim reescrito: lembrar-se de algo não é, de imediato, lembrar-se de si mesmo?","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133050,"enunciado":"Julgue os itens subsequentes, relativos ao seguinte trecho do texto: “lembrar-se de alguma coisa é, de imediato, lembrar-se de si?” L.11).\n\nFicariam mantidos o sentido e a correção gramatical caso o trecho fosse assim reescrito: se recordar de qualquer coisa é, imediatamente, recordar por causa de si?","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":133053,"enunciado":"As formas verbais “dedicou-se” (L.2) e “se afastar” (L.17) estão na voz reflexiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":219056,"enunciado":"Se a palavra “incidência\" (L.12) for substituída pela palavra ocorrência, prejudica-se a informação original do período e a coerência textual.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":219063,"enunciado":"O texto informa que os índices mais elevados de mortalidade infantil concentram-se, curiosamente, nas regiões onde se localizam os principais núcleos econômicos e financeiros do país.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":226367,"enunciado":"Deduz-se que, quanto à tipologia, o texto é dissertativo, por estar redigido de forma expositiva e exemplificado com dados objetivos, sem reiterados julgamentos dos fatos pela redatora.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":226369,"enunciado":"Deduz-se do último parágrafo do texto que a autora posiciona-se em favor da proteção dos jovens, mesmo que esses sejam infratores, por eles serem vítimas de violências e de calúnias na sociedade atual.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":226375,"enunciado":"A hiper-complexidade da sociedade contemporânea, em especial, acerca da forma de ver e agir dos operadores jurídicos, está a exigir que possibilite-se a incorporação permanente das camadas excluídas da população.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":226376,"enunciado":"São as mais variadas, as propostas de modificações da estrutura do sistema judiciário; porém, faz-se necessário, antes de mais nada, uma mudança de mentalidade da população.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":277559,"enunciado":"Mantém-se a correção gramatical do período ao se substituir “mas” (L.13) por embora.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":277561,"enunciado":"O emprego de vírgulas para isolar o segmento “colocando em contato mais de 190 milhões de habitantes” (L.2-3) justifica-se por isolar oração reduzida de gerúndio intercalada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":277564,"enunciado":"Depreende-se das informações do texto que houve, em todas as faixas de renda, uma tendência de expansão do número de pessoas que preferem ter apenas telefone celular.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":318335,"enunciado":"Em relação às informações e estruturas linguísticas do texto acima, julgue os itens que se seguem.\n\nPrejudica-se a correção gramatical do texto ao se substituir “Identificaram-se” (l.23) por Foram identificados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":318339,"enunciado":"Em relação às informações e estruturas linguísticas do texto acima, julgue os itens que se seguem.\n\nSubentende-se das informações do texto que a palavra “Antes” (l.16) remete a período recente, quando o CNJ, já criado, ainda não gozava do prestígio que tem hoje.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":318345,"enunciado":"Com base na leitura do texto acima, julgue os itens a seguir.\n\nNo trecho “Enfatiza o ministro que o bom senso recomenda a mudança” (l.7-8), mantêm-se a informação original e a correção gramatical do período ao se substituir “que o” por cujo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323593,"enunciado":"Com relação às informações e às estruturas linguísticas do texto acima, julgue os itens a seguir:\n\nPrejudica-se a correção gramatical do período ao se substituir “ao relacionamento”(l.12-13) por à relação:","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323594,"enunciado":"Com relação às informações e às estruturas linguísticas do texto acima, julgue o  item  a seguir:\n\nDepreende-se das informações do texto que as ouvidorias das operadoras de planos de saúde deverão prestar à Ouvidoria da ANS esclarecimentos e informações acerca das reclamações e sugestões recebidas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323597,"enunciado":"Com relação às informações e às estruturas linguísticas do texto acima, julgue o  item a seguir:\n\nA expressão “dessas estruturas” (l.10-11) refere-se ao antecedente “empresas” (l.9).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323598,"enunciado":"Com relação às informações e às estruturas linguísticas do texto acima, julgue o  item a seguir:\n\nMantém-se a correção gramatical do período ao se substituir “em especial” (l.12) por especialmente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323599,"enunciado":"Com base na leitura do texto acima, julgue o   item  que se segue.\n\nPrejudica-se a correção gramatical do período ao se substituir “efeito positivo” (l.2) por efeitos positivos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323605,"enunciado":"Com referência às informações e estruturas linguísticas do texto acima, julgue os itens a seguir.\n\nMantêm-se a correção gramatical do período e suas informações originais ao se substituir o termo “pois” (l.10) por qualquer um dos seguintes: já que, uma vez que, porquanto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323606,"enunciado":"Com referência às informações e estruturas linguísticas do texto acima, julgue os itens a seguir.\n\nDepreende-se das informações do texto que a forma de “participação dos consumidores” (l.12-13) sugerida no texto é a reclamação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":323607,"enunciado":"Com referência às informações e estruturas linguísticas do texto acima, julgue os itens a seguir:\n\nMantém-se a correção gramatical do período ao se substituir “é” (l.9) por são, desde que também se substitua “leva” (l.10) por levam.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":326877,"enunciado":"Em relação a ideias e estruturas linguísticas do texto acima, julgue os itens que se seguem.\n\n\nUsou-se vírgula após o termo “água” (l.15) para isolar oração de natureza explicativa subsequente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":326879,"enunciado":"Em relação a ideias e estruturas linguísticas do texto acima, julgue os itens que se seguem.\n\n\nDepreende-se das informações do texto que o Projeto São Francisco não só fornecerá água para regiões tradicionalmente secas como também beneficiará o conhecimento histórico e a proteção da fauna das regiões contempladas pelas obras","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":326885,"enunciado":"Com base no texto acima, julgue os itens a seguir.\n\n\nMantêm-se a correção gramatical e as informações originais do texto ao se substituir a palavra “para” (l.5) pela expressão com o objetivo de.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":326888,"enunciado":"Em relação ao texto acima, julgue os itens que se seguem.\n\n\nEm “espalham-se” (l.1), o termo “se” indica que o sujeito da oração é indeterminado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":326890,"enunciado":"Em relação ao texto acima, julgue os itens que se seguem.\n\n\nMantêm-se as informações originais do período ao se substituir “tremenda”(l.11) por enorme.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":329726,"enunciado":"Na frase “Ele explica que essa emoção, a despeito do conceito popular, muitas vezes é positiva.” (L.10-11), “essa emoção” refere-se à raiva enquanto o “conceito popular” é o de que a raiva é uma emoção destruidora.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":329730,"enunciado":"O trecho “essa antiga perplexidade” (L.3-4) refere-se ao “problema do tempo” (L.2-3).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":329763,"enunciado":"Infere-se do texto que, a despeito de outras razões igualmente poderosas, a precariedade de recursos naturais é a principal responsável pelos baixos índices de crescimento econômico que o Brasil apresenta no último quarto de século.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":329765,"enunciado":"Deduz-se do texto que, no Brasil, em período de retração ou de baixo crescimento, ao contrário do que ocorre em fase de crescimento elevado, os mecanismos indutores da distribuição de renda praticamente deixam de existir, o que faz aumentar a concentração da riqueza nacional em mãos de poucos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":342939,"enunciado":"Com relação à interpretação do texto e à significação das palavras nele empregadas, julgue os seguintes itens.\n\nDepreende-se, a partir do texto, que João era prenome de Pádua","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":342940,"enunciado":"Com relação à interpretação do texto e à significação das palavras nele empregadas, julgue os seguintes itens.\n\nDepreende-se do texto que a vida de Pádua era financeiramente difícil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":342943,"enunciado":"Com relação à interpretação do texto e à significação das palavras nele empregadas, julgue os seguintes itens.\n\nEntre os trechos que justificam o título do texto, inclui-se o seguinte: “Pádua, ou por ordem regulamentar, ou por especial designação, ficou substituindo o administrador” (l.21-23).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":359772,"enunciado":"Julgue os itens que se seguem, relativos a aspectos linguísticos do texto.\n\nAs expressões “em novembro de 2011” (l.1-2), “Até outubro de 2011” (l.10) e “Até 2014” (l.24-25), empregadas como elementos coesivos no texto, referem-se a períodos de adoção, pelo governo, de medidas relativas à alteração da estrutura de cobrança de tributos","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":359781,"enunciado":"Cada um dos itens abaixo apresenta uma proposta de reescrita de trecho do texto — indicado entre aspas —, que deve ser julgada certa se estiver gramaticalmente correta, ou errada, em caso contrário.\n\n“Os maiores desafios (...) meta ideal, de 1” (l.18-21) — Os maiores desafios do país relaciona-se a educação, que é o terceiro componente do IDHM, que, no período de vinte anos, cresceu de 0,279 para 0,637, mas é o mais distante da meta ideal, que é 1.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":377365,"enunciado":"Depreende-se do texto que a participação das mulheres na sociedade brasileira deve-se exclusivamente a fatores culturais e à formação da identidade feminina.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":377371,"enunciado":"Depreende-se do texto que os termos “relação de trabalho” e “relação de emprego” são antônimos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":377372,"enunciado":"Na linha 15, a forma pronominal “la”, em “anunciá-la”, refere- se a “polícia”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":377373,"enunciado":"Infere-se do trecho acima que o personagem está angustiado pelo fato de ter encontrado uma carteira e pelo dilema de usa ou não o dinheiro, que por acaso pudesse encontrar dentro dela.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":417462,"enunciado":"Comparando-se os resultados obtidos nas edições de 2003, 2006 e 2009, é correto afirmar que o menor crescimento da pontuação dos alunos brasileiros se deu em relação à área de ciência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":417465,"enunciado":"Julgue o item seguinte , relativo à ideia do texto acima.\n\nInfere-se que o autor do texto considera Antonio Nicolau Tolentino socialmente excluído no Brasil da época da monarquia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420781,"enunciado":"Narrado em primeira pessoa e tratando de tema científico, o texto classifica-se como artigo científico, ainda que tenha sido publicado em periódico não especializado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420789,"enunciado":"Depreende-se do texto que o “art. 101, n.º 6, da Constituição do Império” (L.16-17) tornou-se letra morta em decorrência da prática política adotada por D. Pedro II.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420798,"enunciado":"Por tratar-se de narrativa em terceira pessoa, o texto apresenta, além do relato das ações, alguns comentários do narrador, sem perscrutar o pensamento do personagem principal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420802,"enunciado":"A forma verbal “Lidamos” (L.9) poderia ser corretamente substituída por Lida-se","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420803,"enunciado":"Seria mantida a correção gramatical do texto caso o trecho “cartões de crédito (...) no mundo físico” (L.3-7) fosse assim reescrito: exige-se, a toda hora afim de identificar alguém no mundo físico, cartões de crédito, RG, CPF, crachás corporativos e carteirinhas de mil e uma entidades que engordam a carteira de todo cidadão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420809,"enunciado":"Nas estruturas “que se repetem” (L.4) e “que se revela” (L.6), o pronome “se” poderia ser deslocado, sem prejuízo da correção gramatical do texto, para imediatamente após as formas verbais “repetem” e “revela” — que repetem-se e que revela-se, respectivamente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":420815,"enunciado":"As orações “que têm afetado” (L.17) e “que pôde ser notado” (L.18) referem-se a “aquecimento global” (L.16).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":483890,"enunciado":"Cada item a seguir apresenta uma proposta de reescrita de trecho do texto II — indicado entre aspas —, que deve ser julgada certa se estiver gramaticalmente correta e mantiver o sentido do texto, ou errada, em caso contrário.\n\n“Logo a seguir, (...) sob vigilância” (l. de 8 a 10): Em seguida, retiram-se os equipamentos dos seus locais de origem e levam-se, ainda no sábado, para as sedes dos TREs, onde as quais permanecem sob vigilância","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":780573,"enunciado":"Leia os dizeres de uma faixa de rua. A leitura atenta do texto permite afirmar:","opcoes":["Os verbos tocar e fazer, ambos no imperativo, apresentam-se como ordem, uma exigência.","A escrita à direita da faixa contextualiza as frases à esquerda, direcionando o entendimento.","A expressão Se toca não permitiria, em outra situação linguística, diferente entendimento, pois seu significado está cristalizado na língua.","As formas verbais toca e faça encontram-se na terceira pessoa do singular, em consonância com o pronome se."],"correta":1,"explicacao":"Gabarito: <strong>A escrita à direita da faixa contextualiza as frases à esquerda, direcionando o entendimento.</strong>.","banca":"UFMT","ano":2017,"temas_relacionados":["colocacaoPronominal"]},{"id":780586,"enunciado":"Sobre o texto, assinale a afirmativa correta.","opcoes":["O trecho a era da inocência acabou refere-se ao fato de, atualmente, até crianças usarem as redes sociais para lazer ou mesmo comunicarem-se com os amiguinhos.","A expressão entre parênteses (ou de pornografia...) foi usada como brincadeira para mostrar que também o especialista norte-americano acessa esse tipo de site.","Do alto dos seus 25 anos de experiência é expressão usada comumente, com alterações devidas, para enfatizar o conhecimento ou a experiência da pessoa a que se refere sobre o assunto em pauta, como é o caso do texto.","O título Sabe de tudo, inocente sintetiza a ideia de que, atualmente, as pessoas não se preocupam se suas ações nas redes sociais se tornam de domínio público."],"correta":2,"explicacao":"Gabarito: <strong>Do alto dos seus 25 anos de experiência é expressão usada comumente, com alterações devidas, para enfatizar o conhecimento ou a experiência da pessoa a que se refere sobre o assunto em pauta, como é o caso do texto.</strong>.","banca":"UFMT","ano":2017,"temas_relacionados":["colocacaoPronominal"]},{"id":825797,"enunciado":"Considerando as ideias e os aspectos linguísticos desse texto, julgue o item a seguir.\n\nDepreende-se da leitura do texto que o Zica vírus surgiu no Brasil e se proliferou para outros países tropicais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":825809,"enunciado":"Julgue o item a respeito dos sentidos do texto e de seus aspectos linguísticos.\n\nNesse texto, que se caracteriza como dissertativo, defende-se a ideia de um novo modelo de desenvolvimento, construído por meio de uma forma de organização coletiva em que as pessoas interajam de modo menos agressivo com o meio ambiente e mais solidário com as demais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":857210,"enunciado":"Assinale a alternativa correta, quanto às classes morfológicas ou funções sintáticas da palavra \"se\" em destaque nas orações abaixo:","opcoes":["O menino feriu-se com a faca. (pronome apassivador)","Vive-se bem nesta cidade. (palavra expletiva ou de realce)","Manuel sempre se pergunta isso. (objeto indireto)","Os professores cumprimentaram-se alegremente. (objeto indireto)","Passaram-se vários anos. (conjunção subordinada integrante)"],"correta":2,"explicacao":"Gabarito: <strong>Manuel sempre se pergunta isso. (objeto indireto)</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["colocacaoPronominal"]},{"id":857220,"enunciado":"Leia o texto abaixo: Como viajar de trem pela Europa Quando vale a pena? Segundo pesquisas, 75% dos viajantes................................................o trem. Entretanto, ................................................procurar outras opções. A vantagem do trem é que as estações são sempre bem localizadas, no centro das cidades (mesmo as pequenas). Mas a ideia de que esse tipo de transporte poupa dinheiro nem sempre é válida, principalmente para longas distâncias, quando compensa voar com aéreas low cost. Um trecho que leva acima de cinco horas nos trilhos pode ser vantajoso de avião, não só para o seu bolso como também para o seu tempo. Os tipos de trem? Cada país da Europa, assim como de outros continentes,........................sua própria companhia ferroviária e algumas operam trechos internacionais. Existem os trens regionais (de distâncias relativamente curtas), os de alta velocidade e os panorâmicos. Em qualquer um, você pode escolher entre primeira ou segunda classe, que diferem em relação ao espaço das poltronas e aos serviços oferecidos, como alimentação e Wi-Fi. Tudo, na verdade,........................dicas! Cabe a você escolher! Fonte: http://revistaviajar.com.br/site/2017/11/14/ como-viajar-de-trem-pela-europa/ Acesso: 15/11/2017. Texto adaptado. Assinale a alternativa que completa corretamente as lacunas do texto, considerando a norma culta da língua escrita quanto ao uso da concordância verbal.","opcoes":["prefere • deve-se • tem • é","prefere • deve-se • têm • são","prefere • devem-se • tem • são","preferem • devem-se • tem • são","preferem • deve-se • têm • é"],"correta":3,"explicacao":"Gabarito: <strong>preferem • devem-se • tem • são</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["colocacaoPronominal"]},{"id":857221,"enunciado":"Assinale a alternativa correta, quanto ao uso da norma culta da língua escrita.","opcoes":["Ninguém obedece-lhe.","Faremos-lhes uma proposta.","Tenho deitado-me cedo todos os dias.","Não é esse o caso por que interesso-me.","Tudo quanto lhe diz respeito é do seu interesse."],"correta":4,"explicacao":"Gabarito: <strong>Tudo quanto lhe diz respeito é do seu interesse.</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["colocacaoPronominal"]},{"id":872736,"enunciado":"Com relação à variação linguística bem como aos sentidos e aos aspectos linguísticos do texto 6A1AAA, julgue o próximo item.\n\n\n\n\nA colocação pronominal observada no trecho “não se tenha insinuado” (ℓ.29) é frequente tanto na língua escrita, sendo utilizada em textos literários, artigos científicos e textos oficiais, quanto na variedade padrão formal falada no Brasil, como a utilizada em telejornais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872750,"enunciado":"No que se refere às ideias, aos fatores de textualidade do texto 6A1AAA e à variação linguística, julgue o seguinte item.\n\n\n\n\nInfere-se dos sentidos do texto que, no trecho “também a sentença que antes parecera imutável para todo o sempre oferece subitamente outra interpretação” (ℓ. 36 e 37), o autor se refere à variação da língua no tempo, ou seja, ao fato de que, com a mudança linguística, novas interpretações são atribuídas aos enunciados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872751,"enunciado":"No que se refere às ideias, aos fatores de textualidade do texto 6A1AAA e à variação linguística, julgue o seguinte item.\n\n\n\n\nConclui-se do texto que é por falta de dinheiro que “o revisor” não tem ao seu dispor “as tecnologias da informática”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872756,"enunciado":"Com relação às ideias e às estruturas linguísticas do texto 6A2AAA, julgue o item a seguir.\n\n\n\n\nNa linha 13, se a forma pronominal “alguma”, em vez de anteposta, estivesse posposta a “coisa”, a correção gramatical do texto seria mantida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872757,"enunciado":"Com relação às ideias e às estruturas linguísticas do texto 6A2AAA, julgue o item a seguir.\n\n\n\n\nNo primeiro parágrafo, apresentando-se como velho, o autor adota um tom de autocomiseração ao afirmar que estudar o envelhecimento implica aprender a lidar com a morte e que esse aprendizado deveria ter prioridade sobre outras reflexões humanas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872758,"enunciado":"Com relação às ideias e às estruturas linguísticas do texto 6A2AAA, julgue o item a seguir.\n\n\n\n\nInfere-se do texto que os jovens, quando conscientes da iminência de sua própria morte, não se importam com essa condição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872765,"enunciado":"Com relação às estruturas linguísticas do texto 6A2AAA, julgue o item que se segue.\n\n\n\n\nA regência do verbo restar é diferente nos trechos “resta pensar” (ℓ.3) e “resta a fazer” (ℓ.4): neste, o sentido do verbo altera-se em relação ao empregado naquele.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872769,"enunciado":"Julgue o próximo item, relativo à estrutura linguística do texto 6A2BBB.\n\n\n\n\nSe a expressão “uma visão revolucionária” (ℓ.27) fosse substituída por ideias revolucionárias, seria necessário alterar a forma verbal “Trata-se” para Tratam-se, para se manter a correção gramatical do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872785,"enunciado":"Considerando as informações e as ideias do texto 6A3BBB, assim como seus aspectos linguísticos, julgue o item a seguir.\n\n\n\n\nA transformação dos métodos tradicionais de gestão pública origina-se, de acordo com o texto, no esforço de lideranças políticas e de gestores públicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872789,"enunciado":"Considerando os aspectos linguísticos e os sentidos do texto 6A3BBB, julgue o item que se segue.\n\n\n\n\nA correção gramatical do texto seria preservada caso o trecho “Mesmo reconhecendo-se” (ℓ.30) fosse substituído por Embora se reconhecesse.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872791,"enunciado":"Em relação às estruturas linguísticas e às ideias do texto 6A4AAA e aos múltiplos aspectos a ele relacionados, julgue o item seguinte.\n\n\n\n\nConclui-se do texto que “o poder de vida ou de morte profissional sobre o autor” (ℓ . 3 e 4) que os revisores têm restringe-se a alterações na forma superficial dos textos, sem atingir seu conteúdo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872792,"enunciado":"Em relação às estruturas linguísticas e às ideias do texto 6A4AAA e aos múltiplos aspectos a ele relacionados, julgue o item seguinte.\n\n\n\n\nA caracterização do revisor como “a pessoa mais importante na vida de quem escreve” (ℓ . 2 e 3) deve-se ao fato de o destino de um autor ser definido pelo texto final apresentado — tarefa do revisor — e não pela mensagem veiculada — tarefa do autor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872797,"enunciado":"Acerca dos sentidos e dos aspectos linguísticos do texto 6A4BBB, julgue o item subsequente.\n\n\n\n\nAo empregar a palavra “continuum” (ℓ .9), a autora do texto grafou-a em itálico para marcá-la como uma palavra que não é própria do léxico do português.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872799,"enunciado":"Acerca dos sentidos e dos aspectos linguísticos do texto 6A4BBB, julgue o item subsequente.\n\n\n\n\nNo último período do texto, o emprego da vírgula imediatamente após “detectados” (ℓ .15) é opcional, pois a oração “preservando-se o máximo possível do texto original” (ℓ . 15 e 16) encontra-se em posição canônica no período, qual seja, após a oração principal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872800,"enunciado":"Acerca dos sentidos e dos aspectos linguísticos do texto 6A4BBB, julgue o item subsequente.\n\n\n\n\nInfere-se do texto que o revisor passa a ser considerado experiente quando, ao revisar um texto, ele opta por um caminho menos simples que se compõe de três passos: identificação de problemas que possam existir no texto objeto de revisão, correção desses problemas e busca de máxima manutenção da produção original.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872801,"enunciado":"Acerca dos sentidos e dos aspectos linguísticos do texto 6A4BBB, julgue o item subsequente.\n\n\n\n\nDe acordo com os sentidos do texto, a atividade de revisão textual pode manifestar-se sob duas formas — a revisão e a reescrita —, cuja diferenciação se dá em termos graduais, escalares.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872804,"enunciado":"No que concerne aos aspectos linguísticos do texto 6A4CCC, julgue o item a seguir.\n\n\n\n\nO público a quem a mensagem do texto 6A4CCC se destina é específico: trata-se de revisores e diagramadores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":872805,"enunciado":"No que concerne aos aspectos linguísticos do texto 6A4CCC, julgue o item a seguir.\n\n\n\n\nNo período “É um orgulho poder contar com você”, a terceira pessoa do singular empregada na forma verbal “É” justifica-se por tratar-se de um verbo impessoal, como em É tarde.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":977631,"enunciado":"No que diz respeito aos aspectos linguísticos e semânticos do texto, julgue o item.\n\n\n\n\nInfere-se do texto que a leitura seja fator fundamental na abertura de horizontes múltiplos para além da família, da etnicidade, da localidade e do tempo, o que é determinante no combate à exclusão e à segregação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":977634,"enunciado":"No que diz respeito aos aspectos linguísticos e semânticos do texto, julgue o item. \n\n\n\n\n\n\n\nNo texto, faz-se referência à existência de processos de exclusão e segregação de jovens brasileiros oriundos das classes menos favorecidas econômica e socialmente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":988748,"enunciado":"Em relação ao texto e às ideias nele expressas, julgue o item a seguir.\n\n\n\n\nDepreende-se da leitura do texto que povos de origem latina, cuja personalidade é inflexível, tendem a somatizar mais que os de origem não latina.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":988755,"enunciado":"No que se refere a aspectos linguísticos do texto, julgue o seguinte item.\n\n\n\n\nA expressão “tal processo” (linhas 25 e 26) refere-se à “maneira como expressam e lidam com seus sentimentos” (linhas 24 e 25).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":988756,"enunciado":"Com relação à correção gramatical e à coerência da proposta de reescrita para cada um dos trechos destacados do texto, julgue o item a seguir.\n\n\n\n\n“O estresse é considerado como o principal causador das doenças emocionais.” (linha 5): Consideram-se o estresse o principal causador das doenças emocionais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":988759,"enunciado":"Considerando a correção gramatical e a coerência das substituições propostas para palavras e expressões destacadas do texto, julgue o item que se segue.\n\n\n\n\n“podem se converter” (linha 3) por podem converterem-se","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1039025,"enunciado":"Considerando as ideias e os aspectos linguísticos do texto, julgue o seguinte item.\n\n\n\n\nNo texto, de estrutura dissertativa, argumenta-se em favor de uma nova política de combate à fome no Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1125327,"enunciado":"Como recurso argumentativo, o texto se refere ao fato de o estudo ter se apoiado em 191 artigos para ter comprobabilidade. Tal recurso, a citação de números e de quantidades, denomina-se intertextualidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"INSTITUTO AOCP","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1125328,"enunciado":"Como característica composicional do gênero ao qual pertence o texto, pode-se afirmar que o primeiro parágrafo resume suas ideias mais gerais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"INSTITUTO AOCP","ano":2018,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1178279,"enunciado":"A respeito das ideias do texto, julgue o item.\n\n\n\n\nInfere‐se do texto que a estratégia corporativa relaciona-se a como uma organização deve utilizar seus recursos, suas capacidades e limitações para construir vantagens competitivas que influenciarão positivamente a decisão de compra dos clientes, bem como sua fidelização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1682794,"enunciado":"Infere-se do trecho “Mas eu ouvia o mormaço com M maiúsculo” que, quando era criança, o autor do texto desconhecia o significado da palavra “mormaço”, já que imaginava tratar-se de uma pessoa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1682797,"enunciado":"Depreende-se dos sentidos do texto que o vocábulo “vernáculo”, no segundo período do texto, refere-se à variante popular rural da língua portuguesa falada no Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1682799,"enunciado":"No trecho “Fi-lo sofrer pelo uso errado que fiz de uma palavra no último Quarto de Badulaques”, a substituição de “Fi-lo” por O fiz, forma mais comum no português do Brasil, manteria a correção gramatical do trecho, de modo que é possível concluir que a escolha do autor visa ironizar a visão que seu amigo tem sobre a língua.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1688296,"enunciado":"No que concerne à estruturação linguístico-gramatical do texto, julgue o item.\n\nO emprego da expressão “o que” (linha 27) relaciona-se ao fato de que cerca de um terço dos jovens entre quinze e dezessete anos de idade está fora da escola devido à falta de interesse.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1688298,"enunciado":"Com relação às ideias do texto, julgue o item.\n\nInfere-se do texto que a superação da desigualdade consiste na necessidade de reconhecê-la como um produto coletivo reproduzido no seio social, cujas soluções dependem da tomada de decisão dos governantes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1688300,"enunciado":"Com relação às ideias do texto, julgue o item.\n\nDeduz-se do texto que a educação, um direito fundamental, deveria ser priorizada, nas políticas públicas, como instrumento que colabora para a igualdade social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1688303,"enunciado":"Com relação às ideias do texto, julgue o item.\n\nDepreende-se do texto que há persistência da desigualdade social no grupo de adolescentes e jovens com pouca ou nenhuma instrução formal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1700595,"enunciado":"A respeito das ideias do texto, julgue o item.\n\n\n\n\nDepreende-se do texto que, muito além do que indica sua tradução literal, o movimento Slow Food propõe o direito ao prazer de comer e torna as etapas de seleção e preparação dos alimentos tão importantes quanto a degustação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1700598,"enunciado":"No que se refere à estruturação linguístico-gramatical do texto, julgue o item.\n\n\n\n\nNo primeiro parágrafo, as duas sentenças interrogativas são retomadas pelo vocábulo “Esses” (linha 3) e estão diretamente vinculadas uma à outra, ou seja, os elementos da primeira sentença relacionam-se, respectivamente, aos elementos da segunda sentença.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1764785,"enunciado":"No que se refere ao texto e a seus aspectos linguísticos, julgue o item.\n\nEntende-se da leitura do texto que a recessão global será uma consequência da drástica diminuição da atividade econômica mundial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1783378,"enunciado":"Acerca das ideias do texto, julgue o item.\n\n\n\n\nDeduz-se da leitura do texto a adoção de pelo menos seis táticas para o controle de enfermidades animais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1783379,"enunciado":"Acerca das ideias do texto, julgue o item.\n\n\n\n\nDo texto se infere que a adoção de controle sanitário animal deveu-se, em parte, à ausência de controle das doenças humanas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1783381,"enunciado":"Acerca das ideias do texto, julgue o item.\n\n\n\n\nCompreende-se do segundo parágrafo do texto a ocorrência de uma fase no controle de doenças animais diretamente relacionada a empreendimentos militares, principalmente os ligados à expansão territorial e econômica.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1783385,"enunciado":"No que concerne aos aspectos linguísticos do texto, julgue o item.\n\n\n\n\nMantém a correção gramatical e os sentidos do texto a seguinte reescritura da sentença “os avanços no controle de doenças limitaram-se ao aperfeiçoamento das técnicas básicas do diagnóstico clínico” (linhas de 19 a 21): os progressos na mitigação de moléstias eram limitados pelo aprimoramento dos métodos básicos do diagnóstico clínico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1783781,"enunciado":"Da relação lógica de sentido estabelecida no segmento “A crise provocada pela pandemia do novo coronavírus” (linha 1) deduz-se que a “pandemia do novo coronavírus” é a causa e “crise”, a consequência.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1783793,"enunciado":"“se mostram” (linha 53) por mostram-se","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1829221,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nIdentifica-se, no texto, uma crítica aos governos cujos discursos não incentivaram a solidariedade social em sua população no combate à pandemia de covid-19.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1829222,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nEntende-se da leitura do texto que, em todo o mundo, as organizações de saúde, embora bem financiadas pelos Estados, são incapazes de atender adequadamente as demandas provindas de uma pandemia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1833366,"enunciado":"A respeito do texto e de seus aspectos linguísticos, julgue o item.\n\n\n\n\nEntende-se da leitura do texto que a acessibilidade plena está associada à inclusão social, dignidade de vida e cidadania.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1833371,"enunciado":"Considerando a correção gramatical e a coerência das substituições propostas para vocábulos e trechos destacados do texto, julgue o item. \n\n\n\n\n“devem se adequar” (linha 20) por devem adequar-se","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1833374,"enunciado":"No que se refere à correção gramatical e à coerência da proposta de reescrita para cada um dos trechos destacados do texto, julgue o item. \n\n\n\n\n“A acessibilidade deve ser garantida” (linha 1): Deve-se garantir a acessibilidade","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1840072,"enunciado":"Julgue o item em relação ao texto e a seus aspectos linguísticos. \n\n\n\n\nNo período “Sob qualquer ângulo observado, trata-se de um avanço espantoso” (linha 5), o sujeito da oração está posposto ao verbo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1844350,"enunciado":"Considerando as ideias e os sentidos do texto apresentado, julgue o item.\n\n\n\n\nConclui-se do texto que o petróleo se tornou uma alternativa ao carvão mineral não por questões ambientais ou econômicas, mas por atender as demandas da Revolução Industrial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1844352,"enunciado":"Considerando as ideias e os sentidos do texto apresentado, julgue o item.\n\n\n\n\nInfere-se do texto que inexistiam carros antes da criação da gasolina.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865405,"enunciado":"Infere-se do segundo parágrafo do texto que Simão Bacamarte classificava os loucos conforme o critério de idade, cuidando primeiro dos pacientes mais velhos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865406,"enunciado":"Depreende-se do texto que os habitantes de Itaguaí desaprovavam as curas do alienista, visto que nem sempre ele obtinha êxito em sua terapêutica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865409,"enunciado":"Infere-se do texto que o alienista se sentiu profissionalmente realizado após curar todos os hóspedes da Casa Verde, haja vista o grande esforço por ele empreendido no tratamento dos enfermos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865412,"enunciado":"O termo “lhe”, em “incutir-lhe” (linha 12), refere-se a “Simão Bacamarte” (linha 19).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865414,"enunciado":"O trecho “Imagina-se o resto” (linha 25) poderia ser reescrito da seguinte forma, mantendo-se sua correção gramatical e seu sentido original: O resto é imaginativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865416,"enunciado":"O trecho “aplicando à terapêutica o método da estratégia militar” (linhas 29 e 30) poderia ser reescrito da seguinte forma, mantendo-se sua correção gramatical e seu sentido original: e a terapêutica era aplicada ao método da estratégia militar.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865420,"enunciado":"A correção gramatical e os sentidos do trecho “na diligência e penetração com que principiou a tratá-los” (linhas 2 e 3) seriam mantidos caso o termo “que” fosse substituído por as quais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1865423,"enunciado":"O trecho “Cada beleza moral ou mental era atacada no ponto em que a perfeição parecia mais sólida” (linhas de 25 a 27) poderia ser reescrito da seguinte forma, mantendo-se sua correção gramatical e seus sentidos originais: Toda a beleza moral ou mental era atacada no ponto em que a perfeição parecia mais sólida.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907270,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.  \n\n\n\n\nDepreende-se do texto que o experimento de inteligência animal conduzido pelas psicólogas alemãs, apesar de engenhoso, não foi totalmente inovador, uma vez que o desenho do estudo foi elaborado a partir de experimento prévio semelhante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907272,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.  \n\n\n\n\nO comportamento motivado por condicionamento simples, referido no penúltimo parágrafo, distingue-se do tipo de comportamento motivado pela compreensão de uma situação, abordado no estudo das psicólogas alemãs.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907278,"enunciado":"Acerca dos aspectos gramaticais e dos sentidos do texto apresentado, julgue o item.\n\n\n\n\nMantendo-se a correção gramatical e os sentidos do terceiro parágrafo, o trecho “O teste ao qual os cachorros foram submetidos consistia essencialmente na encenação de uma situação na qual os pesquisadores tentavam alimentar os animais, mas não conseguiam” (linhas 8 e 9) poderia ser reescrito da seguinte forma: O teste que os cachorros foram submetidos consistia essencialmente na encenação de uma situação em que os pesquisadores tentavam alimentar os animais, mas não conseguiam.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907284,"enunciado":"Acerca dos aspectos gramaticais e dos sentidos do texto apresentado, julgue o item.\n\n\n\n\nSeriam mantidos a correção gramatical e os sentidos do trecho “esperar os que pareciam não querer alimentá-los” (linhas 23 e 24) caso o termo “que” fosse substituído por quem.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907286,"enunciado":"Acerca dos aspectos gramaticais e dos sentidos do texto apresentado, julgue o item.\n\n\n\n\nNo trecho “esperar os que pareciam não querer alimentá-los” (linhas 23 e 24), está elíptico, após o vocábulo “os”, o termo humanos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907574,"enunciado":"No que se refere às ideias e a aspectos linguísticos do texto anterior, julgue o item a seguir.\n\n\n\n\nInfere-se do texto que Karl Popper não era adepto dos métodos da indução e do verificacionismo e até os criticava.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907577,"enunciado":"No que se refere às ideias e a aspectos linguísticos do texto anterior, julgue o item a seguir.\n\n\n\n\nA forma pronominal “esta”, em “é esta a proposta da busca de um mundo melhor” (terceiro período), retoma o que se afirma no segundo período do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1907579,"enunciado":"No que se refere às ideias e a aspectos linguísticos do texto anterior, julgue o item a seguir.\n\n\n\n\nNo segundo período, a posição do pronome “se”, em “constata-se não só seu incômodo”, é motivada pela presença da palavra “não”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1909168,"enunciado":"Julgue o item seguinte, de acordo com as ideias do texto CG2A1-II. \nA participação popular na formulação de determinadas políticas públicas deve-se à influência dos conselhos municipais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1913147,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nEntende-se da leitura do quarto parágrafo do texto que a redução da produção de leite é consequência da perda de apetite do gado leiteiro, causada pela febre aftosa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1913157,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nA forma verbal “incluem-se” (linha 40) está empregada na voz passiva pronominal e poderia ser corretamente substituída por estão incluídos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1917704,"enunciado":"Com relação às ideias do texto, julgue o item. \n\n\n\n\nDepreende-se do texto que os metrossexuais deixaram de existir recentemente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1917707,"enunciado":"Com relação às ideias do texto, julgue o item. \n\n\n\n\nConclui-se das informações apresentadas no texto que as mulheres ainda consomem mais cosméticos e produtos de beleza que os homens.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1917717,"enunciado":"Considerando os sentidos e os aspectos linguísticos do texto, julgue o item. \n\n\n\n\nA forma pronominal “deles” (linha 32) faz referência a “ambientes de trabalho ou de convivência” (linhas 30 e 31).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1917720,"enunciado":"Considerando os sentidos e os aspectos linguísticos do texto, julgue o item. \n\n\n\n\nNa linha 19, a correção gramatical do texto seria prejudicada se o vocábulo “se” fosse colocado depois de “comparado”, da seguinte forma: comparado-se.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1926267,"enunciado":"Em relação às ideias e à tipologia do texto, julgue o item. \n\n\n\n\nEntende-se da leitura do texto que as notícias falsas em saúde põem em risco a segurança das vacinas no Brasil, por isso o Ministério da Saúde criou um mecanismo de checagem da veracidade de boatos que circulam nas redes sociais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1926271,"enunciado":"A respeito de aspectos linguísticos do texto, julgue o item. \n\n\n\n\nDadas as relações de coesão do texto, conclui-se que, no segmento “quem as produz” (linhas 14 e 15), o vocábulo “as” está empregado em referência a “pesquisas científicas” (linha 14).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1939944,"enunciado":"Em relação às ideias do texto, julgue o item. \n\n\n\n\nInfere-se do posicionamento da diretora de gestão da saúde da WTW que, no que diz respeito à saúde mental dos colaboradores que atuam em uma organização, a promoção de ações pontuais de bem-estar não são suficientes para atenderem, de fato, às necessidades dessas pessoas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1939945,"enunciado":"Em relação às ideias do texto, julgue o item. \n\n\n\n\nConclui-se da leitura do último parágrafo que, entre as causas de desequilíbrio psicológico, o estresse é a mais recorrente, sendo também a condição que mais afeta as pessoas no trabalho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1939956,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nHajam vistos os frequentes pedidos de afastamento do trabalho por estresse, solicita-se a contratação urgente de uma equipe de acompanhamento psicológico para dá apoio aos colaboradores desta autarquia, ressaltando a importância da providência tomada neste sentido.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1955629,"enunciado":"Em relação à tipologia do texto e às ideias nele expressas, julgue o item.\n\n\n\n\nEntende-se da leitura do texto que o normal, segundo especialistas, é que, aos cinco anos de idade, as crianças falem fluentemente, sem dificuldade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1973790,"enunciado":"Considerando as ideias do texto CG3A1-I, julgue o seguinte item. \n\n\n\n\nInfere-se do texto que as dificuldades enfrentadas durante uma excursão de caminhada são mais incômodas do que as obrigações do trabalho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1976608,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto apresentado, julgue o item. \n\nNo texto, é feita uma comparação entre o termo despertador e a expressão despertar a dor, concluindo-se que ambos se relacionam com um despertar para a vida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1976620,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto apresentado, julgue o item. \n\nNo trecho “cada um de nós é capaz de desvendá-la” (linha 12), a substituição da forma verbal “é” por somos prejudicaria a correção gramatical do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1976622,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto apresentado, julgue o item. \n\nNo trecho “há uma realidade que nos espera” (linha 7), o pronome “nos” poderia ser deslocado para depois da forma verbal “espera” — escrevendo-se espera-nos —, sem prejuízo dos sentidos e da correção gramatical do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978408,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.\n\nPor um lado, o processo de Haber-Bosch garantiu a sobrevivência de parte da população mundial, ao contribuir para a produção de fertilizantes nitrogenados, relacionados ao desenvolvimento agrícola; por outro lado, acredita-se que esse processo esteja relacionado à morte de milhões de pessoas em conflitos armados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978409,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.\n\nA expressão “esses compostos” (linha 8) refere-se às diferentes formas em que o nitrogênio é encontrado na atmosfera, como a forma gasosa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978410,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.\n\nDepreende-se do texto que o químico alemão Fritz Haber, quando criou uma forma de produzir amônia sem a ação de organismos, intencionava que sua solução fosse utilizada para a fabricação de armas químicas, a produção de fertilizantes nitrogenados e a síntese de salitre.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978411,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.\n\nInfere-se do texto que o processo de síntese da amônia desenvolvido por Haber-Bosch é uma das descobertas científicas mais importantes do século XX, embora não receba o devido reconhecimento pelo público em geral.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978414,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.\n\nA expressão “esses feitos” (linha 18) refere-se à criação, por Fritz Haber, do processo de fixação do N2 atmosférico em amônia sem o intermédio de organismos e à implementação, por Carl Bosch, do uso da síntese de amônia em escala industrial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978415,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.\n\nNo segundo período do quarto parágrafo do texto, explica-se como o químico Fritz Haber deu um grande passo para solucionar o problema da fixação do N2 atmosférico em amônia sem precisar da ação de outros organismos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978417,"enunciado":"Em relação aos aspectos gramaticais e aos sentidos do texto apresentado, julgue o item.\n\nAs formas pronominais “sua” e “ele”, ambas na linha 5, têm como referente a expressão “o nitrogênio” (linha 4).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978422,"enunciado":"Em relação aos aspectos gramaticais e aos sentidos do texto apresentado, julgue o item.\n\nMantendo-se a correção gramatical do texto, a expressão “com o processo” (linha 24) poderia ser substituída por ao processo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1978425,"enunciado":"Em relação aos aspectos gramaticais e aos sentidos do texto apresentado, julgue o item.\n\nSem prejuízo da correção gramatical e dos sentidos do texto, o trecho “Atribui-se à síntese da amônia um aumento de 30% a 50% da produção agrícola do planeta” (linhas 26 e 27) poderia ser reescrito da seguinte forma: A síntese da amônia é atribuída a um aumento de 30% a 50% da produção agrícola do planeta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1982012,"enunciado":"Acerca das ideias do texto apresentado, julgue o item.\n\nInfere-se do texto que a distância entre Atenas e Maratona é de 40 quilômetros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1982013,"enunciado":"Acerca das ideias do texto apresentado, julgue o item.\n\nDepreende-se do texto que, na Grécia antiga, escravos não podiam participar do exército.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1982018,"enunciado":"Em relação aos sentidos e aos aspectos linguísticos do texto apresentado, julgue o item.\n\nA forma pronominal em “mantê-los” (linha 16) retoma “homens livres” (linha 14).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":1996098,"enunciado":"Em relação às ideias, sentidos e análise do texto, julgue o item a seguir:\n\n\n\n\nSegundo o IBGE, ao se fazer referência a pessoas negras, englobam-se pretos e pardos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2017376,"enunciado":"Considerando os aspectos linguísticos e as ideias do texto, julgue o item.\n\n\n\n\nQuanto ao gênero textual, trata-se de uma crônica.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2077728,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\nDepreende-se da leitura interpretativa do texto que a “agência Campinas” (linha 2) é uma organização não governamental (ONG) que se dedica a serviços humanitários e assistenciais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2096516,"enunciado":"Com referência às idéias do texto, julgue o item a seguir.\n\n\n\n\nInfere-se que a acelerada degradação ecológica pôs em xeque os modelos de desenvolvimento e os paradigmas civilizatórios, sobretudo os de países desenvolvidos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2096517,"enunciado":"Com referência às idéias do texto, julgue o item a seguir.\n\n\n\n\nInfere-se que, para o autor, a inserção da Amazônia na discussão de processos econômicos e políticos mundiais é função de sua referência ecológica mundial e do grau de soberania do Estado brasileiro sobre a Amazônia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2183469,"enunciado":"Considerando a estrutura e os aspectos linguísticos do texto, julgue o item.\n\n\n\n\nAs expressões “do edifício” (linhas 1 e 2) e “do furto” (linha 9) classificam-se como locuções adjetivas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2183470,"enunciado":"Considerando a estrutura e os aspectos linguísticos do texto, julgue o item.\n\n\n\n\nEm todas as formas verbais a seguir, o pronome oblíquo átono preso ao verbo estabelece coesão com a palavra “flor”: “Trouxe-a” (linha 2); “coloquei-a” (linha 3); “destina-se” (linha 4); “Passei-a” (linha 6); “conservá-la” (linha 10); e “restituí-la” (linha 11).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2205200,"enunciado":"Com base na estrutura e no conteúdo do texto, julgue o item.\n\n\n\n\nTrata-se de um texto predominantemente informativo, pertencente ao gênero artigo de opinião.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2205203,"enunciado":"Com base na estrutura e no conteúdo do texto, julgue o item.\n\n\n\n\nInfere-se do texto que a primeira edição do Prêmio Raízes surgiu em agosto de 2012, instituída por meio da Lei n.o 2.619, inspirada na fava-de-bolota, e homenageará dezoito profissionais desta vez.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2205205,"enunciado":"Com base na estrutura e no conteúdo do texto, julgue o item.\n\n\n\n\nNo trecho “O prêmio será trienal e, em sua primeira edição − 2023, serão homenageados dezoito profissionais” (linhas 16 e 17), identifica-se uma estrutura de voz passiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2238185,"enunciado":"A partir do texto acima e considerando aspectos marcantes da realidade mundial contemporânea, julgue o item subseqüente.\n\n\n\n\nInfere-se do texto que uma decisão política, como a da invasão do Iraque, tomada por Washington e apoiada por outros países, repercute intensamente na economia, quer por ampliar a capacidade de acumulação de países ricos, como a dos Estados Unidos da América (EUA), quer por favorecer o equilíbrio entre receita e despesa das contas públicas desses países.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2005,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249414,"enunciado":"Com base no texto acima, julgue o item subseqüente.\n\n\n\n\nA opção do autor pelo emprego do artigo “As” (l.1) iniciando o texto deve-se ao respeito às regras gramaticais, pois sua omissão provocaria incoerência textual.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249417,"enunciado":"Com base no texto acima, julgue o item subseqüente.\n\nSubentende-se da argumentação do texto que “região” (l.5) refere-se a América do Sul.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249418,"enunciado":"Com base no texto acima, julgue o item subseqüente.\nPreservam-se a coerência textual e o respeito às regras gramaticais ao substituir “acoplada” (l.6) por aliada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249419,"enunciado":"Com base no texto acima, julgue o item subseqüente.\nTorna-se o texto mais objetivo e preservam-se suas relações semânticas e a organização retórico-argumentativa ao se substituir “a negação da latino-americanidade em favor da globalização” (l.8) por a afirmação da globalização em favor da latino-americanidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249420,"enunciado":"Com base no texto acima, julgue o item subseqüente.\n\n\n\n\nNo texto, o emprego das aspas em ‘sem riscos’ (l.9) justifica-se pela normatização de se marcar por esses sinais palavras que, normalmente, não pertencem à linguagem do autor ou ao nível de formalidade exigido pelo texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249422,"enunciado":"Com base no texto acima, julgue o item subseqüente.\nDepreende-se da argumentação do texto que a afirmação das identidades dos países da América do Sul fica prejudicada com a imposição de modelos exteriores de organização da vida material e imaterial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249432,"enunciado":"Julgue o item que se segue, a respeito do texto acima.\n\nSubentende-se da argumentação final do texto que, se a cultura caipira não fosse uma invenção dos jesuítas, ela seria mais respeitada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249434,"enunciado":"Julgue o item que se segue, a respeito do texto acima.\n\n\n\n\nPreserva-se a coerência da argumentação textual ao se acrescentar o seguinte parágrafo ao texto: Por isso, cabe também ao IPHAN a preservação dos terreiros de Candomblé.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249436,"enunciado":"Julgue o item que se segue, a respeito do texto acima.\n\nMantêm-se a correção e a coerência textual ao se retirar a vírgula logo depois de “descaracterização” (l.3).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249442,"enunciado":"Com base no texto acima, julgue o item seguinte.\nMantêm-se a coerência textual e o respeito às regras da norma culta, tornando-se mais evidente a indeterminação do sujeito, ao se usar o pronome antes do verbo em “Explica-se” (l.6).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249451,"enunciado":"De acordo com o texto acima, julgue o item a seguir.\nDo emprego de “o DOPS” (l.6-7) como sujeito da oração depreende-se que o prédio, projetado para abrigar uma estação da estrada de ferro, “vigiava e mantinha presos suspeitos de ação contra o governo” (l.7-8).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249458,"enunciado":"Tendo os textos acima como referência inicial e considerando o tema que focalizam, com suas inúmeras implicações, julgue o item subseqüente.\n\nApesar dos graves problemas focalizados no segundo texto, sabe-se que o Brasil foi capaz de montar um sistema público de educação que, apontando para a universalização do acesso ao ensino fundamental, cumpre seu objetivo de promover a drástica redução das desigualdades sociais existentes no país, pela via da socialização do conhecimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249459,"enunciado":"Tendo os textos acima como referência inicial e considerando o tema que focalizam, com suas inúmeras implicações, julgue o item subseqüente.\n\nInfere-se da pesquisa citada no segundo texto que, em linhas gerais, uma parcela das escolas brasileiras, em vez de constituir um lugar de inclusão e de convivência de diversidades, transforma-se em ambiente de medo, no qual o aluno sente-se vulnerável e inseguro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249461,"enunciado":"Tendo os textos acima como referência inicial e considerando o tema que focalizam, com suas inúmeras implicações, julgue o item subseqüente.\nAo cenário focalizado no primeiro texto, agrega-se a ação do denominado crime organizado, fortemente ligado ao narcotráfico e em larga medida responsável pela expressiva dimensão alcançada pelo contrabando de armas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249466,"enunciado":"Tendo o texto acima como referência inicial, julgue o item seguinte, relativos ao atual quadro econômico brasileiro.\nInfere-se do texto que os investimentos industriais feitos pelo Brasil são extremamente centralizados, o que determina a concentração de pólos industriais nas regiões metropolitanas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249467,"enunciado":"Tendo o texto acima como referência inicial, julgue o item seguinte, relativos ao atual quadro econômico brasileiro.\nQuando o texto fala em “emprego formal”, está-se referindo à modalidade de trabalho remunerado que segue a legislação relativa ao setor, a começar pelo registro do trabalhador em carteira profissional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249470,"enunciado":"Tendo o texto acima como referência inicial, julgue o item seguinte, relativos ao atual quadro econômico brasileiro.\nO texto confirma o dinamismo da economia de Mato Grosso e, pelo consumo de energia elétrica, vê-se que a opção de desenvolvimento assumida atualmente pelo estado centra-se na indústria de bens duráveis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2249477,"enunciado":"Tendo o texto acima como referência inicial e considerando as múltiplas implicações do tema que ele focaliza, julgue o item subseqüente.\nUm dos graves problemas nacionais suscitados pelo texto, em sua última oração, poderá ser resolvido — ou, pelo menos, reduzido em seus efeitos potencialmente corruptores — com a recente decisão tomada pelo Congresso Nacional de eliminar as doações particulares para as campanhas eleitorais, garantindo-lhes exclusivamente o financiamento público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2320393,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item a seguir.\n\nEm “Acredita‑se que o incêndio da biblioteca foi uma enorme perda para a humanidade” (linhas 8 e 9), a opção pela ênclise foi feita porque o pronome oblíquo “se” está atrelado a um verbo no início de uma frase.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2351089,"enunciado":"Considerando as ideias veiculadas no texto CG1A1, julgue o item a seguir. \n\n\n\n\nDepreende-se do texto que o almirante Álvaro Alberto estava envolvido com o projeto de criação do que viria a ser o CNPq enquanto César Lattes conquistava reconhecimento científico internacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2351091,"enunciado":"Considerando as ideias veiculadas no texto CG1A1, julgue o item a seguir. \n\n\n\n\nEntende-se do texto que, apesar do impacto das descobertas de César Lattes, a ciência brasileira ainda ocupava uma posição marginal no cenário mundial quando da criação do CNPq.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2351093,"enunciado":"Acerca dos mecanismos de coesão textual empregados no texto CG1A1, julgue o próximo item.\n\n\n\n\nNo penúltimo período do segundo parágrafo, o segmento “seus depoimentos” refere-se aos depoimentos do presidente Dutra reproduzidos na coletânea 50 anos do CNPq contados pelos presidentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2358031,"enunciado":"Com base nos sentidos e nas ideias expressos no texto CB1A1, julgue o item a seguir.\nInfere-se do texto que o uso de tecnologias inovadoras como a IA pode ter implicações econômicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2415240,"enunciado":"Julgue o item que se segue, a respeito das ideias e estruturas linguísticas do texto precedente.\n\n\n\n\nEntende-se do texto que o conceito de “sociedade do conhecimento” perdurou por mais de trinta anos, até a sua substituição pela chamada “sociedade da ignorância”, recém-descoberta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":2415244,"enunciado":"Considerando as ideias e os aspectos linguísticos do texto precedente, julgue o item a seguir.\n\n\n\n\nNo último período do texto, as formas pronominais “suas” e “ele” são elementos de coesão referencial que remetem à expressão “o enunciador”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3046807,"enunciado":"Julgue o item a seguir.\n\nO c, com valor de oclusiva velar, das sequências interiores cc (segundo c com valor de sibilante), cç e ct, e o p das sequências interiores pc (c com valor de sibilante), pç e pt, ora se conservam, ora se eliminam. Assim, conservam-se nos casos em que são invariavelmente proferidos nas pronúncias cultas da língua: compacto, convicção, convicto, ficção, friccionar, pacto, pictural; adepto, apto, díptico, erupção, eucalipto, inepto, núpcias, rapto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3091952,"enunciado":"Acerca de aspectos linguísticos do texto apresentado e das ideias nele veiculadas, julgue o item que se segue. \nDefende-se, no texto, o emprego do termo “discriminação” com viés exclusivamente negativo, a fim de se evitar que se confundam as ações afirmativas com atos discriminatórios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3091953,"enunciado":"Acerca de aspectos linguísticos do texto apresentado e das ideias nele veiculadas, julgue o item que se segue. \nInfere-se da leitura do texto que existem situações em que é lícito tratar as pessoas de modo diferenciado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3091954,"enunciado":"Acerca de aspectos linguísticos do texto apresentado e das ideias nele veiculadas, julgue o item que se segue. \nEmbora o texto trate de discriminação em geral, observa-se que a organização de suas ideias progride no sentido de enfocar o tema em um contexto mais específico, o das relações trabalhistas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3091957,"enunciado":"Acerca de aspectos linguísticos do texto apresentado e das ideias nele veiculadas, julgue o item que se segue. \nMantendo-se os sentidos do texto e sua correção gramatical, o trecho “Explica-se: a discriminação, por si só, não é necessariamente medida reprovável” (primeiro período do quinto parágrafo) poderia ser reescrito da seguinte forma: Explica-se que atos discriminatórios, por si só, não são necessariamente medidas reprováveis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":3448590,"enunciado":"Em “o alimento que lhe acompanhará no meio do caminho”, a colocação do pronome “lhe” após o verbo produz erro gramatical, uma vez que ele está no futuro do presente do indicativo. Uma opção gramatical é o uso da mesóclise: “acompanhar-lhe á”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":4120679,"enunciado":"Julgue o seguinte item, referente às estruturas linguísticas e ao vocabulário empregados no texto CG7A1.\n\n\n\n\nA correção gramatical e os sentidos do texto seriam mantidos caso o trecho \"faz-se necessário promover um novo padrão de desenvolvimento que leve em conta, além dos indicadores de eficiência econômica, a preservação da sustentabilidade ambiental\" (segundo parágrafo) fosse reescrito da seguinte forma: a promoção de um novo padrão de desenvolvimento que leve em conta os indicadores de eficiência econômica e a preservação da sustentabilidade ambiental são necessários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]},{"id":4120688,"enunciado":"Julgue o seguinte item, referente às estruturas linguísticas e ao vocabulário empregados no texto CG7A1.\n\n\n\n\nNo trecho \"Por meio dessa agenda, promovem-se o uso eficiente dos recursos naturais, a redução de despesas institucionais e a minimização dos impactos ambientais adversos gerados pelas atividades administrativas\" (último parágrafo), todo o segmento subsequente à forma verbal \"promovem-se\" funciona como seu objeto direto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["colocacaoPronominal"]}];
